\subsection{Case B (\(b=0\))}

Model \eqref{2d} for \(b=0\) has only one equilibrium given explicitly by: 
\begin{eqnarray*}
E_1= \,\left(a,-a+\frac{1}{3} a^3\right),
\end{eqnarray*}
 and the linear part of \(f_{(a,0, c)}\) at $E_1$ has eigenvalues
 \begin{eqnarray}\label{eigb0}
\frac{1}{2} c(1-a^2)\pm \frac{1}{2}\sqrt{(c a^2-c+2) (ca^2-c-2)}.
\end{eqnarray}
Then we may conclude that:

\begin{thm}
\label{Th3.8}
With respect to the vector field $f_{(a,0,c)}$ of \eqref{2d},  the global representations of the transition/bifurcation curves in the space of parameters \((a,c)\in \RR\times \RR\backslash \{0\}\) are as follows:\\
\begin{itemize}
\item[I.]
The equilibrium \(E_1\) undergoes a Belyakov transition along the hyperbola: 
\begin{align*}
T^{b0}_F=\left\{(a,c): c=\pm \frac{2}{a^2-1}\right\}. \\
\end{align*}

\item[II.]
The equilibrium \(E_1\) undergoes a  Hopf bifurcation along the lines: 
 \begin{align*}
T^{b0}_{H}=\left\{(a,c): a=\pm 1\right\}.
\end{align*}
The Hopf bifurcation is supercritical at $a=-1$ and subcritical at $a=1$.\\
\end{itemize}
\end{thm}
Schematic bifurcation lines for \(b=0\) have been plotted  in Figure \ref{CASEC}. Illustrative pictures in the phase space have been depicted in Figure  \ref{globalB}  in the case where the eigenvalues of (\ref{JE2_DZb}) at $E_1$ are complex non-real.\\ 
\bigbreak
\begin{proof}
 We are going to concentrate the proof in the case $b=0$ and $c>0$.   Again, the analysis of the case $b=0$ and $c<0$   has a similar treatment (reversing time).\\
\begin{itemize}

\item[I.] 
  The first claim is a direct consequence of    \eqref{eigb0}.\\
\item[II.]

 The Jacobian matrix at \(E_{1}\) has  a pair of purely imaginary eigenvalues 
\(\pm i.\) Let \(a=\pm1+\mu\) where \(\mu \in \RR\) refers to the bifurcation parameter. The eigenvalues, \(\lambda(\mu),\) corresponding to the Jacobian matrix \eqref{JE2_DZb} at \(E_{1}\) are (computations performed with Maple):
 \begin{eqnarray*}
&\lambda(\mu)=\mp c\mu-\frac{1}{2} c {\mu}^{2}\pm \frac{1}{2}\sqrt {4{c}^{2}{\mu}^{2}\pm 4{c}^{2}{\mu}^{3}+{c}^{2}{\mu}^{4}-4}. &
\end{eqnarray*}
For $\mu$ close to zero, we have $4{c}^{2}{\mu}^{2}+4{c}^{2}{\mu}^{3}+{c}^{2}{\mu}^{4}-4<0$, which means that $\lambda(\mu)$ is complex non-real. Furthermore 
\(\frac{d \, {\rm Re}{\lambda(\mu)}}{d\mu}\big|_{\mu=0}=\mp c\neq 0.\)  
 Following \cite[Equations (2) and (3)]{Verduzco}, the first Lyapunov coeficient is $l=-\frac{1}{32}c$ which is negative for $c > 0.$ 
 Hence the bifurcation is subcritical at $a=1$ and supercritical for $a=-1$. 


 For the case $a=-1$,   $E_1$ is an asymptotically stable equilibrium for $\mu < 0$ and  unstable focus  for $\mu > 0$ with an asymptotically stable periodic solution emerging for  $\mu > 0$.  For the case $a=1$,   $E_1$ is an asymptotically stable equilibrium for $\mu > 0$ and  unstable focus  for $\mu < 0$ with an asymptotically stable periodic solution emerging $\mu > 0$.  
This finishes the proof. \end{itemize}
\end{proof}
\begin{rem}
We may observe in Figure   \ref{globalB} that, for $c>0$ (resp. $c<0$), the Hopf bifurcation (with respect to $a$) is supercritical for $a=-1$ giving rise to a stable (resp. unstable) periodic solution which disappears at a subcritical Hopf bifurcation at \(a=1,\) see regions 5-8 of Table \ref{QB}.  
\end{rem}

\subsection{Case C (\(a > 0,\) \(0<b<1\))}

%\begin{lem}
%If \((x^\star, y^\star)\) is an equilibrium of (\ref{2d}), then \(x^\star\) is a zero of the cubic equation \(H(x)=0,\) where
%\begin{eqnarray*}
%H(x) = -\frac{1}{3} c x^3 + c \left(1 - \frac{1}{b}\right) x + \frac{a c}{b}.
%\end{eqnarray*}
%\end{lem}


If \((x^\star, y^\star)\) is an equilibrium of (\ref{2d}) under the conditions  \(a > 0,\) \(0<b<1,\) then:
\begin{eqnarray*}
x^\star - a +by^\star=0 \Leftrightarrow  y^\star = \frac{a - x^\star}{b}.
\end{eqnarray*}

By substituting \(y^\star = \frac{a - x^\star}{b}\) into the first equation of \eqref{2d}, then \(x^\star\) is a root of \(H(x)=0,\) where
\begin{eqnarray*}
H(x) = -\frac{1}{3} c x^3 + c \left(1 - \frac{1}{b}\right) x + \frac{a c}{b}.
\end{eqnarray*}

The discriminant associated with the polynomial \(H(x)\) is given by 
\begin{eqnarray*}
\Delta = \frac{4}{3} c^4 \left(1 - \frac{1}{b}\right)^3 - 3 \frac{c^4 a^2}{b^2}.
\end{eqnarray*}
For \(0 < b < 1\), the discriminant satisfies \(\Delta < 0\).  According to Cardano's formula, this implies that the polynomial $H(x)$ has exactly one real root, denoted by \(x^\star.\)
Then the equilibrium of (\ref{2d}) is explicitly given by 
\begin{eqnarray*}
\left(x^\star,   \frac{a - x^\star}{b}\right)=(x^\star, y^\star)=:E_1.
\end{eqnarray*}
The characteristic equation of the Jacobian matrix evaluated at \((x^*, y^*)\) is 
\begin{eqnarray*}
\lambda^2 + \frac{c^2 {x^*}^2 - c^2 + b}{c} \lambda + b {x^*}^2 - b + 1 = 0.
\end{eqnarray*}
We may then conclude that:\\

\begin{prop}
\label{Prop3.10}
The following assertions hold for the vector field $f_{(a,b,c)}$ of \eqref{2d},  under the conditions \(a > 0,\) and \(0<b<1\): 
\begin{enumerate}
\item 
The equilibrium point $E_1$ is stable if \(\frac{c^2 {x^*}^2 - c^2 + b}{c} > 0.\)
Conversely, it is unstable if \(\frac{c^2 {x^*}^2 - c^2 + b}{c} < 0.\)
\item 
A non-degenerate Hopf bifurcation occurs at  \(c^2 = \frac{b}{1 - {x^*}^2}.\)
 The resulting limit cycle is attracting when \(c > \sqrt{\frac{b}{1 - {x^*}^2}}\) and repelling for \(c < \sqrt{\frac{b}{1 - {x^*}^2}}\).\\
\end{enumerate}
  \end{prop}
Note that $x^\star \neq \pm 1$ (if  $x^\star = \pm 1$, then $b=0$, which is a contradiction). 
 Illustrative pictures in the phase space have been depicted in Figure  \ref{globalC}. As before, we use the notation $\mbox{Tr}(E_{1})$ and  $\mbox{Det}(E_{1})$ the trace and determinant operators of \(Df_{(a,b, c)},\)  evaluated at $E_1$.

\bigbreak
\begin{proof}

Under the condition \(0<b<1,\) one knows that $\det(E_1)>0.$\\
\begin{enumerate}
\item The result follows by noticing that $\mbox{Tr}(E_{1})=- \frac{c^2 {x^*}^2 - c^2 + b}{c} .\) If $\mbox{Tr}(E_{1})<0$, then the  equilibrium $E_1$ is stable.  Conversely, it is unstable if $\mbox{Tr}(E_{1})>0$.\\ 
\item 
 The Jacobian matrix at \(E_{1}\) has  a pair of purely imaginary eigenvalues 
\(\pm i \sqrt{b {x^*}^2 - b + 1}.\) Let \(b=c^2 \left(1 - {x^*}^2\right)+\mu\) where \(\mu\in \RR\) refers to the bifurcation parameter. The eigenvalues, \(\lambda(\mu),\) corresponding to the Jacobian matrix at \(E_{1},\) 

\begin{eqnarray*}
\begin{pmatrix}
c(1-x^*) & c\\
 -\frac{1}{c} & c{x^*}^2-c-\frac{\mu}{c}
\end{pmatrix},
\end{eqnarray*}
are 
 \begin{eqnarray*}
&\lambda(\mu)=\frac{-\mu\pm \sqrt{\left(2c^2 {x^*}^2-2 c^2-\mu-2 c\right) \left(2c^2 {x^*}^2-2 c^2-\mu+2 c\right) }}{2c}.&
\end{eqnarray*}
If 
  $$\min_{c\geq 0}{c\left(\pm1-c+c {x^*}^2\right)}<\mu<\max_{c\geq 0}{ c\left(\pm1-c+c {x^*}^2\right)},$$  
 then the expression under the square root is negative. Hence there exists a pair of complex non real conjugate eigenvalues. 
 The result follows by observing that (computations performed with Maple): \[\frac{d {\rm Re}\, {\lambda(\mu)}}{d\mu}=-\frac{1}{2c}\neq 0.\]
\end{enumerate}
\end{proof}

 \begin{rem}
 The statement of Proposition \ref{Prop3.10} says nothing about the criticality of the Hopf Bifurcation. Analytically, it is very difficult to compute the first Lyapunov exponent of \eqref{2d} at an equilibrium whose explicit expression we do not know. However, numerics of Figure \ref{globalC} suggest that the Hopf bifurcation is supercritical for for $c=   \sqrt{\frac{b}{1 - {x^*}^2}}$ and subcritical for  $c= -  \sqrt{\frac{b}{1 - {x^*}^2}}$.
 \end{rem}


\section{Canards for the singular case \(c \to+\infty\) in Cases A and B}
\label{s:canards}
The goal of this section is the study of the dynamics of \eqref{2d} when $|c| \to +\infty$. 
 Many  results concerning the asymptotic behaviour of the solution of the FN model as $|c|\to +\infty$ are available in the literature -- see \cite{fitzhughbook, 2D, connections}.  Our concern is to match these results with the local bifurcation study performed in Section \ref{sec3}.   We are particularly interested in \textbf{Cases A} and \textbf{B} whose results have been described in Theorems \ref{th:main1} and \ref{Th3.8}.
 By changing the time scale of \eqref{2d}, considering \(\tau \to t/c\) and \(\varepsilon \to 1/c^2,\) we obtain an equivalent version of \eqref{2d} as follows (written with respect to the \emph{slow time} $\tau$):
\begin{equation} 
\label{2d_epsilon}
\left\{ 
\begin{array}{l}
\varepsilon \dot{x}= \displaystyle \left[y-\left(\frac{x^3}{3}-x\right)\right]=: f(x,y, \varepsilon) \\ \\
 \dot{y}=  \displaystyle - (x-a+by)=: g(x,y, \varepsilon)
\end{array}
\right.
\end{equation}
where \(a, b\in \RR\) and \(c\in \RR\backslash\{0\}.\)
For \(0<\varepsilon \ll 1,\) or equivalently  \(|c|\gg  1,\) system \eqref{2d_epsilon} is what we call a \emph{fast-slow system} (see \cite{GLR2025, Kuehn} and references therein).

A fast-slow system is a system of differential equations in which some variables have their derivatives with larger magnitude than others. 
 This leads to a two time-scale system.
 The general approach to this type of system starts by grouping the variables in two disjoint sets: fast variable $x$ and slow variable $y$. By allowing the dynamics to be separated into two distinct phases, slow and fast, we can study each one independently and understand its underlying dynamics.
This separation is introduced in system (\ref{2d_epsilon}) 
via the parameter \(\varepsilon.\) \\

\subsection{The critical manifold and bifurcations}
  We first analyse the singular case $\varepsilon=0.$
We follow the analysis performed in \cite{GLR2025, KS2001a, KS2001b}. The critical manifold associated with \eqref{2d_epsilon} is the set 
\begin{eqnarray}
\mathcal{C}_0=\{(x,y) \in \RR^2: f(x, y, 0)=0\}= \{(x,y) \in \RR^2: y= x^3/3-x\}
\end{eqnarray}
 \bigbreak
 \begin{defn}
  With respect to \eqref{2d_epsilon}  with critical manifold $ \mathcal{C}_0$:
        \begin{enumerate} 
            \item The subset $S\subset \mathcal{C}_0$ is said to be  \emph{normally hyperbolic} if for all $p=(x,y)\in{S}$, we have:
                                \begin{equation*}
              \frac{\partial f}{\partial x}\left(p,0\right) \text{ has no eigenvalues with zero real part.}
            \end{equation*}
\medskip

 \item A normally hyperbolic set $S$ is said to be  \emph{attracting} (resp. \emph{repelling}) if, for all $p\in{S}$, all eigenvalues of $  \frac{\partial f}{\partial x}\left(p,0\right)$ have negative (resp. positive) real part, respectively. %It is of \textbf{saddle type} if $\left(\mathsf{D}_xf\right)\left(\p,0\right)$ has eigenvalues with   both positive and negative real part.
        \end{enumerate}
 \end{defn}
  \bigbreak
  \begin{defn} \label{def_fold}
         With respect to \eqref{2d_epsilon} with critical manifold $\mathcal{C}_0$, the point $p\in \mathcal{C}_0$ is said to be a  \emph{fold point} if:
        \begin{equation*}
             \frac{\partial f}{\partial x}\left(p,0\right)=0\,,\quad  \frac{\partial^2 f}{\partial x^2}\left(p,0\right)\neq0 \quad\text{ and }\quad  \frac{\partial f}{\partial y}\left(p,0\right)\neq0.
        \end{equation*}
        If $g\left(p,0\right)\neq0$, the fold point is called  \emph{regular}.
    \end{defn}
  \bigbreak
Coming back to system \eqref{2d_epsilon}, we have $f\left(x,y,0\right)= y-x^3/3+x$ and, for $p=(x,y)\in \mathcal{C}_0$, one has: $$\frac{\partial f}{\partial x}\left(p,0\right)= x^2-1\neq0\qquad\text{ if }\,\, x\neq\pm 1.$$
        Therefore, if $b=3/2$,  the equilibria $E_2=(-1, 2/3)$ and $E_3=(1,-2/3)$   are fold points (according to the Definition  \ref{def_fold})  since:
        $$
        \frac{\partial f}{\partial x}(E_{2,3},0)=0, \quad \frac{\partial^2 f}{\partial^2 x}(E_{2,3},0)\neq 0\quad \text{and}\quad \frac{\partial f}{\partial y}(E_{2,3},0)\neq 0
        $$
                   and $S_0=\mathcal{C}_0\setminus\left\{E_2, E_3\right\}$ is normally hyperbolic.
        We may split $S_0$ into three disjoint open subsets:
        %
\begin{equation*}
\begin{aligned}
                \mathcal{C}_{0\text{L}}&= \mathcal{C}_0 \cap {\textstyle \left\{\left(x,y\right)\in\RR^2: x<-1 \right\}}, \\
                \mathcal{C}_{0\text{M}}&= \mathcal{C}_0 \cap {\textstyle \left\{\left(x,y\right)\in\RR^2:-1<x<1\right\}}\quad \text{and} \\
                \mathcal{C}_{0\text{R}}&= \mathcal{C}_0 \cap {\textstyle \left\{\left(x,y\right)\in\RR^2: x>1 \right\}}. \\
            \end{aligned}
        \end{equation*}
        %
        Therefore, we get 
        \begin{equation}
           \label{def: S0}
    S_0=\mathcal{C}_{0\text{L}}\cup\mathcal{C}_{0\text{M}}\cup\mathcal{C}_{0\text{R}},    
        \end{equation}
        %
        where $\mathcal{C}_{0\text{L}}$ and $\mathcal{C}_{0\text{R}}$ are \emph{repelling} subsets and $\mathcal{C}_{0\text{M}}$ is \emph{attracting}. This means that in the fast flow, trajectories of \eqref{2d_epsilon} move backwards either to $\mathcal{C}_{0\text{L}}$ or $\mathcal{C}_{0\text{R}}$ and towards to $\mathcal{C}_{0\text{M}}$ -- see Figure \ref{slow-fast1}.\\

