 Yet in the singular case ($\varepsilon=0$), depending on the values of $a,b\in \RR$, there exists at least one and at most three equilibria, as result of the
intersection of the cubic curve, \(f (x, y, 0) = 0,\) with the line defined by $x-a+by=0$ ($\Leftrightarrow \dot{y} = 0).$ Moreover, when the
system has three equilibria only one of the following scenarios may occur (cf.  \cite{GLR2025}): \\

\begin{description}
\item[Case 1]  either all three equilibria belong to $\mathcal{C}_{0\text{M}}$ 
or else 
\item[Case 2] they are each one in a distinct region, $\mathcal{C}_{0\text{L}},$ $\mathcal{C}_{0\text{M}}$ and $\mathcal{C}_{0\text{R}}$. \\
\end{description}
The independence  of the time scales when \(\varepsilon=0\) makes the system simpler to understand.
 Fenichel's Theorem \cite{Fenichel} says that, near the normally hyperbolic part of  $\mathcal{C}_{0}$, when \(0<\varepsilon\ll1,\) the dynamics of the perturbed system is similar to that of the singular system, with a deviation of \(\mathcal{O}\left(\varepsilon\right).\)  The smaller the \(\varepsilon,\) the \emph{more similar} the system trajectories are to those described in the singular system ($\varepsilon=0$). Fenichel's Theorem guarantees that for \(0<\varepsilon\ll1,\) there exists a set \(S_\varepsilon\), $C^1$--close to $S_0$ (in the Haussdorf topology), that exhibits the {\emph same} behaviour as $S_0$.  
 \begin{defn}
 The set $S_\varepsilon$ is referred to as the \emph{slow manifold} of system \eqref{2d_epsilon}.
 \end{defn}

    When the system's equilibrium is also a fold point, a supercritical (with respect to $b$) Hopf bifurcation occurs, giving rise to a periodic solution. In this section, the \emph{canard phenomenon} described in \cite{KS2001a, KS2001b} bridges the local periodic solution from the Hopf bifurcation to the global limit cycle, as we proceed to explain.
\begin{defn}
           A trajectory segment of a fast-slow system  \eqref{2d_epsilon} is a   \emph{{canard}} if it stays within $\mathcal{O}\left(\varepsilon\right)$ distance to a repelling branch of a slow manifold for a time that is $\mathcal{O}\left(1\right)$ on the slow time scale $\tau = t\varepsilon$.           
\end{defn}

\emph{Canards} are related to equilibria of    \eqref{2d_epsilon} that occur at fold points of the slow manifold. The next definitions deal with the general equation parametrised by $\lambda\in\RR$:
\begin{equation}
\label{general1} 
    \left\{ 
\begin{array}{l}
\varepsilon \dot{x}=   f(x,y, \lambda, \varepsilon) \\  \\
 \,\dot{y}=  g(x,y, \lambda, \varepsilon)
\end{array}
\right.
\end{equation}

   We now introduce the definition of \emph{singular fold point}, which  differs from that of a fold point -- it   is required to coincide with an equilibrium point of  \eqref{2d_epsilon}:
    \begin{defn}\label{def:fold_point}
    With respect to \eqref{general1}, let $p=\left(x,y\right)$ be a fold point. The point $p$ is called a \emph{singular fold} if:
        \begin{equation}
            \label{dobrasingular}
            \begin{aligned}
                &f\left(p,\lambda,0\right)=0, &&\frac{\partial f}{\partial x}\left(p,\lambda,0\right)=0,\\
                &\frac{\partial ^2 f}{\partial x^2}\left(p,\lambda,0\right)\neq0, && \frac{\partial f}{\partial y}\left(p,\lambda,0\right)\neq0 \quad \text{and} \quad g\left(p,\lambda,0\right)=0.
            \end{aligned}
        \end{equation}     
    \end{defn}

    \begin{defn}\label{def:regular_fold}
        A singular fold point $p$ is said to be \emph{regular} if:
        \begin{equation}
            \frac{\partial g}{\partial x}\left(p,\lambda,0\right)\neq0 \quad \text{ and } \quad \frac{\partial g}{\partial \lambda}\left(p,\lambda,0\right)\neq0.
        \end{equation}
    \end{defn}
    %

    The behaviour around a regular singular fold point is described in the next theorem. The existence of \emph{canards} is coupled with the existence of a Hopf bifurcation, which in such systems is referred to as a \emph{singular Hopf bifurcation}.          
       %   \emph{Canards} are related to equilibria of the slow equation that occur at fold points of the slow manifold. 
% We remind the reader that, for \(b=3/2,\) the fold points $E_2$ and $ E_3$ are equilibria of \eqref{2d}. For the sake of completeness, we recall the following result:

 \begin{thm}[\cite{KS2001a, KS2001b}, adapted]
   \label{th:canard}
        Consider a  fast-slow system of the form \eqref{general1} where $\left(x,y\right)=\left(0,0\right)$ is a regular singular fold point for $\lambda=0$, and that may be written in the following form:
        %
        \begin{equation}\label{eq:nformHopfsing}
            \begin{aligned}
                &\dot{x}=-y\,l_1\left(x,y,\lambda,\varepsilon\right)+x^2\,l_2\left(x,y,\lambda,\varepsilon\right) + \varepsilon\,l_3\left(x,y,\lambda,\varepsilon\right)\\
                &\dot{y}=\varepsilon \left(\pm x\,l_4\left(x,y,\lambda,\varepsilon\right)-\lambda \,l_5\left(x,y,\lambda,\varepsilon\right)+y\,l_6\left(x,y,\lambda,\varepsilon\right)\right)
            \end{aligned}
        \end{equation}
        where
        $$
      l_3\left(x,y,\lambda,\varepsilon\right)= \mathcal{O} \left(x,y,\lambda,\varepsilon\right) \quad \text{and}\quad l_j\left(x,y,\lambda,\varepsilon\right)= 1+\mathcal{O} \left(x,y,\lambda,\varepsilon\right), 
        $$
        for $j\in\{1,2,4,5,6\}$.

        Assume that, for $\varepsilon=0$, there is a slow trajectory connecting the repelling and attracting regions of the critical manifold $\mathcal{C}_0$.
        Then, there exist $\varepsilon_0>0$ and $\lambda_0>0$ such that for $0<\varepsilon<\varepsilon_0$ and $|\lambda|<\lambda_0$, the system has an equilibrium point $p\in\RR^2$ near the origin where $p\to\left(0,0\right)$ as $\left(\lambda,\varepsilon\right)\to\left(0,0\right)$.
            Then, there exists a smooth function $\lambda_c:\left[0,\varepsilon_0\right]\to\RR$ that associates each value of $\varepsilon\in \left(0,\varepsilon_0\right]$ to a value $\lambda$ that gives rise to a family of \emph{canards}, asymptotically defined by: 
        %
        \begin{equation*}
            \lambda_c\left(\sqrt{\varepsilon}\right)=-\left(B + A\right)\varepsilon+\mathcal{O}\left(\varepsilon^{3/2}\right),  
        \end{equation*}

        and there exists a continuous function $\lambda_ {H}:\left[0,\varepsilon_0\right]\to\RR$ that associates each value of $\varepsilon\in \left[0,\varepsilon_0\right]$ to a value $\lambda$ of Hopf bifurcations in the system, asymptotically defined by: 
        %
        \begin{equation*}
            \lambda_ {H}\left(\sqrt{\varepsilon}\right)=-B\varepsilon+\mathcal{O}\left(\varepsilon^{3/2}\right),    
        \end{equation*}
        %
        where
        \begin{equation*}
            A=\dfrac{-\dfrac{\partial l_1}{\partial x}+3\dfrac{\partial l_2}{\partial x}-2\dfrac{\partial l_4}{\partial x}+2l_6}{8}\qquad B=\dfrac{\dfrac{\partial l_3}{\partial x}+l_6}{2},    
        \end{equation*}
        %
        where the functions $l_i,\,i=1,\ldots,6$ and their partial derivatives are evaluated at the point $\left(x,y,\lambda,\varepsilon\right)=\left(0,0,0,0\right)$.          The Hopf bifurcation is nondegenerate when $A \neq 0$, it is supercritical if $A < 0$ and subcritical if $A > 0$.
       \end{thm}

\subsection{Case A \((a=0)\)}    

  The curves \(T_F^{2,3}\), \(T_H^{2,3}\), $DH$ and SNL, introduced in Theorem~\ref{th:main1} and Remark~\ref{rem:SNL}, can be  parameterised by \(c \in [1, +\infty)\). From now on, we restrict our attention to the portions of these curves lying within the region defined by \(b, c \geq 1\) -- see Figure \ref{summary1}.
