\section{Calculation of fermion bilinear operators}

A fermion bilinear operator is generally decomposed as
\begin{equation}
  \psi_\alpha^\dag(x)\psi_\beta(y)
  =:\psi_\alpha^\dag(x)\psi_\beta(y):
  +\delta [ \psi_\alpha^\dag(x)\psi_\beta(y) ].
\end{equation}
The first term is regular and the second term is singular in $a\to 0$.
Below, we evaluate the singular components in Eqs.~\eqref{eq:ANC} and \eqref{eq:AC}.

For clarity, we first consider a finite lattice volume $V=Na$ with a periodic boundary condition, and take the infinite-volume limit $N\to \infty$ at the end of the calculation.
We adopt the gamma matrix convention $\gamma^0=\sigma_1$, $\gamma^1=-\ri\sigma_3$, and $\gamma^5=\sigma_2$.
Since the link variable is expanded as $U(x)=\exp\{\ri aeA(x)\} =1+O(a)$, we can approximate $U(x)=1$ for leading-order evaluation.
The free Wilson-Dirac equation in momentum space,
\begin{equation}
    \begin{pmatrix}
        -a\varepsilon(p) & 1-e^{\ri ap}\\
        1-e^{-\ri ap} & -a\varepsilon(p)
    \end{pmatrix}
    \begin{pmatrix}
        \psi_1(p)\\
        \psi_2(p)
    \end{pmatrix}
    =0,
\end{equation}
has the energy eigenvalues
\begin{equation}
\varepsilon(p) = \pm \frac{2}{a} \sin\frac{ap}{2},
\end{equation}
and the eigenvectors
\begin{equation}
  \tilde{u}_R(p)=\frac{1}{\sqrt{2}}\begin{pmatrix}
        1\\
        \ri e^{-\ri\frac{ap}{2}}
    \end{pmatrix},\quad
    \tilde{u}_L(p)=\frac{1}{\sqrt{2}}\begin{pmatrix}
      1\\
      -\ri e^{-\ri\frac{ap}{2}}
  \end{pmatrix}.
\end{equation}
The momentum is quantized as $p=2\pi n/V$ with $n=0,\pm 1,\pm 2, \pm (N-1)/2$ due to the periodic boundary condition. 
In this appendix, we assume that $N$ is odd for simplicity.
(Note that the notation is different from Eqs.~\eqref{eqsinglee} and \eqref{eqsingleq}, where $-2\pi\le p<2\pi$, whereas $-\pi<p<\pi$ here.)

The fermion field operator $\psi(x)$ is expanded as
\begin{equation}
\psi(x) = \frac{1}{\sqrt{V}}\sum_{p}\qty(
  \tilde{a}_R(p)\tilde{u}_R(p)e^{ \ri px}+\tilde{a}_L(p)\tilde{u}_L(p)e^{\ri px}
),
\label{eq:wavefunction}
\end{equation}
where $\tilde{a}^\dag_{R/L}(p)$ and $\tilde{a}_{R/L}(p)$ are creation and annihilation operators satisfying the anticommutation relation,
\begin{equation}
    \{\tilde{a}_R(p),\tilde{a}^\dag_R(p')\}=\delta_{pp'},\quad \{\tilde{a}_L(p),\tilde{a}^\dag_L(p')\}=\delta_{pp'},
\end{equation}
and others are zero.
From these commutation relations, we recover Eq.~\eqref{eqacr}.
Each component of $\psi(x)$ is expressed as
\begin{equation}
  \begin{split}
    \psi_1(x)&=\frac{1}{\sqrt{V}}\sum_p\frac{1}{\sqrt{2}}\qty(\tilde{a}_R(p)+\tilde{a}_L(p))e^{\ri px},\\
    \psi_2(x)&=\frac{1}{\sqrt{V}}\sum_p\frac{1}{\sqrt{2}}\qty( \tilde{a}_R(p)- \tilde{a}_L(p))\ri e^{-\ri\frac{ap}{2}}e^{\ri px}.
  \end{split}
\end{equation}
We note that this convention is different from the relativistic one.
We use the nonrelativistic normalization for the wave function, i.e.,
$\tilde{u}^\dag(p)\tilde{u}(p)=1$, while the relativistic normalization for the wave function $u(p)$ is $u^\dag(p)u(p)=2|a\varepsilon(p)|$.
We further decompose into the positive and negative energy contributions,
\begin{equation}
    \tilde{a}_{R/L}(p)=a_{R/L}(p)+b^\dag_{R/L}(-p)
\end{equation}
with
\begin{equation}\label{eq:decomposition_a}
  \begin{split}
    a_R(p) &= \theta(p)\tilde{a}_R(p),\quad a_L(p) = \theta(-p)\tilde{a}_L(p),\\
    b^\dag_R(-p) &= \theta(-p)\tilde{a}_R(p),\quad b^\dag_L(p) = \theta(p)\tilde{a}_L(p),    
  \end{split}
\end{equation}
where $\theta(p)$ is the step function,
\begin{equation}
    \theta(p)=\begin{cases}
        1 & p\geq0\\
        0 & p<0
    \end{cases}.
    \label{eq:stepfunction}
\end{equation}
The ground state $\ket{\Omega}$ satisfies $a_{R/L}(p)\ket{\Omega}=0$ and $b_{R/L}(p)\ket{\Omega}=0$ for all $p$.

In Eq.~\eqref{eq:ANC}, there are four terms to be evaluated.
The first term is explicitly computed as
\begin{equation}
  \begin{split}
    \ri \psi^\dag(x)\gamma^1\psi(x) 
    &=\psi^\dag_1(x)\psi_1(x)-\psi^\dag_2(x)\psi_2(x) \\
    &=\frac{1}{V}\sum_{p,p'}
    (\tilde{a}^\dag_R(p')\tilde{a}_L(p)+\tilde{a}^\dag_L(p')\tilde{a}_R(p)) e^{\ri (p-p')x} \\
    &=:\psi^\dag_1(x)\psi_1(x):-:\psi^\dag_2(x)\psi_2(x): = :\ri \psi^\dag(x)\gamma^1\psi(x) : ,
  \end{split}
\end{equation}
and thus does not have a singular contribution.
The other terms are also regular,
\begin{align}
    \ri \psi^\dag(x+a)\gamma^1\psi(x+a) &= :\ri \psi^\dag(x+a)\gamma^1\psi(x+a): \, ,\\
    \ri \psi^\dag(x+a)\gamma^1\psi(x) &= :\ri \psi^\dag(x+a)\gamma^1\psi(x): \, ,\\
    \ri \psi^\dag(x)\gamma^1\psi(x+a) &= :\ri \psi^\dag(x)\gamma^1\psi(x+a): .
\end{align}
Summarizing these results and using $U(x) =1+O(a)$, we obtain
\begin{equation}
\begin{split}
    &-\ri ( \nabla \psi(x) )^\dag \gamma^1 \nabla \psi(x) \\
    &= - \frac{\ri}{a^2} :\{ \psi^\dag(x)\gamma^1\psi(x)  + \psi^\dag(x+a)\gamma^1\psi(x+a)
    - \psi^\dag(x) \gamma^1 \psi(x+a) - \psi^\dag(x+a) \gamma^1 \psi(x) \}: + O(a) \\
    &= -\ri : ( \partial_x \psi(x) )^\dag \gamma^1 \partial_x \psi(x) : + O(a) .
\end{split}
\end{equation}
Therefore, the right-hand side of Eq.~\eqref{eq:ANC} is $O(a)$ and goes to zero in the continuum limit.

For Eq.~\eqref{eq:AC}, we need to evaluate
\begin{equation}
\begin{split}
    -\ri \psi^\dag(x+a)\gamma^5(1+\ri\gamma^1)\psi(x) 
    &=2\psi_2^\dag(x+a)\psi_1(x) \\
    &=\frac{1}{V}\sum_{p,p'} -\ri \Bigl(
\tilde{a}^\dag_R(p)\tilde{a}_R(p')+\tilde{a}^\dag_R(p)\tilde{a}_L(p')
- \tilde{a}^\dag_L(p)\tilde{a}_R(p')- \tilde{a}^\dag_L(p)\tilde{a}_L(p') \Bigr) e^{-\ri\frac{ap}{2}} e^{\ri (p'-p)x},
\end{split}
\end{equation}
and its hermitian conjugate.
Using
\begin{equation}
  \begin{split}
    \tilde{a}^\dag_{R}(p)\tilde{a}_R(p')
    &=a^\dag_{R}(p)a_{R}(p')+a^\dag_{R}(p)b^\dag_{R}(-p')  +b_{R}(-p)a_{R}(p')+b_{R}(-p)b^\dag_{R}(-p')\\
    &=:\tilde{a}^\dag_{R}(p)\tilde{a}_R(p'): + \{b_{R}(-p),b^\dag_{R}(-p')\}\\
    &=:\tilde{a}^\dag_{R}(p)\tilde{a}_R(p'): +\theta(-p)\delta_{p,p'},
  \end{split}
\end{equation}
and
\begin{equation}
  \begin{split}
    \tilde{a}^\dag_{L}(p)\tilde{a}_L(p')
    &=a^\dag_{L}(p)a_{L}(p')+a^\dag_{L}(p)b^\dag_{L}(-p') +b_{L}(-p)a_{L}(p')+b_{L}(-p)b^\dag_{L}(-p')\\
    &=:\tilde{a}^\dag_{L}(p)\tilde{a}_L(p'): + \{b_{L}(-p),b^\dag_{L}(-p')\}\\
    &=:\tilde{a}^\dag_{L}(p)\tilde{a}_L(p'): +\theta(p)\delta_{p,p'},
  \end{split}
\end{equation}
we find the divergent contribution
\begin{equation}
  \begin{split}
     \delta [ -\ri \psi^\dag(x+a)\gamma^5(1+\ri\gamma^1)\psi(x) ]
    &=\frac{1}{V}\sum_{p,p'} -\ri (  \theta(-p)\delta_{p,p'}- \theta(p)\delta_{p,p'} ) e^{-\ri\frac{ap}{2}} e^{\ri (p'-p)x}\\
    &=\frac{2}{V}\sum_{p>0}\sin\frac{ap}{2} \\
    &=\frac{2}{a} \frac{1}{2N\tan\frac{\pi}{2N}}.
  \end{split}
\end{equation}
The same is true for the hermitian conjugate.
Taking the limit of $N \to \infty$, we finally obtain 
\begin{equation}
    \delta [ -\ri \psi^\dag(x+a)\gamma^5(1+\ri\gamma^1)\psi(x) ] = \delta [ \ri \psi^\dag(x)\gamma^5(1-\ri\gamma^1)\psi(x+a) ] = \frac{2}{a\pi} .
\end{equation}


