These imply that there is a direct summand decomposition of the $\Sigma_4$-modules:
$$ \underline{\pmb{Q}^{4}_{n_s}} = \Sigma_4(a_{s,\,1}) \bigoplus \Sigma_4(a_{s,\,13}) \bigoplus \Sigma_4(a_{s,\,25}).$$
In the following, it will play a key role in the proof of the theorem.

\begin{lema}\label{bd1}
With the notations above,
\begin{itemize}
\item[i)]  $\Sigma_4(a_{s,\,1})^{\Sigma_4} = \langle [q_{s,\,1}] \rangle,$ with $q_{s,\,1} = \sum_{1\leq j\leq 12}a_{s,\,j};$
\item[ii)]  $\Sigma_4(a_{s,\,13})^{\Sigma_4} = \langle [q_{s,\,2}] \rangle,$ with $q_{s,\,1} = \sum_{13\leq j\leq 24}a_{s,\,j};$
\item[iii)]  $\Sigma_4(a_{s,\,25})^{\Sigma_4} = \langle [q_{s,\,3}] \rangle,$ with $q_{s,\,1} = \sum_{25\leq j\leq 28}a_{s,\,j}.$
\end{itemize}
\end{lema}

\begin{proof}

We first prove Part $i).$ Since the set $\{[a_{s,\,j}]:\, 1\leq j\leq 12 \}$ is a basis of $\Sigma_4(a_{s,\,1}),$ if $[f]\in \Sigma_4(a_{s,\,1})^{\Sigma_4},$ then 
\begin{equation}\label{dt1}
\begin{array}{ll}
f &\equiv \big(\gamma_1a_{s,\,1} + \gamma_2a_{s,\,2} + \gamma_3a_{s,\,3} + \gamma_4a_{s,\,4} + \gamma_5a_{s,\,5} + \gamma_6a_{s,\,6}\\
&\quad \gamma_7a_{s,\,7} + \gamma_8a_{s,\,8} + \gamma_9a_{s,\,9} + \gamma_{10}a_{s,\,10} + \gamma_{11}a_{s,\,11} + \gamma_{12}a_{s,\,12}\big),
\end{array}
\end{equation} in which $\gamma_j\in k$ for every $j.$ Acting the homomorphisms $\sigma_i: P_4\longrightarrow P_4,\, i = 1, 2, 3,$ on both sides of \eqref{dt1}, we get
\begin{equation}\label{dt2}
\begin{array}{ll}
\sigma_1(f) &\equiv \big(\gamma_4a_{s,\,1} +  \gamma_5a_{s,\,2} +  \gamma_{10}a_{s,\,3} +  \gamma_{1}a_{s,\,4} +  \gamma_{2}a_{s,\,5} +  \gamma_{6}a_{s,\,6} +  \gamma_{7}a_{s,\,7}\\
\medskip
&\quad +  \gamma_{11}a_{s,\,8} +  \gamma_{12}a_{s,\,9} +  \gamma_{3}a_{s,\,10} +  \gamma_{8}a_{s,\,11} +  \gamma_{9}a_{s,\,12}\big);\\
\sigma_2(f) &\equiv \big(\gamma_{1}a_{s,\,1} + \gamma_{3}a_{s,\,2} + \gamma_{2}a_{s,\,3} + \gamma_{6}a_{s,\,4} + \gamma_{8}a_{s,\,5} + \gamma_{4}a_{s,\,6} + \gamma_{9}a_{s,\,7}\\
\medskip
&\quad + \gamma_{5}a_{s,\,8} + \gamma_{7}a_{s,\,9} + \gamma_{11}a_{s,\,10} + \gamma_{10}a_{s,\,11} + \gamma_{12}a_{s,\,12}\big).\\
\sigma_3(f) &\equiv \big(\gamma_{2}a_{s,\,1} + \gamma_{1}a_{s,\,2} + \gamma_{3}a_{s,\,3} + \gamma_{5}a_{s,\,4} + \gamma_{4}a_{s,\,5} + \gamma_{7}a_{s,\,6} + \gamma_{6}a_{s,\,7}\\
&\quad + \gamma_{9}a_{s,\,8} + \gamma_{8}a_{s,\,9} + \gamma_{10}a_{s,\,10} + \gamma_{12}a_{s,\,11} + \gamma_{11}a_{s,\,12}\big).
\end{array}
\end{equation}

Since $[f]\in \Sigma_4(a_{s,\,1})^{\Sigma_4},$ $\sigma_i(f)\equiv f$ for $1\leq i\leq 3.$ Combining this and the equalities \eqref{dt1} and \eqref{dt2}, we find that
$$ \begin{array}{ll}
\medskip
(\gamma_1 + \gamma_4)a_{s,\,1} + (\gamma_2 + \gamma_5)a_{s,\,2} + (\gamma_3 + \gamma_{10})a_{s,\,3} + (\gamma_8 + \gamma_{11})a_{s,\,8} + (\gamma_9 + \gamma_{12})a_{s,\,9}& \equiv 0,\\
\medskip
(\gamma_2 + \gamma_3)a_{s,\,2} + (\gamma_4 + \gamma_6)a_{s,\,4} + (\gamma_5 + \gamma_{8})a_{s,\,5} + (\gamma_7 + \gamma_{9})a_{s,\,7} + (\gamma_{10} + \gamma_{11})a_{s,\,10}& \equiv 0,\\
(\gamma_1 + \gamma_2)a_{s,\,1} + (\gamma_4 + \gamma_5)a_{s,\,4} + (\gamma_6 + \gamma_{7})a_{s,\,6} + (\gamma_8 + \gamma_{9})a_{s,\,8} + (\gamma_{11} + \gamma_{12})a_{s,\,11}& \equiv 0.
\end{array}$$
This implies that $\gamma_1  = \gamma_j$ for all $j,\, 2\leq j\leq 12.$ By a similar computation, we also get Part $iii).$

We now prove Part $ii).$ We see that a basis for $\Sigma_4(a_{s,\,13})$ is the set $\{[a_{s,\,j}]:\, 13\leq j\leq 24\}.$ Assume that $[g]\in \Sigma_4(a_{s,\,13})^{\Sigma_4},$ then we have
\begin{equation}\label{dt3}
g\equiv \sum_{13\leq j\leq 24}\beta_ja_{s,\,j},
\end{equation} with $\beta_j\in k,\, j = 13, \ldots, 24. $ Acting the homomorphisms $\sigma_i: P_4\longrightarrow P_4,\, 1\leq i\leq 3,$ on both sides of \eqref{dt3}, we get
\begin{equation}\label{dt4}
\begin{array}{ll}
\sigma_1(g) &\equiv \big(\beta_{16}a_{s,\,13} + \beta_{19}a_{s,\,14} +  \beta_{20}a_{s,\,15} +  \beta_{13}a_{s,\,16} +  \beta_{21}a_{s,\,17} \\
&\quad +  \beta_{22}a_{s,\,18} +  \beta_{14}a_{s,\,19} +  \beta_{15}a_{s,\,20} +  \beta_{17}a_{s,\,21}+  \beta_{18}a_{s,\,22}\\
\medskip
&\quad  +  \beta_{23}x_1^{3.2^s-1}x_2^{2^{s+1}-1}x_4^{2^s-1} +  \beta_{24}x_1^{3.2^s-1}x_2^{2^{s+1}-1}x_3^{2^s-1}\big);\\
\sigma_2(g) &\equiv \big( \beta_{14}a_{s,\,13} +  \beta_{13}a_{s,\,14} +  \beta_{17}a_{s,\,16} +  \beta_{16}a_{s,\,17} +  \beta_{21}a_{s,\,19}  \\
&\quad  +  \beta_{23}a_{s,\,20}+  \beta_{19}a_{s,\,21}+  \beta_{24}a_{s,\,22} +  \beta_{20}a_{s,\,23} +  \beta_{22}a_{s,\,24}\\
\medskip
&\quad  +  \beta_{15}x_2^{3.2^s-1}x_3^{2^{s+1}-1}x_4^{2^s-1} +   \beta_{18}x_1^{2^s-1}x_2^{3.2^s-1}x_3^{2^{s+1}-1}\big);\\
\sigma_3(g) &\equiv \big( \beta_{15}a_{s,\,14} +  \beta_{14}a_{s,\,15} +  \beta_{18}a_{s,\,17} +  \beta_{17}a_{s,\,18} +  \beta_{20}a_{s,\,19} \\
&\quad +  \beta_{19}a_{s,\,20}+   \beta_{22}a_{s,\,21}  +  \beta_{21}a_{s,\,22} +  \beta_{24}a_{s,\,23} +  \beta_{23}a_{s,\,24}\\
&\quad  +  \beta_{13}x_2^{2^s-1}x_3^{3.2^s-1}x_4^{2^{s+1}-1}+  \beta_{16}x_1^{2^s-1}x_3^{3.2^s-1}x_4^{2^{s+1}-1} \big).
\end{array}
\end{equation}
Using Cartan's formula and Theorem \ref{dlSi}, we have
\begin{equation}\label{dt5}
 \begin{array}{ll}
\medskip
x_1^{3.2^s-1}x_2^{2^{s+1}-1}x_4^{2^s-1} &= Sq^{2}(x_1^{3.2^s-3}x_2^{2^{s+1}-1}x_4^{2^s-1}) + a_{s,\,23} \mod (\overline{A}(P_4)_{n_s});\\
\medskip
 x_1^{3.2^s-1}x_2^{2^{s+1}-1}x_3^{2^s-1} &= Sq^{2}(x_1^{3.2^s-3}x_2^{2^{s+1}-1}x_3^{2^s-1} ) + a_{s,\,24} \mod (\overline{A}(P_4)_{n_s});\\
\medskip
x_2^{3.2^s-1}x_3^{2^{s+1}-1}x_4^{2^s-1} &= Sq^{2}(x_2^{3.2^s-3}x_3^{2^{s+1}-1}x_4^{2^s-1}) + a_{s,\,15} \mod (\overline{A}(P_4)_{n_s});\\
\medskip
x_1^{2^s-1}x_2^{3.2^s-1}x_3^{2^{s+1}-1} &= Sq^{2}(x_1^{2^s-1}x_2^{3.2^s-3}x_3^{2^{s+1}-1}) + a_{s,\,18} \mod (\overline{A}(P_4)_{n_s});\\
\medskip
x_2^{2^s-1}x_3^{3.2^s-1}x_4^{2^{s+1}-1} &= Sq^{2}(x_2^{2^s-1}x_3^{3.2^s-3}x_4^{2^{s+1}-1} ) + a_{s,\,13} \mod (\overline{A}(P_4)_{n_s});\\
\medskip
x_1^{2^s-1}x_3^{3.2^s-1}x_4^{2^{s+1}-1} &= Sq^{2}(x_1^{2^s-1}x_3^{3.2^s-3}x_4^{2^{s+1}-1}) + a_{s,\,16} \mod (\overline{A}(P_4)_{n_s}).
\end{array}
\end{equation}
Then, using the equalities \eqref{dt3}, \eqref{dt4} and \eqref{dt5} and the relations $\sigma_i(g)\equiv g,$ for $i\in \{1, 2, 3\},$ deduce that $\beta_{13} = \beta_j$ for all $j,\, 14\leq j\leq 24.$ The lemma is completely proved.
\end{proof}

