We now consider the following cases.

\underline{\it Case $s = 1$}. We have a direct summand decomposition of the $\Sigma_4$-modules:
$$ \overline{\pmb{Q}^{4}_{n_1}} = \Sigma_4(a_{1,\,29}, a_{1,\,32}) \bigoplus \Sigma_4(a_{1,\,35}),$$
where $ \Sigma_4(a_{1,\,29}; a_{1,\,32}) = \langle \{[a_{1,\,j}]:\, j = 29, 30, \ldots, 34, 41, 42, \ldots, 46\} \rangle,$ and 
$$\Sigma_4(a_{1,\,35}) = \langle \{[a_{1,\,j}]:\, 35\leq j\leq 40\} \rangle.$$

\begin{lema}\label{bd2}
The following statements are true:
\begin{itemize}
\item[i)]  $\Sigma_4(a_{1,\,29}; a_{1,\,32})^{\Sigma_4} = \langle [q_{1,\,4}] \rangle,$ with $q_{1,\,4} = \sum_{29\leq j\leq 31}a_{1,\,j} + \sum_{44\leq j\leq 46}a_{1,\,j};$
\item[ii)]  $\Sigma_4(a_{1,\,35})^{\Sigma_4} = 0.$
\end{itemize}
\end{lema}

Combining Lemmas \ref{bd1} and \ref{bd2} gives

\begin{hq}\label{hq1}
The space of $\Sigma_4$-invariants $(\pmb{Q}^{4}_{n_1})^{\Sigma_4}$ is generated by the classes $[q_{1,\,t}]$ for all $t,\, 1\leq t\leq 4.$
\end{hq}

\begin{proof}[{\it Proof of Lemma \ref{bd2}}]

The proof of $ii)$ is straightforward. We prove $i)$ in detail. Suppose that $[g]\in \Sigma_4(a_{1,\,29}; a_{1,\,32})^{\Sigma_4}.$ Then, we have 
\begin{equation}\label{dt6}
g\equiv \big(\sum_{29\leq j\leq 34}\gamma_ja_{1,\,j} + \sum_{41\leq j\leq 46}\gamma_ja_{1,\,j}\big),
\end{equation}
with $\gamma_j\in k.$ Acting the homomorphisms $\sigma_i: P_4\longrightarrow P_4,\, 1\leq i\leq 3,$ on both sides of \eqref{dt6}, we get
\begin{equation}\label{dt7}
\begin{array}{ll}
\sigma_1(g)&\equiv \big(\gamma_{29}a_{1,\,29} + \gamma_{30}a_{1,\,30} + \gamma_{32}a_{1,\,32} + \gamma_{41}a_{1,\,41} + \gamma_{44}a_{1,\,42}\\
    &\quad +\gamma_{45}a_{1,\,43}  + \gamma_{42}a_{1,\,44} + \gamma_{43}a_{1,\,45} + \gamma_{31}x_1^{6}x_2x_3x_4\\   
\medskip
&\quad + \gamma_{33}x_1^{2}x_2x_3x_4^{5} + \gamma_{34}x_1^{2}x_2x_3^{5}x_4 + \gamma_{46}x_1^{4}x_2^{3}x_3x_4\big)\\
\sigma_2(g)&\equiv \big(\gamma_{29}a_{1,\,29} + \gamma_{31}a_{1,\,30} + \gamma_{30}a_{1,\,31} + \gamma_{33}a_{1,\,32} + \gamma_{42}a_{1,\,41}+\gamma_{41}a_{1,\,42} \\
\medskip
&\quad  + \gamma_{44}a_{1,\,44}+ \gamma_{46}a_{1,\,45} + \gamma_{45}a_{1,\,46} + \gamma_{34}x_1x_2^{5}x_3^{2}x_4 + \gamma_{43}x_1x_2^{4}x_3^{3}x_4\big)\\
\sigma_3(g)&\equiv \big(\gamma_{30}a_{1,\,29} + \gamma_{29}a_{1,\,30} + \gamma_{31}a_{1,\,31} + \gamma_{34}a_{1,\,43} + \gamma_{33}a_{1,\,34} + \gamma_{43}a_{1,\,42}+\gamma_{42}a_{1,\,43}\\
&\quad  + \gamma_{45}a_{1,\,44} + \gamma_{44}a_{1,\,45} + \gamma_{46}a_{1,\,46} + \gamma_{32}x_1x_2x_3^{5}x_4^{2} + \gamma_{41}x_1x_2x_3^{4}x_4^{3}\big).
\end{array}
\end{equation}
Using the Cartan formula and Theorem \ref{dlSi}, we have
\begin{equation}\label{dt8}
\begin{array}{ll}
x_1^{6}x_2x_3x_4 &= Sq^{1}(x_1^{5}x_2x_3x_4) + Sq^{2}(x_1^{3}x_2^{2}x_3x_4 + x_1^{3}x_2x_3^{2}x_4 + x_1^{3}x_2x_3x_4^{2})\\
\medskip
&\quad  +  a_{1,\,44} +  a_{1,\,45} +  a_{1,\,46} \mod (\overline{A}(P_4)_{n_1});  \\
\medskip
x_1^{2}x_2x_3x_4^{5} &= Sq^{1}(x_1x_2x_3x_4^{5}) + a_{1,\,29} +  a_{1,\,32} +  a_{1,\,33} \mod (\overline{A}(P_4)_{n_1});  \\
\medskip
x_1^{2}x_2x_3^{5}x_4 &= Sq^{1}(x_1x_2x_3^{5}x_4) + Sq^{2}(x_1x_2x_3^{3}x_4^{2}) + a_{1,\,30} +  a_{1,\,34} +  a_{1,\,41} \mod (\overline{A}(P_4)_{n_1});  \\
x_1^{4}x_2^{3}x_3x_4 &= Sq^{1}(x_1x_2^{5}x_3x_4) + Sq^{2}(x_1x_2^{3}x_3x_4^{2} + x_1x_2^{3}x_3^{2}x_4 + x_1^{2}x_2^{3}x_3x_4)\\
\medskip
&\quad  + a_{1,\,31} +  a_{1,\,42} +  a_{1,\,43} \mod (\overline{A}(P_4)_{n_1});  \\
\medskip
x_1x_2^{5}x_3^{2}x_4 &= Sq^{2}(x_1x_2^{3}x_3^{2}x_4) +  a_{1,\,43} \mod (\overline{A}(P_4)_{n_1});  \\
\medskip
x_1x_2^{4}x_3^{3}x_4 &=Sq^{2}(x_1x_2^{2}x_3^{3}x_4) +  a_{1,\,34} \mod (\overline{A}(P_4)_{n_1});  \\
\medskip
x_1x_2x_3^{5}x_4^{2} &=Sq^{2}(x_1x_2x_3^{3}x_4^{2}) +  a_{1,\,41} \mod (\overline{A}(P_4)_{n_1});  \\
\medskip
x_1x_2x_3^{4}x_4^{3} &=Sq^{2}(x_1x_2x_3^{2}x_4^{3}) +  a_{1,\,32} \mod (\overline{A}(P_4)_{n_1}).
\end{array}
\end{equation}
Combining \eqref{dt6}, \eqref{dt7} and \eqref{dt8}, we get
$$ \begin{array}{ll}
(\sigma_1(g) + g) &\equiv \big( \gamma_{33}(a_{1,\,29} +a_{1,\,32}) +  \gamma_{34}(a_{1,\,30} +a_{1,\,41})+ (\gamma_{31} + \gamma_{46})a_{1,\,31}+(\gamma_{42} + \gamma_{44} + \gamma_{46})a_{1,\,42} \\
\medskip
&\quad + (\gamma_{43} + \gamma_{45} + \gamma_{46})a_{1,\,43} + (\gamma_{31} + \gamma_{42} + \gamma_{44})a_{1,\,44} + (\gamma_{31} + \gamma_{43} + \gamma_{45})a_{1,\,45}\big),\\
(\sigma_2(g) + g) &\equiv \big((\gamma_{30} + \gamma_{31})a_{1,\,30}+ (\gamma_{32} + \gamma_{33})a_{1,\,32} + (\gamma_{34} + \gamma_{43})a_{1,\,34}\\
\medskip
&\quad + (\gamma_{41} + \gamma_{42})a_{1,\,41} + (\gamma_{45} + \gamma_{46})a_{1,\,45}\big)\\
(\sigma_3(g) + g) &\equiv \big((\gamma_{29} + \gamma_{30})a_{1,\,29} + (\gamma_{32} + \gamma_{41})a_{1,\,32} + (\gamma_{33} + \gamma_{34})a_{1,\,33} \\
\medskip
&\quad +(\gamma_{42} + \gamma_{43})a_{1,\,42} + (\gamma_{44} + \gamma_{45})a_{1,\,44}\big).
\end{array}$$
From these equalities and the relations $\sigma_j(g) \equiv g,\, 1\leq j\leq 3,$ we obtain $\gamma_j = 0$ for $j\in \{32, 33, 34, 41, 42, 43\},$ and $\gamma_{29} = \gamma_{30} = \gamma_{31} = \gamma_{44} = \gamma_{45} = \gamma_{46}.$ This completes the proof of the lemma.
\end{proof}

The following assertion is useful.

\begin{md}\label{md1}
We have $(\pmb{Q}^{4}_{n_1})^{G(4)} = \langle [q_{1,\, 4}] \rangle.$
\end{md}

\begin{proof}
Let $h\in (P_4)_{n_1}$ such that $[h]\in (\pmb{Q}^{4}_{n_1})^{G(4)}.$ Since $\Sigma_4\subset G(4),$ $[h]\in (\pmb{Q}^{4}_{n_1})^{\Sigma_4}$ and therefore by Corollary \ref{hq1}, we have $ h\equiv \sum_{1\leq t\leq 4}m_tq_{1,\, t},$ where $m_t\in k$ for every $t.$ Since $[h]\in (\pmb{Q}^{4}_{n_1})^{G(4)},$ $(\sigma_4(h) + h)\equiv 0$ with $\sigma_4: P_4\longrightarrow P_4.$ From Theorem \ref{dlSi} and a direct computation, we obtain
$$ (\sigma_4(h) + h) \equiv (m_1a_{1,\, 1} + (m_1 + m_2)a_{1,\, 8} + (m_2 + m_3)a_{1,\, 17} + \mbox{other terms})\equiv 0.$$
and therefore $h\equiv q_{1,\, 4}.$ The proposition is proved.
\end{proof}

Now, we consider the element
$$ \zeta = (a_1^{(1)}a_2^{(3)}a_3^{(3)}a_4^{(2)} + a_1^{(1)}a_2^{(3)}a_3^{(4)}a_4^{(1)} + a_1^{(1)}a_2^{(5)}a_3^{(2)}a_4^{(1)} +  a_1^{(1)}a_2^{(6)}a_3^{(1)}a_4^{(1)})\in (P_4)_{3(2^{1}-1) + 3.2^{1}}^{*}.$$
Then, it is $\overline{A}$-annihilated. Indeed, due to the well-known unstable condition of the Steenrod squares, we need only to consider the effects of $Sq^{1}$ and $Sq^{2}$. By a direct computation, we get
$$ \begin{array}{ll}
\medskip
(\zeta)Sq^{1} &= a_1^{(1)}a_2^{(3)}a_3^{(3)}a_4^{(1)} + a_1^{(1)}a_2^{(3)}a_3^{(3)}a_4^{(1)} + a_1^{(1)}a_2^{(5)}a_3^{(1)}a_4^{(1)} +a_1^{(1)}a_2^{(5)}a_3^{(1)}a_4^{(1)} = 0,\\
\medskip
(\zeta)Sq^{2} &=  0 + a_1^{(1)}a_2^{(3)}a_3^{(2)}a_4^{(1)} + a_1^{(1)}a_2^{(3)}a_3^{(2)}a_4^{(1)} + 0 = 0.
\end{array}$$
On the other side, since $<\zeta, q_{1,\, 4}>= 1,$ by Proposition \ref{md1}, implies that $$ k\otimes_{G(4)}\mathscr {P}_A((P_4)_{n_1}^{*}) = ((\pmb{Q}^{4}_{n_1})^{G(4)})^{*} = \langle ([q_{1,\, 4}])^{*}\rangle  = \langle[\zeta]\rangle.$$



\underline{Case $s = 2$}. We first have the following remark.

\begin{rem} Based on the bases of $\underline{\pmb{Q}^{4}_{n_s}}$ and $\overline{\pmb{Q}^{4}_{n_s}}$ above, the weight vector of $a_{s,\, j}$ is one of the following sequences:
$$\omega_{(s, 1)}:=   \underset{\mbox{{$s$ times of $3$}}}{\underbrace{(3, 3, \ldots, 3},1,1)},\ \ \omega_{(s, 2)}:= \underset{\mbox{{$(s+1)$ times of $3$}}}{\underbrace{(3, 3, \ldots, 3)}}.$$ Hence, we have the following isomorphisms:
$$ \begin{array}{ll}
\medskip
\pmb{Q}^{4}_{n_s} &\cong (\pmb{Q}^{4}_{n_s})^{\omega_{(s, 1)}} \bigoplus (\pmb{Q}^{4}_{n_s})^{\omega_{(s, 2)}},\\
(\pmb{Q}^{4}_{n_s})^{\omega_{(s, j)}} &\cong (\underline{\pmb{Q}^{4}_{n_s}})^{\omega_{(s, j)}}\bigoplus (\overline{\pmb{Q}^{4}_{n_s}})^{\omega_{(s, j)}},\ j = 1,\, 2.
\end{array}$$
\end{rem}

Then, for $s = 2,$ we have $\pmb{Q}^{4}_{n_2} \cong (\pmb{Q}^{4}_{n_2})^{\omega_{(2, 1)}} \bigoplus (\pmb{Q}^{4}_{n_2})^{\omega_{(2, 2)}}$ and the following.


\begin{md}\label{md2}
The spaces of invariants $((\pmb{Q}^{4}_{n_2})^{\omega_{(2, 1)}})^{G(4)}$ and $((\pmb{Q}^{4}_{n_2})^{\omega_{(2, 2)}})^{G(4)}$ are trivial.
\end{md}

\begin{proof}
We first prove $((\pmb{Q}^{4}_{n_2})^{\omega_{(2, 1)}})^{G(4)} = 0.$ It is clear that the monomial $a_{s,\, 12} = x_1^{2^{s+2}-1}x_2^{2^s-1}x_3^{2^s-1}$ is minimal spike in $(P_4)_{n_s}$ and $\omega(a_{s,\, 12}) = \omega_{(s, 1)}$ for any $s\geq 1.$ Hence, $[a_{s,\, j}]_{\omega_{(s, 1)}} = [a_{s,\, j}].$  Recall that $(\pmb{Q}^{4}_{n_2})^{\omega_{(2, 1)}} \cong (\underline{\pmb{Q}^{4}_{n_2}})^{\omega_{(2, 1)}}\bigoplus (\overline{\pmb{Q}^{4}_{n_2}})^{\omega_{(2, 1)}}.$ Then, by Lemma \ref{bd1}, we get
$(\underline{\pmb{Q}^{4}_{n_2}})^{\omega_{(2, 1)}}  =  \Sigma_4(a_{2,\,1}) \bigoplus \Sigma_4(a_{2,\,13}),$ and
\begin{equation}\label{dt9}
((\underline{\pmb{Q}^{4}_{n_2}})^{\omega_{(2, 1)}})^{\Sigma_4} = \langle [q_{2,\, 1}], [q_{2,\, 2}]\rangle.
\end{equation}

Using an admissible basis of $\overline{\pmb{Q}^{4}_{n_2}}$ above, we have a direct summand decomposition of the $\Sigma_4$-modules:
$$  (\overline{\pmb{Q}^{4}_{n_2}})^{\omega_{(2, 1)}} = \Sigma_4(a_{2,\,41}) \bigoplus \Sigma_4(a_{2,\,53}) \bigoplus \mathbb V,$$
where $$ \begin{array}{ll}
\medskip
& \Sigma_4(a_{2,\,41}) = \langle \{[a_{2,\,j}]:\, 41\leq j\leq 52\} \rangle,\ \Sigma_4(a_{2,\,53}) = \langle \{[a_{2,\,j}]:\, 53\leq j\leq 58\} \rangle,\\
\medskip
&\mathbb V = \langle \{[a_{2,\,j}]:\, j = 29, \ldots, 34, 59, \ldots, 80, 85, \ldots, 94\} \rangle.
\end{array}$$
Then, by a similar technique as in the proof of Lemma \ref{bd2}, we find that
\begin{equation}\label{dt10}
\begin{array}{ll}
\medskip
&\Sigma_4(a_{2,\,41})^{\Sigma_4} = \langle [\widehat{q_{2,\, 1}}] \rangle\ \mbox{with}\ \widehat{q_{2,\, 1}}:= \sum_{41\leq j\leq 52}a_{2,\,j};\\
\medskip
&\Sigma_4(a_{2,\,53})^{\Sigma_4} = \langle [\widehat{q_{2,\, 2}}] \rangle\ \mbox{with}\ \widehat{q_{2,\, 2}}:= \sum_{53\leq j\leq 58}a_{2,\,j};\\
\medskip
&\mathbb V^{\Sigma_4} = 0.
\end{array}
\end{equation}
Thus, from the equalities \eqref{dt9} and \eqref{dt10}, we get 
\begin{equation}\label{dt11}
((\pmb{Q}^{4}_{n_2})^{\omega_{(2, 1)}})^{\Sigma_4} = \langle [q_{2,\, 1}], [q_{2,\, 2}], [\widehat{q_{2,\, 1}}], [\widehat{q_{2,\, 2}}] \rangle.
\end{equation}

Now, let $h\in (P_4)_{n_2}$ such that $[h]\in ((\pmb{Q}^{4}_{n_2})^{\omega_{(2, 1)}})^{G(4)}.$ Since  $[h]\in ((\pmb{Q}^{4}_{n_2})^{\omega_{(2, 1)}})^{\Sigma_4},$ by the equality \eqref{dt11}, we have 
\begin{equation}\label{dt12}
h\equiv (\xi_1q_{2,\, 1} + \xi_2q_{2,\, 2} + \xi_3\widehat{q_{2,\, 1}} + \xi_4\widehat{q_{2,\, 2}}),
\end{equation}
where $\xi_t\in k$ for $1\leq t\leq 4.$ Acting the homomorphism $\sigma_4:P_4\longrightarrow P_4$ on both sides of \eqref{dt12}, and using Theorem \ref{dlSi} with the relation $(\sigma_4(h) + h)\equiv 0,$ we obtain
$$ (\sigma_4(h) + h) \equiv ((\xi_1 + \xi_3)a_{2,\, 1} + \xi_1a_{2,\, 3} + (\xi_1 + \xi_2)a_{2,\, 8} + (\xi_2 + \xi_4)a_{2,\, 13} + \mbox{other terms})  \equiv 0.$$
The last equality implies $\xi_1 = \xi_2 = \xi_3 = \xi_4.$ This means that $((\pmb{Q}^{4}_{n_2})^{\omega_{(2, 1)}})^{G(4)} = 0.$ 

Next, we have $(\pmb{Q}^{4}_{n_2})^{\omega_{(2, 2)}} \cong (\underline{\pmb{Q}^{4}_{n_2}})^{\omega_{(2, 2)}}\bigoplus (\overline{\pmb{Q}^{4}_{n_2}})^{\omega_{(2, 2)}}.$ According to Lemma \ref{bd1}, we get $$((\underline{\pmb{Q}^{4}_{n_2}})^{\omega_{(2, 2)}})^{\Sigma_4} = \langle [q_{2,\, 3}]_{\omega_{(2, 2)}}\rangle.$$
A basis of $(\overline{\pmb{Q}^{4}_{n_2}})^{\omega_{(2, 2)}}$ is the set $\{[a_{2,\,j}]_{\omega_{(2, 2)}}:\, j = 35, 36, \ldots, 40, 81, \ldots, 84\}$ and we have a direct summand decomposition of the $\Sigma_4$-modules:
$$  (\overline{\pmb{Q}^{4}_{n_2}})^{\omega_{(2, 2)}}  = \Sigma_4(a_{2,\,35})\bigoplus \Sigma_4(a_{2,\,81}),$$
where $\Sigma_4(a_{2,\,35}) = \langle \{[[a_{2,\,j}]_{\omega_{(2, 2)}}:\, j = 35, \ldots, 40]\} \rangle$ and $\Sigma_4(a_{2,\,81}) = \langle \{[[a_{2,\,j}]_{\omega_{(2, 2)}}:\, j = 81, \ldots, 84]\} \rangle.$ By using Theorem \ref{dlSi} and a similar computation as above, we also obtain 
$$  \Sigma_4(a_{2,\,35})^{\Sigma_4} = \langle [\widehat{q_{2,\, 3}}]_{\omega_{(2,\, 2)}}\rangle,\ \  \Sigma_4(a_{2,\,81})^{\Sigma_4} = \langle [\widehat{q_{2,\, 4}}]_{\omega_{(2,\, 2)}} \rangle,$$
where $\widehat{q_{2,\, 3}} = \sum_{35\leq j\leq 40}a_{2,\, j}$ and $\widehat{q_{2,\, 4}} = \sum_{81\leq j\leq 84}a_{2,\, j}.$ Then, $$ ((\pmb{Q}^{4}_{n_2})^{\omega_{(2, 2)}})^{\Sigma_4} = \langle [q_{2,\, 3}]_{\omega_{(2,\, 2)}}, \langle [\widehat{q_{2,\, 3}}]_{\omega_{(2,\, 2)}}, \langle [\widehat{q_{2,\, 4}}]_{\omega_{(2,\, 2)}} \rangle.$$
Let $[g]_{_{\omega_{(2,\, 2)}}}\in ((\pmb{Q}^{4}_{n_2})^{\omega_{(2, 2)}})^{G(4)},$ we have $g\equiv_{_{\omega_{(2,\, 2)}}} (\ell_1q_{2,\, 3} + \ell_2\widehat{q_{2,\, 3}} + \ell_3\widehat{q_{2,\, 4}})$ with $\ell_i\in k$ for every $i.$ By a direct computation using the relation $(\sigma_4(g) + g)\equiv_{\omega_{(2,\, 2)}} 0,$ we obtain
$$  (\sigma_4(g) + g)\equiv_{_{\omega_{(2,\, 2)}}} ( (\ell_1 + \ell_2)a_{2,\, 25} + (\ell_2 + \ell_3)a_{2,\, 36} + \ell_3a_{2,\, 83}+ \mbox{other terms})  \equiv_{\omega_{(2,\, 2)}} 0.$$
This means that $\ell_1 = \ell_2 = \ell_3 = 0.$ The proposition follows.
\end{proof}

Now, since $\dim (\pmb{Q}^{4}_{n_2})^{G(4)} \leq \dim ((\pmb{Q}^{4}_{n_2})^{\omega_{(2, 1)}})^{G(4)} +\dim ((\pmb{Q}^{4}_{n_2})^{\omega_{(2, 2)}})^{G(4)},$ by Proposition \ref{md2},  we get
$$ k\otimes_{G(4)}\mathscr {P}_A((P_4)_{n_2}^{*}) = ((\pmb{Q}^{4}_{n_2})^{G(4)})^{*}  = 0.$$

