\item[iii)] $\mathcal M^{\Sigma_4} = \langle [\widehat{q_{s,\, 4}}]_{\omega_{(s, 1)}}, [\widehat{q_{s,\, 5}}]_{\omega_{(s, 1)}}\rangle$ with $$\widehat{q_{s,\, 4}}:= \sum_{70\leq j\leq 73}b_{s,\, j} + b_{s,\, 78} + b_{s,\, 79}, \ \  \widehat{q_{s,\, 5}}:= \sum_{70\leq j\leq 73}b_{s,\, j} + b_{s,\, 80}.$$
\end{lema}

\begin{proof}
We prove Part iii) in detail. The others parts can be computed by a similar idea. Computing the general case is very technical. Indeed, we have the set $\{[b_{s,\, j}]_{\omega_{(s, 1)}}:\, j = 70, 71, 72, 73, 78, 79, 80\},$ which is an admissible basis of $\mathcal M.$ Suppose that $[f]\in \mathcal M^{\Sigma_4},$ then $$ f\equiv_{\omega_{(s, 1)}}\big(\sum_{70\leq j\leq 73}\gamma_jb_{s,\, j} + \sum_{78\leq j\leq 80}\gamma_jb_{s,\, j}\big),\  \mbox{$\gamma_j\in k$ for every $j.$}$$ Using the homomorphisms $\sigma_i: P_4\longrightarrow P_4,\, i = 1, 2, 3,$ we have the following equalities:
$$ \begin{array}{ll}
\medskip
\sigma_1(f)&\equiv_{\omega_{(s, 1)}} \big(\gamma_{73}b_{s,\, 70} + \gamma_{70}b_{s,\, 73} + \gamma_{71}x_1^{2^{s+2}-3}x_2^{3}x_3^{2^{s+1}-1}x_4^{2^{s+2}-2}\\
\medskip
&\quad + \gamma_{72}x_1^{2^{s+2}-3}x_2^{3}x_3^{2^{s+2}-2}x_4^{2^{s+1}-1} + \gamma_{78}x_1^{2^{s+2}-5}x_2^{7}x_3^{2^{s+1}-3}x_4^{2^{s+2}-2}\\
\medskip
&\quad + \gamma_{79}x_1^{2^{s+2}-5}x_2^{7}x_3^{2^{s+2}-3}x_4^{2^{s+1}-2} + \gamma_{80}x_1^{2^{s+1}-5}x_2^{7}x_3^{2^{s+2}-3}x_4^{2^{s+2}-2}\big),\\
&\quad + (\gamma_{81} + \gamma_{85} + \gamma_{86})b_{1,\, 86} + \mbox{others terms}\big)\equiv 0,\\
\medskip
\sigma_2(f)&\equiv_{\omega_{(s, 1)}} \big(\gamma_{71}b_{s,\, 70} + \gamma_{70}b_{s,\, 71} + \gamma_{72}x_1^{3}x_2^{2^{s+2}-2}x_3^{2^{s+2}-3}x_4^{2^{s+1}-1}\\
\medskip
&\quad +  \gamma_{73}x_1^{2^{s+1}-1}x_2^{2^{s+2}-3}x_3^{3}x_4^{2^{s+2}-2} +\gamma_{78}x_1^{7}x_2^{2^{s+1}-3}x_3^{2^{s+2}-5}x_4^{2^{s+2}-2}\\
\medskip
&\quad + \gamma_{79}x_1^{7}x_2^{2^{s+2}-3}x_3^{2^{s+2}-5}x_4^{2^{s+1}-2} +  \gamma_{80}x_1^{7}x_2^{2^{s+2}-3}x_3^{2^{s+1}-5}x_4^{2^{s+2}-2}\big),\\
\medskip
\sigma_3(f)&\equiv_{\omega_{(s, 1)}} \big(\gamma_{72}b_{s,\, 71} + \gamma_{71}b_{s,\, 72} + \gamma_{70}x_1^{3}x_2^{2^{s+1}-1}x_3^{2^{s+2}-2}x_4^{2^{s+2}-3}\\
\medskip
&\quad +  \gamma_{73}x_1^{2^{s+1}-1}x_2^{3}x_3^{2^{s+2}-2}x_4^{2^{s+2}-3} +\gamma_{78}x_1^{7}x_2^{2^{s+2}-5}x_3^{2^{s+2}-2}x_4^{2^{s+1}-3}\\
\medskip
&\quad + \gamma_{79}x_1^{7}x_2^{2^{s+2}-5}x_3^{2^{s+1}-2}x_4^{2^{s+2}-3} +  \gamma_{80}x_1^{7}x_2^{2^{s+1}-5}x_3^{2^{s+2}-2}x_4^{2^{s+2}-3}\big).
\end{array}$$
Using the actions of the Steenrod squares and the Cartan formula, we get
$$  \begin{array}{ll}
x_1^{3}x_2^{2^{s+1}-1}x_3^{2^{s+2}-2}x_4^{2^{s+2}-3}&\equiv_{\omega_{(s, 1)}} b_{s,\, 70},\bigg|\ x_1^{3}x_2^{2^{s+2}-2}x_3^{2^{s+2}-3}x_4^{2^{s+1}-1}\equiv_{\omega_{(s, 1)}} b_{s,\, 72},\\
x_1^{7}x_2^{2^{s+1}-5}x_3^{2^{s+2}-2}x_4^{2^{s+2}-3}&\equiv_{\omega_{(s, 1)}} b_{s,\, 80},\bigg|\ x_1^{7}x_2^{2^{s+1}-3}x_3^{2^{s+2}-5}x_4^{2^{s+2}-2}\equiv_{\omega_{(s, 1)}} b_{s,\, 80},\\
x_1^{7}x_2^{2^{s+2}-5}x_3^{2^{s+1}-2}x_4^{2^{s+2}-3}&\equiv_{\omega_{(s, 1)}} b_{s,\, 78},\bigg|\ x_1^{7}x_2^{2^{s+2}-5}x_3^{2^{s+2}-2}x_4^{2^{s+1}-3}\equiv_{\omega_{(s, 1)}} b_{s,\, 79},\\
x_1^{7}x_2^{2^{s+2}-3}x_3^{2^{s+1}-5}x_4^{2^{s+2}-2}&\equiv_{\omega_{(s, 1)}} b_{s,\, 78},\bigg|\ x_1^{7}x_2^{2^{s+2}-3}x_3^{2^{s+2}-5}x_4^{2^{s+1}-2}\equiv_{\omega_{(s, 1)}} b_{s,\, 79},\\
x_1^{2^{s+1}-5}x_2^{7}x_3^{2^{s+2}-3}x_4^{2^{s+2}-2}&\equiv_{\omega_{(s, 1)}} b_{s,\, 80}, \bigg|\ x_1^{2^{s+1}-1}x_2^{3}x_3^{2^{s+2}-2}x_4^{2^{s+2}-3}\equiv_{\omega_{(s, 1)}} b_{s,\, 73},\\
\medskip
x_1^{2^{s+1}-1}x_2^{2^{s+2}-3}x_3^{3}x_4^{2^{s+2}-2}&\equiv_{\omega_{(s, 1)}} \big(b_{s,\, 73} + b_{s,\, 78} + b_{s,\, 80}\big),  \\
\medskip
x_1^{2^{s+2}-5}x_2^{7}x_3^{2^{s+1}-3}x_4^{2^{s+2}-2}&\equiv_{\omega_{(s, 1)}}  \big(b_{s,\, 78} + b_{s,\, 80}\big),\\
\medskip
x_1^{2^{s+2}-5}x_2^{7}x_3^{2^{s+2}-3}x_4^{2^{s+1}-2}&\equiv_{\omega_{(s, 1)}}  \big(b_{s,\, 79} + b_{s,\, 80}\big),\\
\medskip
x_1^{2^{s+2}-3}x_2^{3}x_3^{2^{s+1}-1}x_4^{2^{s+2}-2}&\equiv_{\omega_{(s, 1)}}  \big(b_{s,\, 71} + b_{s,\, 80}\big),\\
\medskip
x_1^{2^{s+2}-3}x_2^{3}x_3^{2^{s+2}-2}x_4^{2^{s+1}-1}&\equiv_{\omega_{(s, 1)}}  \big(b_{s,\, 72} + b_{s,\, 80}\big).
\end{array}$$
Combining the above computations and the relations $\sigma_i(f)\equiv_{\omega_{(s,\, 1)}} f$ for $1\leq i\leq 3,$ we obtain
$\gamma_{78} = \gamma_{79}$ and $\gamma_{j} + \gamma_{79} + \gamma_{80} = 0,$ for $70\leq j\leq 73.$  The lemma is proved.
\end{proof}

