\subsubsection*{Proof of Theorem \ref{dlct}  (The case $t \geq 4$ and $s\geq 1$)}

We put $n_{s,t}:= 2^{s+t+1} +2^{s+1} - 3,$ then from a result in \cite{N.S}, $ \pmb{Q}^{4}_{n_{s, t}} \cong (\pmb{Q}^{4}_{n_{s,t}})^{\omega_{(s, t, 1)}}\bigoplus (\pmb{Q}^{4}_{n_{s,t}})^{\omega_{(s, t, 2)}},$ where $$\omega_{(s, t, 1)}:= \underset{\mbox{{$s$ times }}}{\underbrace{(3, 3, \ldots, 3},}\underset{\mbox{{$(t+1)$ times }}}{\underbrace{1, 1, \ldots, 1)}}, \ \mbox{and}\ \omega_{(s, t, 2)}:= \underset{\mbox{{$(s+1)$ times }}}{\underbrace{(3, 3, \ldots, 3},}\underset{\mbox{{$(t-1)$ times }}}{\underbrace{2, 2, \ldots, 2)}}.$$ By using an admissible basis for $(\pmb{Q}^{4}_{n_{s,t}})^{\omega_{(s, t, j)}}$ (see \cite{N.S}), we obtain

\begin{md}\label{mdt}
Let $s$ and $t$ be positive integers such that $t\geq 4.$ Then, 
$$ \dim ((\pmb{Q}^{4}_{n_{s,t}})^{\omega_{(s, t, j)}})^{G(4)} =\left\{\begin{array}{ll}
0&\mbox{if $j = 1$ and $s\in \{1, 2\}$},\\
1&\mbox{if $j = 2$ and $s\in \{1, 2\}$},\\
1&\mbox{if $j\in \{1, 2\}$ and $s\geq 3$}.
\end{array}\right.$$
\end{md}
Since the proof of the proposition is similar to that of Proposition \ref{md3}, we omit details here. On the other hand, as $\zeta_{s, t, 1} = a_2^{(2^{s+1}-1)}a_3^{(2^{s+t}-1)}a_4^{(2^{s+t}-1)}$ and $\zeta_{s, t, 2} = a_2^{(2^{s}-1)}a_3^{(2^{s}-1)}a_4^{(2^{s+t+1}-1)}$ belong to ${\rm Ext}_A^{0, n_{s,t}}(P_4, k),$ by Theorem \ref{dlCH}, $\zeta_{s, t, 1}$ and $\zeta_{s, t, 2}$ are representative of the non-zero elements $h_0h_{s+1}h_{s+t}^{2}$ and $h_0h_{s}^{2}h_{s+t+1}\in {\rm Ext}_A^{4, n_{s,t}+4}(k, k)$  respectively. Moreover, by Theorem \ref{dlntg}, the $k$-vector space ${\rm Ext}_A^{4, n_{s,t}+4}(k, k)$ has dimension $2$ for all $s > 0$ and $t > 3.$ In addition, $k\otimes_{G(4)}\mathscr {P}_A((P_4)_{n_{s, t}}^{*})  = \langle [\zeta_{s, t, 1}]\rangle$ for $s = 1, 2$ and $k\otimes_{G(4)}\mathscr {P}_A((P_4)_{n_{s, t}}^{*})  = \langle [\zeta_{s, t, 1}],\, [\zeta_{s, t, 2}]\rangle$ for all $s\geq 3.$ This straightforwardly follows from Proposition \ref{mdt}, which we leave to be proved by the interested reader. The theorem follows.


