$$ \begin{array}{ll}
(\pmb{Q}^{4}_{n_{1,\, t}})^{G(4)}&=\langle [x_1x_2^{2}x_3^{2^{t+1}-4}x_4+x_1x_2^{2}x_3x_3^{2^{t+1}-4}+x_1x_2^{2}x_3^{2^{t+1}-3}+\varphi(p_{4,\, t})] \rangle,\\
