\title{Impact of rotation on synthetic mass-radius relationships of two-layer rocky planets and water worlds}

\titlerunning{}

\author{J.-M. Hur\'e\inst{1} \and P. No\'e\inst{1,2}  \and C. Staelen\inst{1} \and E. Di Folco\inst{1}}
