\begin{figure}
    \centering
    \includegraphics[width=1\linewidth]{fig/evol_Zenv_fg001_4panels.png}
    \caption{
    Same as Fig~\ref{fig: grow_enrichEnv}, but with $f_\mathrm{g}=0.01$.
