\subsection{Optimal Strategies for Closed Intervals}

The following proposition is a verification theorem for the optimal strategies for the closed interval case.

\begin{mypr}\label{prop on verification}
	Let $\ol{\zeta}:=(\ol{\zeta}^{\mc{A}},\ol{\zeta}^{\mc{C}})$. Suppose there exist smooth functions $\ol{\zeta}^{\mc{A}}$ and $\ol{\zeta}^{\mc{C}}$ such that the $\ol{\zeta}$-value function $W^{\ol{\zeta}}$ is $(2,1,1)$-differentiable and satisfies
	\begin{itemize}
		\item $\mc{L}^{a,c}(W^{\ol\zeta})(\ol\zeta^{\mc{A}}(a,c),a,c)\leq 0$ for $(a,c)\in[\ul a,\ol a]\times[\ul c,\ol c]$
		\item $W_a^{\ol\zeta}(x,a,c)\geq 0$ for $(x,a,c)\in[0,\ol\zeta^{\mc{A}}(a,c)]\times[\ul a,\ol a]\times[\ul c,\ol c)$
		\item $W_c^{\ol\zeta}(x,a,c)\leq 0$ for $(x,a,c)\in[0,\ol\zeta^{\mc{A}}(a,c)]\times[\ul a,\ol a]\times[\ul c,\ol c)$,
	\end{itemize}
	if $\ol{\zeta}^{\mc{A}}(a,c)\wedge\ol{\zeta}^{\mc{C}}(a,c)=\ol{\zeta}^{\mc{A}}(a,c)$ and
	\begin{itemize}
		\item $W^{\ol{\zeta}}_x(\ol{\zeta}^{\mc{C}}(a,c),a,c)\leq 1$ for $(a,c)\in[\ul a,\ol a]\times[\ul c,\ol c]$
		\item $W_a^{\ol\zeta}(x,a,c)\geq 0$ for $(x,a,c)\in[0,\ol\zeta^{\mc{C}}(a,c)]\times[\ul a,\ol a]\times[\ul c,\ol c)$
		\item $W_c^{\ol\zeta}(x,a,c)\leq 0$ for $(x,a,c)\in[0,\ol\zeta^{\mc{C}}(a,c)]\times[\ul a,\ol a]\times[\ul c,\ol c)$,
	\end{itemize}
	if $\ol{\zeta}^{\mc{A}}(a,c)\wedge\ol{\zeta}^{\mc{C}}(a,c)=\ol{\zeta}^{\mc{C}}(a,c)$. Then $W^{\ol{\zeta}}=V$.
\end{mypr}


Write $\frac{\partial}{\partial x}b^a_0(0,a, c):=\lim_{x\to0^+}\frac{\partial}{\partial x}b^a_0(x,a,c)$. The following lemmas will be used to prove the main results.

\begin{mylm}\label{sign of 2nd partial b_0^a}
	Let $x>0$.
	\begin{enumerate}
		\item If $\mu a-2(b+c)< 0$ and $\sigma<\sqrt{\frac{-\mu(\mu a-2(b+c))}{2qa}}$, then $\frac{\partial^2}{\partial x^2}b^a_0(x,a, c)<0<\frac{\partial}{\partial x}b^a_0(x,a, c)$ and  $\frac{\partial}{\partial x}b^a_0(0,a, c)>0$.
		\item If $\mu a-2(b+c)\geq 0$ or if $\mu a-2(b+c)< 0$ and $\sigma\geq \sqrt{\frac{-\mu(\mu a-2(b+c))}{2qa}}$, then $\frac{\partial}{\partial x}b^a_0(x,a, c)<0<\frac{\partial^2}{\partial x^2}b^a_0(x,a, c)$ and  $\frac{\partial}{\partial x}b^a_0(0,a, c)<0$.
	\end{enumerate}
\end{mylm}


\begin{myrem}\label{remark on behavior of b0a}
	The function $b^a_0(x,a, c)$ is decreasing and convex in $x$ if $\mu a-2(b+c)\geq 0$ or if $\mu a-2(b+c)< 0$ and $\sigma\geq \sqrt{\frac{-\mu(\mu a-2(b+c))}{2qa}}$. On the other hand, the function $b^a_0(x,a, c)$ is increasing and concave in $x$ if $\mu a-2(b+c)< 0$ and $\sigma<\sqrt{\frac{-\mu(\mu a-2(b+c))}{2qa}}$.
\end{myrem}

\begin{mylm}\label{claim1}
	Let $\mu a-b> 0$ and $a,q,\sigma >0$ such that $(\mu a-b)^2\geq 4q\sigma^2a^2$. Then, $\bar{c}< \frac{\mu a-b-\sqrt{(\mu a-b)^2-4q\sigma^2a^2}}{2}$ for $\bar{c}\leq \frac{q\sigma^2a^2}{2(\mu a -b)}$.
\end{mylm}


\begin{mylm}\label{lemma claim 2}
	Suppose $\mu a - b\neq 0$. Then, $\frac{\ol c}{q}\theta_2(a,\ol c)+1\geq 0$ for $\ol c\leq \frac{q\sigma^2a^2}{2(\mu a-b)}$.
\end{mylm}

The next proposition states that there exists a reserve level $x$ that satisfies the boundary condition \eqref{5.19 boundary condition}.

\begin{mypr}\label{boundary condition claim}
	For $\ol c> \frac{q\sigma^2\ul a^2}{2(\mu \ul a-b)}$ with $\mu \ul a-b\neq 0$, there exists a unique $x_c>0$ such that $\frac{\partial}{\partial x}b^c_0(x_c,\ul a,\ol c)=0$. Moreover, $\frac{\partial}{\partial x}b^c_0(x,\ul a,\ol c)<0$ for $x\in[0,x_c)$ and $\frac{\partial}{\partial x}b^c_0(x,\ul a,\ol c)>0$ for $x\in(x_c,\infty)$. Also, $\frac{\partial^2}{\partial x^2}b^c_0(x_c,\ul a,\ol c)>0$. 
\end{mypr}

The following result proves the uniqueness of the solution of \eqref{5.19} over a neighborhood of $(\ul a,\ol c)$.

\begin{mypr}\label{epsilon-opt for zeta C}
	In the case $\ol c>\frac{q\sigma^2\ul a^2}{2(\mu \ul a-b)}$, there exists a unique solution $\ol\zeta^{\mc{C}}(a,c)$ of \eqref{5.19} with boundary condition \eqref{5.19 boundary condition} in $[\ul a,\ul a+\epsilon^1_c]\times[\ol c-\epsilon^2_c,\ol c]$ for some $\epsilon^1_c,\epsilon^2_c>0$.
\end{mypr}

The next lemma revolves around the properties of the function $\frac{\partial b^a_1}{\partial x}$ and its sign.

\begin{mylm}\label{claim on partial b1a}
	The function $\frac{\partial b^a_1}{\partial x}(x,a,c):(0,\infty)\times[\ul{a},\ol{a}]\times[\ul{c},\ol{c}]\to\mathbb{R}$ is infinitely continuously differentiable. Moreover, it satisfies the following: (1) $\mbox{sgn}\left[\lim_{x\to 0^+}\frac{\partial b^a_1}{\partial x}(x,a,c)\right]= -\mbox{sgn}\left[\mu a-2(b+c)\right]$ and (2) $\lim_{x\to \infty}\frac{\partial b^a_1}{\partial x}(x,a,c)> 0$.
\end{mylm}

The following proposition states that for a large reserve level, the solution $\ol\zeta^{\mc{A}}(a,c)$ exists and is unique over some neighborhood of $(\ul a,\ol c)$.

\begin{mypr}\label{prop epsilon-opt for zeta A}
	Let $x_a\in(0,\infty)$ be large enough. Then there exists a unique solution $\ol\zeta^{\mc{A}}(a,c)$ of \eqref{5.19.5} with boundary condition \eqref{5.19.5 boundary condition} in $[\ul a,\ul a+\epsilon^1_a(x_a)]\times[\ol c-\epsilon_a^2(x_a),\ol c]$ for some $\epsilon^1_a(x_a),\epsilon^2_a(x_a)>0$.
\end{mypr}

The next two propositions state that if the solutions of \eqref{5.19} and \eqref{5.19.5} exist and satisfy their respective boundary conditions \eqref{5.19 boundary condition} and \eqref{5.19.5 boundary condition}, then the solutions must be unique.

\begin{mypr}\label{prop on unique zeta C}
	If $\zeta_1^{\mc C},\zeta_2^{\mc C}:[\ul a,\ol a]\times[\ul c,\ol c]\to [0,\infty)$ are two differentiable solutions of the differential equation \eqref{5.19} satisfying the boundary condition \eqref{5.19 boundary condition} and both $B_1^{c}(\zeta_1^{\mc{C}}(a,c),a,c)$ and $B_1^{c}(\zeta_2^{\mc{C}}(a,c),a,c)$ do not vanish at any $(a,c)\in[\ul a,\ol c]\times[\ul c,\ol c]$, then $\zeta_1^{\mc C}$ and $\zeta_2^{\mc C}$ coincide.
\end{mypr}


\begin{mypr}
	If $\zeta_1^{\mc A},\zeta_2^{\mc A}:[\ul a,\ol a]\times[\ul c,\ol c]\to [0,\infty)$ are two differentiable solutions of the differential equation \eqref{5.19.5} satisfying the boundary condition \eqref{5.19.5 boundary condition} and both $B_1^{a}(\zeta_1^{\mc{A}}(a,c),a,c)$ and $B_1^{a}(\zeta_2^{\mc{A}}(a,c),a,c)$ do not vanish at any $(a,c)\in[\ul a,\ol a]\times[\ul c,\ol c]$, then $\zeta_1^{\mc A}$ and $\zeta_2^{\mc A}$ coincide.
\end{mypr}
\begin{proof}
	The proof is similar to the previous claim.
\end{proof}

The next two results are analogous to Lemmas \ref{W is cont diff} and \ref{Wxx inequality} from the finite set case. 

\begin{mylm}
	$W^{\ol\zeta}(x,a,c)$ is infinitely continuously differentiable at all $x\neq \ol\zeta^{\mc{A}}(a,c)$ and $x\neq \ol\zeta^{\mc{C}}(a,c)$. Moreover, $W^{\ol\zeta}(x,a,c)$ is continuously differentiable at the points $\ol\zeta^{\mc{A}}(a,c)$ and $\ol\zeta^{\mc{C}}(a,c)$.
\end{mylm}
\begin{proof}
	Since $b_0^a,b_0^c,b_1^a,b_1^c$ are infinitely continuously differentiable, then $W^{\ol\zeta}(x,a,c)$ is also infinitely continuously differentiable at all $x\neq \ol\zeta^{\mc{A}}(a,c)$ and $x\neq \ol\zeta^{\mc{C}}(a,c)$. $H^{\ol\zeta}$ defined in \eqref{H zeta} is continuously differentiable in $x$. Hence, by construction, $W^{\ol\zeta}(x,a,c)$ must also be continuously differentiable at the points $\ol\zeta^{\mc{A}}(a,c)$ and $\ol\zeta^{\mc{C}}(a,c)$.
\end{proof}

\begin{mylm}\label{lemma on Wxx closed int}
	It holds that $W^{\ol\zeta}_{xx}(\ol\zeta^{\mc{A}}(a,c)-,a,c)-W^{\ol\zeta}_{xx}(\ol\zeta^{\mc{A}}(a,c)+,a,c)\geq 0$ and $W^{\ol\zeta}_{xx}(\ol\zeta^{\mc{C}}(a,c)-,a,c)-W^{\ol\zeta}_{xx}(\ol\zeta^{\mc{C}}(a,c)+,a,c)\geq 0$.
\end{mylm}

We can now state the main result for the optimal strategies of the closed interval case. It states that under specific conditions, $W^{\ol\zeta}$ is the optimal value function over a neighborhood of $(\ul a,\ol c)$.

\begin{myth}\label{theorem on verification final}
	Write $\ol\zeta:=(\ol\zeta^{\mc{A}},\ol\zeta^{\mc{C}})$. Suppose $\ol c>\frac{q\sigma^2\ul a^2}{2(\mu \ul a-b)}$, $M(a)>0$, and $\frac{\partial }{\partial x}b_1^a(\ol\zeta^{\mc A}(a,c),a,c)N(c)\geq 0$ if $\mu a-2(b+c)<0$ and $\sigma<\sqrt{\frac{-\mu(\mu a-2(b+c))}{2qa}}$ or  $\frac{\partial }{\partial x}b_1^a(\ol\zeta^{\mc A}(a,c),a,c)N(c)> 0$ otherwise, where $M(a)$ and $N(c)$ are respectively defined in \eqref{H zeta solution a} and \eqref{H zeta solution c}. Then there exist $\epsilon_1,\epsilon_2>0$ such that $W^{\ol \zeta}=V$ in $[0,\infty)\times[\ul a,\ul a+\epsilon_1]\times[\ol c-\epsilon_2,\ol c]$, where $\ol\zeta:=(\ol\zeta^{\mc{A}},\ol\zeta^{\mc{C}})$, $\ol\zeta^{\mc{C}}$ is the unique solution of \eqref{5.19} with boundary condition \eqref{5.19 boundary condition}, and $\ol\zeta^{\mc{A}}$ is the unique solution of \eqref{5.19.5} with boundary condition \eqref{5.19.5 boundary condition}.
\end{myth}
In other words, $W^{\ol\zeta}$ is $(\epsilon_1,\epsilon_2)$-optimal. It must be noted that the theorem does not state that $W^{\ol\zeta}$ is no longer optimal outside the specified interval. Similar to the result in \cite{albrecher2022}, the proof for the general intervals $[\ul a,\ol a]$ and $[\ul c,\ol c]$ would be a potential extension of Theorem \ref{theorem on verification final}.

\begin{myrem}
	Suppose either $\mu a-2(b+c)\geq 0$ or $\mu a-2(b+c)<0$ and $\sigma\geq \sqrt{\frac{-\mu(\mu a-2(b+c))}{2qa}}$ holds. The condition $\frac{\partial }{\partial x}b_1^a(\ol\zeta^{\mc A}(a,c),a,c)N(c)=0$ is equivalent to $N(c)=0$ since  $\frac{\partial }{\partial x}b_1^a(\ol\zeta^{\mc A}(a,c),a,c)\neq 0$ from Proposition \ref{zeta implicit equations}. If these conditions are satisfied, then, from Lemma \ref{sign of 2nd partial b_0^a} and the boundary condition $K^{\ol\zeta}(\ul a,\ol c)=0$, we have that
	\begin{align*}
		B^a_{xx}(x_a,\ul a,\ol c)=-\frac{\partial^2 b_0^a}{\partial x^2}(x_a,\ul a,\ol c)-\frac{\partial^2 b_1^a}{\partial x^2}(x_a,\ul a,\ol c)K^{\ol\zeta}(\ul a,\ol c)=-\frac{\partial^2 b_0^a}{\partial x^2}(x_a,\ul a,\ol c)<0.
	\end{align*}
	This implies that $B^a_{xx}(x,a,c)<0$ in some neighborhood
	\begin{align*}
		U_a:=(x_a-\epsilon_a,x_a+\epsilon_a)\times[\ul a,\ul a+\epsilon_a)\times(\ol c-\epsilon_a\ol c]\subset [0,\infty)\times[\ul a,\ul a+\epsilon_a^1]\times[\ol c-\epsilon_a^2,\ol c].
	\end{align*}
	Moreover, the function $B^a(\cdot,a,c)$ reaches a strict local maximum at $x=\ol\zeta^{\mc{A}}(a,c)$, which leads to $B^a(x,a,c)<0$ for some neighborhood of $(x_a,\ul a,\ol c)$. This yields a function $W^{\ol\zeta}\neq V$, that is, $W^{\ol\zeta}$ is not the desired optimal value function, since $W^{\ol\zeta}_a(x,a,c)\leq 0$ for $x\in(0,\ol\zeta^{\mc{A}}(a,c))$. The same analysis can be made for when the condition $M(a)=0$ is satisfied.
\end{myrem}

\section{Numerical Examples}\label{section:examples}


%Discrete Case #5.R 
Consider the case $\mu=6$, $\sigma=1.5$, $b=2$, $q=0.1$, $\mc{A}=\{0.80,0.90\}$, and $\mc{C}=\{2,4\}$. We obtain the following optimal threshold levels: $z^*_{1,1}=13.04$ and $y^*_{1,2}=348.5$. The sequence of reinsurance-dividend level changes follows $(0.9,2)\stackrel{x=13.04}{\longrightarrow}(0.9,4)\stackrel{x=348.5}{\longrightarrow}(0.8,4)$ as illustrated in Figures \ref{fig:plot-1-v1} and \ref{fig:plot-1-v2}. The optimal strategy is to increase the dividend level first and then decrease the retained proportion of incoming claims if ruin time does not occur before or within these level changes. In Figure \ref{fig:plot-1-v2}, we can see that $W^{y^*,z^*}(x,a_1,c_1)$ (in red) is greater than $W^{y^*,z^*}(x,a_1,c_2)$ (in blue) when $x<z^*_{1,1}$.

%Discrete Case #6.5.R
Consider the case $\mu=10$, $\sigma=1.5$, $b=2$, $q=0.1$, $\mc{A}=\{0.80,0.90\}$, and $\mc{C}=\{2,4\}$. We obtain the following optimal threshold levels: $y^*_{1,1}=0$, and $z^*_{2,1}=1.92$. The sequence of reinsurance-dividend level changes follows $(0.90,2)\stackrel{x=0}{\longrightarrow}(0.80,2)\stackrel{x=1.92}{\longrightarrow}(0.80,4)$ and is illustrated in Figure \ref{fig:plot-2-v1}. The curves $W^{y^*,z^*}(x,a_1,c_1)$ and $W^{y^*,z^*}(x,a_2,c_1)$ coincide since it is optimal to increase the reinsurance level right away assuming that the initial reserve level is positive. The dividend level is then increased as soon as the reserve reaches the threshold level $z^*_{2,1}=1.92$. 

It is also interesting to note that in the second setup, we have $\mu a_1-2(b+c_1)<0$ and $\sigma<\sqrt{\frac{-\mu(\mu a_1-2(b+c_1))}{2qa_1}}$, which implies that $\frac{\partial}{\partial a}\theta_2(a,c)<0$. In the first setup, we have $\mu a_1-2(b+c_1)>0$, which implies that $\frac{\partial}{\partial a}\theta_2(a,c)>0$.

%Discrete Case 33 #3.R
Finally, consider the case $\mu=10$, $\sigma=1.5$, $b=2$, $q=0.1$, $\mc{A}=\{0.80,0.85,0.90\}$, and $\mc{C}=\{2,3,4\}$. In this scenario, the maximum dividend and the minimum retention levels are the same as the previous examples. The main difference is that there is an intermediate level before reaching the extremes. We obtain the following optimal threshold levels: $y^*_{1,1}=0$, $z^*_{2,1}=1.56$, $z^*_{2,2}=1.91$, and $y^*_{2,3}=9.79$. The sequence of reinsurance-dividend level changes follows $(0.90,2)\stackrel{x=0}{\longrightarrow}(0.85,2)\stackrel{x=1.56}{\longrightarrow}(0.85,3)\stackrel{x=1.91}{\longrightarrow}(0.85,4)\stackrel{x=9.79}{\longrightarrow}(0.80,4)$ as illustrated in Figures \ref{fig:plot-3-v1} and \ref{fig:plot-3-v2}. Similar to the second example, the optimal strategy is to increase the reinsurance level immediately. The dividend level is then maximized first before maximizing the reinsurance level if the ruin time does not occur before or within these level changes.

