\section{Derivation of the governing equations for the MNLD model}
\label{Apx:psi_defination}

Here we present the derivation of the governing equations for the Modified non-local Damage (MNLD) model. The Helmholtz free energy density is defined as:
\begin{equation}
\psi (\varepsilon_{ij},\bar\varepsilon,d) = \dfrac{1}{2} [(1-d) + f_a] \varepsilon_{ij} C_{ijkl} \varepsilon_{kl} + \dfrac{1}{2}h \left[({f_r \varepsilon} - \bar\varepsilon)^2 + c \bar\varepsilon_{,i}^2 \right]
\end{equation}

The derivatives of the free energy with respect to the state variables $d$,$\varepsilon_{ij}$ and $\bar\varepsilon$ are:
\begin{equation}
\dfrac{\partial \psi}{\partial \varepsilon_{ij}} =  [(1-d) + f_a] C_{ijkl} \varepsilon_{kl} + h(f_r \varepsilon - \bar\varepsilon) \dfrac{\partial \varepsilon}{\partial \varepsilon_{ij}}
\end{equation}

\begin{equation}
\dfrac{\partial \psi}{\partial \bar\varepsilon} =
 - h ((f_r\varepsilon - \bar\epsilon)
+
h c \bar\varepsilon_{,i} 
\end{equation}

\begin{equation}
\frac{\partial \psi}{\partial d} = \frac{1}{2} \left[-1 + \dfrac{\partial f_a}{\partial d} \right] \varepsilon_{ij} C_{ijkl} \varepsilon_{kl} - h \left( f_r\varepsilon - \bar{\varepsilon} \right) \varepsilon
\end{equation}

\begin{equation}
Y = -\frac{\partial \psi}{\partial d} = \frac{1}{2} \left[1 - \dfrac{\partial f_a}{\partial d} \right] \varepsilon_{ij} C_{ijkl} \varepsilon_{kl} + h \left( f_r\varepsilon - \bar{\varepsilon} \right) \varepsilon \dfrac{\partial f_r}{\partial d}
\end{equation}

The term $\dfrac{\partial f_r}{\partial d}$ becomes zero for large values of $n$ and $d<1$. For thermodynamic consistency, the following global dissipation inequality must be satisfied:

\begin{equation}
\dot{\mathscr{D}} = \int_V (\sigma_{ij} \dot{\varepsilon_{ij}} - \dot{\psi}) dV \geq 0
\end{equation}

\begin{align}
\dot{\mathscr{D}} & = \int_V \left(\sigma_{ij} \dot{\varepsilon_{ij}} 
-
\left[
\dfrac{\partial \psi}{\partial \varepsilon_{ij}} \dfrac{\partial \varepsilon_{ij}}{\partial t} 
+ 
\dfrac{\partial \psi}{\partial d} \dfrac{\partial d}{\partial t} 
+
\dfrac{\partial \psi}{\partial \bar\epsilon} \dfrac{\partial \bar\epsilon}{\partial t} 
\right]
\right) dV  \\
& =
\int_V \underbrace{\sigma_{ij} \dot{\varepsilon_{ij}} 
- 
\dot{\varepsilon_{ij}} \left[[(1-d)+ f_a] C_{ijkl} \varepsilon_{kl} + h(f_r \varepsilon - \bar\varepsilon) \dfrac{\partial \varepsilon}{\partial \varepsilon_{ij}}\right]}_{\dot{\mathscr{D}_{\varepsilon_{ij}}}} \\
& \underbrace{+ \dot{d} \left[ \frac{1}{2} \left[-1 + \dfrac{\partial f_a}{\partial d} \right]\varepsilon_{ij} C_{ijkl} \varepsilon_{kl} - h \left( f_r\varepsilon - \bar{\varepsilon} \right) \varepsilon \right]}_{\dot{\mathscr{D}_{d}}}
\underbrace{+ \dot{\bar\varepsilon} \left[
 - h (f_r\varepsilon - \bar\epsilon)
+
h c \bar\varepsilon_{,i}   \right] }_{\dot{\mathscr{D}_{\bar\varepsilon}}} dV
\end{align}

\begin{equation}
\dot{\mathscr{D}} = \dot{\mathscr{D}_{\varepsilon_{ij}}} + \dot{\mathscr{D}_{d}} + \dot{\mathscr{D}_{\bar\varepsilon}} \geq 0
\end{equation}

The governing equations are obtained from the non-dissipative terms $\dot{\mathscr{D}_{\varepsilon_{ij}}} $ and $\dot{\mathscr{D}_{\bar\varepsilon}}$.

\subsection{$\dot{\mathscr{D}_{\varepsilon_{ij}}}$}
\begin{align}
\dot{\mathscr{D}_{\varepsilon_{ij}}} & = 0
\end{align}


\begin{align}
\int_V \dot{\varepsilon_{ij}} \left[\sigma_{ij}  
- 
 \left[[(1-d)+ f_a] C_{ijkl} \varepsilon_{kl} + h(f_r \varepsilon - \bar\varepsilon) \dfrac{\partial \varepsilon}{\partial \varepsilon_{ij}}\right] \right] \ dV = 0
\end{align}

Thus, 

\begin{equation}
\sigma_{ij}  
 = 
 \left[[(1-d)+ f_a] C_{ijkl} \varepsilon_{kl} + h(f_r \varepsilon - \bar\varepsilon) \dfrac{\partial \varepsilon}{\partial \varepsilon_{ij}}\right]
 \label{New_stress_definition}
\end{equation}

The expression in Eqn. \ref{New_stress_definition} represents the new definition of stress. 


\subsection{$\dot{\mathscr{D}_{\bar\varepsilon}}$}

\begin{equation}
\dot{\mathscr{D}_{\bar\varepsilon}} = 0
\end{equation}

\begin{equation}
\int_V \dot{\bar\varepsilon} \left[
 - h (f_r\varepsilon - \bar\epsilon)
+
h c \bar\varepsilon_{,i}   \right] \ dV  = 0
\end{equation}

\begin{equation}
\int_V \dot{\bar\varepsilon} \left[
h (f_r\varepsilon - \bar\epsilon)
+
h c \bar\varepsilon_{,ii}  \right] \ dV  - \int_S - \dot{\bar\varepsilon} h c \bar\varepsilon_{,i} n_i\ dS= 0
\end{equation}

Following earlier derivations of non-local gradient relationships (e.g. \cite{peerlings2004thermodynamically, mobasher2018thermodynamic}), the localization of the above equation leads to:
\begin{equation}
\left[
 (f_r\varepsilon - \bar\epsilon)
+
 c \bar\varepsilon_{,ii}  \right] = 0~~  \text{in}~ V 
\end{equation}

\begin{equation}
\varepsilon_{,i} n_i = 0~~  \text{on}~ S
\end{equation}

