%     \bm{E}_{\bm{Z}\sim \bm{q}(\bm{Z})} \big[\frac{1}{C}\sum_{c=1}^C \log \bm{P}(\bm{t}^{(c)},\bm{Z};\bm{\Omega}) - \log \bm{q}(\bm{Z}) \big],
% \end{align}
% where $\bm{q}(\bm{Z})$ is an arbitrary distribution of $\bm{Z}$. The loglikelihood function is uniformly larger than (\ref{eq_11_2}) over $\bm{\Omega}$, and coincides with (\ref{eq_11_2}) when $\bm{q}(\bm{Z}) =  \prod_{c=1}^C\prod_{i = 1}^N \bm{P}(Z_i^c \mid \bm{t}^{(c)}; \bm{\Omega})$.   
% In addition, we replace the low-rank penalty by its convex relaxation of nuclear norm. 
% Therefore, the objective function is 
\begin{align*}%\label{eq_11_2}
    \argmax_{\bm{q}(\bm{Z}), \bm{\Omega}} & \mathbb{E}_{\bm{q}(\bm{Z})} \big[\frac{1}{C}\sum_{c=1}^C \log \mathbb{P}(\bm{t}^{(c)},\bm{Z};\bm{\Omega})\big] - \big[ \mathbb{E}_{\bm{q}(\bm{Z})} \log \bm{q}(\bm{Z}) \big]\; %\\ \nonumber
    %\label{eq_13} 
    \text{s.t. } \bm{\Theta}\odot (\bm{I}-\bm{A}) = \bm{0}, \; \|\bm{\Psi}\|_{\star} \leq \rho,
\end{align*}
where $\mathbb{E}_{\bm{q}(\bm{Z})}$ is expectation of $\bm{Z}$ in terms of a factorizable distribution as $\bm{q}(\bm{Z}) =  \prod_{c=1}^C\prod_{i = 1}^N \mathbb{P}(Z_i^c \mid \bm{t}^{(c)}; \bm{\Omega})$. 
%$\bm{q}(\bm{Z})$ is an arbitrary distribution of $\bm{Z}$. Note that the log-likelihood function is uniformly larger than the objective in (\ref{eq_11_2}) over $\bm{\Omega}$, and coincides with it when $\bm{q}(\bm{Z}) =  \prod_{c=1}^C\prod_{i = 1}^N \bm{P}(Z_i^c \mid \bm{t}^{(c)}; \bm{\Omega})$.
The above objective function can be optimized via EM-type algorithm by iteratively updating $\bm{q}(\bm{Z})$ and $\bm{\Omega}$. Specifically, given the parameters $\bm{\Omega}^{(m)}$ at the $m$-th step:
\begin{align*} 
    &\textbf{E-step:} \hspace{35mm} \bm{q}(\bm{Z};\bm{\Omega}^{(m)}) = \prod_{c=1}^C\prod_{i = 1}^N \mathbb{P}(Z_i^c \mid \bm{t}^{(c)}; \bm{\Omega}^{(m)})\\
    &\textbf{M-step:} \; \bm{\Omega}^{(m+1)} \! = \!\argmax_{\bm{\Omega}} \frac{1}{C}\sum_{c=1}^{C }\mathbb{E}_{\bm{q}(\bm{Z};\bm{\Omega}^{(m)})} \big[ \log  \mathbb{P}(\bm{t}^{(c)}\!,\bm{Z};\bm{\Omega})  \big]\;  
     \text{s.t. }  \bm{\Theta}\!\odot\! (\bm{I}-\bm{A}) = 0, \|\bm{\Psi}\|_{\star}\! \leq \!\rho.
    %& \text{subject to }  \|\bm{\Theta} \odot \bm{A} \|_1 \leq s_1, \; \|\bm{\Psi}\|_{\star} \leq s_2.
\end{align*}
In E-step, the posterior distribution of network indicators $\hat{\pi}_i^{c} = \mathbb{P}(Z_i^c \mid \bm{t}^{(c)}; \bm{\Omega}^{(m)})$ can be explicitly updated via ($\ref{E_step}$).
In M-step, the objective function $\bm{Q}(\bm{\Omega}\mid \bm{\Omega}^{(m)}) := \frac{1}{C}\sum_{c=1}^{C }\mathbb{E}_{\bm{q}(\bm{Z};\bm{\Omega}^{(m)})} \big[ \log  \mathbb{P}(\bm{t}^{(c)},\bm{Z};\bm{\Omega})\big] $ can be decomposed as $\bm{Q}(\bm{\Omega}\mid \bm{\Omega}^{(m)}) = \bm{Q}_1(\bm{\Theta}\mid \bm{\Omega}^{(m)}) + \bm{Q}_2(\bm{\Psi}\mid \bm{\Omega}^{(m)}) + \bm{Q}_3(\bm{\pi}\mid \bm{\Omega}^{(m)})$, and $\bm{Q}_1(\bm{\Theta} \mid \bm{\Omega}^{(m)}) = \frac{1}{C}\sum_{c=1}^C \sum_{i=1}^N g_1(i,c)$, $\bm{Q}_2(\bm{\Psi} \mid \bm{\Omega}^{(m)}) = \frac{1}{C}\sum_{c=1}^C \sum_{i=1}^N g_2(i,c)$, $\bm{Q}_3(\bm{\pi} \mid \bm{\Omega}^{(m)}) = \frac{1}{C}\sum_{c=1}^C \sum_{i=1}^N g_3(i,c)$, where 
\begin{align*}
    &g_1(i,c) := \hat{\pi}_{i}^c\log\big\{ \mathbbm{1}( t^c_i<T) \mathbb{P}_{I}(t^c_i; \bm{\Theta}_{\cdot i}) + \mathbbm{1}( t^c_i\geq T) \mathbb{P}_{U}(T; \bm{\Theta}_{\cdot i})\big\}\\
    &g_2(i,c) := (1-\hat{\pi}_{i}^c)\log\big\{ \mathbbm{1}( t^c_i<T) \mathbb{P}_{I}(t^c_i; \bm{\Psi}_{\cdot i}) + \mathbbm{1}( t^c_i\geq T) \mathbb{P}_{U}(T; \bm{\Psi}_{\cdot i})\big\}\\
    &g_3(i,c): = \hat{\pi}_i^c\log \pi_i + (1 - \hat{\pi}_i^c)\log (1 - \pi_i),   
\end{align*}
and $\{\hat{\pi}_i^c\}$ depends on $\bm{\Omega}^{(m)}$ via (\ref{E_step}). Then $\bm{\Theta}$, $\bm{\Psi}$, and $\bm{\pi}$ can be updated parallelly as
\begin{align}
    &\text{M.1}: \bm{\Theta}^{(m+1)} =  \argmax_{\bm{\Theta}} \bm{Q}_1(\bm{\Theta}\mid \bm{\Omega}^{(m)})\; \text{ s.t. }\; \bm{\Theta}\odot (\bm{I}-\bm{A}) = \bm{0} \label{eq_12} \\
    &\text{M.2}: \bm{\Psi}^{(m+1)} =  \argmax_{\bm{\Psi}} \bm{Q}_2(\bm{\Psi}\mid \bm{\Omega}^{(m)})\; \text{ s.t. }\; \|\bm{\Psi}\|_{\star} \leq \rho \label{eq_12_2}\\
    &\text{M.3}: \bm{\pi}^{(m+1)} =  \argmax_{\bm{\pi}} \bm{Q}_3(\bm{\pi}\mid \bm{\Omega}^{(m)}) \label{eq_12_3}.
\end{align}
%where the explicit forms of $\bm{Q}_1(\bm{\Theta}\mid \bm{\Omega})$, $\bm{Q}_2(\bm{\Psi}\mid \bm{\Omega})$, and $\bm{Q}_3(\bm{\pi}\mid \bm{\Omega})$ are provided in Appendix. 
When the structural network $\bm{A}$ is not observed, one can impose $l_1$ norm penalty to pursue sparsity structure in $\bm{\Theta}$. Accordingly, the constraint in optimization (\ref{eq_12}) is replaced by $\| \bm{\Theta} \|_1 \leq s' $ where $s'>0$ is the sparsity tuning parameter. %Then the sparse $\bm{\Theta}$ and low-rank $\bm{\Psi}$ diffusion matrices are identifiable based on Proposition 2. 
The main advantage of the proposed estimation is that the M-step becomes convex optimization problems. Specifically, denote parameter spaces $\bm{\Xi}_{\bm{\Theta}}(s): = \{ \bm{\Theta} \in  [0,\beta_1]^{N\times N} \mid \bm{\Theta}\odot (\bm{I}- \bm{A}) =\bm{0}\} $ with $s = \| \bm{A} \|_0$, $\bm{\Xi}_{\bm{\Psi}}(\rho):= \{  \bm{\Psi} \in  [0,\beta_2]^{N\times N} \mid  \| \bm{\Psi} \|_{\star} \leq \rho \}$, and $\bm{\Xi}_{\bm{\pi}}: = \{ \bm{\pi} \in [\epsilon,1-\epsilon]^N\}$ where $\beta_1,\beta_2$ are nonnegative constants and $0< \epsilon < 0.5$. We have the following result:  
\begin{theorem}
The parameter spaces $\bm{\Xi}_{\bm{\Theta}}(s)$, $\bm{\Xi}_{\bm{\Psi}}(\rho)$, and $\bm{\Xi}_{\bm{\pi}}$ are convex set for any $s>0,\; \rho>0$, and $\bm{Q}_3(\bm{\pi}\mid \bm{\Omega}^{(s)})$ is concave on $\bm{\pi}$. 
%If the hazard function $H(t\mid t',\lambda)$ satisfies $\frac{\partial H^2(t\mid t',\lambda)}{\partial \lambda^2} \geq 0$ for $t \geq t'$, 
If the survival function $S$ is log-concave and hazard function $H$ is concave, 
then $\bm{Q}_1(\bm{\Theta}\mid \bm{\Omega}^{(s)})$ and $\bm{Q}_2(\bm{\Psi}\mid \bm{\Omega}^{(s)})$ are concave on $\bm{\Theta}$ and $\bm{\Psi}$, respectively. Furthermore, if for any node $i$, the probabilities of being source node $\bm{P}(v)>0$ for $v \in \mathcal{R}$ where $\mathcal{R}$ denotes the set of nodes from which $i$ is reachable via a directed path, then $\mathbb{E}_{\bm{t}}[\bm{Q}_1(\bm{\Theta}\mid \bm{\Omega}^{(s)})]$ and $\mathbb{E}_{\bm{t}}[\bm{Q}_2(\bm{\Psi}\mid \bm{\Omega}^{(s)})]$ are also strictly concave in terms of $\bm{\Theta}$ and $\bm{\Psi}$, respectively.  
\end{theorem}
The assumption on survival function can be satisfied by popular risk models including Exp, Pow, and Ray model, and other additive risk models. 
Theorem 3.1 guarantees that each sub-optimization (\ref{eq_12}), (\ref{eq_12_2}), and (\ref{eq_12_3}) in the M-step is convex optimization, and hence has an unique and optimal solution. The tuning parameter of low-rank penalty in (\ref{eq_12_2}) can be adaptively selected. Specifically, we first randomly separate the total cascade samples into a training subset $C_{train}$ and a validation subset $C_{val}$, and estimate model parameters $\bm{\hat{\Omega}}_{\mu}$ on $C_{train}$ given a specific $\mu$. Then we calculate the log-likelihood of validation samples as $\frac{1}{|C_{val}|}\sum_{c\in C_{val}} \log \mathbb{P}(\bm{t}^{(c)}, \bm{\hat{\Omega}}_{\mu})$, and select $\mu$ such that 
$$  \mu = \argmax_{\mu \in \bm{G}} \frac{1}{|C_{val}|}\sum_{c\in C_{val}} \log \bm{P}(\bm{t}^{(c)}, \bm{\hat{\Omega}}_{\mu}),$$
where $\bm{G}$ is a grid of candidates for penalty values. We summarize the optimization and more optimization details in Appendix.
