\section{Theory}


In this section, we establish both computational and statistical convergence of the model parameter estimation based on the concavity of auxiliary function $\bm{Q}(\bm{\Omega}\mid \bm{\Omega}')$. Let $\bm{\Omega}^{\star}: = \{\bm{\Theta}^{\star}, \bm{\Psi}^{\star}, \bm{\pi}^{\star} \} \in  \bm{\Xi}_{\Omega}(s,\rho)$ be the true model parameters where $\bm{\Xi}_{\Omega}(s,\rho):= \bm{\Xi}_{\bm{\Theta}}(s) \times \bm{\Xi}_{\bm{\Psi}}(\rho) \times  \bm{\Xi}_{\bm{\pi}}$. We follow the notations in Section \ref{sec-3}, and introduce parameter space metric as $\| \bm{\Omega} - \bm{\Omega}'\|^2: = \| \bm{\Theta} - \bm{\Theta}'\|^2_{F} + \| \bm{\Psi} - \bm{\Psi}'\|^2_{F} + \| \bm{\pi} - \bm{\pi}'\|^2_{2}$ where $\bm{\Omega}, \; \bm{\Omega}' \in \bm{\Xi}_{\Omega}$. Denote $\bm{\hat{\pi}}_{\bm{c}} = ( \hat{\pi}^c_1,\cdots, \hat{\pi}^c_N)$ where $\hat{\pi}^c_i$ is the posterior probability defined in (\ref{E_step}). To establish theoretic guarantee, assumptions required as as follows. 

\begin{assumption}
For any fixed $\bm{\Omega}, \; \bm{\Omega}' \in \bm{\Xi}_{\Omega}(s,\rho)$, there exists $\epsilon_{\bm{\Theta}}(C,\delta)>0,\epsilon_{\bm{\Psi}}(C,\delta)>0, \epsilon_{\bm{\pi}}(C,\delta)>0$ such that with probability at least $1 - \delta$: 
  $\|  \frac{\partial \bm{Q}_1(\bm{\Theta}\mid \bm{\Omega}')}{\partial \bm{\Theta}} - \mathbb{E}_{\bm{t}}(\frac{\partial \bm{Q}_1(\bm{\Theta}\mid \bm{\Omega}')}{\partial \bm{\Theta}} )\|_{F} \leq \epsilon_{\bm{\Theta}}(C,\delta)$,
$\|\frac{\partial \bm{Q}_2(\bm{\Psi}\mid \bm{\Omega}')}{\partial \bm{\Psi}} - \mathbb{E}_{\bm{t}}(\frac{\partial \bm{Q}_2(\bm{\Psi}\mid \bm{\Omega}')}{\partial \bm{\Psi}} )\|_{F} \leq \epsilon_{\bm{\Psi}}(C,\delta)$, 
$ \| \frac{1}{C}\sum_{c=1}^C \bm{\hat{\pi}}_{\bm{c}} - \mathbb{E}_{\bm{t}}(\bm{\hat{\pi}}_{\bm{c}}) \|_{2} \leq \epsilon_{\bm{\pi}}(C,\delta)$,
where $C$ is the number of cascade samples and $0<\delta<1$.
\end{assumption}
Assumption 1 quantifies the deviations of sample gradients of auxiliary function on $(\bm{\Theta},\bm{\Psi}, \bm{\pi})$ from their population counterparts, where $\epsilon_{\bm{\Theta}}, \epsilon_{\bm{\Psi}},\epsilon_{\bm{\pi}}$ characterize finite-samples statistical errors. Conditions similar to Assumption 1 are utilized in \citep{10.1214/16-AOS1435, yi2015regularized} to analyze convergence of EM algorithm.  

\begin{assumption}
  For any $\bm{\Omega}, \; \bm{\Omega}' \in \bm{\Xi}_{\Omega}$, there exists constant $\kappa_{\bm{\pi}}>0$ such that $\| \mathbb{E}_{\bm{t}}\big(\bm{\hat{\pi}_{c}}(\bm{\Omega})\big) - \mathbb{E}_{\bm{t}}\big(\bm{\hat{\pi}_{c}}(\bm{\Omega}')\big) \|_2^2 \leq  \kappa_{\bm{\pi}} \|  \bm{\Omega} - \bm{\Omega}'\|^2$. 
\end{assumption}
Assumption 2 states that the posterior probability of network indicator ${Z_i^c}$ is continuous over $\bm{\Omega}$. Intuitively, Assumption 2 plays the similar role of gradient smoothness condition in \citep{10.1214/16-AOS1435, yi2015regularized, wang2014high} to ensure that auxiliary function $ \mathbb{E}_{\bm{t}}(\frac{\partial\bm{Q}(\bm{\Omega\mid \bm{\Omega}'})}{\partial \bm{\Omega}})$ is smooth over $\bm{\Omega}'$. Notice that $\kappa_{\bm{\pi}}$ implicitly depends on the separability of true diffusion networks as $\| \bm{\Theta}^{\star} - \bm{\Psi}^{\star} \|_2$. 

%corresponding to the posterior distribution of missing data. 
%However, Assumption 2 relaxes the gradient smoothness condition due to the continuity of $\mathbb{E}_{\bm{t}}\big(\bm{\hat{\pi}_{c}}(\bm{\Omega})\big)$ is easier to validate and satisfy due to the explicit form of $\bm{\hat{\pi}_{c}}$ in our model.   

\begin{assumption}
    The log-likelihoods of cascade $\bm{t}^{(c)}$ over networks $\bm{\Theta}$ and $\bm{\Psi}$ are $g_1(c): = \sum_{i=1}^Ng_1(i,c)$ and $g_2(c): = \sum_{i=1}^Ng_2(i,c)$. Let $\lambda_{min}$ denote the smallest eigenvalue.
    For all cascade samples $\{\bm{t}^{(c)}\}_{c=1}^C$,
    there exists constant $L>0$ such that 
    \begin{align*}
        \big| \lambda_{min}\Big( \frac{\partial^2 g_1(c)}{\partial\bm{\Theta}^2}   \Big) \big| \leq L, \; \big| \lambda_{min}\Big( \frac{\partial^2 g_2(c)}{\partial\bm{\Psi}^2} \Big) \big| \leq L. 
         \end{align*}
\end{assumption}
%Notice that $g_1(c)$ and $g_2(c)$ are concave, and therefore the corresponding Hessian matrices are negative semi-definite. 
Assumption 3 is a regularity condition requiring eigenvalues are bounded, which guarantee the smoothness of $\bm{Q}(\bm{\Omega}\mid \bm{\Omega}')$ over $\bm{\Omega}$. Denote the smallest and largest eigenvalues of Hessian matrices $\mathbb{E}_{\bm{t}}\big[\frac{\partial^2 \bm{Q}_1(\bm{\Theta}\mid \bm{\Omega}')}{\partial\bm{\Theta}^2} \big]$ and $\mathbb{E}_{\bm{t}}\big[\frac{\partial^2 \bm{Q}_1(\bm{\Psi}\mid \bm{\Omega}')}{\partial\bm{\Psi}^2} \big]$ as $\lambda_{min}(\bm{\Theta},\bm{\Omega}'), \lambda_{min}(\bm{\Psi},\bm{\Omega}')$ and $\lambda_{max}(\bm{\Theta},\bm{\Omega}'), \lambda_{max}(\bm{\Psi},\bm{\Omega}')$. Notice that both smallest and largest eigenvalues are continuous functions of the corresponding Hessian matrices \citep{horn2012matrix}, which are continuous on $\bm{\Theta},\bm{\Psi},\bm{\Omega}'$.
Then there exist constants $0< \gamma_l < \gamma_u $ such that $|\max_{\bm{\Xi_{\Theta}}(s)\times \bm{\Xi_{\Omega}}}\lambda_{max}(\bm{\Theta},\bm{\Omega}')| \geq \gamma_l$, $|\max_{\bm{\Xi_{\Psi}}(\rho)\times \bm{\Xi_{\Omega}}}\lambda_{max}(\bm{\Psi},\bm{\Omega}')| \geq \gamma_l$, and $|\min_{\bm{\Xi_{\Theta}}(s)\times \bm{\Xi_{\Omega}}}\lambda_{min}(\bm{\Theta},\bm{\Omega}')| \leq \gamma_u$,  $|\min_{\bm{\Xi_{\Psi}}(\rho)\times \bm{\Xi_{\Omega}}}\lambda_{min}(\bm{\Psi},\bm{\Omega}')| \leq \gamma_u$ based on the strong concavity of $\mathbb{E}_{\bm{t}}(\bm{Q}_1(\bm{\Theta}\mid \bm{\Omega}'))$ and $\mathbb{E}_{\bm{t}}(\bm{Q}_2(\bm{\Psi}\mid \bm{\Omega}'))$ from Theorem 3.1, and compactness of $\bm{\Xi}_{\bm{\Theta}}(s) \times \bm{\Xi}_{\bm{\Psi}}(\rho) \times  \bm{\Xi}_{\bm{\pi}}$. 
