\section{Geometrical computations} \label{sec:appendix_geometry}
\vspace{-0.3cm}
%
The expression for the local altitude along the line of sight $h\qty(r)$ (where $r$ is ranging from $0$ to $R$) is given by solving the triangle $\qty(h\qty(r)+R_{\bigoplus}, r, R_{\bigoplus})$. Which gives
%
\begin{align} \label{eq:hlocal}
    h\qty(r) = - R_{\bigoplus} + \sqrt{r^2 + R_{\bigoplus}^2 - 2r R_{\bigoplus} \cos{\qty(\gamma)}} \ .
\end{align}
%
From the triangle $\qty(h_X + R_{\bigoplus}, L_X, R_{\bigoplus})$ we obtain the local altitude for the $X_{\rm max}$ location
%
\begin{align}
    h_X = -R_{\bigoplus} + \sqrt{L_X^2+R_{\bigoplus}^2 + 2L_X R_{\bigoplus}\cos{\qty(\theta)}} \ ,
\end{align}
%
with $L_X$ being the longitudinal distance between $X_{\rm max}$ and the ground.
In the triangle $\qty(h_X + R_{\bigoplus}, R_X, R_{\bigoplus})$ we derive the distance between an observer (located in the direction defined by $\omega$ w.r.t the shower axis) and $X_{\rm max}$
%
\begin{align}
   R_X = \qty(h_X + R_{\bigoplus})\cos{\qty(\bar{\theta}+\omega)} \pm \sqrt{R_{\bigoplus}^2 - \qty(h_X + R_{\bigoplus})^2 \sin^2{\qty(\bar{\theta}+\omega)}} \ ,
\end{align}
%
after solving the second order polynomial in $R_X$, and where $\bar{\theta}$ is the local zenith angle of the shower.
Using the triangle $\qty(ct', R_X, R)$ we have the distance between an emission point (located at $ct'$ along the shower axis) and an observer
%
\begin{align}
    R = \sqrt{\qty(ct')^2 + R_X^2 - 2ct' R_X \cos{\qty(\omega)}} \ .
\end{align}
%
The local height $h_0$ of an emission point along the shower axis is defined from the triangle $\qty(h_0+R_{\bigoplus}, L_X -ct', R_{\bigoplus})$, which gives
%
\begin{align}
    h_0 = - R_{\bigoplus} + \sqrt{\qty(L_X - ct')^2 + R_{\bigoplus}^2 + 2\qty(L_X - ct')R_{\bigoplus} \cos{\qty(\theta)}} \ .
\end{align}
%
The angle $\gamma$ defining the direction of the line of sight from the observer location is obtained from the triangle $\qty(h_0+R_{\bigoplus}, R, R_{\bigoplus})$
%
\begin{align}
   \cos{\qty(\gamma)} = \frac{R^2 - h_0^2 - 2h_0 R_{\bigoplus}}{2 R R_{\bigoplus}} \ .
\end{align}
%
The angle $\bar{\theta}$ defining the local zenith angle can be obtained from the triangle $\qty(R_{\bigoplus}, L_X, h_X + R_{\bigoplus})$
%
\begin{align}
   \cos{\qty(\bar{\theta})} = \frac{L_X + R_{\bigoplus} \cos{\qty(\theta)}}{h_X + R_{\bigoplus}} \ .
\end{align}
%
In the case of a curved ground, there is a maximal value for $\omega$ beyond which no light path can be drawn from the $X_{\rm max}$ point and the observer, because the observer is below the horizon
%
\begin{align}
    \omega_{\rm max} = \arcsin{\qty(\frac{R_{\bigoplus}}{h_X + R_{\bigoplus}})} - \bar{\theta} \ ,
\end{align}
%
this is also true for any emission point at an altitude below $X_{\rm max}$ (obtained by replacing $h_X$ by $h_0$).


