\section{Refractive index computations} \label{sec:appendix_refractive_index}
\vspace{-0.3cm}
%
To integrate the effective refractive index as defined in Sec.~\ref{sec:refrac_index}, we develop $h\qty(r)$ (Eq.~\ref{eq:hlocal}) at the second order in terms of $r/R_{\bigoplus}$, which gives
%
\begin{align}
    h\qty(r) \approx -r \cos{\qty(\gamma)} + \frac{1}{2}\frac{r^2}{R_{\bigoplus}}\qty(1 -{\cos^2{\qty(\gamma)}}) + \mathcal{O}\qty(\frac{r^3}{R_{\bigoplus}^3}) \ .
\end{align}
%
Injecting the above expression into the effective refractive index expression (Eq.~\ref{eq:effective_refractive_index}), leads to
%
\begin{align}
      \expval{n\qty(R)} &= 1 + \frac{k}{R} \int_0^R e^{-C h\qty(r)} \dd{r} =  1 + \frac{k}{R} \int_0^R e^{C\qty(r\cos{\qty(\gamma) - \frac{r^2}{2R_{\bigoplus}}\qty[1 - \cos^2{\qty(\gamma)}]})} \dd{r} \ .
\end{align}
%
Where the integral part, noted $I\qty(R)$ can be express as
%
\begin{align}
   I\qty(R) =  \sqrt{\frac{\pi R_{\bigoplus}}{2C \Gamma}}\ e^{\frac{R_{\bigoplus}C \cos^2{\qty(\gamma)}}{2 \Gamma}} \qty[\erf{\qty(\sqrt{\frac{R_{\bigoplus}C}{2}\Gamma}\ \qty(\frac{R}{R_{\bigoplus}} - \frac{\cos{\qty(\gamma)}}{\Gamma}))} + \erf{\qty(\sqrt{\frac{R_{\bigoplus}C \cos^2{\qty(\gamma)}}{2\Gamma}})}] \ ,
\end{align}
%
with $\Gamma=1 - \cos^2{\qty(\gamma)}$.

\vspace{-0.3cm}
%----------------------------------------------------------------
\section{Cherenkov angles computations} \label{sec:appendix_cherenkov_angle}
\vspace{-0.3cm}
%
The computation of the Cherenkov angle as defined in Sec.~\ref{sec:boost_factor} (see Eq.~\ref{eq:general_boost_exp}), requires the derivative of $I\qty(R)$, given by
%
\begin{align}
    &\dv{I\qty(R)}{R} = I\qty(R) \frac{\cos{\qty(\gamma)}}{\Gamma} \dot{\gamma} \qty(1+\frac{CR_{\bigoplus}}{\Gamma})+ e^{CR\qty(\cos{\qty(\gamma)} - \frac{\Gamma R}{2 R_{\bigoplus}})} \qty[1 - \frac{\dot{\gamma}}{\Gamma}\qty(\frac{R_{\bigoplus}}{\Gamma} + \cos{\qty(\gamma)}R)] + \frac{ R_{\bigoplus}}{\Gamma^2} \dot{\gamma} \ ,
  \\ &{\rm with\ }  \dot{\gamma} = \dv{\cos{\qty(\gamma)}}{R} = \frac{1}{R_{\bigoplus}} - \frac{\cos{\qty(\gamma)}}{R} + \qty(\frac{h_0}{R_{\bigoplus}}+1)\frac{L_X - ct' + R_{\bigoplus}\cos{\qty(\theta)}}{\qty[ct'-R_X\cos{\qty(\omega)}]\qty[h_0 + R_{\bigoplus}]} \ .
\end{align}


