    \includegraphics[width=\linewidth]{FigLT.pdf}
    \caption{Plot of the mean switching time of a single photon detector, showing feasibility of dark count time above 100~s (violet dots and magenta dashed curve). Other curves correspond to heating the copper cavity from 21 mK to 40, 60 and 80 mK (blue, red, yellow/orange dots), respectively.}
    \label{fig:LT}
\end{figure}
