\section{Four cosmologies}
%Friedmann-Lema{\^i}tre-Robinson-Walker 
\label{Friedmann-Lemaitre-Robinson-Walker cosmologies}
\par
The Hubble frequency $H(a)$ varies 
with the scale factor $a$ as 
\begin{equation}
H(a) ={} \sqrt{\frac{8 \pi G}{3} 
\Big( \rho_\Lambda(a) + \rho_K(a) + \rho_m{a} + \rho_r(a) \Big)} .
\label {first-order Friedmann equation}
\end{equation}
Its present value,
the Hubble constant
$H_0 = H(a_0) = H(1)$, 
is approximately 
\begin{equation}
H_0 ={}  \sqrt{\frac{8\pi G}{3} \, \rho_c}
= 2.1976 \by 10^{-18} \, \text{s}^{-1}  
\end{equation} 
in which $ \rho_c $ 
is the critical density (\ref{critical density}).
The ratio of these frequencies
in $\Lambda$CDM cosmology is
\begin{equation}
\frac{H_{\Lambda\text{CDM}}(a)}
{H_0} ={}
\sqrt{\Omega_{\Lambda} 
+ \Omega_{k} \, a^{-2} 
+ \Omega_{m} \, a^{-3}  
+ \Omega_{r} \, a^{-4} } .
\label {LambdaCDM ratio}
\end{equation} 

\par
In DESI cosmology,
the corresponding ratio of Hubble frequencies is
\begin{equation}
\frac{H_{\text{\tiny{DESI}}}(a)}{H_0} ={}
\sqrt{\Omega_{\Lambda} \, 
 a^{-3(1 + w_0 + w_a)} \,
e^{-3 w_a (1-a)} 
+ \Omega_{k} \, a^{-2}   
+ \Omega_{m} \, a^{-3}  
+ \Omega_{r} \, a^{-4} } .
\end{equation}
The ratios for the Pantheon+, Union3 and DESY5 
combinations 
(\ref{Pantheon+}, \ref{Union3}, \ref{DESY5})
are 
\begin{align}
\frac{H_{\text{\tiny{P+}}}(a)}{H_0} ={}&
\sqrt{\Omega_{\Lambda} \, a^{1.374} \,
e^{1.86 (1-a)}  
+ \Omega_{k} \, a^{-2}   
+ \Omega_{m} \, a^{-3}  
+ \Omega_{r} \, a^{-4} } 
\\
\frac{H_{\text{\tiny{U3}}}(a)}{H_0} ={}&
\sqrt{\Omega_{\Lambda} \, a^{2.271} \,
e^{3.27 (1-a)}  
+ \Omega_{k} \, a^{-2}   
+ \Omega_{m} \, a^{-3}  
+ \Omega_{r} \, a^{-4} } 
\\
\frac{H_{\text{\tiny{D5}}}(a)}{H_0} ={}&
\sqrt{\Omega_{\Lambda} \, a^{1.836} \,
e^{2.58 (1-a)}  
+ \Omega_{k} \, a^{-2}   
+ \Omega_{m} \, a^{-3}  
+ \Omega_{r} \, a^{-4} } .
\label {DESY5 ratio}
\end{align} 

\par
The $\Omega$'s of equations
(\ref{LambdaCDM ratio}--\ref{DESY5 ratio})
