\thmPrefixPseudo*


\begin{proof}
   To prove the theorem, we give the following algorithm and show that it is optimal and has pseudopolynomial running time.
   \begin{enumerate}
       \item Initialize $Q = \emptyset$.
       \item Compute the following guesses\footnote{We use the term \enquote{guess} to express that we want to brute-force certain values. E.g., if we say that the algorithm guesses $i_1,i_2 \in \items$ then this means that the algorithms tries all tuples $(i_1,i_2) \in \items \times \items$} about the smallest set $Q_F^*$ that satisfies $U_{\bar{F}(Q_F^*)} \le c \cdot p^*$:
       \begin{enumerate}
           \item Guess the item $i_1 \in \bar{F}(Q_F^*)$ that has the smallest optimistic density $\odensity_{i_1}(Q_F^*)$ in $\bar{F}(Q_F^*)$, i.e., the last item in the prefix $\bar{F}(Q_F^*)$ in the $\bar{\prec}_Q$-order. Furthermore, guess whether $i_1 \in Q_F^*$ or $i_2 \not\in Q^*$. If the guess is $i_1 \in Q$, then add $i_1$ to $Q$. This leads to a total of $\mathcal{O}(n)$ guesses.
           \item Guess the item $i_2 \in \items \setminus \bar{F}(Q_F^*)$ that has the largest optimistic density $\odensity_{i_2}(Q_F^*)$ in $\items \setminus \bar{F}(Q_F^*)$, i.e., the item that comes first among the items of $\items\setminus \bar{F}(Q_F^*)$ in the $\bar{\prec}_{Q_F^*}$-order. Furthermore, guess whether $i_2\in Q_F^*$ or $i_2 \not\in Q_F^*$. If the guess is $i_2\in Q$, then add $i_2$ to $Q$. Together with the guesses from the previous step, this leads to a total of $\mathcal{O}(n^2)$ guesses.
           \item If the guesses are correct, then there exists an optimal solution $Q_F^*$ such that $i_1$ is the last item in $\bar{F}_{Q_F^*}$ and $i_2$ is the first item outside of $\bar{F}_{Q_F^*}$. That is, $i_1$ and $i_2$ are direct neighbors in the order $\bar{\prec}_{Q_F^*}$.
       \end{enumerate}
       \item Based on guesses of $i_1$ and $i_1$, and based on the current $Q$, which at this point is a subset of $\{i_1,i_2\}$, we partition $\items \setminus \{i_1,i_2\}$ into four sets $A,R,S_1$ and $S_2$. Provided that the guesses are correct, the sets $A$ and $R$ satisfy $A \subseteq Q_F^*$ and $R \cap Q_F^* = \emptyset$. Hence, we add $A$ to our solution $Q$ and omit the items in $R$. The items in $S_1$ and $S_2$ will be handled in consecutive steps.
       \begin{enumerate}
           \item Let $A := \{i \in \items \setminus Q \mid i_1 \bar{\prec}_{Q} i \bar{\prec}_{Q} i_2\}$ denote the set of items $i$ with an optimistic density $\odensity_i(Q)$ between $\odensity_{i_2}(Q)$ and $\odensity_{i_1}(Q)$. If the guesses of $i_1$ and $i_2$ is correct, then there exists an optimal solution $Q_F^*$ such that $i_1$ and $i_2$ are direct neighbors in the order $\bar{\prec}_{Q_F^*}$. Hence, we must have $A \subseteq Q_F^*$ as the items in $A \setminus Q_F^*$ would be between $i_1$ and $i_2$ in $\bar{\prec}_{Q_F^*}$.
           If any item $i \in A$ remains between $i_1$ and $i_2$ in the order $\bar{\prec}_{Q \cup A}$, then we immediately know that the current guess was incorrect. 
           \item Let $R := R_1 \cup R_2$ with $R_1 := \{i \in \items \setminus Q \mid i_2 \bar{\prec}_{Q} i\}$ and $R_2 := \{i \in \items \setminus Q \mid i \bar{\prec}_{Q} i_1 \land i_1 \bar{\prec}_{Q\cup \{i\}} i \bar{\prec}_{Q\cup \{i\}} i_2 \}$.     
           The items $i$ in $R_1$ are behind $i_2$ in the order $\bar{\prec}_{Q}$, which implies that they stay behind $i_2$ also in the order $\bar{\prec}_{Q \cup \{i\}}$. Provided that the guesses are correct, $R_1 \not\in \bar{F}(Q_F^*)$ and $R_1 \not\in \bar{F}(Q_F^* \setminus R_1)$, which implies $\bar{F}(Q_F^*) = \bar{F}(Q_F^* \setminus R_1)$. Hence, a correct guess implies $Q_F^* \cap R_1 = \emptyset$.
           The items in $R_2$ are before $i_1$ in the order $\bar{\prec}_Q$ and between $i_1$ and $i_2$ in the order $\bar{\prec}_{Q \cup \{i\}}$. That is, if an $i \in R_2$ is queried, it moves between $i_1$ and $i_2$  in the optimistic density order. If the guesses for $i_1$ and $i_2$ are correct, then there are no elements between $i_1$ and $i_2$ in the order $\bar{\prec}_{Q^*_F}$, which implies $R_2 \cap Q^*_F = \emptyset$. In particular, for correct guesses we have $R_2 \subseteq \bar{F}(Q^*_F)$.

           \item Let $S := \items \setminus (A \cup R \cup Q) = \{i \in \items \setminus (Q \cup R_2) \mid  i \bar{\prec}_Q i_1\}$. The items in $S$ come before $i_1$ in the order $\bar{\prec}_Q$. We further partition $S$ into the two subsets  $S_1 = \{i \in S \mid i_2 \bar{\prec}_{Q \cup \{i\}} i\}$ and $S_2 = S \setminus S_1$. That is, $S_1$ contains the set of items that come before $i_1$ in the optimistic density order $\bar{\prec}_Q$ but will move behind $i_1$ \emph{and} $i_2$ once they are queried. Since $S \cap R = \emptyset$, the definition of the set $R_2$ above implies that the items of $S_2$ will stay in front of $i_1$ in the optimistic density order, even if they are queried. 
       \end{enumerate}
       \item If our guesses are correct, then it remains to compute the subset of $S$ that should be added to $Q$. To this end, we guess $n_1 := |S_1 \cap Q_F^*|$ and $n_2 := |S_2 \cap Q_F^*|$. Together with the previous guesses, this leads to a total of $\mathcal{O}(n^4)$ guesses.  We proceed by computing the $n_1$ items of $S_1$ and the $n_2$ items of $S_2$ that should be added to $Q$:
       \begin{enumerate}
           \item 
           First, consider the set $S_1$. 
           Note that, for the current set $Q$, we already have that $i_1$ and $i_2$ are next to each other in the order $\bar{\prec}_Q$ as $Q$ contains the set $A$ from the previous step.
           In order to be consistent with our guesses for $i_1$ and $i_2$, we have to add a subset $P \subseteq S_1$ to $Q$ such that $i_1 \in \bar{F}(Q \cup P)$ and $i_2 \not\in \bar{F}(Q \cup P)$. Since $i_1$ and $i_2$ are already next to each other in $\bar{\prec}_Q$ and by definition of set $S_1$, this then implies that $i_1$ is last in $\bar{F}(Q \cup P)$ in the order $\bar{\prec}_{Q \cup P}$ and $i_2$ is first in $\items \setminus  \bar{F}(Q \cup P)$ in the order $\bar{\prec}_{Q \cup P}$, which is consistent with the guesses.


           To this end, let $K = \max\left\{\left(\sum_{j \bar{\prec}_Q i_1} w_j\right) - B + w_{i_1},0\right\}$ denote the minimum weight of items in $S_1$ that has to be queried for $i_1$ to enter the prefix. If $K = 0$, then $i_1$ is already part of $\bar{F}(Q)$. Similarly, let $H = \max\left\{\left(\sum_{j \bar{\prec}_Q i_2} w_j\right) - B + w_{i_2} -1,0\right\}$ denote the maximum amount of weight of items in $S_1$ that can be queried without $i_2$ entering the prefix.

           To be consistent with the guesses of $i_1$, $i_2$ and $n_1$, we need to select a subset $P \subseteq S_1$ with $K \le \sum_{i \in P} w_i \le H$ and $|P| = n_1$. Since the elements of $S_1 \setminus P$ will be part of the prefix $\bar{F}_{Q \cup P}$, we would like to minimize $\sum_{i  \in S_1 \setminus P} U_i = U_{S_1} - \sum_{i  \in S_1 \cap P} U_i$, which is equivalent to maximizing $\sum_{i  \in S_1 \cap P} U_i$. This leads to the following problem:

           \begin{equation}
               \tag{\ensuremath{\mathcal{P}_{S_1}}}
               \begin{array}{lll}
                   \max &\sum_{i \in S_1} x_i \cdot U_i\\
                   \text{s.t. }& \sum_{i \in S_1} x_i \cdot w_i \ge K & \\
                   & \sum_{i \in S_1} x_i \cdot w_i \le H & \\
                   & \sum_{i \in S_1} x_i = n_1 & \\
                   & x_i \in \{0,1\}& \forall i \in S_1
               \end{array}
           \end{equation}

           Our algorithm optimally solves~\eqref{density:sub:ILP} in pseudopolynomial time and adds the computed solution $P$ to $Q$.

           This can be done using the following dynamic program that slightly extends the textbook knapsack DP~\cite{IbarraK75}. Our goal is to compute the following DP-cells for all $i \in \{0,\ldots,|S_1|\}$, $b \in \{0,\ldots,D\}$ and $k \in \{0,\ldots, n_1\}$:
           $$
               T[i,b,k] := \max_{P \subseteq \{1,\ldots,i\} \colon |P| = k \land w(P) = b} \sum_{j \in P} U_j.
           $$
           If there is no packing $P \subseteq \{1,\ldots,i\}$ with $|P| = k$ and $w(P) = b$, then we want the DP-cell to store
           $$
              T[i,b,k] := - \infty.
           $$

           If we can correctly compute these DP-cells, then the optimal objective value for~\eqref{density:sub:ILP} is stored in one of the cells $T[|S_1|,b,k]$ with $K \le b \le H$ and $k = n_1 n_1$. If all these cells have value $-\infty$, then our guesses were certainly wrong.
           We proceed by describing how to compute the DP-cells.

           To this end, we use the following two base cases:
           \begin{itemize}
               \item $T[0,0,0] = 0$ since all packings $P$ with $w(P) = 0$ and $|P| = 0$ have $\sum_{j \in P} U_j = 0$.
               \item $T[0,b,k] = -\infty$ if $b > 0$ or $k > 0 $ as there exists no $P \subseteq \emptyset$ with $|P| > 0$ or $w(P) > 0$.
           \end{itemize}

           For $i \ge 1$, $b \in \{0,\ldots,D\}$ and $k \in \{0,\ldots, n_1\}$, we distinguish two cases:
           \begin{itemize}
               \item If $b-w_i < 0$ or $k-1 <0$, then the packing $P$ that maximizes 
               $$\max_{P \subseteq \{1,\ldots,i\} \colon |P| = k \land w(P) = b} \sum_{j \in P} U_j$$
               cannot contain $i$ and, thus,
               $$\max_{P \subseteq \{1,\ldots,i\} \colon |P| = k \land w(P) = b} \sum_{j \in P} U_j = \max_{P \subseteq \{1,\ldots,i-1\} \colon |P| = k \land w(P) = b} \sum_{j \in P} U_j.$$
               Provided that the cell $T[i-1,b,k]$ has been computed correctly, this implies $T[i,b,k] = T[i-1,b,k]$.
               \item Next, assume $b-w_i \ge 0$ and $k-1 \ge 0$. Then, we can rewrite 
               \begin{align*}
                   &\max_{P \subseteq \{1,\ldots,i\} \colon |P| = k \land w(P) = b} \sum_{j \in P} U_j =\\
                   & \max\left\{\max_{P \subseteq \{1,\ldots,i-1\} \colon |P| = k \land w(P) = b} \sum_{j \in P} U_j, U_i + \max_{P \subseteq \{1,\ldots,i-1\} \colon |P| = k-1 \land w(P) = b-w_i} \sum_{j \in P} U_j  \right\}
               \end{align*}
               by separating the packings $P$ that do not contain $i$ (first term in the maximum) and the packings $P$ that contain $i$ (second term of the maximum).
               Thus, we can compute the DP-cell as follows:
               $$T[i,b,k] = \max\{T[i-1,b-w_i,k-1] + U_i, T[i-1,b,k]\}.$$
           \end{itemize}
           Together, the two cases lead to the following recursive formula:
           $$T[i,b,k] = \begin{cases}
               \max\{T[i-1,b-w_i,k-1] + U_i, T[i-1,b,k]\} & \text{ if } b-w_i \ge 0 \land k-1 \ge 0\\
               T[i-1,b,k] & \text{ otherwise }
           \end{cases}$$


           The running time of this DP is in $\mathcal{O}(n^2 \cdot \sum_{i \in S_1} w_i)$. The optimal objective value for the instance of \eqref{density:sub:ILP} is contained in one of the cells $T[|S_1|,b,k]$ with $K \le b \le H$ and $k = n_1$. We can find this cell in time $\mathcal{O}(n^2 \cdot \sum_{i \in S_1} w_i)$ and compute the corresponding solution via backtracking.
           We omit the correctness proof for the DP, but remark that it can be shown using essentially the same proof as for the textbook knapsack DP.

           \item Next, we want to compute the elements of $S_2$ that should be added to $Q$. The current set $Q$ (including the elements added in the previous step 4a) was selected in such a way that $S_2 \subseteq \bar{F}(Q)$ and $S_2 \subseteq \bar{F}(Q \cup P)$ for every $P\subseteq S_2$. That is, the elements of $S_2$ are part of prefix $\bar{F}(Q)$ and will stay part of the prefix, even if they are queried. Thus, for every $P \subseteq S_2$, we have $U_{\bar{F}(Q)}(Q) - U_{\bar{F}(Q)}(Q \cup P) = \sum_{i \in P} (U_i-p_i)$. This implies that we should select the $n_2$ elements of $S_2$ with maximum $U_i-p_i$ and add them to $Q_2$. We can find these items in time $\mathcal{O}(|S_2| \log |S_2|)$ by sorting $S_2$.
       \end{enumerate}
       \item Among the sets $Q$ computed for the different guesses, return a set $Q$ of minimum cardinality subject to $U_{\bar{F}_Q}(Q) \le D$.
   \end{enumerate}

   \paragraph*{Running time.} The running time of the algorithm is in $\mathcal{O}(n^6 \cdot \sum_{i \in S_1} w_i)$ since there are $\mathcal{O}(n^4)$ guesses and the running time per guess is dominated by the running time $\mathcal{O}(n^2 \cdot \sum_{i \in S_1} w_i)$ of the DP in step~5a.

   \paragraph*{Correctness.} Since the algorithm tries all guesses for $i_1,i_2,n_1$ and $n_2$, there will be one iteration such that there exists an optimal solution $Q_F^*$ to the prefix problem such that $i_1$ is the last element in $\bar{F}(Q_F^*)$, $i_2$ is the first element in $\items \setminus \bar{F}(Q_F^*)$ in the order $\bar{\prec}_{Q_F^*}$ and $|S_1 \cap Q^*| = n_1$, $|S_1 \cap Q^*| = n_2$ for the sets $S_1$ and $S_2$ as computed for the guesses $i_1$ and $i_2$ in step~3. As argued above, $Q^*$ must satisfy $A \subseteq Q_F^*$ and $R \cap Q^* = \emptyset$ for the sets $S$ and $R$ as computed in step~3 for guesses $i_1$ and $i_2$. Furthermore, again as argued above,  we have $R_2 \subseteq \bar{F}(Q_F^*)$.

   By definition of the sets $S_1$ and $S_2$, we have $\bar{F}(Q_F^*) = S_2 \cup (S_1 \setminus Q_F^*) \cup R_2 \cup \{i_1\}$. Hence,
   $$
   U_{\bar{F}(Q_F^*)}(Q_F^*) = \sum_{j \in S_2} U_j - \left(\sum_{j \in S_2 \cap Q_F^*}  U_j - p_j\right) + \sum_{j \in S_1} U_j - \left(\sum_{j \in S_1 \cap Q_F^*}  U_j\right) + U_{R_2} + U_{i_1}(Q^*_F),
   $$
   with $|S_2 \cap Q_F^*| = n_2$, $|S_1 \cap Q_F^*| = n_1$ $K \le w(S_1 \cap Q_F^*) \le H$, where $H$ and $K$ are the parameter of~\eqref{density:sub:ILP} for the correct guesses.

   The set $Q$ computed by the algorithm for the correct guesses also satisfies $A \subseteq Q$ and $R \cap Q = \emptyset$. Since also $w(S_1 \cap Q^*) \le H$, we get $\bar{F}(Q) \subseteq S_2 \cup (S_1 \setminus Q) \cup R_2 \cup \{i_1\}$. Hence,
   $$
   U_{\bar{F}(Q)}(Q) \le  \sum_{j \in S_2} U_j - \left(\sum_{j \in S_2 \cap Q}  U_j - p_j\right) + \sum_{j \in S_1} U_j - \left(\sum_{j \in S_1 \cap Q}  U_j\right) + U_{R_2} + U_{i_1}(Q^*_F),
   $$
   where we use that $U_{i_1}(Q^*_F) = U_{i_1}(Q)$ holds as we correctly guessed whether $i_1 \in Q_F^*$.

   As $S_2$ maximizes $\sum_{j \in S_2 \cap Q}  U_j - p_j$ subject to $|S_2 \cap Q| \le n_2$ and $S_1$ maximizes $\sum_{j \in S_1 \cap Q}  U_j$ subject to $K \le w(S_1 \cap Q) \le H$ and $|S_1 \cap Q| = n_1$, we can conclude that $|Q| = |Q_F^*|$ and
   $$
   D \ge U_{\bar{F}(Q_F^*)}(Q_F^*) \ge  U_{\bar{F}(Q)}(Q),
   $$
   where the first inequality follows from $Q_F^*$ being an optimal solution for the prefix problem with parameter $D$. Thus, $Q$ is also an optimal solution.
\end{proof}

\thmPrefixNonPseudo*


\begin{proof}
   Our goal is to adjust the algorithm given in~\Cref{thm:prefix:pseudo} to achieve a polynomial running time at the cost of a worse guarantee. To this end, we replace step 4a and step 5 of the algorithm in~\Cref{thm:prefix:pseudo}. 

   We first argue how to replace step 4a. Observe that the only part of the algorithm given in~\Cref{thm:prefix:pseudo} with a pseudopolynomial running time is the subroutine for solving~\eqref{density:sub:ILP}. Recall that this subroutine is used to compute the subset $P \subseteq S_1$ that is added to the prefix problem solution $Q$.
   We replace this subroutine with the following polynomial time algorithm:
   \begin{enumerate}
       \item Consider the following relaxation of~\eqref{density:sub:ILP}, which drops the first constraint of~\eqref{density:sub:ILP} and removes the integrality constraint for the variables:
       \begin{equation}
           \tag{\ensuremath{\mathcal{P}'_{S_1}}}\label{density:sub:ILP:relax}
           \begin{array}{lll}
               \max &\sum_{i \in S_1} x_i \cdot U_i\\
               \text{s.t. } & \sum_{i \in S_1} x_i \cdot w_i \le H & \\
               & \sum_{i \in S_1} x_i = n_1 & \\
               & x_i \in \{0,1\}& \forall i \in S_1
           \end{array}
       \end{equation}
       \item Compute an optimal basic feasible solution $x^*$ of~\eqref{density:sub:ILP:relax}.
       \item Return $P = \{i \in S_1 \mid x^*_i = 1\}$ and add $P$ to $Q$.
   \end{enumerate}

   Finally, we adjust step 5 to return among all guesses the set $Q$ of minimum cardinality subject to $U_{\bar{F}(Q)}(Q) \le D  + 2 \cdot \max_{i \in \items} U_i$. 



   We claim these two changes are sufficient to satisfy the theorem. First, note that the new step 4a has a polynomial running time as the running time is dominated by solving the LP. If we plug the subroutine into the algorithm of~\Cref{thm:prefix:pseudo}, this yields a polynomial running time. 

   It remains to show that $|Q'| \le |Q^*_F|$  and  $U_{\bar{F}(Q')}(Q') \le D + 2 \cdot \max_{i \in \items} U_i$ holds for the computed solution $Q$.
   The former holds as replacing the subroutine of step 4a with the approach above can only decrease the size of the solution since we omit the fractional variables.

   As shown in~\cite{CapraraKPP00}, an optimal basic feasible solution $x^*$ of~\eqref{density:sub:ILP:relax} has at most two fractional variables, i.e., at most two $i \in S_1$ have $1 > x^*_i > 0$. Let $P^*$ denote an optimal solution of~\eqref{density:sub:ILP}. Using that~\eqref{density:sub:ILP:relax} is a relaxation and that $x^*$ has at most two fractional values, we get
   \begin{equation}\label{eq:5}
       \sum_{i \in P} U_i  \ge \left(\sum_{i \in S_1} U_i \cdot x^*_i\right) - 2 \cdot \max_{i \in S_i} U_i \ge U_{P^*} - 2 \cdot \max_{i \in S_i} U_i.
   \end{equation}

   Finally, fix the solution $Q$ computed for the correct guesses. If this solution satisfies $|Q| \le |Q^*_F|$  and  $U_{\bar{F}(Q)}(Q) \le D + 2 \cdot \max_{i \in \items} U_i$, then the returned solution $Q'$ also satisfies $|Q'| \le |Q^*_F|$  and  $U_{\bar{F}(Q')(Q')} \le D + 2 \cdot \max_{i \in \items} U_i$.

   Note that the guesses are still with respect to an optimal solution $Q^*_F$ for the prefix problem with threshold $D$. With the same argumentation as above, we still get that
   $$
   U_{\bar{F}(Q_F^*)}(Q_F^*) = \sum_{j \in S_2} U_j - \left(\sum_{j \in S_2 \cap Q_F^*}  U_j - p_j\right) + \sum_{j \in S_1} U_j - \left(\sum_{j \in S_1 \cap Q_F^*}  U_j\right) + U_{R_2} + U_{i_1}(Q^*_F),
   $$
   with $|S_2 \cap Q_F^*| = n_2$, $|S_1 \cap Q_F^*| = n_1$ $K \le w(S_1 \cap Q_F^*) \le H$, where $H$ and $K$ are the parameter of~\eqref{density:sub:ILP} for the correct guesses, and 
   $$
   U_{\bar{F}(Q)}(Q) \le  \sum_{j \in S_2} U_j - \left(\sum_{j \in S_2 \cap Q}  U_j - p_j\right) + \sum_{j \in S_1} U_j - \left(\sum_{j \in S_1 \cap Q}  U_j\right) + U_{R_2} + U_{i_1}(Q^*_F),
   $$
   where we use that $U_{i_1}(Q^*_F) = U_{i_1}(Q)$ holds as we correctly guessed whether $i_1 \in Q_F^*$.

   As $S_2$ maximizes $\sum_{j \in S_2 \cap Q}  U_j - p_j$ subject to $|S_2 \cap Q| \le n_2$, we have  
   $$
   \sum_{j \in S_2} U_j - \left(\sum_{j \in S_2 \cap Q_F^*}  U_j - p_j\right) \ge \sum_{j \in S_2} U_j - \left(\sum_{j \in S_2 \cap Q}  U_j - p_j\right).
   $$
   Hence, 
   $$
   U_{\bar{F}(Q)}(Q) -  U_{\bar{F}(Q_F^*)}(Q_F^*) \le \left(\sum_{j \in S_1 \cap Q_F^*}  U_j\right) - \left(\sum_{j \in S_1 \cap Q}  U_j\right).
   $$
   By~\eqref{eq:5} and using that $ S_1 \cap Q_F^*$ is a feasible solution to~\eqref{density:sub:ILP} (as argued in the proof of~\Cref{thm:prefix:pseudo}), we get
   $$
   U_{\bar{F}(Q)}(Q) -  U_{\bar{F}(Q_F^*)}(Q_F^*) \le 2 \cdot \max_{i \in S_i} U_i,
   $$
   and, thus,
   $$
    U_{\bar{F}(Q)}(Q) \le  U_{\bar{F}(Q_F^*)}(Q_F^*) + 2 \cdot \max_{i \in S_i} U_i \le D + 2 \cdot \max_{i \in \items} U_i.
   $$
\end{proof}


