\section{Numerical Results}\label{Numerical_study}
In this section, we evaluate our prediction-correction method for four functions with increasing numerical complexity: (i) a smooth circular interface function, which enables a thorough assessment of the method (including convergence order, influence of the predictor problem, and analysis of the Nitsche parameter); (ii) a piecewise constant function; (iii) a complex example involving a sharply varying interface; and (iv) a three-dimensional case, demonstrating the ease with which our method can be extended to 3D problems.
To analyze the convergence towards the exact solution, we denote the difference between the numerical approximation, $\phi_{h}$, and the exact solution, $\phi_{ex}$ , as
\begin{equation}
%e(\underline{x})=\phi_{h}(\underline{x}) - \phi_{ex}(\underline{x}), \quad \underline{x} \in D_{h}
e(\phi_{h}(x))=\phi_{h}(x) - \phi_{ex}(x), \quad x \in D_h.
\end{equation} 
We evaluate this error in the $L^{2}$ norm
\begin{equation}
%    \left\Vert e\right\Vert _{L^{2}\left(D\right)}^{2}=\int_{D_{h}}e^{2}(\underline{x})\,dx.
\left\Vert e\right\Vert _{L^{2}\left(D_h\right)}^{2}=\frac{\int_{D_h}e^{2}(\phi_{h}(x))\,dx}{\int_{D_h}\,dx}.
\end{equation} 
\par
Furthermore, to evaluate the method's ability to converge towards the solution of the Eikonal equation \eqref{eq:signed_distance}, we introduce the Eikonal error, defined as
\begin{equation}
    e_{\text{eik}}(\phi_{h}(x))=1-\left|\nabla\phi_{h}(x)\right|, \quad x \in D_h.
\end{equation} 
We compute this error using the $L^{2}$ norm
\begin{equation}
    \left\Vert e_{\text{eik}}\right\Vert _{L^{2}\left(D_h\right)}^{2}=\frac{\int_{D}e^{2}_{\text{eik}}(\phi_{h}(x))\,dx}{\int_{D_h}\,dx}.
\end{equation} 
Finally to assess the method's precision in preserving the initial interface $\Gamma_h^0$ we define the 
following norm with respect to the  solution of the prediction problem $\phi_{h}^{0}$
\begin{align}\label{error_interface}
    \left\Vert \phi_{h}\right\Vert _{L^{2}{\left(\Gamma\right)}}^{2} &= \int_{\phi^{0}_{h}=0}\left(\phi_{h}(x)-\phi_{h}^{0}(x)\right)^{2}\text{ }ds \\
    &=\int_{\phi_{h}^{0}=0}\left(\phi_{h}(x)\right)^{2}\text{ }ds.
\end{align}
