\section{Pseudo $H$-type nilpotent Lie groups}\label{se.rseudo.htnlg}

Let $(N,g)$ be a 2-step pseudo-Riemannian nilmanifold and $\mathfrak n=\mathfrak z\oplus\mathfrak v$ be its Lie algebra endowed with a scalar product $\langle.\,,.\rangle$
making the center non-degenerate. We identify $(\mathfrak z,\langle.\,,.\rangle_{\mathfrak z})$ with the pseudo Euclidean vector space
$\mathbb{R}^{r,s}=(\mathbb{R}^{r+s},\langle.\,,.\rangle_{r,s})$, where 
$$
\langle Z, W \rangle_{r,s} =
\sum_{i=1}^r z_i\, w_i-\sum_{j=1}^s z_{r+j}\, w_{r+j}, \quad Z,W \in \mathbb{R}^{r+s}.
$$
If the linear operator $J\colon\mathfrak{z} \rightarrow \mathfrak{so}(\mathfrak{v})$ is defined by
\begin{equation}\label{eq:JJ}
\langle J_Z(X),Y \rangle_{\mathfrak v}=\langle [X,Y],Z\rangle_{r,s}, \quad X,Y\in \mathfrak{v},\ Z\in \mathfrak{z}=\mathbb{R}^{r,s},
\end{equation}
and satisfies $J_Z^2 (X)=-\langle Z,Z \rangle_{r,s} X$ for any $Z \in \mathbb{R}^{r,s}$ and all $X \in \mathfrak{v}$,
then $\mathfrak{n}=\mathfrak n_{r,s}$ is called the {\color{blue}pseudo} $H$(eisenberg)-type Lie algebra. It is easy to check that 
this definition %the definition of {\color{blue}pseudo} $H$-type Lie algebra 
implies
\begin{equation}\label{eq:JJJ}
\langle J_Z(X),J_W(X) \rangle_{\mathfrak v}=\langle Z,W \rangle_{r,s}\langle X,X \rangle_{\mathfrak v}.
\end{equation}
We denote by ${N}_{r,s}$ the connected simply connected Lie group, whose Lie algebra is the {\color{blue}pseudo} $H$-type Lie algebra $\mathfrak n_{r,s}$. The $H$-type Lie algebras $N_{r,0}$ with a positive definite scalar product were introduced in~\cite{Kap80}
and with an arbitrary indefinite scalar product in~\cite{Cia}, see also~\cite{GKM13}.
%We use the same notation for the pseudo-Riemannian manifold $({N},g)$,
%where $g$ is the left translation of the bilinear form $\langle \cdot\, ,\cdot \rangle$ and call
%$({N},g)$ the $H$-type nilmanifold ${N}$. See details e.g. in~\cite{AFMV}.
%\smallskip

These 
%$H$-type 
Lie algebras are related to the representations of the
Clifford algebras in the following way. Let $J\colon\operatorname{Cl}(\mathbb{R}^{r,s}) \rightarrow \operatorname{End} (\mathfrak{v})$ be a representation of
the Clifford algebra $\operatorname{Cl}(\mathbb{R}^{r,s})$ generated by the pseudo Euclidean vector space $\mathbb{R}^{r,s}$.
If there is a scalar product $\langle \cdot\,,\cdot \rangle_{\mathfrak{v}}$ on the representation space $\mathfrak{v}$ (Clifford module)
such that the linear map $J_Z$ is skew-symmetric for any $Z\in \mathbb{R}^{r,s}$; that is
$$
\langle J_Z(X),Y \rangle_{\mathfrak v}=-\langle X,J_Z(Y) \rangle_{\mathfrak v},\quad Z\in \mathbb{R}^{r,s},\quad X,Y\in\mathfrak v,
$$ 
then we get a pseudo $H$-type Lie algebra with the commutators defined in~\eqref{eq:JJ},
see details in~\cite{Kap81, Cia, KapTir, GMKMV, FuMa16, FuMa17, FuMa19, FuMa21}. The scalar product $\langle \cdot\,,\cdot \rangle_{\mathfrak{v}}$ in this case is called admissible and $\mathfrak v$ is called admissible (Clifford) module.

It is important that, see e.g.~\cite{Cia}, or~\cite[Propososition 2.2.2]{FuMa21})
the signature of the scalar product space $(\mathfrak{v},\langle \cdot\,,\cdot \rangle_{\mathfrak{v}})$
is neutral and $(\mathfrak{v},\langle \cdot\,,\cdot \rangle_{\mathfrak{v}})$ is isometric to $\mathbb{R}^{l,l}$ for some $l \in \mathbb{N}$ if $s>0$,
whereas the corresponding signature is either $(l,0)$ or $(0,l)$ for some $l \in {\color{blue}2}\mathbb{N}$ if $s=0$.

We use the symbol $^t$ for the transposition according to the standard Euclidean product on $\mathfrak{v}=\mathbb{R}^{2l}$.
On the other hand, we use the symbol $ ^{\tau}$ for the transposition according to scalar product $\langle \cdot\,,\cdot \rangle_{l,l}$
on $\mathfrak{v}=\mathbb{R}^{l,l}$ or $\langle \cdot\,,\cdot \rangle_{r,s}$
on $\mathfrak{z}=\mathbb{R}^{r,s}$.
In particular, for any operator $A$ on $\mathfrak{v}$, we get $\langle A(X),Y \rangle=\langle X, A^{\tau}(Y) \rangle$, $X,Y \in \mathfrak{v}$, and
$J_Z^{\tau}=-J_Z$ for any $Z\in \mathfrak{z}$.
If $\eta=\diag(\Id_l,-\Id_l)$, then $J_Z^{\tau}=\eta J_Z^t \eta$ and
$A^{\tau}=\eta A^{t} \eta$.
\smallskip
%
%In terms of matrices from $GL(p+q)$, we get $O(p,q) = \{X\in GL(p+q) \,|\, X^t \eta_{p,q}X= \eta_{p,q}\}$, where $\eta_{p,q}=\diag(\Id_p,-\Id_q)$
%and
%$\mathfrak{o}(p,q) = \{A\in \mathfrak{gl}(p+q) \,|\, \eta_{p,q}A^t \eta_{p,q}= -A\}$.
%We may suppose that an admissible scalar product on $\mathfrak{v}=\mathbb{R}^{l,l}$ is as follows: $\langle A,B \rangle=\trace (A \eta B\eta )$.

Thus we use the identification $\mathbf{V}=J(\mathfrak{z}) \subset \mathfrak{so}(\mathfrak{v})=\mathfrak{so}(l,l)$.
Recall that $\dim \mathbf{V}=\dim \mathfrak{z}=r+s$.
In the next proposition we collect some useful results.

\begin{prop}\label{pr.triple.1}
Let $\mathfrak{n}_{r,s}$ be a pseudo $H$-type Lie algebra, $\mathbf{N}$ and $\mathbf{Z}$ the normalizer and the centralizer of $\mathbf{V}=J(\mathfrak z)$ in $\mathfrak{so}(l,l)$. Then we have the following properties:

1. $[\mathbf{V},\mathbf{V}]$ and $\mathbf{L}:=[\mathbf{V},\mathbf{V}]+\mathbf{V}$ are Lie subalgebras in $\mathfrak{so}(l,l)$;
\smallskip

2. the Lie algebra $[\mathbf{V},\mathbf{V}]$ is isomorphic to $\mathfrak{so}(r,s)$;
\smallskip

3. $[\mathbf{V},\mathbf{V}]\subset \mathbf{N}$ and $\dim \mathbf{N} \geq (r+s)(r+s-1)/2$;
\smallskip

4. $\Bigl(\mathbf{L},[\mathbf{V},\mathbf{V}]\Bigr)$ is a symmetric pair,
i.e., $\mathbf{V}$ is a Lie triple system;
\smallskip

5. the Lie algebra $\mathbf{L}~\text{is commutative if}~ 
(r, s)\in\left\{(1,0), (0,1)\right\}$,
it is simple if\\ %\linebreak
\hspace{0.8cm} $(r, s)\not\in \left\{(1,0), (0,1),(3,0), (1,2)\right\}$,
and it is semisimple if $(r, s)\in \left\{(3,0), (1,2)\right\}$;
\smallskip

6. $\mathbf{N}=[\mathbf{V},\mathbf{V}] \oplus \mathbf{Z}$ {\rm(}a direct sum of Lie algebras{\rm)}.
\end{prop}


\begin{proof} We give an outline of the proof.
For every pair of orthogonal vectors $Z', Z'' \in \mathfrak{z}$, the map $\Phi_{Z',Z''}$, defined by
\begin{equation}\label{eq:Phi}
\Phi_{Z',Z''}(X + Z) = J_{Z'}J_{Z''}(X)+2 \langle Z',Z\rangle Z''-2 \langle Z'',Z\rangle Z',\quad Z\in \mathfrak{z},\quad X\in \mathfrak{v},
\end{equation}
is a skew-symmetric derivation of $(\mathfrak{n}_{r,s}, \langle \cdot\,, \cdot \rangle)$,
see e.g. Lemma 2.2 in~\cite{CiaCo} or \cite{Rie82}.
Since $[J_{Z'},J_{Z''}]=2J_{Z'}J_{Z''}$, then $[\mathbf{V},\mathbf{V}]\subset \mathbf{N}$, due to the fact that $\Phi_{Z',Z''}$ and, hence, $[J_{Z'},J_{Z''}]$
is in the isotropy Lie algebra $\mathfrak{h}$, see \eqref{isotalg1} and Proposition \ref{pr.isgr.1}. Moreover,
$[\mathbf{V},\mathbf{V}]$ is a Lie subalgebra in $\mathbf{N}$, that is isomorphic to  $\mathfrak{so}(r,s)$.
Indeed, by Lemma 5.1 in~\cite{AFMV}, we can choose an orthonormal basis $Z_i$, $i=1,\dots, r+s$, for  $\mathfrak{z}=\mathbb{R}^{r,s}$, such that
$\mathbf{V} =J(\mathfrak{z})=J(\mathbb{R}^{r,s}) \subset \mathfrak{so}(l,l)$ has a basis of the following type:
$\{J_{Z_i}\}$, $i=1,\dots, r+s$, while
$\{J_{Z_j}J_{Z_k}\}$, $j,k = 1,\dots, r+s$, $j<k$, constitute a basis in
$[\mathbf{V},\mathbf{V}]\subset \mathbf{N}$. Therefore,
$[\mathbf{V},\mathbf{V}]$ is isomorphic to  $\mathfrak{so}(r,s)$, then $\dim  \mathbf{N}\geq \dim [\mathbf{V},\mathbf{V}]=\dim \mathfrak{so}(r,s)=(r+s)(r+s-1)/2$.
This result also follows from \cite[Proposition 3.2.4]{FuMa21}.


One can easily check that
$[[\mathbf{V},\mathbf{V}],\mathbf{V}]\subset \mathbf{V}$, which means that $[\mathbf{V},\mathbf{V}]\subset \mathbf{N}$.
Moreover, $\mathbf{L}=[\mathbf{V},\mathbf{V}]+\mathbf{V}$ is a Lie algebra
and $\mathbf{V}$ is a Lie triple system (see Proposition 5.2 in \cite{AFMV}).
\smallskip

Finally, the Lie algebra
$\mathbf{L}$ is commutative and $1$-dimensional if $(r, s)\in \left\{(1,0), (0,1)\right\}$, it is simple if $(r, s)\not\in \left\{(1,0), (0,1), (3,0), (1,2)\right\}$,
and it is semisimple if $(r, s)\in \left\{(3,0), (1,2)\right\}$
by Theorem 5.1 in \cite{AFMV}.

It is known that  each $B\in \mathbf{N}$ (i.e., each skew-symmetric derivation of $\mathfrak{z}$)
decomposes as a sum $B_0 + B_1$, where $B_0\in \mathbf{Z}$ and $B_1 \in [\mathbf{V},\mathbf{V}]$,
see detail in \cite[Corollary 2.6]{CiaCo}. Therefore, $\mathbf{N}=[\mathbf{V},\mathbf{V}] \oplus \mathbf{Z}$.
On the level of automorphism groups, similar results were obtained in \cite[Subsection 3.2]{FuMa21}.
\end{proof}




It should be noted that the intersection of $\mathbf{V}$ and $[\mathbf{V},\mathbf{V}]$ can be nontrivial.
We have the following result.

\begin{lemma}[see e.g. Lemma 6 in \cite{BerNik09}]\label{le.ideal_h1}
Suppose that $K:=\mathbf{V} \cap [\mathbf{V},\mathbf{V}]$ is non-trivial. Then $K$ is an ideal in $\mathbf{L}= \mathbf{V}+[\mathbf{V},\mathbf{V}]$.
If, in addition, $\mathbf{L}$ is simple, then $K=\mathbf{V}=[\mathbf{V},\mathbf{V}]=\mathbf{L}$.
\end{lemma}

\begin{proof}
We see that
$$
[K,\mathbf{V}]\subset [\mathbf{V},\mathbf{V}], \quad [K,\mathbf{V}]\subset [[\mathbf{V},\mathbf{V}],\mathbf{V}] \subset \mathbf{V},
$$
$$
[K,[\mathbf{V},\mathbf{V}]]\subset[\mathbf{V},[\mathbf{V},\mathbf{V}]] \subset \mathbf{V}, \quad
[K,[\mathbf{V},\mathbf{V}]]\subset [[\mathbf{V},\mathbf{V}],[\mathbf{V},\mathbf{V}]]\subset [\mathbf{V},\mathbf{V}].
$$
Therefore,
$$
[K,\mathbf{V}]\subset\mathbf{V} \cap [\mathbf{V},\mathbf{V}]= K, \quad [K,[\mathbf{V},\mathbf{V}]]\subset\mathbf{V} \cap [\mathbf{V},\mathbf{V}]= K,
\quad [K,\mathbf{L}]\subset K,
$$
hence, $K$ is an ideal of $\mathbf{L}$.
\end{proof}

Note that the constant $k=k(T)$ in  Proposition~\ref{pr.geodlem1} can be different from zero for pseudo-Riemannian manifolds, see~\cite{Bar}, where it is shown that $k$ depends on the reparametrization of a homogeneous geodesic and it could be $k(T)\neq 0$ for a null initial velocity $T$ of such a geodesic. We show that such a reparametrization in case of pseudo $H$-type Lie groups $N_{r,s}$ is a multiplication by a non-vanishing real constant, that is, 
it is a linear rescaling, which implies that $k=0$.



Recall that the isometry group of the pseudo $H$-type Lie group $N_{r,s}$ with a given left invariant pseudo Riemannian metric is identified with the group $G=N_{r,s}\rtimes H$, where $H$ is defined in~\eqref{isotgr1} and its Lie algebra $\mathfrak h$ is given by 
~\eqref{isotalg1}. 
\begin{prop}\label{prop:k=0}
Let $\gamma\colon l  \mapsto \gamma(l)\in N_{r,s} (\,\cong G/H)$, be a geodesic
passing through the identity element $e=[H]\in N_{r,s}$, 
which is homogeneous with respect to the isometry group  $G\cong N_{r,s}\rtimes H$; that is there exists a
one parameter subgroup $\{\phi(t)\}$ of $G$,
such that $\gamma(l(t))=\phi(t)\cdot e$, 
for a diffeomorphism $l\colon \mathbb R\to I$, $l(0)=0$. Then $l(t)=t$.
\end{prop}

\begin{proof}
The Lie algebra of the pseudo $H$-type Lie group $N_{r,s}$ is 
$n_{r,s}=\mathfrak z\oplus\mathfrak v\cong \mathbb R^{r,s}\oplus\mathbb R^{n,n}$, where $\mathfrak{v}$ is a minimal admissible module of the Clifford algebra $\Cl(\mathbb R^{r,s})$. We use coordinates of the first kind for 
$$
N_{r,s}\ni(v,w)=\exp_N(v Z+wX)\quad\text{for}\quad Z\in \mathfrak z, \ X\in\mathfrak v,
$$
that is, in this case we identify the group and its Lie algebra as sets.
Then $v=(v_1,\ldots, v_{r+s})$, $w=(w_1,\ldots,w_{2n})$. 
%We also write $[w,w']=\sum_{i,j=1}^{2n}(w_iw'_j-w'_iw_j)$.

Without loss of generality, we can consider a geodesic $\gamma\colon I\to G/H=N_{r,s}$, $I=(-a,a)\subset \mathbb R$, $$
\gamma(l)=(z(l),x(l))=(z_1(l),\ldots,z_{r+s}(l),x_1(l),\ldots,x_{2n}(l))\quad \gamma(0)=e,\quad \dot\gamma(0)=(\dot z(0),\dot x(0)),\quad l\in I.
$$ 
Then
\begin{equation}\label{eq:one-0}
z(l)=l\dot z(0)+\frac{1}{2}\int_0^l[x(s),\dot x(s)]\,ds,\quad x(l)=\int_0^l\exp_H(s J_{\dot z(0)})\cdot\dot x(0)\,ds,
	\end{equation}
where $J_{\dot z(0)}$ is the Clifford multiplication by the element
$\dot{z}(0)\in\mathfrak{z}$,
$J_{\dot{z}(0)}:\mathfrak{v} \to \mathfrak{v}$ (see~\cite{DBO}). 
Assume that $\gamma$ is a homogeneous geodesic for a one-parameter subgroup $\phi$ of isometry group $G=N_{r,s}\rtimes H$.
We write $\phi(t)=(v(t),w(t),c(t),a(t))$, where we use the coordinate representation $(v(t),w(t))\in N_{r,s}$ and $(c(t), a(t))\in H$ for $t\in\mathbb R$. Then there is  $D=(C,A)\in\mathfrak h$, such that coordinates of $\phi(t)$ have the form
\begin{align}
&w(t)=\int_0^t\exp_H(sA)\dot{w}(0)\, ds,
~~v(t)=\int_0^t\, \exp_H(sC)\dot{v}(0)\,+\,\frac{1}{2}[(w(s),\dot{w}(s)]\, ds,
\label{eq:one-1}\\
&c(t)=\exp_H(tC),\quad  a(t)=\exp_H(tA).\label{eq:one-2}
\end{align}
Let assume a geodesic  $\gamma(l)$ in~\eqref{eq:one-0} is homogeneous
under  a rescaling $l=l(t)$ through a diffeomorphism $\mathbb{R}\ni t\mapsto l(t)\in \mathbb{R}$, 
then $D=(C,A)\in\mathfrak h$ are such that 
$$
[J_z,A]=J_{C^{\tau}(z)},\quad z\in\mathfrak z,\quad C(\dot z(0))=0,\quad A(\dot x(0))=J_{\dot z(0)}(\dot x(0)),
$$
and the orbit through $e\in N_{r,s}$ is expressed as
\begin{align}
z(l(t))&=l(t)\dot{z}(0)+\frac{1}{2}\int_0^{l(t)}[x(s),\dot{x}(s)]\,ds\label{eq:one-2}\\
&=\int_0^t\exp_H(sC)\dot{z}(0)\,+\,\frac{1}{2}[w(s),\dot{w}(s)]\, ds=v(t)\notag
\intertext{and}
%\begin{equation}
&x(l(t))=\int_0^l\exp_H(s J_{\dot{z}(0)})\dot{x}(0)\,ds=\int_0^t\exp_H(sA)\dot{x}(0)\, ds=w(t).
\label{eq:one-3}
\end{align}	
By differentiating equation~\eqref{eq:one-2}, we obtain
$$
\dot l(t)\dot z(0)=\exp_H(tC)\cdot \dot z(0),\qquad \ddot l(t)\dot z(0)=\exp_H(tC)\cdot C( \dot z(0))=0.
$$
If $\dot z(0)\neq  0$, then we obtain that $\ddot l(t)=0$, and $l(t)=c t$, $c\in\mathbb R\setminus \{0\}$. In fact $c=1$, since 
\[
\dot l(0)\dot{z}(0)=c\dot{z}(0)=\dot{z}(0).%\qquad\text{Hence}~c=1.
\]
If $\dot z(0)=  0$, then we may assume $\dot x(0)\neq 0$, since we are considering non-trivial initial conditions. 
Then by differentiating equation ~\eqref{eq:one-3} we can deduce
$$
0= J_{\dot z(0)}(\dot x(0))=A(\dot x(0)).
$$
Then~\eqref{eq:one-0} and~\eqref{eq:one-1} imply
$$
x(l(t))=l(t)\dot x(0)=t\dot x(0).
$$
Therefore again $l(t)=t$. Thus, 
we see, that for any initial velocity $\dot\gamma(0)=(\dot x(0),\dot z(0))\not=0$ the reparametrization $l(t)$ of a homogeneous geodesic is the trivial one; that is $l(t)=t$. 
\end{proof}

\begin{corollary}
	In the notation of Proposition~\ref{pr.geodlem1} for a pseudo $H$-type Lie group $N_{r,s}$, for any $T\in  \mathfrak{n}_{r,s}$ there is $P = P(T) \in \mathfrak{h}$ such that 
	\begin{equation} \label{geodlem11}
		\langle[T + P, Q]_{\mathfrak{n}_{r,s}}, T \rangle = 0
	\end{equation}
	for any $Q\in  \mathfrak{n}_{r,s}$.
\end{corollary}
\begin{proof}
We write $X=T+P$, $\mathfrak n_{r,s}=\mathfrak z\oplus\mathfrak v$. The general form of the geodesic lemma states that there is a function $k=k(l)$ ($l=l(t)$ is a reparametrization)
such that,
\[
\langle[X,Q]_{\mathfrak{v}},T_{\mathfrak{v}}\rangle=k(l^{-1}(t))\,\langle T, Q\rangle,\qquad Q\in\mathfrak{n}_{r,s}
\]
holds.
The function $k$ is related with the reparametrization $l(t)$ as follows, see~\cite{Bar}. A geodesic $\gamma$ is homogeneous, if and only if the left invariant 
vector field $X^{*}$  defined by $X$ satisfies the equation
\begin{equation}\label{geodesic equation}
\nabla_{X*}(X^{*})=-k(l^{-1}(t))X^{*},\quad k(l^{-1}(t))=-\frac{\ddot{l}(t)}{\dot{l}(t)}
\quad \text{and is a  constant},
\end{equation}
where $\nabla$ is the Levi-Civita connection on $N_{r,s}$.

Since we showed that $l(t)=t$ in Proposition~\ref{prop:k=0},
we can deduce $k(l^{-1}(t))=0$. 
\end{proof}



