\begin{theorem}\label{pr_totgeod_h1}
Let $(N,g)$ be a 2-step pseudo-Riemannian nilmanifold with a non degenerate centre. Let us consider non-degenerate subspaces
$\mathfrak{z}_1\subset \mathfrak{z}$ and $\mathfrak{v}_1 \subset \mathfrak{v}$ and
the corresponding
orthogonal decompositions $\mathfrak{z}=\mathfrak{z}_1\oplus \mathfrak{z}_2$ and $\mathfrak{v}=\mathfrak{v}_1\oplus \mathfrak{v}_2$.
Then the following assertions hold:

{\rm 1)} If $J_Z(\mathfrak{v}_1)\subset \mathfrak{v}_2$ for any $Z\in \mathfrak{z}_2$,
then $\mathfrak{n}_1:=\mathfrak{z}_1\oplus \mathfrak{v}_1$ is a Lie subalgebra of $\mathfrak{n}$.


{\rm 2)} If $J_Z(\mathfrak{v}_1)\subset \mathfrak{v}_2$ for any $Z\in \mathfrak{z}_2$ and $J_Z(\mathfrak{v}_1)\subset \mathfrak{v}_1$ for any $Z\in \mathfrak{z}_1$,
then the Lie subalgebra $\mathfrak{n}_1$ {\rm(}with the induced scalar product{\rm)} generates
a totally geodesic submanifold $(N_1,g_1)$ of $(N,g)$.
\end{theorem}


\begin{proof} The first assertion is almost obvious. Indeed, $[\mathfrak{z}_1,\mathfrak{n}_1]\subset [\mathfrak{z},\mathfrak{n}]=0$ and we have
$\langle [X,Y],Z\rangle=\langle J_Z(X),Y \rangle=0$ for all $X,Y \in \mathfrak{v}_1$ and any  $Z\in \mathfrak{z}_2$ by the condition in 1).
Hence, $[\mathfrak{n}_1,\mathfrak{n}_1]=[\mathfrak{v}_1,\mathfrak{v}_1]\subset \mathfrak{z}_1 \subset \mathfrak{n}_1$, that proves 1).

Let us show the second assertion.
If $\nabla$ is the Levi-Civita connection on $(N,g)$, then we need to prove that $\nabla_X Y \in \mathfrak{n}_1$ for all $X,Y \in \mathfrak{n}_1$
($X,Y$ are identified with left-invariant vector fields).
Recall the Koszul formula
$$
2\langle \nabla_XY,W\rangle=\langle [X,Y],W\rangle +\langle [W,X],Y\rangle+\langle X,[W,Y]\rangle,\quad X,Y,W \in \mathfrak{n}.
$$
If $U=Z_1+X_1$ and $V=Z_2+X_2$, with $Z_1,Z_2 \in  \mathfrak{z}$, $X_1,X_2 \in \mathfrak{v}$, then
$$
2\nabla_{U} V=[X_1,X_2]-J_{Z_2} (X_1)-J_{Z_1} (X_2),
$$
see details, e.g.~\cite[page 813]{Eber94.2}.


Now, if $Z_1,Z_2 \in  \mathfrak{z}_1$, $X_1,X_2 \in \mathfrak{v}_1$,
then $[X_1,X_2]\in  \mathfrak{n}_1$ by 1) and $J_{Z_2} (X_1), J_{Z_1} (X_2) \in \mathfrak{v}_1$ by the condition of 2).
Therefore, $\nabla_{U} V \in \mathfrak{n}_1$ for all $U,V \in \mathfrak{n}_1$. This implies 2).
\end{proof}
\smallskip

Theorems~\ref{th_ps_totgeod} and~\ref{pr_totgeod_h1} will be useful for us in the following reformulation.

\begin{corollary}\label{co.totgeod.1}
Let $N$ be a 2-step pseudo $H$-type Lie group with the Lie algebra $\mathfrak n$. Let $\mathfrak n_1\subset\mathfrak n$
be a subalgebra which generates a totally geodesic submanifold $N_1$ of $N$. If $N_1$ is not a geodesic orbit manifold, then $N$ is neither a geodesic orbit manifold.
\end{corollary}


\section{The groups $N_{r,s}$ with $r+s> 3$, $(r,s)\neq (3,4)$}\label{sec:mod4}

%In this section we collect a series of results that allows us to reduce the study of geodesic orbit properties to the pseudo $H$-type Lie groups
%$N_{r,s}$ with $\max\{r,s\}< 8$ and $\min\{r,s\}< 4$, $s>1$, $r\geq 1$.

\subsection{Pseudo $H$-type Lie groups $N_{r,s}$ with $r+s=0\mod 4$}

We extend a result of~\cite{Kap83} to the pseudo $H$-type Lie algebras $\mathfrak n_{r,s}$.

\begin{lemma}\label{lem:even}
Let $D\in\mathfrak h$ be a skew-symmetric derivation of a pseudo $H$-type Lie algebra $\mathfrak n_{r,s}$, $r+s=0\mod 4$, see~\eqref{isotalg1}. If we write $D=(C,A)$, then $A$ satisfies
    $$
    A\prod_{i=1}^{r+s}J_{Z_i}=\prod_{i=1}^{r+s}J_{Z_i}A \quad\text{for}\ \ r+s=0\mod 4
    $$
    and any orthonormal basis $\{Z_1,\ldots,Z_{r+s}\}$ as in~\eqref{eq:brs}.
\end{lemma}
\begin{proof}
Note that if $D=(C,A)$ is a skew-symmetric derivation as in~\eqref{isotalg1}, then 
$$
A\prod_{i=1}^{r+s}J_{Z_i}=\prod_{i=1}^{r+s}J_{Z_i}A- \prod_{i=1}^{r+s}J_{Z_1}\ldots J_{C(Z_i)}\ldots J_{Z_{r+s}}.
$$
Thus we need to show that the last product on the right hand side vanishes.

Let $r+s=2$ and let $D=(C,A)$ be as in~\eqref{isotalg1}. Assume that $\{Z_1,Z_2\}$ is an orthonormal basis for $\mathfrak z$ and consider 3 possibilities.

If $\|Z_1\|^2=\|Z_2\|^2=\pm 1$ then any skew-symmetric map $C$ is given by $\pm a\begin{pmatrix}0&1\\-1&0\end{pmatrix}$, $a\in\mathbb R$.
    It implies
    \begin{eqnarray*}
        AJ_{Z_1}J_{Z_2}&=&J_{Z_1}J_{Z_2}A-J_{C(Z_1)}J_{Z_2}-J_{Z_1}J_{C(Z_2)}
        \\
        &=&
        J_{Z_1}J_{Z_2}A-a\Big(\mp J_{Z_1}^2\pm J_{Z_2}^2\Big)
      =
        J_{Z_1}J_{Z_2}A-a\Big(\Id-\Id\Big).
    \end{eqnarray*}

If $\|Z_1\|^2=-\|Z_2\|^2=1$ then any skew-symmetric map $C$ is given by $a\begin{pmatrix}0&1\\1&0\end{pmatrix}$, $a\in\mathbb R$, and analogous calculations show
$AJ_{Z_1}J_{Z_2}=J_{Z_1}J_{Z_2}A$.

We perform now the proof by induction of the dimension of the center.
    Let write a matrix $C=\{c_{ij}\}\subset \mathfrak{so}(r,s)$ with $r+s=4$. Then we will obtain
    \begin{eqnarray*}
        A\prod_{i=1}^4J_{Z_i}&=&\prod_{i=1}^4J_{Z_i}A
        \\
        &+&\Big(c_{12}J_{Z_2}^2+c_{21}J_{Z_1}^2\Big)J_{Z_3}J_{Z_4}
        -\Big(c_{13}J_{Z_3}^2+c_{31}J_{Z_1}^2\Big)J_{Z_2}J_{Z_4}
        +\Big(c_{14}J_{Z_4}^2+c_{41}J_{Z_1}^2\Big)J_{Z_2}J_{Z_3}
        \\
        &+&\Big(c_{23}J_{Z_3}^2+c_{32}J_{Z_2}^2\Big)J_{Z_1}J_{Z_4}
        -\Big(c_{24}J_{Z_4}^2+c_{42}J_{Z_2}^2\Big)J_{Z_1}J_{Z_3}
        +\Big(c_{34}J_{Z_4}^2+c_{43}J_{Z_3}^2\Big)J_{Z_1}J_{Z_2}
        \\
        &=&\prod_{i=1}^4J_{Z_i}A,
    \end{eqnarray*}
    since $c_{ij}J_{Z_j}^2+c_{ji}J_{Z_i}^2=0$ due to the skew symmetry in $\mathfrak{so}(r,s)$.
    By the induction of this arguments we obtain for any $r+s=4k$, $k=1,2,\ldots$
    $$
    \prod_{i=1}^{4k}J_{Z_1}\ldots J_{C(Z_i)}\ldots J_{Z_{4k}}=
    \sum_{i<j}(-1)^{j-i+1}\big(c_{ij}J_{Z_j}^2+c_{ji}J_{Z_i}^2\big)J_{Z_1}\ldots \hat J_{Z_i}\ldots \hat J_{Z_j}\ldots J_{Z_{4k}}=0,
    $$
    where $\hat J_{Z_i}$ denotes the omitted term in the product and $C=\{c_{ij}\}\in \mathfrak{so}(r,s)$, $r+s=0\mod 4$.
\end{proof}

\begin{prop}\cite[Proposition 3.3]{LowMich89}\label{prop:3page22}
    The volume element $\omega=\prod_{i=1}^{r+s}Z_i$ in $\Cl(\mathbb R^{r,s})$ has the following basic
    properties. Let $n=r+s$. Then
    \begin{equation}\label{eq:3.7}
        \omega^{2}=(-1)^{\frac{n(n+1)}{2}+s}.
    \end{equation}
    In particular, if $n=r+s$ is odd, then $Z\omega=\omega Z$ for all $Z\in \mathbb R^{r,s}$, and if $n=r+s$ is even, then $Z\omega=-\omega Z $ for all $Z\in \mathbb R^{r,s}$. Formula~\eqref{eq:3.7} can be also written as
\begin{equation}\label{eq:3.7-1}
\omega^2=
\begin{cases}
(-1)^s\quad&\text{if}\quad r+s=0\ \text{or}\ 3\mod 4,
\\
(-1)^{s+1}\quad&\text{if}\quad r+s=1\ \text{or}\ 2\mod 4.
\end{cases}
\end{equation}
\end{prop}

\begin{theorem}\label{th:42}
    If $r+s=0\mod 4$, $s=0\mod 2$, then the pseudo $H$-type Lie group $N_{r,s}$ is not a geodesic orbit nilmanifold.
\end{theorem}
\begin{proof} Let $Z_1,\ldots, Z_{r+s}$ be an orthonormal basis of the centre as in~\eqref{eq:brs} of the pseudo $H$-type Lie algebra $\mathfrak n_{r,s}=\mathfrak z\oplus\mathfrak v$.
    Consider the volume form $\omega=\prod_{i=1}^{r+s}Z_i$ in $\Cl(\mathbb R^{r,s})$. Then $\omega^2=1$ by Proposition~\ref{prop:3page22} since
$\frac{n(n+1)}{2}+s$ is even. Then operator
$J_{\omega}\colon \mathfrak v\to \mathfrak v$ decomposes the module $\mathfrak v$ into the eigenspaces of $\omega$:
    $$
    \mathfrak v=\mathfrak v^+\oplus\mathfrak v^-.
    $$
Moreover, since $A\omega=\omega A$ by Lemma~\ref{lem:even}, any $A$ in $D=(C,A)$ will leave the spaces $\mathfrak v^{\pm}$ invariant.

Take any $X\in \mathfrak v^+$ and $Z\in\mathfrak z$ as initial vector of a geodesic in the group $N_{r,s}$ (we can assume that $Z=Z_1$). Note that since $n=r+s$ is even we have
$
J_{Z_1}\omega=-\omega J_{Z_1}$
by Proposition~\ref{prop:3page22}. It implies that
\begin{equation}\label{eq:J1}
J_{Z_1}\colon \mathfrak v^+\to \mathfrak v^-.
\end{equation}
Thus if a skew-symmetric derivation $D=(C,A)$ exists, then it should leave the spaces $\mathfrak v^{\pm}$ invariant. This contradicts to the behavior of the restriction of $D=(C,A)$ to the set $\mathfrak x=\spann\{X,J_{Z_1}X,Z_1\}$ by~\eqref{eq:J1}.
\end{proof}

\begin{corollary}\label{cor:mu-nu}
The pseudo $H$-type Lie groups $N_{\mu,\nu}$, $(\mu,\nu)\in\{(8,0),(0,8),(4,4)\}$ are not geodesic orbit.
\end{corollary}

\begin{remark}
In the proof of Theorem~\ref{th:42} we implicitly used that for any non-null vector $Z\in\mathfrak z$ the map
$J_{Z}=(0,A)$ is a skew-symmetric derivation acting on the space $\mathfrak x=\spann_{\mathbb R}\{X,J_{Z}X,Z\}$ for any $X\in\mathfrak v$. Note also that for $\|X\|^2=\|Z\|^2=1$ the space $\mathfrak x$ is isometric to the Heisenberg algebra $\mathfrak n_{1,0}$, and for $\|X\|^2=\pm 1$, $\|Z\|^2=-1$ the space $\mathfrak x$ is isometric to the pseudo $H$-type algebra $\mathfrak n_{0,1}$.
\end{remark}



Before we proceed to show that $N_{r,s}$ is not geodesic orbit for $r+s=0\mod 4$, $s=1\mod 2$ we formulate a generalization of~\cite[Theorem 6]{Rie84} for the pseudo $H$-type Lie algebras.
Let us write $\mathfrak h=\mathfrak h_{r,s}$ in~\eqref{isotalg1} as
$$
\mathfrak h_{r,s}=(\mathfrak h_{r,s})_1\oplus (\mathfrak h_{r,s})_0,
$$
where
$$
(\mathfrak h_{r,s})_0=\{ D_0=(0,A),\ [A,J_{Z_j}]=0,\ \ j=1,\ldots,r+s \}
$$
is the Lie algebra of automorphisms of $\mathfrak n_{r,s}$ acting as identity on the center, and
$$
(\mathfrak h_{r,s})_1=\{D_1=(C,A),\ AJ_{Z}-J_{Z}A=J_{C^{\tau}(Z)} \}.
$$
According to formula~\eqref{eq:Phi} for an orthonormal basis $\{ Z_1,\ldots,Z_{r+s} \}$ for $\mathfrak z$ we have that a corresponding skew-symmetric derivation $D_1=(C,A)\in (\mathfrak h_{r,s})_1$ can be written as
$$
A(X)=J_{Z_i}J_{Z_j}(X),\quad C(Z)=2(\langle Z_i, Z \rangle_{r,s}Z_j-\langle Z_j, Z \rangle_{r,s}Z_i)=\ad_{Z_iZ_j}Z=[Z_iZ_j,Z].
$$
Let $Z_0\in\mathfrak z$ 
%and $X_0\in\mathfrak v$ 
be a non-null vector and
$\mathfrak z_0=\spann\{Z_0\}^{\perp}$ be the orthogonal complement in $\mathfrak z$. We also write $\Cl(\mathbb R^{r',s'})=\Cl(\mathfrak z_0)$, $r'+s'=r+s-1$ for the Clifford algebra generated by the space $(\mathfrak z_0,\langle\cdot\,,\cdot\rangle_{r,s})\vert_{\mathfrak z_0}$ and acting on the module $\mathfrak v$.

\begin{lemma}\label{lem:01}
Any extension of the skew-symmetric  derivation $(0,J_{Z_0})$
to a skew-symmetric derivation $D=(C,A)\in \mathfrak h_{r,s}$  must belong to
    $$
    \mathfrak h_{r,s}=(\mathfrak h_{r',s'})_1+(\mathfrak h_{r,s})_0,\quad r'+s'=r+s-1.
    $$
\end{lemma}
\begin{proof}
    Let us assume that $D=(C,A)\in\mathfrak h_{r,s}$ is an extension of $(0,J_{Z_0})$. Then $C(Z_0)=0$. Any $D\in(\mathfrak h_{r,s})_0$ will satisfy it. Let
    $Z_0,Z_1,\ldots, Z_{r+s-1}$ be an orthonormal basis of $\mathfrak z_{r,s}$. We write $\mathfrak z_{r',s'}=\spann\{Z_1,\ldots, Z_{r+s-1}\}$ then the set
    $$
    \{Z_kZ_l,\ \  0< k<l\leq r+s-1\}
    $$
    form a basis of $\mathfrak{so}(\mathfrak z_{r',s'})$ and $D_1=D_1(Z_kZ_l)=(C,A)$ generated by $Z_kZ_l$ satisfies
    $$
    A(X)=J_{Z_k}J_{Z_l}(X),\quad
    C(Z_0)=
    \begin{cases}
        0\quad&\text{if}\quad 0<k<l\leq r+s-1
        \\
        2\|Z_0\|^2 Z_l &\text{if}\quad 0=k<l\leq r+s-1.
    \end{cases}
    $$
    Thus $D_1(Z_kZ_l)=(C,A)\in (\mathcal D_{r',s'})_1$ and $C(Z_0)=0$.
\end{proof}

\begin{theorem}
    If $r+s=0\mod 4$, $s=1\mod 2$, then the pseudo $H$-type Lie group $N_{r,s}$ is not geodesic orbit manifold.
\end{theorem}
\begin{proof}
Let us write $s=s'+1$ and consider the  last vector $Z_{r+s}$, $\|Z_{r+s}\|^2=-1$ in the orthonormal basis $\{Z_1,\ldots, Z_{r+s}\}$ for $\mathfrak z_{r,s}$.
Note that $\omega^2=1$, where $\omega=\prod_{i=1}^{r+s}Z_i$ by~\eqref{eq:3.7-1}. The module $\mathfrak v_{r,s}$ of $\Cl(\mathbb R^{r,s})$ is decomposed into the direct sum of two subspaces
$$
\mathfrak v_{r,s}=\mathfrak v^+_{r,s'}+\oplus \mathfrak v^-_{r,s'},
$$
that are the eigenspaces of the volume form $\omega$. The spaces $\mathfrak v^{\pm}_{r,s'}$ are the non-equivalent modules of $\Cl(\mathbb R^{r,s'})=\Cl(\mathfrak z_{r,s}^{\perp})$, where $\mathfrak z_{r,s}^{\perp}$ is the orthogonal complement of $\spann\{Z_{r,s}\}$ in $\mathfrak z_{r,s}$.
%The spaces $\mathfrak v^{\pm}_{r,s'}$ are not submodules of $\Cl(\mathbb R^{r,s})$.
Due to $J_{Z_{r+s}}\omega=-\omega J_{z_{r+s}}$, the map $J_{Z_{r+s}}\colon
\mathfrak v^{+}_{r,s'}\to \mathfrak v^{-}_{r,s'}$ is an isomorphism  of vectors spaces.

If $D=(0,A)\in(\mathfrak h_{r,s})_0$, then
$$
[A,J_{Z_i}]=0\quad\Longrightarrow\quad A\omega=\omega A
$$
by Lemma~\ref{lem:even} and therefore $A$ must preserve the spaces $\mathfrak v^{\pm}_{r,s'}$. If  $D=(C,A)\in(\mathfrak h_{r,s'})_1$, then $A$ also leaves spaces $\mathfrak v^{\pm}_{r,s'}$ invariant since $\mathfrak v^{\pm}_{r,s'}$ are submodules of the Clifford algebra $\Cl(\mathbb R^{r,s'})=\Cl(\mathfrak z_{r,s}^{\perp})$.

The extension $D=(0,A)$ of $(0,J_{Z_{r+s}})$ acting on the $\mathfrak x=\spann\{X,J_{Z_{r+s}}(X),Z_{r+s}\}$, $X\in \mathfrak v^+_{r,s'}$ must belong to $(\mathfrak h_{r,s'})_1+(\mathfrak h_{r,s})_0$ by Lemma~\ref{lem:01}. By the above arguments $A$ should preserve the submodule $\mathfrak v^+_{r,s'}$. But this contradicts to the fact that the restriction $A\vert_{\mathfrak x}=J_{Z_{r+s}}$ of $A$ to $\mathfrak x$ has the property $J_{Z_{r+s}}(X)\in\mathfrak v^-_{r,s'}$.
\end{proof}




\subsection{The geodesic orbit property and the periodicity property}

As another illustration of Theorem~\ref{pr_totgeod_h1} and Corollary~\ref{co.totgeod.1} and the structure of admissible modules under the periodicity property,
we show the following theorem.

\begin{theorem}\label{th:NGO1}
If a pseudo $H$-type Lie group $N_{r,s}$ is not geodesic orbit, then $N_{r+\mu,s+\nu}$ with $(\mu,\nu)\in\{(8,0),(0,8),(4,4)\}$ is neither geodesic orbit.
\end{theorem}

\begin{proof}
Consider a pseudo $H$-type Lie algebra $\mathfrak n_{r+\mu,s+\nu}$ with the minimal admissible module $\mathfrak v_{r+\mu,s+\nu}=\mathfrak v_{r,s}\otimes \mathfrak v_{\mu,\nu}$, the scalar product
$$
\langle\cdot\,,\cdot\rangle_{\mathfrak v_{r+\mu,s+\nu}}=\langle\cdot\,,\cdot\rangle_{\mathfrak v_{r,s}}\cdot\langle\cdot\,,\cdot\rangle_{\mathfrak v_{\mu,\nu}},
$$
and the basis $\{u_i\otimes v_k,\ i=1,\ldots,\dim(\mathfrak v_{r,s}),\ k=1,\ldots,16\}$. Here $\{u_i\}_{i=1}^{\dim(\mathfrak v_{r,s})}$
is an orthonormal invariant basis for $\mathfrak v_{r,s}$ generated by a vector $u\in E^{+1}_{r,s}$ with $\langle u, u\rangle_{\mathfrak v_{r,s}}=1$,
see Proposition~\ref{prop:basis}. Analogously, $\{v_k\}_{k=1}^{16}$ is the orthonormal invariant basis for $\mathfrak v_{\mu,\nu}$ from~\eqref{eq:basis-munu}
generated by a unit vector $v\in E^{+1}_{\mu,\nu}$. The orthonormal basis
\begin{equation}\label{eq:brsmn}
Z_1,\ldots,Z_{r+s},\zeta_1,\ldots,\zeta_{\mu+\nu}
\end{equation}
%{\color{magenta} Is this basis a union of two arbitrary bases for the centers of $\mathfrak n_{r,s}$ and $\mathfrak n_{\mu,\nu}$?}
for $\mathbb R^{r+\mu,s+\nu}$ is the union of the basis~\eqref{eq:brs} for $\mathbb R^{r,s}$ and the basis~\eqref{eq:zeta-basis} for $\mathbb R^{\mu,\nu}$. The basis~\eqref{eq:brsmn}
acts on
$\mathfrak v_{r+\mu,s+\nu}=\mathfrak v_{r,s}\otimes \mathfrak v_{\mu,\nu}$ by
$$
\tilde J_{Z_{l}}=J_{Z_{l}}\otimes\Id, \ l=1,\ldots,\dim{\mathfrak v_{r,s}},
\qquad \tilde J_{\zeta_{m}}=\Id\otimes J_{\zeta_{m}},\ m=1,\ldots,16.
$$
The commutators in $\mathfrak n_{r+\mu,s+\nu}$ satisfy the following relations
\begin{equation}\label{eq:111}
    [u_i\otimes v_k,u_j\otimes v_k]_{\mathfrak v_{r+\mu,s+\nu}}=[u_i,u_j]_{\mathfrak v_{r,s}}\|v_k\|^2,\quad i,j=1,\ldots,\dim{\mathfrak v_{r,s}},
\end{equation}
for any $k=1,\ldots,16$. Indeed, let $Z\in\mathbb R^{r,s}$, then
\begin{eqnarray*}
    \langle Z,[u_i\otimes v_k,u_j\otimes v_k]_{\mathfrak v_{r+\mu,s+\nu}}\rangle_{r+\mu,s+\nu}
    &=&
    \langle \tilde J_Z(u_i\otimes v_k),u_j\otimes v_k\rangle_{\mathfrak v_{r+\mu,s+\nu}}
    \\
    &=&\langle J_Z(u_i)\otimes v_k,u_j\otimes v_k\rangle_{\mathfrak v_{r+\mu,s+\nu}}
    \\
    &=&
    \langle J_Z(u_i),u_j\rangle_{\mathfrak v_{r,s}}\cdot\langle v_k,v_k\rangle_{\mathfrak v_{\mu,\nu}}
    \\
    &=&
    \langle Z, [u_i,u_j]_{\mathfrak v_{r,s}}\rangle_{r,s}\|v_k\|^2.
\end{eqnarray*}
since
$
\langle Z,\bullet\rangle_{r+\mu,s+\nu}=\langle Z,\bullet\rangle_{r,s}
$
for any $Z\in \mathbb R^{r,s}$. Analogously
\begin{equation}\label{eq:112}
    [u_k\otimes v_i,u_k\otimes v_j]_{\mathfrak v_{r+\mu,s+\nu}}=[v_i,v_j]_{\mathfrak v_{\mu,\nu}}\|u_k\|^2\quad i,j=1,\ldots,16,
\end{equation}
and any $k=1,\ldots,\dim{\mathfrak v_{r,s}}$.
\\

We denote
$$\mathbb R^{r,s}=\mathfrak z_1=\spann\{Z_1,\ldots, Z_{r+s}\},\qquad\mathbb R^{\mu,\nu}=\mathfrak z_2=\spann\{\zeta_1,\ldots, \zeta_{\mu+\nu}\},
$$
Equality~\eqref{eq:111} and Theorem~\ref{pr_totgeod_h1} show that the pseudo $H$-type Lie algebra $\mathfrak n_{r,s}=\mathfrak v_{r,s}\oplus\mathbb R^{r,s}$ is a subalgebra of $\mathfrak n_{r+\mu,s+\nu}=\mathfrak v_{r+\mu,s+\nu}\oplus\mathbb R^{r+\mu,s+\nu}$. We have 16 such subalgebras, which have the form
$$
\mathfrak v_{r,s}\otimes\spann\{v_k\}\oplus\mathbb R^{r,s},\quad v_k\in \mathfrak v_{\mu,\nu},\quad k=1,\ldots, 16.
$$

Analogously,~\eqref{eq:112} implies that there are $m=\dim(\mathfrak v_{r,s})$ subalgebras isomorphic to $\mathfrak n_{\mu,\nu}$ inside the Lie algebra $\mathfrak n_{r+\mu,s+\nu}=\mathfrak v_{r+\mu,s+\nu}\oplus\mathbb R^{r+\mu,s+\nu}$. Analogously to the above, they have the form
$$
\spann\{u_k\}\otimes \mathfrak v_{\mu,\nu}\oplus\mathbb R^{\mu,\nu},\quad u_k\in \mathfrak v_{r,s},\quad k=1,\ldots, \dim(\mathfrak v_{r,s}).
$$

Now, we want to apply Corollary~\ref{co.totgeod.1}. We set
$$
\mathfrak v_1=\mathfrak v_{r,s}\otimes E^{+1}_{\mu,\nu},\quad \mathfrak v_2=\bigoplus_{j=1}^{8}\Big(\mathfrak v_{r,s}\otimes J_{\zeta_{j}}E^{+1}_{\mu,\nu}\Big)\bigoplus_{j=2}^{8}\Big(\mathfrak v_{r,s}\otimes J_{\zeta_1}J_{\zeta_j}E^{+1}_{\mu,\nu}\Big).
$$
Under this notation we obtain from~\eqref{eq:111} for $v_1=v\in E^{+1}_{\mu,\nu}$
$$
\mathfrak v_{r+\mu,s+\nu}=\mathfrak v_1\oplus \mathfrak v_2,\quad \mathfrak n_1=\mathfrak v_1\oplus\mathfrak z_1\cong\mathfrak n_{r,s}
$$
and moreover
$$
J_{Z_i}(\mathfrak v_1)\subset\mathfrak v_1\ \ \text{for all}\ \ Z_i\in\mathfrak z_1,\qquad
J_{\zeta_j}(\mathfrak v_1)\subset\mathfrak v_2\ \ \text{for all}\ \ \zeta_j\in\mathfrak z_2.
$$
This implies that the pseudo $H$-type Lie algebra $\mathfrak n_1\cong\mathfrak n_{r,s}$ generates a totally geodesic subgroup $N_{r,s}$ in $N_{r+\mu,s+\nu}$. By the hypothesis of the theorem $N_{r,s}$ is not geodesic orbit and Corollary~\ref{co.totgeod.1} implies that $N_{r+\mu,s+\nu}$ is neither geodesic orbit.
\end{proof}
\smallskip

\begin{theorem}
Pseudo $H$-type Lie groups $N_{r,s}$ with
$\max\{r,s\}\geq 8$ and $\min\{r,s\}\geq 4$ are not geodesic orbit.
\end{theorem}
\begin{proof}
Let $N_{r',s'}$ be a pseudo $H$-type Lie group with $\max\{r,s\}\geq 8$ and $\min\{r,s\}\geq 4$. Then write $r'=r+\mu$, $s'=s+\nu$ for some $(\mu,\nu)\in\{(8,0),(0,8),(4,4)\}$. Arguing as in the proof of Theorem~\ref{th:NGO1}, we show that for
$$\mathbb R^{r,s}=\mathfrak z_1=\spann\{Z_1,\ldots, Z_{r+s}\},\qquad\mathbb R^{\mu,\nu}=\mathfrak z_2=\spann\{\zeta_1,\ldots, \zeta_{\mu+\nu}\},
$$
and
$$
\mathfrak v_1=\spann\{u\}\otimes \mathfrak v_{\mu,\nu},\quad
\mathfrak v_2=\mathfrak v_{r,s}\otimes E^{+1}_{\mu,\nu},
$$
where $u\in E^{+1}_{r,s}$ with $\langle u, u\rangle_{\mathfrak v_{r,s}}=1$, the Lie algebra
$$
\mathfrak n_2=\mathfrak v_2\oplus\mathfrak z_2\cong \mathfrak n_{\mu,\nu}
$$
is a subalgebra of $\mathfrak n_{r+\mu,s+\nu}$. Moreover
$$
J_{Z_i}(\mathfrak v_2)\subset\mathfrak v_2\ \ \text{for all}\ \ Z_i\in\mathfrak z_1,\qquad
J_{\zeta_j}(\mathfrak v_2)\subset\mathfrak v_1\ \ \text{for all}\ \ \zeta_j\in\mathfrak z_2.
$$
It implies that the pseudo $H$-type Lie algebra $\mathfrak n_2\cong\mathfrak n_{\mu,\nu}$ generates a totally geodesic subgroup $N_{\mu,\nu}$ in $N_{r+\mu,s+\nu}$.
By Corollary~\ref{cor:mu-nu}
the group $N_{\mu,\nu}$ is not geodesic orbit and Corollary~\ref{co.totgeod.1} implies that $N_{r+\mu,s+\nu}$ is neither geodesic orbit.
\end{proof}








\subsection{Pseudo $H$-type groups $N_{r,s}$, for  $(r,1)$, $r\geq 3$ and $(0,s)$, $s>0$.}

\begin{theorem}\label{th:s>3}
    The pseudo $H$-type Lie groups $N_{0,s}$ with $s\geq 4$ are not geodesic orbit.
\end{theorem}

\begin{proof}
Let $\{Z_{i}\}_{i=1}^{s}$ be an orthonormal basis of the center $\mathbb{R}^{0,s}$.
Consider a positive involution $p=Z_{1}Z_{2}Z_{3}Z_{4}$ and a vector $X\in\mathfrak v$, $\langle X,X\rangle_{\mathfrak v}=1$ such that $J_{p}(X)=X$.

Assume that a geodesic defined by an initial vector $(X,Z_{1})\in \mathfrak n_{0,s}$ is homogeneous.
Then there is $D=(C,A)\in\mathfrak h$ such that
$$
A(X)=J_{Z_{1}}(X),\quad  C(z_{1})=0,\quad [A,J_{Z}]=J_{C(Z)}, \quad Z\in \mathbb{R}^{0,s}.
$$
Then we obtain
\begin{eqnarray}\label{eq:YYY}
J_{Z_{1}}(X)&=&A(X)=A(J_{p}(X))
\\
&=&
J_{p}A(X)-J_{Z_1}J_{C(Z_2)}J_{Z_3}J_{Z_4}(X)-J_{Z_1}J_{Z_2}J_{C(Z_3)}J_{Z_4}(X)-J_{Z_1}J_{Z_2}J_{Z_3}J_{C(Z_4)}(X)\nonumber
\\
&=&
-J_{Z_{1}}(X)-
J_{Z_1}J_{C(Z_2)}J_{Z_3}J_{Z_4}(X)-J_{Z_1}J_{Z_2}J_{C(Z_3)}J_{Z_4}(X)-J_{Z_1}J_{Z_2}J_{Z_3}J_{C(Z_4)}(X),\nonumber
\end{eqnarray}
where in the last step we used
\begin{equation}\label{eq:Th10}
J_{p}A(X)=J_{p}J_{Z_{1}}(X)=-J_{Z_{1}}J_{p}(X)=-J_{Z_{1}}(X).
\end{equation}
 Hence $2J_{Z_{1}}(X)=Y$ with
$$
Y=-J_{Z_1}J_{C(Z_2)}J_{Z_3}J_{Z_4}(X)-J_{Z_1}J_{Z_2}J_{C(Z_3)}J_{Z_4}(X)-J_{Z_1}J_{Z_2}J_{Z_3}J_{C(Z_4)}(X).
$$
From one side $Y$ satisfies $\langle Y,Y\rangle>0$ by~\eqref{eq:JJJ}. From the other side $\langle 2J_{Z_{1}}(X),2J_{Z_{1}}(X)\rangle=-4$,
which is a contradiction.
\end{proof}


\begin{theorem}\label{th:s=1}
The pseudo $H$-type Lie groups $N_{r,1}$, $r\geq 2$, are not geodesic orbit.
\end{theorem}

\begin{proof}
Fix a basis $\{Z_i\}_{i}^{r+1}$ as in~\eqref{eq:brs}. Let $\mathcal S$ be a maximal subgroup of  $G(B_{r,1})$ of positive involutions and let $PI_{r,1}$ be its generating set. Note that $PI_{r,1}=PI_{r,0}$ by the structure of involutions, see~\eqref{eqT1T2}, which says that none of positive involutions in $PI_{r,1}$  contains the basis vector $Z_{r+1}$. We assume that the set $PI_{r,1}$ contains an involution $q=Z_{i_1}\ldots J_{Z_{i_a}}$ of Type 2 as was defined in~\eqref{eqT1T2}. This assumption always can be achieved by removing one of the basis vectors or multiplying some of the involutions.

Let us choose a geodesic $\gamma(t)=(z(t),x(t))$ with an initial vector $(Z_{r+1},X)$ such that $\langle X,X\rangle_{\mathfrak v}=1$, and $J_q(X)=X$ and assume that the geodesic is homogeneous.
Then there is $D=(C,A)\in\mathfrak h$ such that
$$
A(X)=J_{Z_{r+1}}(X),\quad C(Z_{r+1})=0,\quad
[A,J_{Z}]=J_{C^{\tau}(Z)},\quad Z\in \mathbb{R}^{r,0}.
$$
The condition $C(Z_{r+1})=0$ implies that $C$ has vanishing last column. Now as in~\eqref{eq:YYY} of Theorem~\ref{th:s>3} we have an equality
    \[
J_{Z_{r+1}}(X) =A(X)= A(J_q(X))=J_qA(X)-J_{\dot{q}}(X)
    =-J_{Z_{r+1}}(X)-J_{\dot{q}}(X)
    \]
    with
 \[
\dot{q}=C(Z_{i_1})\cdots Z_{i_a}+Z_{i_1}C(Z_{i_2})\cdots Z_{i_a}+
\ldots +Z_{i_1}Z_{i_2}\cdots C(Z_{i_a}).
\]
In the last equality we used $J_{q}J_{Z_{r+1}}(X)=-J_{Z_{r+1}}J_{q}(X)$ since $q$ contains odd number of basis vectors and does not contain $Z_{r+1}$. The rest of calculations as in~\eqref{eq:Th10}.
$$
2J_{Z_{r+1}}(X)=-J_{\dot{q}}(X).%\label{right terms}
$$
Note that $\dot{q}$ does not include $Z_{r+1}$  because $C(Z_{i})=\sum_{j=1}^{r}c_{ij}Z_j$ since $c_{ij}=0$ for $j=r+1$. Therefore $\langle J_{\dot{q}}(X),J_{\dot{q}}(X)\rangle_{\mathfrak v}\geq 0$ by~\eqref{eq:JJJ}. From the other side $\langle 2J_{Z_{r+1}}(X),2J_{Z_{r+1}}(X)\rangle_{\mathfrak v}=-4$, which is a contradiction.
\end{proof}

