In general there are two cases of the dimensions of minimal admissible modules $\mathfrak v_{r,s}$
according to the relations of the values $\ell(r,s)$, $\ell(r+1,s)$ and $\ell(r,s+1)$:
\[
\ell(r,s)\leq \ell(r+1,s)\leq \ell(r,s)+1~\text{and}~\ell(r,s)\leq \ell(r,s+1)\leq \ell(r,s)+1.
\]
Then
\begin{align*}
    & [1]\quad \ell(r,s)=\ell(r+1,s)~~~\text{implies}~~\dim \mathfrak v_{r+1,s}=2\dim \mathfrak v_{r,s},\\
    & [2]\quad \ell(r,s)+1=\ell(r+1,s)~~~\text{implies}~~\dim \mathfrak v_{r+1,s}=\dim \mathfrak v_{r,s},\\
    & [3]\quad \ell(r,s)=\ell(r,s+1)~~~\text{implies}~~\dim \mathfrak v_{r,s+1}=2\dim \mathfrak v_{r,s},\\
    & [4]\quad \ell(r,s)+1=\ell(r,s+1)~~~\text{implies}~~\dim \mathfrak v_{r,s+1}=\dim \mathfrak v_{r,s}.
\end{align*}

In cases $[1]$  and $[3]$ a module $\mathfrak v_{r,s}$ is a submodule of $\mathfrak v_{r+1,s}$ ($\mathfrak v_{r,s+1}$), which is not true for cases $[2]$ and $[4]$. This can be shown as follows.

We fix a set $PI_{r,s}$, construct an orthonormal basis $\{X_i\}_{i=1}^{\dim \mathfrak v_{r,s}}$ for $\mathfrak v_{r,s}$ as in Proposition~\ref{prop:basis} generated by a vector $v$, $\langle v,v\rangle_{\mathfrak v_{r,s}}=1$ which is $1$-eigen vector for all the involutions in $PI_{r,s}$.
We restrict the proof to the case $\mathfrak n_{r,s+1}$, since for $\mathfrak n_{r+1,s}$ the arguments are similar.
The set $\mathfrak v_{r,s}=\spann\{{X_i,\ i=1,\ldots,\dim \mathfrak v_{r,s}}\}$ is a subset of $\mathfrak v_{r,s+1}$ and a module under the action of $\Cl(\mathbb R^{r,s})$. The map $J_{Z_{r+s+1}}$ is an orthogonal transformation on $\mathfrak v_{r,s+1}$ and therefore  $J_{Z_{r+s+1}}(\mathfrak v_{r,s})\subset \mathfrak v_{r,s+1}$ and moreover $J_{Z_{r+s+1}}(\mathfrak v_{r,s})$ is a minimal admissible module for $\Cl(\mathbb R^{r,s})$. Thus
$$
\mathfrak v_{r,s+1}=\mathfrak v_{r,s}\oplus J_{Z_{r+s+1}}(\mathfrak v_{r,s})
$$
is an orthogonal decomposition in two minimal admissible modules for $\Cl(\mathbb R^{r,s})$. The set $\{X_i,J_{Z_{r+s+1}}(X_i),\ i=1,\ldots,\dim(\mathfrak v_{r,s})\}$ is an orthonormal basis for $\mathfrak v_{r,s+1}$.

\begin{theorem}\label{th:1-3}
In the above notation in cases $[1]$ and $[3]$ the pseudo $H$-type Lie groups $N_{r,s}$ are totally geodesic submanifolds of $N_{r+1,s}$ and $N_{r,s+1}$, respectively.
\end{theorem}
\begin{proof} We write for $\mathfrak n_{r,s+1}$
$$
\mathbb R^{r,s}=\mathfrak z_1=\spann\{Z_1,\ldots,Z_{r+s}\},\quad\mathfrak z_2=\spann\{Z_{r+s+1}\},
$$
and
$$
\mathfrak v_1=\mathfrak v_{r,s}\quad \mathfrak v_2=J_{Z_{r+s+1}}(\mathfrak v_{r,s}).
$$
Then we obtain that
$$
J_{Z_k}(\mathfrak v_1)\subset \mathfrak v_1,\quad \text{for any}\quad Z_k\in\mathfrak z_1
$$
since $\mathfrak v_1$ is a submodule of $\Cl(\mathbb R^{r,s})$. We also have
$$
J_{Z_{r+s+1}}(\mathfrak v_1)\subset \mathfrak v_2.
$$
Applying Theorem~\ref{pr_totgeod_h1} and Corollary~\ref{co.totgeod.1} we finish the proof.
\end{proof}

\begin{corollary}
The pseudo $H$-type Lie groups
$$
N_{2,7},\quad N_{3,6},\quad N_{3,7}\quad N_{6,3},\quad N_{7,2},\quad N_{7,3}
$$
are not geodesic orbit
\end{corollary}
\begin{proof}
Applying Theorem~\ref{th:1-3} to the groups in Table~\ref{tab:1}  and using Table~\ref{tab:2}   we finish the proof. For instance since $N_{7,1}$ is not geodesic orbit and
$$
\ell(7,1)=\ell(7,2)=\ell(7,3).
$$
We conclude that $N_{7,2}$ and $N_{7,3}$ are not geodesic orbit.
\end{proof}
\begin{remark} One can show the following.
In the cases $[2]$ and $[4]$, the module $\mathfrak v_{r+1,s}$ (or $\mathfrak v_{r,s+1}$)
is also a minimal admissible module
of the Clifford algebra $\Cl(\mathbb R^{r,s})$. In these  cases the natural inclusion map
    \[
    \mathfrak{n}_{r,s}(\mathfrak v_{r,s})=
    \mathfrak{n}_{r,s}(\mathfrak v_{r+1,s})\subset  \mathfrak{n}_{r+1,s}(\mathfrak v_{r+1,s})
    \]
    is not a Lie algebra homomorphism
\end{remark}

\begin{theorem}
The pseudo $H$-type Lie groups $N_{r,s}$ for 
$$
(r,s)\in\{(1,4),(1,5),(1,6),(2,3),(2,4),(2,5),(3,2),(3,3),(4,2),(4,3),(5,2)\}
$$
are not geodesic orbit.
\end{theorem}
\begin{proof}
We start from {\it pseudo $H$-type Lie groups $N_{1,4}$ and $N_{3,2}$}.

We choose an orthonormal basis for centers as in~\eqref{eq:brs} and the generating set $\{p_1,p_2\}$ for the maximal group of positive involutions,
where
$$
p_1=Z_1Z_2Z_3,\quad p_2=Z_2Z_3Z_4Z_5.
$$
Let $v\in \{X\in \mathfrak v:\ J_{p_1}(X)=J_{p_2}(X)=X\}$, $\|v\|^2=1$.
We construct an orthonormal invariant basis for $\mathfrak v$:
$$
\begin{array}{lllll}
& X_1=v,\quad & X_2=J_{Z_2}(v),\quad & X_3=J_{Z_4}(v),\quad & X_4=J_{Z_2}J_{Z_4}(v),\quad
\\
&X_5=J_{Z_1}(v),\quad &X_6=J_{Z_3}(v),\quad &X_7=J_{Z_5}(v),\quad &X_8=J_{Z_3}J_{Z_4}(v).
\end{array}
$$
We denote
$$
\mathfrak z_1=\spann\{Z_2,Z_4\},\quad \mathfrak z_2=\spann\{Z_1,Z_3,Z_5\},\quad \mathfrak z=\mathfrak z_1\oplus \mathfrak z_2,
$$
$$
\mathfrak v_1=\spann\{X_1,\ldots X_4\},\quad \mathfrak v_2=\spann\{X_5,\ldots ,X_8\},\quad \mathfrak v=\mathfrak v_1\oplus \mathfrak v_2.
$$
It is obvious that $J_{Z_k}(\mathfrak v_1)\subset \mathfrak v_1$ for $k=1,4$. If $(r,s)=(1,4)$, then the pseudo $H$-type Lie algebra $\mathfrak z_1\oplus \mathfrak v_1$ is isomorphic to $\mathfrak n_{0,2}$. If $(r,s)=(3,2)$, then the pseudo $H$-type Lie algebra $\mathfrak z_1\oplus \mathfrak v_1$ is isomorphic to $\mathfrak n_{1,1}$.

To show that $J_{Z_k}(\mathfrak v_1)\subset \mathfrak v_2$ for $k=2,3,5$ we observe that $p_1p_2=-Z_1Z_4Z_5$ and $J_{Z_1Z_4Z_5}(v)=-v$. Then it is easy to see the following
$$
\begin{array}{lllll}
&J_{Z_1} (X_1)=\pm X_5,\quad &J_{Z_1} (X_2)=\pm X_6,\quad &J_{Z_1} (X_3)=\pm X_7,\quad &J_{Z_1} (X_4)=\pm X_8,\quad
\\
&J_{Z_3} (X_1)=\pm X_6,\quad &J_{Z_3} (X_2)=\pm X_5,\quad &J_{Z_3} (X_3)=\pm X_8,\quad &J_{Z_3} (X_4)=\pm X_7,\quad
\\
&J_{Z_5} (X_1)=\pm X_7,\quad &J_{Z_5} (X_2)=\pm X_8,\quad &J_{Z_5} (X_3)=\pm X_5,\quad &J_{Z_5} (X_4)=\pm X_6.
\end{array}
$$
Theorem~\ref{pr_totgeod_h1} and Corollary~\ref{co.totgeod.1} imply that pseudo $H$-type Lie groups $N_{1,4}$ and $N_{3,2}$ are not geodesic orbit.

Consider {\it pseudo $H$-type Lie groups $N_{1,6}$ and $N_{5,2}$}.

We choose an orthonormal basis for the center as in~\eqref{eq:brs} and the generating set $\{p_1,p_2,p_3\}$ for the maximal group of positive involutions,
where
$$
p_1=Z_1Z_2Z_3,\quad p_2=Z_2Z_3Z_4Z_5, \quad p_2=Z_2Z_3Z_6Z_7.
$$
Let $v\in \{X\in \mathfrak v:\ J_{p_1}(X)=J_{p_2}(X)=J_{p_3}(X)=X\}$, $\|v\|^2=1$.
We construct an orthonormal invariant basis for $\mathfrak v$:
$$
\begin{array}{lllll}
&X_1=v,\quad &X_2=J_{Z_2}(v),\quad &X_3=J_{Z_4}(v),\quad &X_4=J_{Z_2}J_{Z_4}(v),\quad
\\
&X_5=J_{Z_1}(v),\quad &X_6=J_{Z_3}(v),\quad &X_7=J_{Z_5}(v),\quad &X_8=J_{Z_3}J_{Z_4}(v),\quad
\\
&X_9=J_{Z_6}(v),\quad &X_{10}=J_{Z_7}(v),\quad &X_{11}=J_{Z_2}J_{Z_6}(v),\quad &X_{12}=J_{Z_2}J_{Z_7}(v),\quad
\\
&X_{13}=J_{Z_4}J_{Z_6}(v),\quad &X_{14}=J_{Z_4}J_{Z_7}(v),\quad &X_{15}=J_{Z_2}J_{Z_4}J_{Z_6}(v),\quad &X_{6}=J_{Z_2}J_{Z_4}J_{Z_7}(v).
\end{array}
$$
We denote
$$
\mathfrak z_1=\spann\{Z_2,Z_4\},\quad \mathfrak z_2=\spann\{Z_1,Z_3,Z_5,Z_6,Z_7\},\quad \mathfrak z_{1,6}=\mathfrak z_1\oplus \mathfrak z_2
$$
$$
\mathfrak v_1=\spann\{X_1,\ldots X_4\},\quad \mathfrak v_2=\spann\{X_5,\ldots ,X_{16}\},\quad \mathfrak v_{1,6}=\mathfrak v_1\oplus \mathfrak v_2
$$
As in the previous case we show that if $(r,s)=(1,6)$, then $\mathfrak z_1\oplus \mathfrak v_1$ is isomorphic to $\mathfrak n_{0,2}$ and if $(r,s)=(5,2)$, then $ \mathfrak z_1\oplus \mathfrak v_1$ is isomorphic to $\mathfrak n_{1,1}$.
Theorem~\ref{pr_totgeod_h1} and Corollary~\ref{co.totgeod.1} imply that the groups $N_{1,6}$ and $N_{5,2}$  are not geodesic orbit.


{\it Pseudo $H$-type Lie group $N_{2,3}$}.
We choose an orthonormal basis for the center as in~\eqref{eq:brs} and the generating set $PI_{2,3}=\{p_1,p_2\}$ for the maximal group of positive involutions,
where
$$
p_1=Z_1Z_4Z_5,\quad p_2=Z_1Z_2Z_3Z_4.
$$
Let $v\in \{X\in \mathfrak v_{2,3}:\ J_{p_1}(X)=J_{p_2}(X)=X\}$, $\|v\|^2=1$.
We construct an orthonormal invariant basis as in the case $N_{3,2}$.
All other calculations are analogous to the case $N_{3,2}$.

{\it Pseudo $H$-type Lie groups $N_{2,4}$ and $N_{3,3}$}.
We choose an orthonormal basis for the center as in~\eqref{eq:brs} and the generating set $\{p_1,p_2,p_3\}$ for the maximal group of positive involutions,
where
$$
p_1=Z_1Z_4Z_5,\quad p_2=Z_1Z_2Z_3Z_4,\quad p_3=Z_1Z_2Z_5Z_5
$$
Let $v\in \{X\in \mathfrak v:\ J_{p_1}(X)=J_{p_2}(X)=J_{p_3}(X)=X\}$, $\|v\|^2=1$.
We construct an orthonormal invariant basis for $\mathfrak v$:
$$
\begin{array}{lllll}
&X_1=v,\quad &X_2=J_{Z_5}(v),\quad &X_3=J_{Z_6}(v),\quad &X_4=J_{Z_5}J_{Z_6}(v),\quad
\\
&X_5=J_{Z_1}(v),\quad &X_6=J_{Z_2}(v),\quad &X_7=J_{Z_3}(v),\quad &X_8=J_{Z_4}(v).
\end{array}
$$
We denote
$$
\mathfrak z_1=\spann\{Z_5,Z_6\},\quad \mathfrak z_2=\spann\{Z_1,Z_2,Z_3,Z_4\},\quad \mathfrak z=\mathfrak z_1\oplus \mathfrak z_2,
$$
$$
\mathfrak v_1=\spann\{X_1,\ldots X_4\},\quad \mathfrak v_2=\spann\{X_5,\ldots ,X_{8}\},\quad \mathfrak v=\mathfrak v_1\oplus \mathfrak v_2.
$$
It is obvious that $J_{Z_k}(\mathfrak v_1)\subset \mathfrak v_1$ for $k=5,6$. The pseudo $H$-type Lie algebra $\mathfrak z_1\oplus\mathfrak v_1$ is isomorphic to $\mathfrak n_{0,2}$.
To show that $J_{Z_k}(\mathfrak v_1)\subset \mathfrak v_2$ for $k=1,2,3,4$ one can check the following
$$
\begin{array}{lllll}
&J_{Z_1} (X_1)=\pm X_5,\quad &J_{Z_1} (X_2)=\pm X_8,\quad &J_{Z_1} (X_3)=\pm X_7,\quad &J_{Z_1} (X_4)=\pm X_6,\quad
\\
&J_{Z_2} (X_1)=\pm X_6,\quad &J_{Z_2} (X_2)=\pm X_7,\quad &J_{Z_2} (X_3)=\pm X_8,\quad &J_{Z_2} (X_4)=\pm X_5,\quad
\\
&J_{Z_3} (X_1)=\pm X_7,\quad &J_{Z_3} (X_2)=\pm X_6,\quad &J_{Z_3} (X_3)=\pm X_5,\quad &J_{Z_3} (X_4)=\pm X_8,\quad
\\
&J_{Z_4} (X_1)=\pm X_8,\quad &J_{Z_4} (X_2)=\pm X_5,\quad &J_{Z_4} (X_3)=\pm X_6,\quad &J_{Z_4} (X_4)=\pm X_7.
\end{array}
$$
Theorem~\ref{pr_totgeod_h1} and Corollary~\ref{co.totgeod.1} imply that pseudo $H$-type Lie groups $N_{2,4}$ and $N_{3,3}$ are not geodesic orbit.


To finish the proof we apply Theorem~\ref{th:1-3} to the cases
$$
\ell(1,4)=\ell(1,5),\quad \ell(3,2)=\ell(4,2),\quad \ell(2,4)=\ell(2,5),\quad \ell(3,3)=\ell(4,3).
$$
\end{proof}




