\begin{remark}\label{re.act.rank.1}
Recall that the matrices $J_{Z_i}$, $i=1,\dots,7$, as well as $B$ are skew-symmetric with respect the inner product $\langle \cdot\, , \cdot\rangle_{4,4}$.
Therefore, if $A$ is one of such matrices and $Y\in \mathfrak{v}=\mathbb{R}^{4,4}$, then the vector $\overline{Y}=A(Y)$ is such that
$$
\langle Y, \overline{Y}\rangle_{4,4}=y_1\overline{y}_1+y_2\overline{y}_2+y_3\overline{y}_3+y_4\overline{y}_4-y_5\overline{y}_5-y_6\overline{y}_6-y_7\overline{y}_7-y_8\overline{y}_8=0.
$$
This implies that for a given $Y$, the linear space $\mathbf{L}(Y)$ for $\mathbf{L}=\mathbf{V} \oplus [\mathbf{V},\mathbf{V}]$ has dimension $\leq 7$.
\end{remark}

The following result is useful for various computations.

\begin{lemma}\label{le.invarform.1}
If a matrix Lie group $G$ with the Lie algebra $\mathfrak{g}\subset \mathfrak{gl}(m,\mathbb{R})$ preserves the value $\sum_{ij} c_{ij} y_i y_j$ for some fixed
$Y=(y_1,\dots,y_m)$, where $c_{ij} \in \mathbb{R}$, then for any matrix $A\in \mathfrak{g}$ we have $\sum_{ij} c_{ij} \Bigl((A(Y))_i y_j+(A(Y))_j y_i\Bigr)=0$,
where $A(Y)$ is the image of $Y$ under the action of $A$.
\end{lemma}


\begin{proof} For any $Q\in G$ and any $Y\in \mathbb{R}^m$ we have $\sum_{ij} c_{ij} (Q(Y))_i (Q(Y))_j=\sum_{ij} c_{ij} y_i y_j$, where $G(Y)$ is the image of $Y$ under the action of the matrix $G$. If $Q=\exp(tA)=\Id +t A +o(t)$ when $t \to 0$ for some $A\in \mathfrak{g}$, then
\begin{eqnarray*}
\sum_{ij} c_{ij} (Q(Y))_i (Q(Y))_j&=&\sum_{ij} c_{ij} (Y+tA(Y))_i (Y+tA(Y))_j +o(t)\\
&=&\sum_{ij} c_{ij} y_i y_j +t\sum_{ij} c_{ij} \Bigl(A(Y)_i y_j+A(Y)_j y_i\Bigr) +o(t)
\end{eqnarray*}
when $t \to 0$, that proves the lemma.
\end{proof}

