%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Linear Stability Analysis}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Once again, our first action is to consider the stability of the system about the uniform steady-state solution (given in Appendix~\ref{sec:SuppLinearStability3D}). Non-dimensionalising (see Table \ref{tab:AMAParameters}), we find the following system of linear dynamical equations
\begin{equation}\label{eq:linear_AMA}
\begin{aligned}
  &\partial_t\delta\rho_{\mathrm{m}} + \partial_x\delta v - \mathrm{Pe}^{-1}\partial_x^2\delta\rho_{\mathrm{m}} = \Bar{k}_{\mathrm{on}}^{a}\delta\rho_{\mathrm{a}} + \Bar{k}_{\mathrm{on}}^{A}\delta\rho_{\mathrm{A}} - \Bar{k}_{\mathrm{off}}^{m}\delta\rho_{\mathrm{m}}\textrm{,} \\
  &\partial_t\delta\rho_{\mathrm{a}} + \partial_x \delta v = \Bar{k}_{\mathrm{p}}\delta\rho_{\mathrm{A}} - \Bar{k}_{\mathrm{dp}}\delta\rho_{\mathrm{a}}\textrm{,} \\
  &\partial_t\delta\rho_{\mathrm{A}} + \partial_x \delta v - \mathrm{Pe}^{-1}\partial_x^2\delta\rho_{\mathrm{A}} = \Bar{k}_{\mathrm{o n}}^A\delta\rho_{\mathrm{m}}- \Bar{k}_{\mathrm{off}}^A\delta\rho_{\mathrm{A}}\textrm{,}
  %& \partial_x^2\delta v - \delta v - \Bar{\chi}_a\partial_x\delta\rho_{\mathrm{a}} + h(\rho_{\mathrm{m}}^*) \partial_x \delta\rho_{\mathrm{m}} = 0\textrm{,}
\end{aligned}
\end{equation}
which are coupled by the (linearised) relation
\begin{equation}\label{eq:delta_v_AMA}
    \partial_x^2\delta v - \delta v - \Bar{\chi}_a\partial_x\delta\rho_{\mathrm{a}} + h(\rho_{\mathrm{m}}^*) \partial_x \delta\rho_{\mathrm{m}} = 0\textrm{.}
\end{equation}
Here, we have assumed that the rate at which anillin diffuses is identical to that of myosin (diffusion is athermal in our model, being attributed to myosin processivity, and anillin is bound to myosin).

In reciprocal space, (\ref{eq:delta_v_AMA}) can be incorporated into (\ref{eq:linear_AMA}) to result in linear equations of the form,
%
\begin{equation}
    \partial_t{\bs{\delta\Bar{\rho}}}'_{q} = \mathsf{A}^\prime\cdot{\bs{\delta\Bar{\rho}}}'_{q}\text{,}
\end{equation}
%
where ${\bs{\delta \Bar{\rho}}}'_{q} = (\delta\Bar{\rho}_{\mathrm{a}}, \delta\Bar{\rho}_{\mathrm{m}}, \delta\Bar{\rho}_{\mathrm{A}})^{\mathrm{T}}$ and 
%
\begin{widetext}
    \begin{equation}\label{eq:linearResponseMatrix3D}
   \mathsf{A}^\prime =  \left( \begin{matrix}
    -\Tilde{k}_{\mathrm{dp}} -\Tilde{\chi}_a\frac{q^2}{q^2+1} &\frac{q^2 h(\rho_{\mathrm{m}}^*)}{q^2+1} & \Bar{k}_{p}\\
        \Bar{k}_{\mathrm{on}}^{a} -\Tilde{\chi}_a\frac{q^2}{q^2+1} &  -\Bar{k}_{\mathrm{off}}^{m} -\mathrm{Pe}^{-1}  q^2+\frac{q^2 h(\rho_{\mathrm{m}}^*)}{q^2+1} & \Bar{k}_{\mathrm{on}}^{A}\\
         -\Tilde{\chi}_a\frac{q^2}{q^2+1} & q^2+\frac{q^2 h(\rho_{\mathrm{m}}^*)}{q^2+1} + \Bar{k}_{\mathrm{on}}^A & - \Bar{k}_{\mathrm{off}}^A-\mathrm{Pe}^{-1}  q^2
    \end{matrix}\right)
\end{equation}
\end{widetext}

