\subsubsection*{Eigensystem}
Here, we provide the full-length expressions of the eigensystem (eigenvalues and right-eigenvectors, respectively) of the linear response matrix $\mathsf{A}$ (Eq.~\ref{eq:linearResponseMatrix2D}). The full-length eigenvalues ($\lambda_i$) are given by,
\begin{align}\label{eq:eigenvalues_FL}
    \lambda_{1,2} &= -\frac{1}{2 \left(q^2+1\right)}\Bigg(\Tilde{k}_{\mathrm{off}} +\Tilde{k}_{\mathrm{dp}} +\mathrm{Pe}^{-1}  q^4+\Tilde{k}_{\mathrm{off}}  q^2+\mathrm{Pe}^{-1} q^2+\Tilde{k}_{\mathrm{dp}}  q^2-h(\rho_{\mathrm{m}}^*) q^2+\Tilde{\chi}_a  q^2 \pm \bigg(\Tilde{k}_{\mathrm{dp}} +\mathrm{Pe}^{-1}  q^4\nonumber\\
    &+\Tilde{k}_{\mathrm{off}}  \left(q^2+1\right)+q^2 \left(\mathrm{Pe}^{-1} +\Tilde{k}_{\mathrm{dp}} -h(\rho_{\mathrm{m}}^*) +\Tilde{\chi}_a \right)\bigg)^2-4 \left(q^2+1\right) \bigg(\Tilde{k}_{\mathrm{off}}  \left(\Tilde{k}_{\mathrm{dp}} +\Tilde{k}_{\mathrm{dp}}  q^2+\Tilde{\chi}_a  q^2\right) \nonumber\\
    &+q^2 \left(\mathrm{Pe}^{-1} \left(\Tilde{k}_{\mathrm{dp}} +\Tilde{k}_{\mathrm{dp}}  q^2+\Tilde{\chi}_a  q^2\right)-h(\rho_{\mathrm{m}}^*)  (\Tilde{k}_{\mathrm{dp}} +\Hat{k}_{\mathrm{on}} )\right)\bigg)^{1/2}\Bigg)\text{.}
\end{align}
\\
The associated full-length right-eigenvectors (${\bf u}_{r_i}$) of eigenvalues in Eq.~\ref{eq:eigenvalues_FL} are given by,
\begin{align}\label{eq:eigenvectors_FL}
    {\bf u}_{r_{1,2}} = \left(\frac{\psi \pm \sqrt{\sigma}}{\sqrt{1 + (\psi \pm \sqrt{\sigma})^2}}, \frac{1}{\sqrt{1 + (\psi \pm \sqrt{\sigma})^2}} \right)^{\mathrm{T}}\textrm{,}
\end{align}
where, 
\begin{align}
    \psi =& \frac{1}{2 q^2 \left(\Tilde{\chi}_a -\Hat{k}_{\mathrm{on}} \right)-2 \Hat{k}_{\mathrm{on}}}\left(\Tilde{k}_{\mathrm{dp}} -\Tilde{k}_{\mathrm{off}}  \left(q^2+1\right)+q^2 \left(\Tilde{k}_{\mathrm{dp}} +h(\rho_{\mathrm{m}}^*) +\Tilde{\chi}_a -\mathrm{Pe}^{-1} \left(q^2+1\right)\right)\right)\textrm{,}\nonumber\\
    & \nonumber\\
    \sigma =& \frac{1}{2 q^2 \left(\Tilde{\chi}_a -\Hat{k}_{\mathrm{on}} \right)-2 \Hat{k}_{\mathrm{on}}}\Bigg( (\Tilde{k}_{\mathrm{dp}}) ^2+q^8(\mathrm{Pe}^{-1}) ^2 + 2 q^6  \mathrm{Pe}^{-1}\left(\mathrm{Pe}^{-1} -\Tilde{k}_{\mathrm{dp}} -h(\rho_{\mathrm{m}}^*) -\Tilde{\chi}_a \right) \nonumber\\
    &+q^4 \bigg((\mathrm{Pe}^{-1}) ^2 -2 \mathrm{Pe}^{-1} \bigg(2 \Tilde{k}_{\mathrm{dp}} +h(\rho_{\mathrm{m}}^*) +\Tilde{\chi}_a \bigg)+(\Tilde{k}_{\mathrm{dp}}) ^2+2 \Tilde{k}_{\mathrm{dp}}  \left(h(\rho_{\mathrm{m}}^*) +\Tilde{\chi}_a \right)+\left(h(\rho_{\mathrm{m}}^*) -\Tilde{\chi}_a \right)^2 \nonumber\\
    &+4 h(\rho_{\mathrm{m}}^*)  \Hat{k}_{\mathrm{on}} \bigg)+\Tilde{k}_{\mathrm{off}} ^2 \left(q^2+1\right)^2 +2 q^2 \bigg(-\mathrm{Pe}^{-1}  \Tilde{k}_{\mathrm{dp}} +\Tilde{k}_{\mathrm{dp}}  \left(\Tilde{k}_{\mathrm{dp}} +h(\rho_{\mathrm{m}}^*) +\Tilde{\chi}_a \right)+2 h(\rho_{\mathrm{m}}^*)  \Hat{k}_{\mathrm{on}} \bigg)\nonumber\\
    &+2 \Tilde{k}_{\mathrm{off}} \left(q^2+1\right)\left(-\Tilde{k}_{\mathrm{dp}} +\mathrm{Pe}^{-1}  q^4+q^2 \left(\mathrm{Pe}^{-1} -\Tilde{k}_{\mathrm{dp}} -h(\rho_{\mathrm{m}}^*) -\Tilde{\chi}_a \right)\right)\Bigg)\nonumber\textrm{.}
\end{align}

