\title{Run-and-tumble chemotaxis using reinforcement learning }
\author{Ramesh Pramanik$^{1}$, Shradha Mishra$^2$ and Sakuntala Chatterjee$^1$}
\affiliation{(1) Physics of Complex Systems, S.N. Bose National Centre for Basic Sciences, Salt Lake Sector 3, Kolkata 700106, India \\
