\title[Relative portfolio optimization via a VaR-based constraint]{Relative portfolio optimization via a value at risk based constraint}
\author[N. \smash{B\"auerle}]{Nicole B\"auerle$^*$}
\address[N. B\"auerle]{Department of Mathematics,
