\begin{theorem}[Logarithmic utility] \label{thm:nash_log2}
Let $\alpha_i,\, \beta_i \in [0,1],\, x_0^i > 0,\, i=1,2.$ If $x_0^2 < \alpha_2 \beta_1 x_0^1$, there is no Nash equilibrium. Otherwise, i.e.\ if $x_0^2 \ge  \alpha_2 \beta_1 x_0^1$, there exist three cases. 
\begin{itemize}
    \item[a)] If $\alpha_i = 1, \, \beta_i = 1,\, i=1,2,$ there are infinitely many Nash equilibria of the form $(X,X)$, where $X$ is an $\mathcal{F}$-measurable random variable with $\EE[Z_T X] = x_0^1$. 
    \item[b)] {\color{black} If $\alpha_2 = 1$ and $ \alpha_1 \beta_1 \beta_2 < 1$ } then the unique Nash equilibrium is given by 
    $$ X_1^* = \frac{x_0^1}{Z_T} \mbox{   and   } X_2^* = \frac{x_0^2}{Z_T}. $$
    \item[c)] If $\alpha_1 \leq 1,\, \alpha_2 < 1,$ there are two  cases. If $x_0^2 \geq \beta_1 x_0^1$, the unique Nash equilibrium is given by 
    $$X_1^* = \frac{x_0^1}{Z_T} \mbox{   and   } X_2^* = \frac{x_0^2}{Z_T}.$$
    Otherwise, i.e.\ if $x_0^2 < \beta_1 x_0^1$ there are infinitely many Nash equilibria of the form
    $$ X_1^* = \frac{x_0^1}{Z_T}  \mbox{   and   } X_2^* = \frac{\beta_1 x_0^1}{Z_T} \mathbbm{1}_{A_2} + \frac{x_0^2 - \alpha_2 \beta_1 x_0^1}{(1-\alpha_2)Z_T} \mathbbm{1}_{A_2^c}$$
    with $A_2\in \mathcal{F}$ such that $\PP(A_2) = \alpha_2.$
\end{itemize}
\end{theorem}



