\subsection{Power utility}
We consider now the same problem with power utility for the agents. Note that we use the same parameter for the utility function for both agents. More precisely, we consider for $U(x)= \frac{1}{1-\gamma} x^{1-\gamma},\,  {\color{black}\gamma >0 ,\gamma \neq 1},$ the individual portfolio problems
$$(P_2) \left\{ \begin{array}{l}
\EE U(X_i) \to \max\\
\PP(X_i \ge \sum_{j\neq i} \beta_j X_j) \ge \alpha_i,\\
\EE[Z_TX_i]=x_0^i,\\
X_i \mbox{ is } \mathcal{F}-\mbox{measurable,}
\end{array}\right.$$
for $i=1,2$. For notational convenience, we abbreviate $\varepsilon_\gamma := \EE\big[Z_T^{1-1/\gamma} \big].$


As in the previous case of logarithmic utility, it is easy to see that for $x_0^1 \ge \beta_2 x_0^2 \ge \beta_1\beta_2 x_0^1$ the optimal terminal wealths without constraint constitute a Nash equilibrium, i.e. 
$$ X_1^* =  \frac{x_0^1}{\varepsilon_\gamma} Z_T^{-1/\gamma}, \mbox{   and   } X_2^* = \frac{x_0^2}{\varepsilon_\gamma}  Z_T^{-1/\gamma},$$
since $I(x):= x^{-1/\gamma}$ is the inverse function of $U'$ \citep[see e.g.][]{korn2013optionsbewertung}.

We concentrate now on the interesting case which is determined by the parameters $\beta_1\beta_2<1$ and {\color{black} for $\gamma \in(0,1)$} by
\begin{equation}
  \beta_1 x_0^1 > x_0^2\ge \frac{\beta_1 x_0^1}{\varepsilon_\gamma}  \int_{Z_T\ge z_{1-\alpha_2}} Z_T^{1-1/\gamma}d\PP,  \label{eq:case2}
\end{equation}
and  {\color{black} for $\gamma >1$ by 
\begin{equation}
  \beta_1 x_0^1 > x_0^2\ge \frac{\beta_1 x_0^1}{\varepsilon_\gamma}  \int_{Z_T\le z_{\alpha_2}} Z_T^{1-1/\gamma}d\PP,  \label{eq:case3}
\end{equation}
}
where $z_{\alpha}$ is the $\alpha-$quantile of $Z_T$, i.e.  $ \PP(Z_T \le z_\alpha)=\alpha$. Since $Z_T>0$ we necessarily have that $z_\alpha> 0.$ 

\begin{theorem}[Power utility]\label{lem:power}
     Let $\beta_1\beta_2<1$.
\begin{itemize}
    \item[a)] If $\gamma \in(0,1)$  and the inequality in \eqref{eq:case2} holds true,  the unique Nash equilibrium is given by
     \begin{equation}\label{eq:NEpower2} 
X_1^* = \frac{x_0^1}{\varepsilon_\gamma} Z_T^{-1/\gamma}, \mbox{   and   } X_2^* = \left\{ \begin{array}{cr}  (\lambda_2Z_T)^{-1/\gamma},& Z_T < z_{1-\alpha_2},\\ \beta_1 \frac{x_0^1}{\varepsilon_\gamma} Z_T^{-1/\gamma},& Z_T \ge  z_{1-\alpha_2}, \end{array}\right. \end{equation} 
     where  $\lambda_2>0$ is such that $\EE[Z_T X_2^*]=x_0^2$.
    \item[b)] {\color{black} If $\gamma>1$  and the inequality in \eqref{eq:case3} holds true,  the unique Nash equilibrium is given by
     \begin{equation}\label{eq:NEpower3} 
X_1^* = \frac{x_0^1}{\varepsilon_\gamma} Z_T^{-1/\gamma}, \mbox{   and   } X_2^* = \left\{ \begin{array}{cr}  (\lambda_2Z_T)^{-1/\gamma},& Z_T > z_{\alpha_2},\\ \beta_1 \frac{x_0^1}{\varepsilon_\gamma} Z_T^{-1/\gamma},& Z_T \le   z_{\alpha_2}, \end{array}\right. \end{equation} 
     where  $\lambda_2>0$ is such that $\EE[Z_T X_2^*]=x_0^2$.}
\end{itemize}     

\end{theorem}
%Here we claim that a Nash equilibrium is given by
\begin{proof} We restrict the proof to case a). Case b) is similar.
Using Lemma \ref{lem:bound} and rearranging the terms, we obtain that a Nash equilibrium is necessarily of the form
 \begin{align*}
  X_1^* &=  {Z_T}^{-1/\gamma} \Big( \lambda_1  \1_{A_1^c}+ \max\{\beta_2\lambda_2,\lambda_1\} \1_{A_1}\Big),\\
         X_2^* &=  {Z_T}^{-1/\gamma} \Big( \lambda_2  \1_{A_2^c}+ \max\{\beta_1\lambda_1,\lambda_2\} \1_{A_2}\Big)
     \end{align*}
     for some $\lambda_1,\lambda_2 >0$ and measurable sets $A_1,A_2$ with probability $\PP(A_i)=\alpha_1, i=1,2.$
Distinguishing the cases where the maximum is attained, it is possible to see that only the case $\lambda_1 \ge \beta_2\lambda_2$ yields a solution. Moreover, it follows that
$$X_1^* = \frac{x_0^1}{\varepsilon_\gamma} Z_T^{-1/\gamma}.$$
In order to determine the precise form of $X_2^*$,  we will proceed in a different way as in the logarithmic case. This is necessary, because in the power setting it will turn out that it really matters where the region is located precisely where the probability constraint is satisfied. This does not follow from Lemma \ref{lem:bound}. \\
We write $\kappa := U'(x_0^1/\varepsilon_\gamma)$, i.e. $I(\kappa) = x_0^1/\varepsilon_\gamma.$ It follows that $I(\lambda_2) < \beta_1 I(\kappa)$, because otherwise the price of $X_2^*$ would be larger or equal than $\beta_1 x_0^1$ which contradicts our assumption. This implies $\lambda_2 > \kappa \beta_1^{-\gamma}$. 
%We again check that $X_1^*$ is the best response to $X_2^*$ and vice versa. Obviously $X_1^*$ is the optimal solution to the unconstrained problem and satisfies the constraint due to our assumptions. In order 
It remains to prove that $X_2^*$ is the best response to $X_1^*$. Thus, we consider the following function
     $$ L(X,\lambda_2,\eta_2) := U(X) -\lambda_2 Z_T X +\eta_2 \1\{X\ge \beta_1 I(\kappa Z_T)\},$$
     where
     $$ \eta_2 := U(I(\lambda_2z_{1-\alpha_2}))- U(\beta_1I(\kappa z_{1-\alpha_2}))+ \lambda_2 z_{1-\alpha_2} \Big( \beta_1I(\kappa z_{1-\alpha_2})- I( \lambda_2 z_{1-\alpha_2})\Big) $$
and $\kappa,\lambda_2$ as before. Note that $\eta_2\ge 0$ since
\begin{align*}
    \eta_2\ge 0 & \Leftrightarrow U(I(\lambda_2z_{1-\alpha_2}))- U(\beta_1I(\kappa z_{1-\alpha_2})) \ge \lambda_2 z_{1-\alpha_2} \Big( I( \lambda_2 z_{1-\alpha_2})- \beta_1I(\kappa z_{1-\alpha_2}) \Big)\\
    &  \Leftrightarrow \frac{U(I(\lambda_2z_{1-\alpha_2}))- U(\beta_1I(\kappa z_{1-\alpha_2}))}{I( \lambda_2 z_{1-\alpha_2})- \beta_1I(\kappa z_{1-\alpha_2}) } \le \lambda_2 z_{1-\alpha_2}\\ &  \Leftrightarrow  U'(\xi) \le \lambda_2 z_{1-\alpha_2}
\end{align*}
for some $\xi \in (I(\lambda_2z_{1-\alpha_2}), \beta_1 I(\kappa z_{1-\alpha_2})).$ Because $U'$ is non-increasing, we obtain $ U'(\xi) \le U'(I(\lambda_2z_{1-\alpha_2}))=\lambda_2z_{1-\alpha_2}.$
Now we can show that for any other admissible terminal wealth $X_2$ we obtain
\begin{align*}
    \EE U(X_2^*) - \EE U(X_2) \geq \EE L(X_2^*,\lambda_2,\eta_2)- \EE L(X_2,\lambda_2,\eta_2)\ge 0,
\end{align*}
since $X_2^*$ maximizes $X\mapsto L(X,\lambda_2,\eta_2)$ pointwise (see App. \ref{sec:A2}) which implies that $X_2^*$ maximizes the objective of agent 2 under the VaR-based constraint. Now it only remains to discuss the existence of $\lambda_2>0$ such that $\E[Z_T X_2^*] = x_0^2$. We can solve
$$\E[Z_T X_2^*] = \lambda_2^{-1/\gamma} \E\Big[Z_T^{1-1/\gamma} \1 \{Z_T< z_{1-\alpha_2}\} \Big] + \frac{\beta_1 x_0^1}{\varepsilon_\gamma} \E\Big[Z_T ^{1-1/\gamma} \1 \{Z_T \geq z_{1-\alpha_2}\} \Big] = x_0^2$$ 
for $\lambda_2$ to obtain 
$$ \lambda_2 = \E\Big[Z_T^{1-1/\gamma} \1 \{Z_T< z_{1-\alpha_2}\} \Big]^{\gamma} \bigg(x_0^2 -  \frac{\beta_1 x_0^1}{\varepsilon_\gamma} \E\Big[Z_T ^{1-1/\gamma} \1 \{Z_T \geq z_{1-\alpha_2}\} \Big]\bigg)^{-\gamma}.$$
Since \eqref{eq:case2} holds, we have $\lambda_2 > 0$ which concludes the proof.
\end{proof}


\begin{remark}
\begin{enumerate}
    \item[a)] Note that for power utility, in contrast to logarithmic utility, the position of the set $A$ that guarantees that the probability constraint is satisfied is not arbitrary. This is remarkable since the limit $\gamma \to 1$ results in a logarithmic utility function. {\color{black} Moreover, it turns out that for $\gamma >1$ the constraint is satisfied on the set $\{Z_T \leq z_{\alpha_2}\}$ whereas for $\gamma\in(0,1)$, the constraint is satisfied on the set $\{Z_T > z_{1-\alpha_2}\}$. In both cases the constraint is satisfied on the side where it is cheaper to achieve. This is the main reason for the non-continuous behavior of the optimal terminal wealth as a function of $\gamma.$ It cannot  be explained by the risk aversion.  The relative risk aversion of the power utility is given by $-x\frac{U''(x)}{U'(x)}=\gamma$ and thus risk aversion is increasing in $\gamma$. When we consider as an example again the Black Scholes market, it holds that large $Z_T$ correspond to small stock prices and vice versa.  This means that the less risk-averse investor (less risk averse than log-utility) tries to outperform the other agent  in the event of small stock prices, whereas the more risk-averse investor (more risk averse than log-utility) tries to outperform the other agent in the event of large stock prices.}
     %   on which the constraint is satisfied in the power utility case to the set $\{Z_T \leq z_{\alpha_2}\}$ discussed in Remark~\ref{rem:choice_A2}. There we searched for the set $A_2$ with $\PP(A_2) = \alpha_2$ that maximizes the expected terminal wealth of agent 2 in the Nash equilibrium under logarithmic utility. On the contrary, the set $\{Z_T > z_{1-\alpha_2}\}$ found in Theorem~\ref{lem:power} minimizes the expected terminal wealth discussed in Remark~\ref{rem:choice_A2}. Nevertheless, it does not come as a surprise that the constraint is satisfied on the set $\{Z_T > z_{1-\alpha_2}\}$ since it is 'cheaper' to satisfy the constraint there as the terminal wealth of agent 1 is decreasing in $Z_T$.
     \item[b)] \textcolor{black}{It is possible to derive the replicating strategies for the Nash equilibrium from Theorem~\ref{lem:power} using Theorem~E.1 from \cite{jin2008behavioral}. However, the resulting expressions become even more complex than the ones obtained for logarithmic utility which is why we refrain from presenting them here.}
\end{enumerate}

\end{remark}


