Suppose  $Y\ge 0$ is an arbitrary $\mathcal{F}-$measurable random variable, $U:[0,\infty)\to \R$ a strictly increasing, strictly concave and differentiable utility. We want to solve the following problem
$$(P_Y) \left\{ \begin{array}{l}
\EE  U(X) \to \max\\
X \ge Y,\; X \mbox{ is } \mathcal{F}-\mbox{measurable,}\\
\EE[Z_TX]=x_0.
\end{array}\right.$$
Obviously $x_0\ge \EE[Z_TY]$ since otherwise it is not possible to fulfill the constraint.
We claim that the optimal solution is given as follows (cp. \cite{el2005optimal}, Prop. 2.2 for a special case).
\begin{lemma}\label{lem:bound}
The optimal solution of problem $(P_Y)$ is given by
 $$ X^* = \max\Big\{Y, I(\lambda Z_T)\Big\},$$
where $\lambda>0  $ is such that $\EE[Z_TX^*]=x_0$ and $I$ is the inverse function of $U'.$  It is the unique solution up to sets of measure zero.  
\end{lemma}
\begin{proof}
    Obviously $X^*$ is admissible for $(P_Y)$.
In order to show optimality, let $X$ be another feasible random variable. Since $U$ is concave and differentiable it holds that
$$ U(X)\le U(X^*)+U'(X^*) (X-X^*).$$
Now we have to show $\EE [U'(X^*) (X-X^*)]\le 0.$ Let $A:= \{X^*= I(\lambda Z_T)\}.$ Observe first that
$$U'(X^*) = \1_A U'( I(\lambda Z_T)) + \1_{A^c} U'(Y)= \1_A \lambda Z_T + \1_{A^c} U'(Y).$$
Thus, we obtain
\begin{align*}
U'(X^*) (X-X^*) &= \left[  \1_A \lambda Z_T + \1_{A^c} U'(Y) \right] (X-X^*)\\
&=  \lambda {Z_T}  (X-X^*) +  \1_{A^c}\big(U'(Y)-\lambda Z_T \big)(X-X^*)\\
&=  \lambda {Z_T}  (X-X^*) +  \1_{A^c}\big(U'(Y)-\lambda Z_T \big)(X-Y).
\end{align*}
The last equation is true since on $A^c$ we have $X^*=Y.$ Now we   take the expectation on both sides. Since $X$ and $X^*$ are both feasible we have $\EE[Z_T (X-X^*) ]=x_0-x_0=0.$ Thus
$$\EE [U'(X^*) (X-X^*)] =  \EE \left[ \1_{A^c}\big(U'(Y)-\lambda Z_T \big)(X-Y) \right] \le 0.  $$
The inequality is true since $X\ge Y$ and $$ U'(Y) \le \lambda Z_T \Leftrightarrow Y \ge I(\lambda Z_T)$$
which is true on $A^c.$ Finally we show uniqueness. Suppose that both $X^*$ and $\tilde X$ are optimal, i.e.\ $\EE  U(X^*)=\EE  U(\tilde X)$ and both are admissible. Consider $X := \alpha X^* + (1-\alpha) \tilde X$ for $\alpha\in (0,1).$ Obviously $X$ is again admissible and $$ \EE  U(X) > \alpha \EE  U(X^*)+(1-\alpha) \EE  U(\tilde X)$$
as long as $X^*$ and $\tilde X$ do not coincide outside a set of measure zero, which leads to the contradiction that $X$ attains a higher value.
\end{proof}

If $U(x)=\ln(x)$ we obtain $I(x)=1/x.$ Thus, with a slight misuse of the parameter $\lambda$ (instead of $\lambda$ we rather consider $1/\lambda$), we obtain in the situation of Lemma \ref{lem:bound} that $X^* = \max\Big\{Y, \lambda/ Z_T\Big\}$ where $\lambda  $ is such that $\EE[Z_TX^*]=x_0$. 
%Now suppose that $\EE[Z_T Y]=x_0.$ However, we only need to satisfy $X\ge Y$ on a measurable set $A$ with $\PP(A)<1.$ When we define $$ X^* = \1_A Y + \1_{A^c} \frac{\lambda}{Z_T}$$
%where $\lambda$ is such that $\EE[Z_TY\1_A^c]=\lambda \PP(A^c)$ then $\EE \ln(X^*) \ge \EE \ln(Y)$ and we get a strict inequality if $\PP(X^*\neq Y)>0.$

\subsection{Utility maximization with lower bounds II}\label{sec:A1+}
Now we consider the  problem with logarithmic utility where the constraint only has to be satisfied on a subset of $\Omega.$ We assume here that $Y>0.$ Then the optimization problem reads as
$$(P_A) \left\{ \begin{array}{l}
\EE  \ln (X) \to \max\\
X \ge Y \1_A,\; X \mbox{ is } \mathcal{F}-\mbox{measurable}, A \in \mathcal{F},\\
\PP(A)=\alpha,\\
\EE[Z_TX]=x_0.
\end{array}\right.$$
Note that the optimization is over $X$ and the set $A$ here.
Obviously, $x_0\ge \EE[Z_TY \1_A]$ has to be fulfilled for an $A\in \mathcal{F}$, otherwise it is not possible to fulfill the constraint. Let us define
$$ M_\lambda := \{ Y \le \lambda/Z_T\}$$
and let $\lambda_\alpha := \inf\{\lambda : \PP(M_\lambda)\ge \alpha\}.$ Note that if $\lambda_\alpha \le x_0$ then the problem is trivial and the optimal solution is given by $X^*=x_0/Z_T.$

\begin{lemma}\label{lem:bound2}
The optimal solution of problem $(P_A)$ is given by
 $$ X^* = \1_{M_{\lambda_\alpha}}\max\Big\{Y,  \lambda/Z_T\Big\}+ \1_{M_{\lambda_\alpha}^c}  \lambda/Z_T$$
where $\lambda  $ is such that $\EE[Z_TX^*]=x_0$.
\end{lemma}

\begin{proof}
    First it is slightly more convenient to transform the random variables as follows. Define
    \begin{align}
        \tilde Y := Y Z_T, \mbox{  and  } \tilde X := X Z_T.
    \end{align}
    Then, instead of $(P_A)$ we can consider
%    \todo[inline, color = orange!40]{Hier lieber $(\tilde{P}_A)$ schreiben? Sonst wirkt es so, als ob man die danach definierte Menge $\tilde{A}$ hier festhält, aber man optimiert ja weiter über $A$}
   $$(\tilde P_{ A}) \left\{ \begin{array}{l}
\EE  \ln (\tilde X) \to \max\\
\tilde X \ge \tilde Y \1_A,\; \tilde X \mbox{ is } \mathcal{F}-\mbox{measurable}, A \in \mathcal{F},\\
\PP(A)=\alpha,\\
\EE[\tilde X]=x_0.
\end{array}\right.$$
%Of course in order to find the optimal $\tilde X$ we can skip the constant term $ \EE  \ln (Z_T)$ from the optimization.

We begin with the special case that $\tilde Y$ is discrete and has finitely many different values, i.e.
$$ \tilde Y = \sum_{k=1}^m y_k 1 _{A_k}$$
for a partition $(A_k)_{k=1,\ldots,m}$ of $\Omega.$ Suppose $\tilde X$ is admissible for $(\tilde P_{A})$ and define $\tilde A := \{ \tilde X \ge \tilde Y\}$. Since $\tilde X$ is admissible we must have $\PP(\tilde A) \ge \alpha.$ Further let
\begin{align}
     B_k := A_k \cap \tilde A, \quad C_k := A_k \cap \tilde A^c.
\end{align}
I.e.\ we split the sets $A_k$ where $\tilde Y$ is constant into those parts where $\tilde{X}\geq \tilde{Y}$ and those where $\tilde{X} < \tilde{Y}$. We define now a new random variable $\hat X$ by
\begin{align}
    \hat X := \sum_{k=1}^m x_k^1 1 _{B_k}+ \sum_{k=1}^m x_k^2 1 _{C_k},
\end{align}
where 
\begin{align}
    x_k^1 := \frac{1}{\PP(B_k)} \int_{B_k} \tilde X d\PP, \quad  x_k^2 := \frac{1}{\PP(C_k)} \int_{C_k} \tilde X d\PP.
\end{align}
This means we replace $\tilde X$ on the sets $B_k, C_k$ by the corresponding expectation. Note that $\hat X$ is again admissible for $(\tilde P_{ A})$ since on $B_k$ we have $\tilde X \ge y_k$ and thus $x_k^1\ge y_k.$ Moreover, we obtain that $\EE \ln(\hat X) \ge \EE \ln(\tilde X)$ because due to the Jensen inequality we have (we denote by $\PP_{B_k}$ the conditional probability of $\PP$ given $B_k$, i.e. $\PP_{B_k}(D) = \PP(D\cap B_k)/\PP(B_k)$) that
\begin{align}
     \int_{B_k} \ln(\tilde X)  d\PP & =  \PP(B_k) \int \ln(\tilde X) d\PP_{B_k} \le  \PP(B_k) \ln\Big( \int \tilde Xd\PP_{B_k}\Big) =  \PP(B_k) \ln(x_k^1)
\end{align}
and the same for the sets $C_k$. Summing up these integrals we see that the expected utility of $\hat X$ is not less than the expected utility for $\tilde X.$ Thus, we can restrict the optimization to random variables $\hat X$ which are discrete and have finitely many positive values.

Fix an admissible discrete $\hat X$ and assume that there exists a measurable set $F\subset B_k$ for an arbitrary $k$ and a measurable set $\tilde F\subset C_j$ for $j\neq k$ and with $\PP(F)=\PP(\tilde F)>0$ such that $y_k>y_j.$ Note that $\PP(F)$ may be arbitrary small. This means that the constraint is satisfied on a larger level $y_k$ whereas it is not satisfied on a smaller level $y_j.$ By construction, the random variable $\hat X$ takes value $x_k^1$ on set $B_k$ and value $x_j^2$ on $C_j.$ Thus we have 
$$ x_j^2 < y_j < y_k \le x_k^1. $$
Now define the random variable
$$ X^* := \hat X \1_{(F\cup \tilde F)^c} + y_j \1_{\tilde F}+ (x_j^2+x_k^1-y_j) \1_F.$$
Note that $x_j^2+x_k^1-y_j>0$ and $\EE \hat X=\EE X^*.$ Moreover, $X^*$ also satisfies the constraint due to our construction. Let us consider the difference in expected utility of $\hat X$ and $X^*:$
\begin{align}
    \EE \ln(X^*) - \EE \ln(\hat X)= \PP(F) \Big(\ln(y_j)+\ln(x_j^2+x_k^1-y_j)-\ln(x_k^1)-\ln(x_j^2)\Big)>0.
\end{align}
The latter inequality follows since $\R^m\ni (x_1,\ldots,x_m)\mapsto \sum_{k=1}^m \ln(x_k)$ is Schur-concave (see \cite{marshall1979inequalities}, Chapt.1, Sec. A). Thus, we obtain that it is always better to satisfy the constraint on a set where $Y$ takes the smallest values. This implies the statement for discrete $Y$. In order to show the statement for arbitrary $Y$, approximate $Y$ by a sequence of discrete $(Y_n)$ almost surely. Taking the limit $n\to \infty$ then implies the general result.
\end{proof}

\subsection{Maximizing L}\label{sec:A2}
Recall that 
 $$ L(X,\lambda_2,\eta_2) := U(X) -\lambda_2 Z_T X +\eta_2 \1_{[X\ge \beta_1 I(\kappa Z_T)]}$$
 with $\lambda_2, \eta_2 \ge 0$ fixed. We show that $L$ is maximized by $X_2^*$ from \eqref{eq:NEpower2}. Obviously the maximum points can either be $I(\lambda_2 Z_T)$ or $\beta_1 I(\kappa Z_T)$ where $I(\lambda_2 Z_T) < \beta_1 I(\kappa Z_T).$ We can compare the two possible values of the function $L$:
 \begin{align*}
     F(Z_T) := U(I(\lambda_2 Z_T))- \lambda_2 Z_T I(\lambda_2 Z_T) - \Big\{U(\beta_1 I(\kappa Z_T)) -\lambda_2 Z_T \beta_1 I(\kappa Z_T)+\eta_2 \Big\}. 
 \end{align*}
Differentiating $F$ yields
\begin{align*}
    F'(Z_T) &= \lambda_2 \big(\beta_1 I(\kappa Z_T) -  I(\lambda_2 Z_T)\big) - \beta_1 \kappa Z_T I'(\kappa Z_T)(\kappa \beta_1^{-\gamma}-\lambda_2) \\
    &= Z_T^{-1/\gamma} \bigg(\lambda_2 \Big(\beta_1 \kappa^{-1/\gamma} - \lambda_2^{-1/\gamma} \Big) + \frac{\beta_1 \kappa^{-1/\gamma}}{\gamma} \Big(\kappa \beta_1^{-\gamma} - \lambda_2 \Big) \bigg) =: Z_T^{-1/\gamma} f(\lambda_2).
\end{align*}

Since $Z_T>0$, it suffices to consider the sign of $f(\lambda_2)$ to discuss the monotonicity of $F$. We observe that 
$$ f\big(\kappa \beta_1^{-\gamma} \big) = 0.$$
Moreover, differentiating $f$ yields 
\begin{align*}
    f'(\lambda_2) &= \Big(1-1/\gamma \Big)\Big(\beta_1 \kappa^{-1/\gamma} - \lambda_2^{-1/\gamma}\Big),
\end{align*}
so that $f'(\lambda_2) < 0$ for all $\lambda_2 > \kappa \beta_1^{-\gamma}$ {\color{black}(in case $0<\gamma <1$. The inequality reverses if $\gamma >1$)}. Thus, since we already saw in the proof of Theorem~\ref{lem:power} that $\lambda_2 > \kappa\beta_1^{-\gamma}$, we deduce that $F'(Z_T) < 0$ for all values of $Z_T$. Moreover, by definition of $\eta_2$, we have $F(z_{1-\alpha_2}) = 0$ which implies that $X_2^*$ maximizes the function $L$.



