\subsubsection{Statement of results}
 The approach in this paper is to construct a power series interpolating the (twisted) moments of $L$-functions which reveals a general $p$-adic structure of such moments. This power series is constructed from the \emph{horizontal $p$-adic $L$-function} as defined in \cite[Definition 5.3]{KrizNordentoft} via the main novelty of this paper; the \emph{digit construction}. 

We will now describe a precise version of (\ref{eq:padicmoment}) for general holomorphic newforms of even weight. Let $m\geq 1$ and consider holomorphic newforms $f_1,\ldots ,f_m$ of respective levels $N_1,\ldots,N_m$, even weights $k_1,\ldots, k_m$ and trivial nebentypus. We say  that $p$ is \emph{$(f_1,\ldots, f_m)$-good} if there exists a place $\mathfrak{p}|p$ of the compositum of the Hecke fields of $f_1,\ldots, f_m$ such that there exist infinitely many \emph{joint Taylor--Wiles primes mod $\mathfrak{p}$} for $f_1,\ldots, f_m$, i.e.  primes $\ell$ such that 
\begin{equation}\label{eq:TWcondjoint} \ell\equiv 1\modulo p,\quad (\ell,N_i)=1,\quad a_{f_i}(\ell)\not\equiv 2\modulo \mathfrak{p},\quad i=1,\ldots,m,\end{equation} 
where $a_{f_i}(\ell)$ denotes the $\ell^\mathrm{th}$ Fourier coefficient of $f_i$ (see Definition \ref{def:TW}). Denote by $\C_p$ the complex $p$-adic numbers and by $v_p:\C_p\rightarrow \Q\cup\{\infty\}$ the unique valuation with $v_p(p)=1$. We fix an embedding $\overline{\Q}\hookrightarrow  \C_p$ corresponding to a prime of $\overline{\Q}$ above $\mathfrak{p}$ and a sequence of compatible, primitive $p$-power roots of unity $\zeta_{p}, \zeta_{p^2},\ldots\in \C_p$, meaning that $(\zeta_{p^{n_1}})^{p^{n_2}}=\zeta_{p^{n_1-n_2}}$ for all $n_1\leq n_2$. 

\begin{theorem}\label{thm:widemoment2}
Let $f_1,\ldots, f_m$ be holomorphic newforms as above (not necessarily distinct) and let $p$ be a $(f_1,\ldots, f_m)$-good prime.  Let $\ell_1,\ell_2,\ldots$ be a sequence of primes congruent to $1$ modulo $p$ such that for $n$ large enough $\ell_n$ is a joint Taylor--Wiles prime for $f_1,\ldots, f_m$. For $i\geq 1$ let $b_i\in (\Z/\ell_i)^\times $ be a choice of generator and put $L_{n}=\ell_1\cdots \ell_{n}$ for $n\geq 1$. 

Then there constants  $\mu\in \Q_{\geq 0}\cup\{ \infty\}$ and $ \lambda\in \Z_{\geq 0}$ such that for all $n$ large enough the following holds: let $\chi_n$ be the order $p$ Dirichlet character of conductor $\ell_n$ such that $\chi_n(b_n)=\zeta_p$. Then we have that
\begin{align}\label{eq:widemoment2}%(depending on $E_1,\ldots, E_k$, $p$, and the Taylor--Wiles primes)
v_p& \left(\frac{1}{p^{n-1}}\sum_{\substack{\chi\modulo L_{n-1}\\\mathrm{even},\,\chi^p=\mathbf{1}}} \left(\prod_{i=1}^m\frac{L^{\ast}(f_i,\chi\chi_n,k_i/2)}{\Omega_{f_i}^+}\right)u_{n-1}(\chi)\right)\\
\nonumber &=\mu-\frac{1}{p-1}+\frac{\lambda+1}{p^{n}-p^{n-1}},
\end{align}
where the sum is over even Dirichlet characters of order $p$ with conductor dividing $L_{n-1}$, $L^{\ast}(f_i,\chi,s)/\Omega_{f_i}^+$ denotes the algebraically normalized $L$-function of $f_i$ twisted by $\chi$ with modified Euler factors at primes dividing the conductor of $\chi$ (see (\ref{eq:interpolationfinal}) for the precise formula), and $u_{n-1}(\chi)$ is a product of cyclotomic units:
\begin{equation}\label{eq:cycunit}u_{n-1}(\chi):=\prod_{i=1}^{n-1} \frac{\zeta_{p^{n-i+1}}-1}{\zeta_{p^{n-i+1}}\overline{\chi_i(b_i)}-1},\end{equation}
where $\chi_i$ denotes the restriction of $\chi$ to $(\Z/\ell_i)^\times$.

Furthermore, we have $\mu=\infty$ (i.e. the quantity inside the argument of $v_p$ on the left-hand side of (\ref{eq:widemoment2}) is zero for $n$ sufficiently large) if and only if 
$$\prod_{i=1}^m L(f_i,\chi,k_i/2)=0,$$ 
for all Dirichlet characters $\chi$ with $\chi^p=1$ and conductor given by a product of the primes $\ell_1,\ell_2,\ldots$ (including the trivial character).
\end{theorem}

\begin{remark} Theorem \ref{thm:widemoment2} follows from a general result Proposition \ref{prop:widemoment} for horizontal measures. When comparing the two, note that the quantity $\mu$ appearing in (\ref{eq:widemoment2}) is equal to the quantity $\tfrac{\mu}{e}$ appearing in (\ref{eq:widemoment}) with $e$ equal to the ramification index of $F_{\mathfrak{p}}/\Q_p$ where $F$ is the compositum (over $\Q$) of the Hecke fields of $\{f_i\}_{i = 1}^m$ and $F_{\mathfrak{p}}$ is its completion at the prime $\mathfrak{p}|p$ chosen above. In other words, if $\pi$ is a uniformizer of $F_{\mathfrak{p}}$ then $v_p(\pi) = \tfrac{1}{e}$.
\end{remark}

\begin{remark}\label{rem:Kurihara}
We expect that it always holds that $\mu<\infty$ (at least if the Taylor--Wiles primes are not too sparse). The dependence of the invariants $\mu,\lambda$ as in (\ref{eq:widemoment2}) on the modular forms and the Taylor--Wiles primes (as well as the choice of primitive roots $b_n\in (\Z/\ell_n)^\times$) seems very mysterious in general. However, in the case where the modular forms correspond to elliptic curves $E_1,\ldots, E_m$, then in certain low rank cases $\mu,\lambda$ should be related to key arithmetic invariants:
\begin{enumerate}
\item firstly, if $L(f_{E_i},1)\neq0,i=1,\ldots, m$ and $p$ does not divide the BSD-formula for any of the elliptic curves $E_1,\ldots, E_m$ then $\mu=0$ and $\lambda=0$, 
\item secondly, if $m=1$ and $E_1$ satisfies the mod $p$ Kurihara Conjecture with $r=1$ and $\ell_1=q_1$, meaning that (\!\cite[Equation (1.6)]{KrizNordentoft}) is satisfied:
\begin{equation}\label{eq:Kolderiv}\sum_{a=1}^{q_1}a\left\langle \tfrac{(\zeta_{q_1})^{a}}{q_1} \right\rangle^+_E\not\equiv 0\modulo p,\end{equation}
where $\langle x\rangle_E^+= \Re2\pi i \int_x^\infty f_E(z) dz/\Omega_E^+ $ denotes \emph{modular symbols} and 
$\zeta_{q_1}$ denotes a generator of $(\Z/q_1)^\times$, then we have $\mu=0$ and $\lambda=1$. The mod $p$ Kurihara conjecture has been proved in many cases \cite{BurungaleCastellaGrossiSkinner}.
\end{enumerate}
We refer to Section \ref{sec:constant} for more details.
\end{remark}
\begin{remark}
    In \cite{KrizNordentoft} the authors obtained information about the $p$-adic valuation of the individual $L$-values in the same family as that of Theorem \ref{thm:widemoment2} (see Theorem 1.6 and Corollary 5.20 in \emph{loc.\ cit.}). But nothing was said about the $p$-adic oscillations, which conjecturally (for elliptic curves by the BSD conjectures) should encode deep arithmetic information. Clearly the valuation of the above moments depends crucially on these oscillations and how they interact with cyclotomic units, which themselves carry arithmetic meaning. 
\end{remark}
\begin{remark}
The above $p$-adic valuation arises from $p$-adic properties of the underlying automorphic periods which force a rigid structure on the moments. Different incarnations of automorphic periods implying (surprising) structure in moments of $L$-functions in the archimedean aspect include the topics of \emph{spectral reciprocity} \cite{BlomerKhan19}, \cite{BlomerLiMiller19} and \emph{wide moments} \cite{NordentoftWide2}, \cite{NordentoftWide1}. 
\end{remark}




\section{Recollections on $p$-adic measures}\label{sec:recoll}
In this section we will recall some general facts about \emph{horizontal} and \emph{vertical measures}.  %In particular, this implies that the \emph{Kato--Kolyvagin derivative} of our horizontal measure is equal modulo $p$ to the \emph{actual} derivative of the power series associated by the digit construction (Section \ref{sec:firstdigit}). This will give a general arithmetic criterion for non-vanishing of measures. %Finally, our constructions unveil a number of ``hidden'' actions and operations on the Iwasawa algebra coming from symmetries of the \emph{digit group} $(\Z/p)^\N$ (Section \ref{sec:hidden}) that might have applications elsewhere (we hope to return to this is in future work).  
\subsection{The Amice transform and the Weierstrass Preparation Theorem}In this section we recall some classical results on vertical Iwasawa algebras over $p$-adic rings. For simplicity, we will restrict ourselves to our setting where $R \subset \C_p$ is a $p$-adically complete subring. Let $R\llbracket \Z_p\rrbracket := \varprojlim_nR[\Z/p^n]$, where the inverse limit is given by the projections $\Z/p^n \rightarrow \Z/p^{n-1}$. Thus $R\llbracket \Z_p\rrbracket$ is the space of $R$-valued measures on $\Z_p$, i.e. the $R$-linear topological dual of the space of continuous functions $\Z_p \rightarrow \Z_p$. Recall Mahler's theorem \cite[p. 52]{Washington}, which says that for any continuous function $f : \Z_p \rightarrow \Z_p$ we can write $f = \sum_{n = 0}^{\infty}a_n\binom{x}{n}$ for uniquely determined $a_n \in \Z_p$ with $\lim_{n \rightarrow \infty}v_p(a_n) = \infty$, where $\binom{x}{n} \in \Q[x]$ is the usual binomial coefficient (which is easily seen to take values in $\Z_p$ for $x \in \Z_p$, as it is $p$-adically continuous and takes values in $\Z$ for $x \in \Z$). In particular, we see that any $\nu \in R\llbracket \Z_p\rrbracket$ is uniquely determined by its values $\nu(\binom{x}{n}) \in R$. Precisely, we have the following  result of Amice (which is sometimes referred to as the \emph{Amice transform}, \cite[Theorem 7.1, Chapter 12]{Washington}): 

\begin{theorem}\label{thm:Amice}There is a canonical isomorphism of $R$-algebras
\begin{equation}\label{eq:amice}R\llbracket \Z_p\rrbracket \cong R\llbracket T\rrbracket, \hspace{1cm} \nu \mapsto \sum_{n = 0}^{\infty}\nu\left(\binom{x}{n}\right)T^n.\end{equation}
\end{theorem}

We also recall the classical \emph{Weierstrass preparation theorem} (\!\cite[Theorem 7.3]{Washington}), adapted to our setting.

\begin{theorem}\label{thm:Weierstrassprep}Suppose $R \subset \C_p$ is the ring of integers of a finite extension of $\Q_p$. Let $\pi$ be a uniformizer of $R$. Then any non-zero element $f \in R\llbracket T\rrbracket$ admits a unique factorization $f = \pi^{\mu(f)}g(T)u(T)$ where $\mu(f) \in \Z_{\ge 0}$, $g(T) = T^{\lambda(f)} + a_{\lambda(f)-1}T^{\lambda(f)-1} + \cdots + a_0$ with $a_i \in (\pi)$ for all $0 \le i \le \lambda(f)-1$, and $u(T) \in R\llbracket T\rrbracket^{\times}$.
\end{theorem}
In the discussion below we continue to denote the invariants associated to $f\in R\llbracket T\rrbracket$ as in the above theorem by $\mu(f),\lambda(f)$ and refer to them as, respectively the $\mu$-\emph{invariant} and $\lambda$-\emph{invariant of $f$}. For $f=0$ we set $\mu(f)=\infty$ and $\lambda(f)=0$.
\subsection{The horizontal Iwasawa algebra}In this section we recall some of the background material from \cite[Section 2.1]{KrizNordentoft}. Let $\N = \Z_{> 0}$. Suppose we are given a finite sequence of finite abelian groups $G_1, G_2,\ldots$. The product group $\prod_{n \in \N}G_n$ is canonically a projective limit
$$G_{\N} = \varprojlim_{\substack{A \subset \N\\\text{ finite}}}\prod_{n \in A}G_n$$
where the transition maps are given by the canonical projections
$$\pi_{A,A'} : \prod_{n \in A}G_n\twoheadrightarrow \prod_{n \in A'}G_n$$
if $A' \subset A$. For each finite set, we give $\prod_{n \in A}G_n$ the discrete topology. Then $G_{\N}$ has the induced product topology, which is the coarsest topology such that each projection $G_{\N} \rightarrow \prod_{n\in A}G_n$ is continuous. This also realizes $G_{\N}$ as a profinite group. Let $R$ be a commutative ring and define 
\begin{equation}\label{eq:defhoralg}\Lambda_{G_\N, R}^{\mathrm{hor}}:=R\llbracket G_\N \rrbracket= \varprojlim_{\substack{\pi_{A,A'} \\ A' \subset A \subset \N\\A, A'\text{finite}}}R\left[\prod_{n \in A}G_n\right].\end{equation}
We endow $\Lambda_{G_\N, R}^{\mathrm{hor}}$ with the inverse limit topology and refer to it as the \emph{horizontal Iwasawa algebra (associated to $G_\N$ and $R$)}. We note that the rings $\Lambda_{G_\N,R}^{\mathrm{hor}}$ are quite badly behaved: they are non-noetherian and not integral domains. For example, observe that for each $n\in \N$ we have canonical embeddings
\begin{align}\label{eq:nonintdom}R[G_n]\hookrightarrow \Lambda_R^{\mathrm{hor}},\end{align}
induced from the group embeddings $G_n\hookrightarrow \prod_{i=1}^{n'}G_i$ for $n'\geq n$ and clearly for $g\in G_n$ non-trivial of order $m\geq 1$ we have 
$$([g]-1)([g^{m-1}]+\ldots+[g]+1)=0\in R[G_n].$$ 
