\subsection{Recollections on horizontal $p$-adic $L$-functions of holomorphic newforms}In this section we briefly recall some background results on the horizontal $p$-adic $L$-function attached to a holomorphic newform from \cite[Section 5]{KrizNordentoft}. We refer to \emph{loc.\ cit.}\ for full details. Throughout this section we let $f$ be a holomorphic newform of level $N$, even weight $k$, nebentype $\epsilon_f$ and Fourier expansion  $f(z)=\sum_{n\geq 1} a_f(n)q^n$ at infinity. Recall the definition of the $L$-function as in (\ref{eq:Lfunction}). Let $\mathcal{O}_f$ denote the ring of integers of the Hecke field $K_f$ of $f$. Given a prime $\mathfrak{p}$ of $\mathcal{O}_f$ we let $\mathcal{O}_{f,\mathfrak{p}}$ denote the $\mathfrak{p}$-adic completion of $\mathcal{O}_f$. First we recall the notion of \emph{Taylor--Wiles primes}.

\begin{definition}[Taylor--Wiles primes]\label{def:TW}
We define the set of \emph{Taylor--Wiles primes for $f$ (modulo $\mathfrak{p}$)} as: 
%TW(f;p):=\{\ell\text{ prime}: \ell\nmid N, p|\ell-1, \mathrm{ev}_p(a_f(\ell)-1-\epsilon_f(\ell))=0\}. 
\begin{equation}\label{eq:TWdef}
TW(f;\mathfrak{p}):=\{\ell\text{ prime}: \ell\nmid N, p|\ell-1, a_f(\ell)-1-\epsilon_f(\ell)\in (\mathcal{O}_{f,\mathfrak{p}})^\times\}, 
\end{equation}
We say that $\mathfrak{p}$ is \emph{$f$-good} if $TW(f;\mathfrak{p})$ has positive density among all primes.
\end{definition}
The condition of $\mathfrak{p}|p$ being $f$-good follows from a \emph{big image} assumption and is thus generically true for non-CM forms. We refer to \cite[Section 4]{KrizNordentoft} for more details.

In \cite{KrizNordentoft} the authors showed how to $p$-adically interpolate the $L$-values given by $p$-power order characters with conductor given by a product of Taylor--Wiles primes. 

\begin{definition}[Horizontal $p$-adic $L$-function of a holomorphic newform, Definition 5.3 of \cite{KrizNordentoft}]\label{def:padicL}
   Let $p$ be a prime number and let $\mathfrak{p}|p$ be a place of $K_f$ above $p$ which is $f$-good in the sense of Definition \ref{def:TW}. Let $R$ denote the ring of integers of the completion $K_{f,\mathfrak{p}}$ of $K_f$ at $\mathfrak{p}$. Let $r\geq 0$ be an integer, $\pm$ a sign, and let $\mathcal{L}=(\ell_n)_{n\in \N}$ be a sequence of distinct primes not dividing $N$, congruent to $1$ modulo $p$, and such that $\ell_n\in TW(f;\mathfrak{p})$ for $n\geq r+1$. For $n\in \N$ put   $m_{n}=v_p(\ell_n-1)$.%Let $\underline{m}=(m_n)_{n\in \N}$ be the sequence of positive integers given by  $m_{n}=v_p(\ell_n-1),n\in\N$. 

   Let 
\begin{equation}\label{eq:horpadicL}\nu^\pm_{f,\mathcal{L},r}\in  R\left\llbracket \prod_{n\in \N} \Z/p^{m_n} \right\rrbracket  ,
\end{equation}
  be the \emph{horizontal $p$-adic $L$-function of $f$ associated to $(\mathcal{L},r,\pm)$} from \cite[Definition 5.3]{KrizNordentoft}. 
\end{definition}
We emphasize that the fact that we can allow for finitely many non-Taylor--Wiles primes $\{\ell_1,\ldots,\ell_r\}$, suppressed from the notation, is key for many applications, see Remark \ref{rem:Kurihara}.

The $p$-adic measure $\nu^{\pm}_{f,\mathcal{L},r}$ is uniquely determined by the interpolation property \cite[Corollary 5.4]{KrizNordentoft} which we will now recall.  Suppose we are given a finite order Dirichlet character $\chi$ of  conductor $D_{\chi}$ dividing $\prod_{n \in \N}\ell_n$ and sign $\pm$, i.e. $\chi(-1) = \pm 1$. Then as in \cite[Equation (5.13)]{KrizNordentoft} we define the modified $L$-value of $f$ twisted by $\chi$:
\begin{align}\nonumber L^\ast_f(\chi)&:=\left(\prod_{1\leq i\leq r: \ell_i\nmid D_\chi}(a_f(\ell_i)\ell_i^{-(k-2)/2}-\chi(\ell_i)-\epsilon_f(\ell_i)\overline{\chi}(\ell_i))\right)\\
\label{eq:interpolationfinal} &\cdot \left(\prod_{i\geq r+1: \ell_i|D_\chi}(a_f(\ell_i)\ell_i^{-(k-2)/2}-\chi^{(i)}(\ell_i)-\epsilon_f(\ell_i)\overline{\chi}^{(i)}(\ell_i))\right)^{-1} \\
&\nonumber\cdot \tau(\overline{\chi})L(f,\chi,k/2)/\Omega_f^\pm.\end{align} 
Here $\chi^{(i)} \pmod{\frac{D_{\chi}}{\ell_i}}$ denotes the Dirichlet character obtained by restricting $\chi$ modulo  $\frac{D_{\chi}}{\ell_i}$, the twisted $L$-function $L(f,\chi,s)$ is defined as in (\ref{eq:Lfunction}), $\tau(\chi)$ is a Gauss sum, and $\Omega_f^{\pm}$ denotes a plus/minus period of $f$, see \cite[Section 3]{KrizNordentoft} for details. In particular, for $f=f_E$ corresponding to an elliptic curve $E/\Q$ one can pick $\Omega_{f_E}^\pm\in \Omega_E^\pm\Q^\times$ where $\Omega_E^\pm$ denotes the N\'{e}ron periods of $E$.

\begin{corollary}[Interpolation property of the horizontal $p$-adic $L$-function]\label{cor:measure}
Let $f$ be a newform of even weight $k$, level $N$ and nebentypus $\epsilon_f$. Let $\nu^\pm_{f,\mathcal{L},r}\in R\left\llbracket \prod_{n\in \N} \Z/p^{m_n} \right\rrbracket $ be a horizontal $p$-adic $L$-function of $f$ as in Definition \ref{def:padicL}. Let $\chi$ be a Dirichlet character of $p$-power order with conductor dividing $\prod_{n\in \N}\ell_n$. Write $\chi=\tilde{\chi}\circ \rho_\N$ in terms of the projection $\rho_\N: \prod_{n\in \N}(\Z/\ell_n)^\times \twoheadrightarrow \prod_{n\in \N}\Z/p^{m_n}$ and a character  $\tilde{\chi}:\prod_{n\in \N}\Z/p^{m_n}\rightarrow \C_p^\times$. Let $\pm$ denote the sign of $\chi$, i.e. $\chi(-1)=\pm 1$. Then we have \begin{equation}\label{eq:interpolationmeasure}\nu^\pm_{f,\mathcal{L},r}(\tilde{\chi})=L^\ast_f(\chi).\end{equation} 
\end{corollary}




\section{The digit construction}\label{sec:digitconstr}%%%%%%%%%%%%
In this section we introduce a method for turning horizontal measures as in \cite{KrizNordentoft} into usual \emph{vertical measures}, i.e. elements of the \emph{vertical Iwasawa algebra} $\Z_p\llbracket \Z_p\rrbracket$. Applying the Amice transform (Theorem \ref{thm:Amice}), we then produce a power series whose values can be related to the original horizontal measure via Fourier theory. Applying this construction to the \emph{horizontal $p$-adic $L$-functions} associated to holomorphic cusp forms constructed in \cite{KrizNordentoft} together with the Weierstrass Preparation Theorem (Theorem \ref{thm:Weierstrassprep}) then yields the $p$-adic valuation of the twisted moments of the shape (\ref{eq:padicmoment}).

The starting point for our construction is the \emph{set theoretic} bijection 
$$(\mathbb{Z}/p)^\N \cong_{\mathrm{Sets}} \mathbb{Z}_p,$$
given by the usual $p$-adic digit expansion (see Definition \ref{def:digitgen} for the general case). This yields an isomorphism of topological $\Z_p$-modules 
$$\Z_p\llbracket (\Z/p)^\N \rrbracket \cong \Z_p\llbracket \mathbb{Z}_p\rrbracket.$$
We call this latter map the \emph{digit map}. This allows us to obtain $p$-adic valuation of certain ``twisted moments'' of horizontal measures (Proposition \ref{prop:widemoment}). %When the horizontal measure come from arithmetic (e.g. induced by modular symbols or Heegner points), this latter information about the zeros can be parlayed into information about the non-vanishing of periods (e.g. $L$-values and derivatives of $L$-values) in twist families.  

It is a general fact that given two pro-finite groups $G_1,G_2$ then any homeomorphism as profinite sets $G_1\xrightarrow{\sim} G_2$ induces an isomorphism of $R$-modules of the corresponding group rings $R\llbracket G_1 \rrbracket\xrightarrow{\sim}R\llbracket G_2 \rrbracket$ (which is \emph{not} necessarily an isomorphism of $R$-algebras). Of course, most such identifications will not reveal much about the properties of $R\llbracket G_1 \rrbracket$ as the ring structure is obscured. It turns out that the digit construction \emph{does} see parts of the group structure as we will see in the following sections (what we call the {\lq\lq}last digit trick{\rq\rq}). This ultimately leads to the appearance of cyclotomic units in Theorem \ref{thm:widemoment2}.  

\subsection{The digit map} As in the previous section let $G_1,G_2,\ldots $ be a sequence of finite abelian groups. Assume that for each $n \in \N$, $G_n$ admits $\mathbb{Z}/p^{m_n}$ as a quotient for some $m_n\geq 1$; for $k\geq 1$ we henceforth give $\mathbb{Z}/p^k$ the discrete topology, so that in particular any quotient map $G_n \rightarrow \mathbb{Z}/p^{m_n}$ is continuous. The purpose of this section is to show how to {\lq\lq}verticalize{\rq\rq} elements of $R\llbracket G_\N\rrbracket$ (i.e. horizontal measures), and turn them into elements of $R\llbracket \mathbb{Z}_p\rrbracket$  (i.e. vertical measures). This will be done via a certain ``digit map''. %, which will take as input a \emph{sequence} (i.e. ordered set) of integers $\underline{m} = (m_n)_{n\in \N}$, in order to produce a bijection of sets $\prod_{n\in \N}\mathbb{Z}/p^{m_n} = \mathbb{Z}_p$. 

Given a sequence (i.e. ordered set) of positive integers $\underline{m}=(m_n)_{n\in \N}$ we define the \emph{digit group (associated to $\underline{m})$} by
$$\Pi_{\underline{m}}=\prod_{n\in \N}\mathbb{Z}/p^{m_n}.$$
%which we note up to isomorphism only depends on the underlying set of $\underline{m}$.  
%\subsubsection{The digit map}
For $n \in \N$ we have a natural projection
$$\pi_n' : \prod_{i=1}^n\mathbb{Z}/p^{m_i} \rightarrow \prod_{i=1}^{n-1}\mathbb{Z}/p^{m_i}$$
given by quotienting out by the $n^{\mathrm{th}}$ factor $\mathbb{Z}/p^{m_n}$. Then we have a canonical isomorphism of groups 
\begin{equation}\label{eq:aboveiso}\Pi_{\underline{m}} \cong \varprojlim_n \prod_{i=1}^n\mathbb{Z}/p^{m_i}.\end{equation}
Let $R$ be a commutative ring and define the \emph{digit algebra (associated to $\underline{m}$ and $R$)} as 
$$\Lambda_{R,\underline{m}}^{\mathrm{dig}} = \varprojlim_{\pi_n'} R\left[\prod_{i=1}^n\mathbb{Z}/p^{m_i}\right].$$
We note that despite the notation, $\Lambda_{R,\underline{m}}^{\mathrm{dig}}$ depends up to isomorphism on the underlying set of $\underline{m}$ (and not on the ordering of $\underline{m}$). %We give $\Lambda_{R,\underline{m}}^{\mathrm{dig}}$ the inverse limit topology\todo{we never use the topology}. 

Now pick projections $\rho_n:G_n\twoheadrightarrow \Z/p^{m_n}$ for $n\geq 1$ and consider the  associated continuous group surjection
\begin{equation}\label{eq:projectionrhogroup}\rho=\prod_{n\in \N} \rho_n :G_\N \twoheadrightarrow  \Pi_{\underline{m}}.
\end{equation} 
We then get a continuous $R$-algebra surjection (which we will denote by the same symbol) 
\begin{equation} \label{eq:projectionrho} \rho:\Lambda_R^{\mathrm{hor}} \twoheadrightarrow \Lambda_{R,\underline{m}}^{\mathrm{dig}}.\end{equation}
%(the action of $S_{\infty}$ on $\Lambda_R^{\mathrm{hor}}$ descends to an action of $S_{\infty}$ on $\Lambda_{R,\underline{m}}^{\mathrm{dig}}$. )
The following key definition allows us to verticalize the digit algebra to relate it to the usual Iwasawa algebra. 
\begin{definition}[The digit map]\label{def:digitgen}For $m\geq 1$ and $a \in \mathbb{Z}/p^m$, let $0 \le \tilde{a} \le p^m-1$ be the unique integer with $\tilde{a} \modulo p^m = a$. Let $\underline{m}=(m_n)_{n\in \N}$ be a sequence of positive integers. For any $n\in \N \cup\{\infty\}$ we have a commutative diagram of maps of sets:
\begin{equation}\label{eq:digitdefinition}\begin{tikzcd}[column sep = large]
\prod_{i=1}^n(\mathbb{Z}/p^{m_i})  \arrow{r}{d_{n,\underline{m}}} & \mathbb{Z}/p^{m_1+\ldots +m_n} \\
\Pi_{\underline{m}} \arrow{u}{} \arrow{r}{d_{\infty,\underline{m}}} & \mathbb{Z}_p \arrow{u}{}\\
  \end{tikzcd}.
  \end{equation}
where $d_{n,\underline{m}}$ is the set bijection given by 
$$\prod_{i=1}^n(\mathbb{Z}/p^{m_i}) \ni (a_i)_i \xmapsto{d_{n,\underline{m}}} \sum_{i = 1}^n\tilde{a}_ip^{m_1+\ldots+m_{i-1}} \in \mathbb{Z}/p^{m_1+\ldots+m_n}.$$
The commutativity of (\ref{eq:digitdefinition}) gives natural compatibilities of the diagrams (\ref{eq:digitdefinition}), which in turn gives the continuity of $d_{n,\underline{m}}$ for all $0 \le n \le \infty$. 
\end{definition}
We note that by the continuity of $d_{n,\underline{m}}$, for every $0 \le n < \infty$ we get an isomorphism of topological $R$-modules
$$d_{n,\underline{m}} : R\left[\prod_{i=1}^n\mathbb{Z}/p^{m_i}\right] \xrightarrow{\sim} R[\mathbb{Z}/p^{m_1+\ldots+m_n}].$$
This induces an isomorphism of topological $R$-modules
$$d_{\infty,\underline{m}} : \Lambda_{R,\underline{m}}^{\mathrm{dig}} \xrightarrow{\sim} R\llbracket \mathbb{Z}_p\rrbracket.$$
The case where there exists $m\geq 1$ such that $m_n=m$ for all $n\geq 1$ is of special interests to us as it will be connected to non-vanishing of twists of order \emph{precisely} $p^m$.  In this case we denote the associated digit group by  
$$(\Z/p^m)^\N=\varprojlim_{\pi'_n} \prod_{i=1}^n\mathbb{Z}/p^{m},$$
and denote the associated digit map by $d_{\infty,m}:(\Z/p^m)^\N\rightarrow \Z_p$ which we refer to as the \emph{$p^m$-adic digit map}. Similarly, we denote the associated digit algebra by
$$ \Lambda^\mathrm{dig}_{R,m}= \varprojlim_{\pi'_n} R\left[\prod_{i=1}^n\mathbb{Z}/p^{m}\right],$$ 
and refer to it as the \emph{$p^m$-adic digit algebra}. 
%\begin{remark}[The ``Abstract Digit Algebra'']\label{rem:abstract}\todo{Maybe consider leaving out?}For any cyclic $G_n$ let $G_{n,p}$ denote its maximal pro-$p$ quotient. Thus the product group $\prod_{n \in \N}G_{n,p}$ is the maximal pro-$p$ quotient of $\prod_{n \in \N}G_n$. Let
%$$\Lambda_{R,\mathrm{abs}}^{\mathrm{dig}} = \varprojlim_{\substack{A \subset \N\\A \; \text{finite}}}R[\prod_{n \in A}G_{n,p}].$$
%Thus the canonical quotient map $\prod_{n \in \N}G_n \twoheadrightarrow \prod_{n \in \N}G_{n,p}$ induces a surjective map of $R$-algebras
%$$\Lambda_R^{\mathrm{hor}} \rightarrow \Lambda_{R,\mathrm{abs}}^{\mathrm{dig}}.$$
%We also have a ``canonical'' choice of $\underline{m}$: for each $n \in \N$, let $p^{\mathbf{m}_n}$ be the maximal power of $p$ dividing $\#G_n$. Then letting $\underline{\mathbf{m}} = (\mathbf{m}_1,\mathbf{m}_2,\ldots)$ we have a (non-canonical) $R$-algebra isomorphism
%$$\Lambda_{R,\mathrm{abs}}^{\mathrm{dig}} \xrightarrow{\sim} \Lambda_{R,\underline{\mathbf{m}}}^{\mathrm{dig}}.%$$
%The reader may find the objects $\Lambda_{R,\mathrm{abs}}^{\mathrm{dig}}$ or $\Lambda_{R,\underline{\mathbf{m}}}^{\mathrm{dig}}$ more natural to work with than $\Lambda_{R,\underline{m}}^{\mathrm{dig}}$, and thus ask why we consider the latter. However, in many settings one can only invert the Euler-like factors appearing in norm relations (as in \cite[Section 2.1.1]{KrizNordentoft}) \emph{after} projecting to the digit algebra and also for our argument (particularly to study the non-vanishing of our horizontal measures at characters of exact order $p^m$ for a given $m$), we will need the extra flexibility in the choice of $\underline{m}$ as well as to work with multiple different $\underline{m}$. 
%\end{remark}
\begin{remark}\label{rem:moregeneraldigit}
One can consider more general ``digit maps'' obtained from any sequence of bijections $\prod_{i=1}^n\Z/p^{m_i}\xrightarrow{\sim} \Z/p^{\Sigma_{i=1}^n m_i}$ making the diagram (\ref{eq:digitdefinition}) commute. These correspond exactly to picking for each $n$ an automorphism of $ \Z/p^{m_n}$ as a \emph{set} rather than as a group). These maps also yield a verticalization procedure but with less favorable properties (see Remark \ref{rem:generaldigitfourier} below).   
\end{remark} 
%Using the digit map $d_\infty$ we obtain a {\lq\lq}hidden{\rq\rq} $R$-action of $S_\infty^\mathrm{big}$ on $R\llbracket \mathbb{Z}_p\rrbracket.$.  


\subsection{Fourier coefficients of the digit map}\label{sec:lastdigit}
In this section we will translate between characters of $\Z_p$ and those of $\prod_{n\in \N}\mathbb{Z}/p^{m_n}$ under the digit map. We start by recording a simple but key property  of the digit map: given an additive character of $\Z_p$ then the restriction to the {\lq\lq}last digit{\rq\rq} yields a character of the corresponding factor $\mathbb{Z}/p^{m_n}$.     
\begin{lemma}[The last digit trick]\label{lem:lastdigitgen}
Let $\psi:\Z_p\rightarrow \C_p^\times$ be an additive character of $\Z_p$ of conductor $p^n$. Then $\psi_{|p^{n-m}\Z_p}$ defines an order $p^m$ character of $p^{n-m}\Z_p/p^n\Z_p\cong \Z/p^m$.
\end{lemma}       
\begin{proof}
Since $\psi$ is trivial on $p^n\Z_p$ and has order $p^n$, we see that indeed $\psi^{p^{n-m}}$ has order $p^m$ and factors through the claimed quotient. This yields the assertion since $\psi$ is an additive character.%We see that for $x,y\in\Z_p/p\Z_p$ we have $\chi(p^{n-1}(x+y))$ 
\end{proof}
Given a character $\psi:\Z_p\rightarrow \C_p^\times$ of conductor $p^n$ we will view it as a character $\psi:\Z/p^n\rightarrow \C_p^\times$ via the projection $\Z_p \rightarrow \Z/p^n$ and for $1\leq m<n$, we will denote by 
\begin{equation}\psi^{p^m}:\Z/p^{n-m}\rightarrow \C_p^\times,\end{equation} 
the character obtained by precomposing $\psi$ with the natural inclusion 
\[\Z/p^{n-m} \underset{\sim}{\xrightarrow{x \mapsto p^mx}}p^m\Z/p^n\Z \subset \Z/p^{n}\] given by multiplication by $p^m$. 

Let $G$ be a finite abelian group and denote by $\widehat{G}$ the group of $\C_p^\times$-valued characters. For $f:G\rightarrow \C_p$ and $\chi\in \widehat{G}$ we define the \emph{Fourier coefficient of $f$ against $\chi$} as:
\begin{equation}\langle f,\chi\rangle := \sum_{g\in G} f(g)\overline{\chi}(g). \end{equation} 
Then orthogonality of characters (i.e. Fourier inversion) yields the following Fourier expansion of $f$
\begin{equation}\label{eq:Finv}f(g)=\frac{1}{|G|}\sum_{\chi\in \widehat{G}}\langle f,\chi\rangle \chi(g),\quad g\in G. \end{equation}
The {\lq\lq}last digit trick{\rq\rq} above yields the following key restriction on the Fourier expansion of additive characters. This ultimately accounts for the appearance of cyclotomic units in Theorem \ref{thm:widemoment2}.  
\begin{lemma}\label{lem:lastdigitexpansion}
Let $\underline{m}=(m_n)_{n\in \N}$ be a sequence of positive integers and let  $\psi$ be an additive character of $\Z_p$ of conductor $p^{m_1+\ldots+m_{n-1}+k}$ with $1\leq k\leq m_n$. Then the Fourier coefficient of 
$$ \psi\circ (d_{n,\underline{m}})^{-1}: \prod_{i=1}^n (\Z/p^{m_i})\rightarrow \C_p^\times, $$
against a character $\chi=(\chi_1,\ldots, \chi_n)\in \prod_{i=1}^n \widehat{\Z/p^{m_i}}$ is zero unless $\chi_n=\psi^{p^{m_1+\ldots+m_{n-1}}}$ in which case we have
$$ \langle \psi\circ (d_{n,\underline{m}})^{-1},\chi\rangle =p^{m_n}\prod_{i=1}^{n-1}\frac{\psi(p^{m_1+\ldots+m_i})-1}{\psi(p^{m_1+\ldots+m_{i-1}})\overline{\chi_i}(1)-1}. $$ 
In particular, all non-zero Fourier coefficients have the same $p$-adic valuation.  
\end{lemma}
\begin{proof}
Let $\chi=(\chi_1,\ldots,\chi_n)\in \prod_{i=1}^n \widehat{\Z/p^{m_i}}$. Then since $\psi$ is an additive character, we see that for  $a=(a_1,\ldots,a_n)$ with $a_i\in \Z/p^{m_i}$; 
\begin{align} 
\psi((d_{n,\underline{m}})^{-1}(a))\overline{\chi(a)}&=\psi\left(\sum_{i=1}^{n}\tilde{a}_ip^{m_1+\ldots+m_{i-1}}\right)\overline{\chi}(a)\\
&= \prod_{i=1}^n (\psi(\tilde{a}_ip^{m_1+\ldots+m_{i-1}})\overline{\chi}_i(a_i)),
\end{align}
which yields the factorization
$$\langle \psi\circ (d_{n,\underline{m}})^{-1}, \chi \rangle= \prod_{i=1}^{n}\left(\sum_{a=0}^{p^{m_i}-1}\psi(ap^{m_1+\ldots+m_{i-1}}) \overline{\chi}_i(a)\right).$$
By Lemma \ref{lem:lastdigitgen} and orthogonality of characters, we see that the above vanishes unless 
$$\chi_n(1)=\psi^{p^{m_1+\ldots+m_{n-1}}}(1),$$
which yields the first claim. For $i<n$, we get a geometric series which amounts to 
\begin{align*}\sum_{a=0}^{p^{m_i}-1}\psi(ap^{m_1+\ldots+m_{i-1}}) \overline{\chi}_i(a)&= \sum_{a=0}^{p^{m_i}-1}(\psi(p^{m_1+\ldots+m_{i-1}})\overline{\chi}_i(1))^a\\
&=\frac{\psi(p^{m_1+\ldots+m_{i}})-1}{\psi(p^{m_1+\ldots+m_{i-1}})\overline{\chi_i}(1)-1}
\end{align*}
using that $\chi_i(1)^{p^{m_i}}=1$. This implies the desired formula. Finally it follows by the above formula that the $p$-adic valuation is the same for all the non-zero Fourier coefficients.
\end{proof}
\begin{remark}\label{rem:generaldigitfourier}
If one considers more general digit maps $d:\prod_{i=1}^\N \Z/p^{m_i}\xrightarrow{\sim} \Z_p$ as described in Remark \ref{rem:moregeneraldigit}, one can prove the following; with $\psi:\Z_p\rightarrow \C_p^\times$ and $\chi=(\chi_1,\ldots,\chi_n)$ as in Lemma \ref{lem:lastdigitexpansion}, we have that $\langle \psi\circ (d_{n,\underline{m}})^{-1}, \chi\rangle=0$ when $\chi_n$ is trivial. The Fourier coefficients do however not seem to admit a nice expression in this generality and in particular the $p$-valuation is not the same for the different Fourier coefficients. 
\end{remark}
From this we get the following translation between horizontal and vertical measures.
\begin{corollary}\label{cor:lastdigit}
Let $\underline{m}=(m_n)_{n\in \N}$ be a sequence of positive integers and let $\Lambda_{R,\underline{m}}^\mathrm{dig}$ be the associated digit algebra. Let $\nu\in \Lambda_{R,\underline{m}}^\mathrm{dig}$ be a horizontal measure and let $\psi$ be a character of $\Z_p$ of conductor $p^N$ with 
$$m_1+\ldots+m_{n}<N\leq m_1+\ldots+m_{n+1}.$$ 
Then we have
\begin{align}\label{eq:Fourierexpansionhor}
d_{\infty,\underline{m}}(\nu)(\psi)=&\frac{\psi(p^{m_1+\ldots+m_n})-1}{p^{m_1+\ldots+m_n}(\psi(1)-1)}\\
&\cdot\sum_{(\chi_i)\in \Pi_{i=1}^n\widehat{\Z/p^{m_i}}}c_{\psi}(\chi_1,\ldots, \chi_{n})\nu(\chi_1,\ldots,\chi_{n},\psi^{p^{m_1+\ldots+m_{n}}} ),   
\end{align} 
where 
\begin{align}c_{\psi}(\chi_1,\ldots, \chi_{n})=\prod_{i=1}^{n} \frac{\psi(p^{m_1+\ldots+m_{i-1}})-1}{\psi(p^{m_1+\ldots+m_{i-1}})\overline{\chi_i}(1)-1}. \end{align}
%In particular, if $d_\infty(\rho(\nu))(\psi)\neq 0$ with $\psi$ of conductor $p^n$ then there exists a character $\chi$ of $(\Z/p)^n$ with non-trivial last component such that $\rho(\nu)(\chi)\neq 0$.  
\end{corollary}
\begin{proof}
This follows directly from taking the Fourier expansion $d_{\infty,\underline{m}}(\nu)(\psi)$ in terms of the characters of $\prod_{i=1}^n \Z/p^{m_i}$ as in (\ref{eq:Finv}) combined with Lemma \ref{lem:lastdigitexpansion} by reordering the factors appropriately.
\end{proof}
\begin{remark}\label{rem:intermsof}
We will be applying Corollary \ref{cor:lastdigit} to measures $\rho(\nu)\in \Lambda_{R,\underline{m}}^\mathrm{dig}$ obtained from a horizontal measure $\nu\in \Lambda_R^\mathrm{hor}$ and a choice of projections $\rho_n:G_n\twoheadrightarrow \Z/p^{m_n}$. In this case the right-hand side of (\ref{eq:Fourierexpansionhor}) can be written in terms of $\nu$ evaluated at characters $\chi:G_\N\rightarrow  \C_p^\times$ which factor through the projection $\prod_{i=1}^n \rho_i$. In particular, if $m_n=1$ for all $n\geq 1$ this corresponds exactly to character of order $p$ (as well as the trivial character).  
\end{remark}



\subsection{Valuation of twisted moments}\label{sec:widemoment}
Using the above properties of the digit map we arrive at the following general result for twisted $p$-adic moments of horizontal measures. We let $\C_p$ be the $p$-adic complex numbers and fix a $p$-adic valuation $v_p:\C_p\rightarrow (-\infty,\infty]$ normalized so that $v_p(p)=1$.  
\begin{proposition}\label{prop:widemoment}
Let $R\subset \C_p$ be the ring of integers of a finite extension of $\Q_p$ with ramification index $e\geq 1$. Let $\nu\in \Lambda_R^\mathrm{hor}$ be a horizontal measure in the horizontal Iwasawa algebra defined from groups $(G_n)_{n\in \N}$. Let $m\geq 1$ be an integer and assume that there exists surjections $\rho_n:G_n\twoheadrightarrow \Z/p^{m},n\geq 1$. Let $\rho:\Lambda_{R}^\mathrm{hor}\rightarrow \Lambda_{R,m}^\mathrm{dig}$ be the pushforward to the $p^m$-adic digit algebra by the associated projection as in (\ref{eq:projectionrho}).
%Let $G_1,G_2,\ldots$ be any sequence of finite abelian groups with surjections $\rho_n:G_n\twoheadrightarrow \Z/p^m,n\geq 1$, and let $\Pi_\infty=\varprojlim \prod_{i\leq n} G_i$. Let $\rho: $Let $R$ be the ring of integers of a finite extension of $\Q_p$ and let $\nu\in R\llbracket \Pi_\infty \rrbracket$ be a non-zero horizontal measure. 
Let $\zeta_{p}, \zeta_{p^2},\ldots$ be a sequence of compatible, primitive $p$-power roots of unity, i.e. $(\zeta_{p^{n_1}})^{p^{n_2}}=\zeta_{p^{n_1-n_2}}$ for $n_1\leq n_2$. 

Let $ \mu\in \Z_{\geq 0}\cup\{ \infty\}$ and  $ \lambda\in \Z_{\geq 0}$  denote the $\mu$ and $\lambda$-invariants of the power series associated to $d_{\infty,m}(\rho(\nu))$ via the Amice transform. Then for $n$ large enough the following holds: If $\chi_0$ denotes the character of $\Z/p^m$ satisfying $\chi_0(1)=\zeta_{p^m}$, then we have
\begin{align}\label{eq:widemoment}
v_p&\nonumber\left(\frac{1}{p^{mn}}\sum_{(\chi_i)\in \widehat{(\Z/p^m)}^{n}} \left(\prod_{i=1}^{n}u_{m,n-i}(\chi_i)\right)\rho(\nu)(\chi_1,\ldots,\chi_{n},\chi_0 )\right)\\
&=\frac{\mu}{e}-\tfrac{1}{p^m-p^{m-1}} +\frac{\lambda+1}{p^{m(n+1)}-p^{m(n+1)-1}},
\end{align}
where $u_{m,n-i}(\chi_i)$ are cyclotomic units given by
$$u_{m,n-i}(\chi_i)= \frac{\zeta_{p^{m(n-i+2)}}-1}{\zeta_{p^{m(n-i+2)}}\overline{\chi_i(1)}-1},\quad 1\leq i\leq n.$$
Furthermore, $\mu= \infty$ (meaning that quantity in the argument of $v_p$ on the left-hand side of (\ref{eq:widemoment}) is zero for $n$ sufficiently large) if and only if $\rho(\nu)=0$.
\end{proposition}
\begin{proof}
%We pick the surjection $s:G_n\twoheadrightarrow \Z/p^m$ so that when we write $\chi_0=\chi_0'\circ s$ for some $\chi_0'\in \widehat{\Z/p^m}$ then we have $\chi_0'(1)=\zeta_{p^m}$. 
Let $\rho(\nu)\in \Lambda_{R,m}^\mathrm{dig}$ be the horizontal measure associated to $\nu$ via the projection $\rho$. Applying the $p^m$-adic digit map we obtain a vertical measure $d_{\infty,m}(\rho(\nu))\in R\llbracket \Z_p\rrbracket$. Let $f_{\nu,m}(T)\in R\llbracket T\rrbracket $ be the power series associated to $d_{\infty,m}(\rho(\nu))$ via the Amice transform (Theorem \ref{thm:Amice}). Then by Corollary \ref{cor:lastdigit} we see that the left-hand side of (\ref{eq:widemoment}) is equal to 
\begin{align*}&v_p\left(\frac{\psi(1)-1}{\psi(p^{mn})-1} f_{\nu,m}(\zeta_{p^{m(n+1)}}-1)\right)\\
&= v_p\left(f_{\nu,m}(\zeta_{p^{m(n+1)}}-1)\right)+\tfrac{1}{p^{m(n+1)}-p^{m(n+1)-1}}-\tfrac{1}{p^m-p^{m-1}}.
\end{align*}
Assume that $\rho(\nu)\neq 0$. Then since the digit map is an $R$-isomorphism we conclude that $d_{\infty,m}(\rho(\nu))\in R\llbracket \Z_p \rrbracket$ is non-zero. Thus by the Weierstrass Preparation Theorem (Theorem \ref{thm:Weierstrassprep}) we can write
\begin{equation}\label{eq:Weierstrassprep}f_{\nu,m}(T)=\pi^{\mu} u(T) \left(T^{\lambda}+\sum_{i=1}^{\lambda} T^{\lambda-i}a_i \right) ,\end{equation}
where  $\pi$ is the uniformizer of $R$, $\mu=\mu(f_{\nu,m})$, $\lambda=\lambda(f_{\nu,m})$, $v_p(a_i)>0$ for $1\leq i \leq \lambda$ and $u(T)\in R\llbracket T\rrbracket^\times$. Now as $n\rightarrow \infty$ we see that 
$$v_p\left( (\zeta_{p^{m(n+1)}}-1)^{\lambda}\right)= \frac{\lambda}{p^{m(n+1)}-p^{m(n+1)-1}}\rightarrow 0.$$
This implies by (\ref{eq:Weierstrassprep}) that for $n$ large enough we have
$$v_p\left(f_{\nu,m}(\zeta_{p^{m(n+1)}}-1)\right)=\frac{\mu}{e}+\frac{\lambda}{p^{m(n+1)}-p^{m(n+1)-1}}, $$
since $u(\zeta_{p^{m(n+1)}}-1)$ is a $p$-adic unit. This yields the desired evaluation upon rearranging the terms appropriately. 
\end{proof}
%Similarly, we have a version when applying (un)lacing which we will not write out explicitly.


\subsection{Proof of the main theorem}We are now in a position to prove our main theorem. 

\begin{proof}[Proof of Theorem \ref{thm:widemoment2}]Let $f_1,\ldots, f_M$ be holomorphic newforms of even weights $k_1,\ldots, k_M$. Applying Proposition \ref{prop:widemoment} to $\nu = \prod_{i = 1}^M\nu^{\pm}_{f_i,\mathcal{L},r}$ from (\ref{eq:horpadicL}), with $\rho:\Lambda_{R}^\mathrm{hor}\rightarrow \Lambda_{R,1}^\mathrm{dig}$ equal to the pushforward to the $p$-adic digit algebra defined by the canonical projections $\rho_n:\Z/p^{m_n}\rightarrow  \Z/p$, we get all the assertions once we note that 
\[\rho(\prod_{i = 1}^M\nu^{\pm}_{f_i,\mathcal{L},r})(\tilde{\chi}_1,\ldots,\tilde{\chi}_{n}) = \prod_{i = 1}^ML_f^{\ast}(\chi_1\cdots \chi_n,k_i/2)\]
by the interpolation property (\ref{eq:interpolationmeasure}), for $\chi_i\modulo \ell_i$ an order $p$ Dirichlet characters corresponding to $\tilde{\chi}_i: \Z/p\rightarrow \C_p^\times$ (i.e. $\tilde{\chi}_i(1)=\chi_i(b_i)$ where $b_i$ denotes the (chosen) generators of $(\Z/\ell_i)^\times$).
\end{proof}


\begin{remark}It is clear that Proposition \ref{prop:widemoment} can be applied to $\nu = \prod_{i = 1}^M\nu^{\pm}_{f_i,\mathcal{L},r}$ with $\rho : \Lambda_R^{\mathrm{hor}} \rightarrow \Lambda_{R,m}^{\mathrm{dig}}$ with any $m \in \Z_{\ge 1}$ to yield a generalization of Theorem \ref{thm:widemoment2}. For simplicity of exposition, we have only written out the statement for $m = 1$.
\end{remark}
\section{On the constants in the asymptotic formula}\label{sec:constant} The quantities $\mu$ and $\lambda$  appearing in (\ref{eq:widemoment2}) are in general very mysterious and might even depend on the ordering of the Taylor--Wiles primes. In this section we will show how under certain assumptions one can relate them to natural invariants of horizontal measure (see \cite[Definition 2.15]{KrizNordentoft}) and  determine them in terms of arithmetic invariants. 

\subsection{Kato--Kolyvagin derivatives}\label{sec:firstdigit} For the rest of this section, let $R$ be the ring of integers of a finite extension of $\Q_p$. Let $\nu\in \Lambda_{R}^\mathrm{dig}$ be an element of the digit algebra and denote by $f_{\nu}(T)\in R\llbracket T\rrbracket$ the associated power series obtained by applying the Amice transform (\ref{eq:amice}) to $d_{\infty,1}(\mu) \in R\llbracket \Z_p\rrbracket$.  Let $\pi_r:(\Z/p)^\N\twoheadrightarrow (\Z/p)^r$ denote the projection to the first $r$ factors and let $\nu_r:=\pi_r(\nu)\in R[(\Z/p)^r]$ denote the measure obtained by pushforward. For an integer $r\geq 0$, we define the \emph{$r^\mathrm{th}$ Kato--Kolyvagin derivative of $\nu$}  to be 
\begin{align}\label{eq:Dr}
 D^r \nu&:=\sum_{a_1=1}^{p}\cdots \sum_{a_r=1}^{p} \left(\prod_{i=1}^r a_i\right)\nu(\mathbf{1}_{\pi_r^{-1}\{(a_1,\ldots, a_r)\}})\\
 &=\sum_{a_1=1}^{p}\cdots \sum_{a_r=1}^{p} \left(\prod_{i=1}^r a_i\right)\nu_r([(a_1,\ldots, a_r)])\in R.  
 \end{align} 
These correspond to Kolyvagin derivatives considered in \cite{WZhang} in the setting of elliptic curves over $\mathbb{Q}$ considered over imaginary quadratic fields. When $r=0$ this is understood to mean $D^0\nu=\nu(\mathbf{1})$ where $\mathbf{1}$ denotes the trivial character. When $r = 1$ we will write $D^r = D$ for brevity. 

The main result of this section is a result relating the power series associated via the digit construction with the Kato--Kolyvagin derivative. For simplicity of exposition, we will henceforth only consider the case $r \leq  1$, although many of the results in the sequel admit generalizations to general $r$ by considering analogues of the digit map to power series algebras over $\Z_p$ in $r$ variables.
\begin{proposition}\label{prop:kolyvaginderiv}
Let $\nu\in \Lambda_R^\mathrm{dig}$ be a horizontal measure and denote by $f_{\nu}(T)\in R\llbracket T\rrbracket$ the associated power series obtained by applying the Amice transform (Theorem \ref{thm:Amice}) to $d_{\infty,1}(\mu) \in R\llbracket \Z_p\rrbracket$ (where $d_{\infty,1}$ is the digit map of Definition \ref{def:digitgen}). Then we have
\begin{align}
    f_{\nu}(0)= D^0\nu=\nu(\mathbf{1})
\end{align}
and the following congruences between elements of $R$, 
\begin{align}\label{eq:derivativecong} \frac{d}{dT}f_{\nu}(T)_{|T=0}&\equiv D\nu\modulo p. 
\end{align}
\end{proposition} 
\begin{proof}
By the definition of the Amice transform (Theorem \ref{thm:Amice}) we have
$$f_{\nu}(T)= \sum_{n = 0}^{\infty}d_{\infty,1}(\nu)\left(\binom{x}{n}\right)T^n ,$$
where $d_{\infty,1}: (\Z/p)^\N\rightarrow \Z_p$ denotes the digit map defined above. By plugging in $T=0$ we conclude the first equality.

Secondly, by taking the derivative in $T$ we  arrive at  
\begin{equation}\label{eq:partialderiv}\frac{d}{dT}f_{\nu}(T)_{|T=0}=d_{\infty,1}(\nu)(x),\end{equation} 
where $x:\Z_p\rightarrow \Z_p$ denotes the moment function $x\mapsto x$. This we can rewrite modulo $p$ as follows
\begin{align}\label{eq:momcongr} d_{\infty,1}(\nu)(x)
&\equiv \sum_{a=0}^{p-1}a\cdot d_{\infty,1}(\nu)\left(\mathbf{1}_{a+p\Z_p}\right)\\
& \equiv\sum_{a=0}^{p-1}a\cdot \nu\left(\mathbf{1}_{(\pi_1)^{-1}\{a\}}\right)\equiv D\nu \modulo p,\end{align}
which yields the desired statement.
\end{proof}
\begin{corollary}\label{cor:kolynonvan} Let $\nu\in \Lambda_R^\mathrm{dig}$ be a horizontal measure. Then:
\begin{enumerate}
    \item $D^0\nu=\nu(\mathbf{1})$ is a $p$-unit if and only if $\mu(f_\nu)=\lambda(f_\nu)=0$.
    \item $D^0\nu=\nu(\mathbf{1})$ is not a $p$-unit and $D\nu$ is a $p$-unit if and only if  $\mu(f_\nu)=0$ and $\lambda(f_\nu)=1$.
\end{enumerate}
\end{corollary}
\begin{proof}
(1) From Proposition \ref{prop:kolyvaginderiv} we conclude $\nu(\mathbf{1})$ is a $p$-unit exactly if $f_\nu(0)$ is a $p$-unit, which is equivalent to $f_\nu$ being invertible as an element of $R\llbracket T \rrbracket $. By Theorem \ref{thm:Weierstrassprep} this is equivalent to $\mu(f_\nu)=\lambda(f_\nu)=0$.

\noindent (2)  To prove the first implication, note that by Proposition \ref{prop:kolyvaginderiv} the assumption that $D\nu$ is a $p$-unit implies that $\frac{d}{dT}f_{\nu}(T)_{|T=0}$ is a $p$-unit. Taking a derivative in Theorem \ref{thm:Weierstrassprep}, we conclude that $\mu(f_\nu)=0$ and $\lambda(f_\nu)\leq 1$. Since $D^0\nu$ is not a $p$-unit we conclude that $\lambda(f_\nu)=1$. The other implication follows easily by a similar argument.
\end{proof}
We note that under the assumptions of  Corollary \ref{cor:kolynonvan}, it holds that $\mu(f_\nu)=\mu(\nu)$ and $\lambda(f_\nu)=\lambda(\nu)$ where $\mu(\nu),\lambda(\nu)$ denotes the \emph{horizontal Iwasawa invariants} of $\nu$ as defined in \cite[Definition 2.15]{KrizNordentoft}. In general, such a relation does not seem to hold.
\subsubsection{Arithmetic instances} In this final section we will explain how to apply Corollary \ref{cor:kolynonvan} to obtain the values of $\mu,\lambda$ as claimed in Remark \ref{rem:Kurihara}. The hypothesis of Corollary \ref{cor:kolynonvan} that $D^r\nu$ is a unit for $r\leq 1$  can be verified in many arithmetic situations via known cases of Kolyvagin's conjecture. We refer to \cite[Section 5.3]{KrizNordentoft} for more details on these and related matters.  \begin{enumerate}
    \item Assume that  $f_1,\ldots, f_m$ are holomorphic newform of even weights $k_i$  such that $p$ is $(f_1,\ldots, f_m)$-good, $L(f_i,k_i/2)\neq 0$ and the normalized $L$-values $L(f_i,k_i/2)/\Omega_{f_i}^+$ are all $p$-units. Note that the last condition holds for $p$ sufficiently large given the non-vanishing condition. Then by definition $\nu(\mathbf{1})$ is a $p$-unit where $\nu$ is the horizontal measure given by the product of the (plus) horizontal $p$-adic $L$-functions attached to $f_1,\ldots,f_m$ (using the joint Taylor--Wiles primes). Thus in this case we conclude from  Corollary \ref{cor:kolynonvan} that $\mu=\lambda=0$ in the asymptotic formula (\ref{eq:widemoment2}).
    \item Let $p > 2$ be an odd prime and let $E/\Q$ be an elliptic curve with positive analytic rank and with good ordinary reduction at $p$ such that $\mathrm{Sel}_{p^{\infty}}(E/\Q)$ has $\Z_p$-corank 1. Then by the main result of \cite{BurungaleCastellaGrossiSkinner} on the cyclotomic Kolyvagin conjecture, one can find a (non-Taylor--Wiles) prime $q_1\equiv 1\modulo p$ such that the congruence (\ref{eq:Kolderiv}) is satisfied. It now follows from a quick calculation (see \cite[Corollary 5.16]{KrizNordentoft}) that $D\nu$ is a $p$-unit  when $\nu$ is the horizontal $p$-adic $L$-function attached to $E$ and a sequence of primes $\ell_1,\ell_2,\ldots $ such that $\ell_1=q_1$ and $\ell_n$ is Taylor--Wiles for $n>1$ (assuming here implicitly that $p$ is $f_E$-good so that the horizontal $p$-adic $L$-function exists). Thus by Corollary \ref{cor:kolynonvan} we conclude that $\mu=0$ and $\lambda=1$ in this case. 
\end{enumerate}
 We conclude in both cases that the $\lambda$-invariant is closely related to the rank of the elliptic curve.  



