\subsubsection{(Un)lacing}\label{sec:unlacing}%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
 In this section we will define a general procedure for interlacing multiple copies of horizontal Iwasawa algebras into a single one. To simplify the exposition we will restrict to the case where $G_n\cong G$ for some fixed finite abelian group $G$. Actually it is more convenient to describe the converse process of {\lq\lq}unlacing{\rq\rq}, which is naturally described by the combinatorial data of \emph{colorings}.
\begin{definition}
Define an \emph{$r$-coloring} to be a map $c:\N\rightarrow \{1,\ldots, r\}$ with infinite fibers. Given an $r$-coloring we denote the fibers by 
$$c^{-1}(\{i\})=\{c_i(1)<c_i(2)<\ldots<c_i(n)<\ldots\},$$ 
for $1\leq i\leq r$.

Define the \emph{standard $r$-coloring} to be the $r$-coloring $c_{\mathrm{std},r}:\N\rightarrow \{1,\ldots, r\}$ defined by the condition 
$$c_{\mathrm{std},r}(n)\equiv n \modulo r.$$ 
\end{definition} 
Such a coloring defines a way to go from from one copy of $G^\N$ to $r$ such copies via the process which we call \emph{unlacing}. 
\begin{definition}[Unlacing]\label{def:unlacing}
Let $1\leq r\leq \infty$ and let $G$ be a finite abelian group. Let $c$ be an $r$-coloring. Define the \emph{$r$-unlacing associated to $(c,G)$} as the bijection 
$$ L_{c,G}:G^\N \rightarrow (G^\N)^r $$ 
given by
$$ (g_n)_{n\in \N} \mapsto (g_{c_i(n)})_{n\in \N,1\leq i\leq r}. $$
When $c=c_{\mathrm{std},r}$ is the standard $r$-coloring we denote the unlacing map simply by $L_{r,G}$. %(One has a similar construction for general sequences $\underline{m}$.)
\end{definition} 
We call the inverse of the isomorphism $L_{c,G}$ the \emph{$r$-lacing associated to $(c,G)$}, although we will not use this map in the remaining discussion. Notice that any $r$-unlacing $L_{c,G}$ can be obtained by precomposing the standard $r$-unlacing with the $S_\infty$-action on $G^\N$. 

\subsection{Kato--Kolyvagin Derivatives}\label{sec:firstdigit}
Consider a sequence of finite abelian groups $(G_n)_{n\in \N}$ such that each $G_n$ admits $\Z/p$ as a quotient. Assume furthermore that the first $r$ groups $G_1,\ldots, G_r$ are cyclic with $G_i=\langle g_i\rangle$ and $h_i=|G_i|$. Let $R$ be the ring of integers of a finite extension of $\Q_p$. 

For an integer $r\geq 0$, we define the \emph{$r^\mathrm{th}$ Kato--Kolyvagin derivative} to be the element
\begin{align}\label{eq:Dr}
 D^r:=\sum_{n_1=1}^{h_1}\cdots \sum_{n_r=1}^{h_r} \left(\prod_{i=1}^r n_i\right)[(g_1^{n_1},\ldots, g_r^{n_r})] \in R[G_1\times \cdots \times G_r].  
 \end{align}
These correspond to Kolyvagin derivatives considered in \cite{WZhang} in the setting of elliptic curves over $\mathbb{Q}$ considered over imaginary quadratic fields. When $r=0$ this is understood to be the element $D^0=[1]\in R[\langle 1\rangle]$. Now given an element of the group algebra $\nu\in R[G_1\times \cdots \times G_r]$ we get, by the duality $\mathrm{Hom}_R(R[G_1 \times \cdots \times G_r],R) \cong R[G_1 \times \cdots \times G_r]$, an associated function which we denote by
 $$\varphi_\nu: G_1\times \cdots \times G_r \rightarrow R. $$
 We define the \emph{$r$-th Kato--Kolyvagin derivative of} $\nu$ to be
 $$D^r(\varphi_\nu)=\nu(\varphi_{D^r})\in R.$$
 The key point is that this interacts very nicely with the (standard) $r$-unlacing map $L_r$ defined in Section \ref{sec:unlacing}. More precisely, as in equation (\ref{eq:rthunlacing}) we obtain an $R$-linear isomorphism 
 $$d^r_1: \Lambda^\mathrm{dig}_{R,1}\cong R\llbracket \Z_p^r\rrbracket,$$
 where $d^r_1=(d_{\infty,1})^r\circ L_{r,\Z/p}$. Given a horizontal measure $\nu\in \Lambda_R^\mathrm{hor}$ and a projection $\rho:\Lambda_R^\mathrm{hor}\rightarrow \Lambda_{R,1}^\mathrm{dig}$ we denote by 
\begin{equation}\label{eq:f_nur}f_{\nu,r}(T_1,\ldots, T_r)\in R\llbracket T_1,\ldots, T_r\rrbracket,\end{equation}
 the $r$-variable power series associated to $d^r_1(\rho(\nu))\in R\llbracket \Z_p^r\rrbracket $ via the Amice transform. We would like to relate Kato--Kolyvagin derivative to the actual derivative of our power series $f_{\nu,r}$. A key observation is that 
 $$\Z/p\hookrightarrow (\Z/p)^\N \xrightarrow{d_{\infty,1}} \Z_p \twoheadrightarrow \Z_p/p\Z_p,$$
 is an isomorphism of groups (where the first inclusion is given by $a\mapsto (a,0,0,\ldots)$). We will need the following $r$ variable consequence for measures.
 \begin{lemma}[The first digit trick]\label{lem:firstdigit}
 Let $g:\Z_p^r\rightarrow \C_p$ be a continuous map which factors through the projection $\Z_p^r\twoheadrightarrow (\Z_p/p\Z_p)^r$. Let $\pi_r$ be the composition $(\Z_p)^r\twoheadrightarrow (\Z_p/p\Z_p)^r \xrightarrow{\sim} (\Z/p)^r$ and write $g=\tilde{g}\circ \pi_r$ with $\tilde{g}\in \Hom_\mathrm{Sets}((\Z/p)^r,\C_p)$. 

 Then for any horizontal measure $\nu\in \Lambda_{R,1}^\mathrm{dig}$, we have
 $$ d^r_1(\nu)(g)=\tilde{\pi}_r(\nu)(\tilde{g}),$$
 where $\tilde{\pi}_r(\nu)$ is the pushforward of $\nu$ under the projection map to the first $r$ factors; 
 $$\tilde{\pi}_r:(\Z/p)^\N \twoheadrightarrow (\Z/p)^r, \quad (a_1,a_2,\ldots)\mapsto (a_1,a_2,\ldots, a_r).$$% where the last map is given by $(a_1,a_2,\ldots)\mapsto (a_1,a_2,\ldots, a_r)$.%%{\color{red} Alternatively one can phrase it in terms of measures $\nu\in R\llbracket(\Z/p)^\N\rrbracket$.}  
 \end{lemma}  
 \begin{proof} This follows directly from the definition of $d^r_1$ as the composition $(d_{\infty,1})^r\circ L_{r,\Z/p}$ (here $d_{\infty,1}$ is the digit map) by recalling that the standard $r$-unlacing map $L_r: (\Z/p)^\N\xrightarrow{\sim} \Z_p^r$ sends 
 $$(a_1,\ldots, a_r,0,0,\ldots)\mapsto (\tilde{a_1},\ldots, \tilde{a_r}),$$
 where $0\leq \tilde{a_i}\leq p-1$ is determined by $\tilde{a_i}\equiv a_i\modulo p$.  
 \end{proof}
 From this we conclude that following consequence for power series. %The following proof might appear harder than it actually is due to formal nature of the result.  
\begin{proposition}\label{prop:kolyvaginderiv}
Let $R$ be the ring of integers of a finite extension of $\Q_p$. Let $\nu\in \Lambda_R^\mathrm{hor}$ be a horizontal measure defined from groups $(G_n)_{n\in \N}$ all admitting $\Z/p$ as a quotient and denote by $f_{\nu,r}(T_1,\ldots, T_r)\in R\llbracket T_1,\ldots, T_r\rrbracket$ the associated $r$-variable power series as in (\ref{eq:f_nur}). For $1\leq i\leq r$ let $G_i=\langle g_i\rangle$ be cyclic of order $h_i$ and denote by $D^r$ the $r^{\mathrm{th}}$ Kato--Kolyvagion derivative (\ref{eq:Dr}). Then we have the following congruence between elements of $R$; 
\begin{align}
\left(\frac{\partial}{\partial T_1}\cdots \frac{ \partial}{ \partial T_r}f_{\nu,r}\right)_{|T_1=\ldots =T_r=0}\equiv \nu(\varphi_{D^r})\modulo p. 
\end{align}
\end{proposition} 
\begin{proof}
By the definition of the Amice transform (see for example \cite[Chapter I.3.1 (1)]{deShalit}) we have
$$f_{\nu,r}(T_1,\ldots, T_r)= \int_{\Z_p^r} (T_1+1)^{x_1}\cdots (T_r+1)^{x_r} \mathrm{d}\, d^r_1(\nu)(x_1,\ldots, x_r).$$
By compactness it follows by the above formula that  
\begin{equation}\label{eq:partialderiv}\left(\frac{\partial}{\partial T_1}\cdots \frac{ \partial}{ \partial T_r}f_{\nu,r}\right)_{|T_1=\ldots =T_r=0}= \int_{\Z_p^r} x_1\cdots x_r\mathrm{d}\, d_r(\nu)(x_1,\ldots, x_r)=d^r_1(\nu)(\mathrm{mom}_r),\end{equation} 
where $\mathrm{mom}_r: \Z_p^r\rightarrow \Z_p$ is the $(1,\ldots,1)$-moment function
$$ (x_1,\ldots, x_r)\mapsto \prod_{i=1}^r x_i.$$
This we can rewrite modulo $p$ as follows
\begin{equation}\label{eq:momcongr} \mathrm{mom}_r(x_1,\ldots, x_r) 
\equiv \sum_{a_1=0}^{p-1}\cdots \sum_{a_r=0}^{p-1} \left(\prod_{i=1}^r a_i\right)\left( \prod_{i=1}^r\mathbf{1}_{a_i+p\Z_p}(x_i)\right)\modulo p.\end{equation}
We denote by $\overline{\mathrm{mom}}_r$ the function on the right-hand side of (\ref{eq:momcongr}).
The maps $\mathbf{1}_{a_i+p\Z_p}$ clearly factor through $\Z_p/p\Z_p\cong \Z/p$ and furthermore, we see that $\overline{\mathrm{mom}}_r=\phi\circ \pi_r$  where
\begin{equation}\label{eq:phi} \phi:=\sum_{a_1\in \Z/p}\cdots\sum_{a_r\in \Z/p} \left(\prod_{i=1}^r \tilde{a}_i\right) \mathbf{1}_{(a_1,\ldots,a_r)}\in \Hom((\Z/p)^r, \Z_p), \end{equation}
and $\pi_r:(\Z_p)^r\twoheadrightarrow (\Z/p)^r$ is defined as in Lemma \ref{lem:firstdigit}. 

Now let $\rho=\varprojlim_{n} \rho_n:\Pi_\infty\twoheadrightarrow (\Z/p)^\N$ be the projection obtained from a compatible system of projections 
$$\rho_n: \prod_{i=1}^nG_i\twoheadrightarrow (\Z/p)^n,\quad n\geq 1,$$
where $\rho_r: \prod_{i=1}^rG_i\twoheadrightarrow (\Z/p)^r$ is defined from the generators $g_1,\ldots, g_r$. Then we conclude by Lemma \ref{lem:firstdigit} applied to $\rho(\nu)\in \Lambda_{R,1}^{\mathrm{dig}}$ that 
\begin{equation}\label{eq:firstcongruence} d^r_1(\rho(\nu))(\mathrm{mom}_r)\equiv d^r_1(\rho(\nu))(\overline{\mathrm{mom}}_r)\equiv \rho_r (\nu) (\phi)\modulo p, \end{equation}
since $\tilde{\pi}_r\circ \rho=\rho_r$ (with $\tilde{\pi}_r:(\Z/p)^\N\twoheadrightarrow (\Z/p)^r$ as in Lemma \ref{lem:firstdigit}). 
On the other hand we see that  
\begin{equation}\label{eq:Drmodp}D^r\equiv \sum_{(a_i)_i\in (\Z/p)^r} \left(\prod_{i=1}^r a_i\right)\sum_{\substack{1\leq n_1\leq h_1\\ n_1\equiv a_1\modulo p}}\cdots \sum_{\substack{1\leq n_r\leq h_1\\ n_r\equiv a_r\modulo p}} [(g_1^{n_1},\ldots, g_r^{n_r})]\mod p. \end{equation}
The right-hand side above is exactly the pullback under $\rho_r$ of the measure
\begin{equation}\label{eq:phiM} \mu:=\sum_{a_1\in \Z/p}\cdots\sum_{a_r\in \Z/p} \left(\prod_{i=1}^r \tilde{a}_i\right) [(a_i)_i]\in R[(\Z/p)^r], \end{equation}
which satisfies that the associated map $\varphi_\mu\in \Hom((\Z/p)^r,R)$ is equal to $\phi$ defined in (\ref{eq:phi}). Note that for any group homomorphism $\rho:G \rightarrow H$ and $\nu_1\in R[G],\nu_2\in R[H]$, we have
$$ \nu_1(\varphi_{\rho_\ast( \nu_2)})=\sum_{g\in G} \nu_1(\mathbf{1}_g)\nu_2(\mathbf{1}_{\rho(g)})=\sum_{h\in H} \nu_2(\mathbf{1}_h)\sum_{g\in \rho^{-1}(\{h\})} \nu_1(\mathbf{1}_g)= \rho(\nu_1)(\varphi_{\nu_2}).$$
Thus we conclude that 
$$  \nu(\varphi_{D^r})\equiv \nu(\varphi_{(\rho_r)_\ast(\mu)})\equiv \rho_r(\nu)(\phi)\mod p, $$
%$$  \nu(\varphi_{D^r})\equiv D^r (\varphi_{\rho_r(\nu)})\equiv (\rho_r)_\ast (\mu)(\varphi_{\rho_r(\nu)})\equiv  \nu_r((\rho_r)_\ast \varphi_{\mu})\equiv \rho_r(\nu)(\phi)\mod p, $$
which combined with (\ref{eq:firstcongruence}) and (\ref{eq:partialderiv}) yields the desired congruence.
\end{proof}  
By the above result, the Kato--Kolyvagin derivative gives a powerful way of controlling the zeroes of the specializations of the multivariable power series. 
\begin{corollary}\label{prop:kolyvagin}
Keep the setting and notation from Proposition \ref{prop:kolyvaginderiv}. Then the power series 
\begin{equation}\label{eq:PIE}\sum_{I\subset \{1,\ldots,r\}} (-1)^{|I|} (f_{\nu,r})_{|T_i=0,i\in I, T_i=T,i\notin I}\in R\llbracket T\rrbracket ,\end{equation}
is of the form $aT^r+T^{r+1}R\llbracket T\rrbracket$ where 
$$a\equiv \nu(\varphi_{D^r}) \modulo p.$$

In particular, if  $\nu(\varphi_{D^r})\not\equiv 0\modulo p$ then the power series (\ref{eq:PIE}) lies in $T^rR\llbracket T\rrbracket^\times$, and furthermore there exists a strict subset $I\subset \{1,\ldots,r\}$ such that the power series 
$$(f_{\nu,r})_{|T_i=0,i\in I, T_i=T,i\notin I}\in R\llbracket T\rrbracket,$$ 
has at most $r$ zeroes (counted with multiplicity). 
\end{corollary}
\begin{proof}
Write 
$$ f_{\nu,r}(T_1,\ldots, T_r)=\sum_{k_1,\ldots, k_r\geq 0} a_{k_1,\ldots, k_r}T_1^{k_1}\cdots T^{k_r}.$$
By the principle of inclusion-exclusion we see that the coefficient of $T^j$ for $0\leq j \leq r$ of the power series  
$$ \sum_{I\subset \{1,\ldots,r\}} (-1)^{|I|} (f_{\nu,r})_{|T_i=0,i\in I, T_i=T,i\notin I},$$
is exactly 
$$\sum_{k_1+\ldots +k_r=j} a_{k_1,\ldots, k_r}\sum_{ I\subset \{i: k_i= 0\} }(-1)^{|I|}= \begin{cases} 0,& j\neq r\\
 a_{1,1,\ldots, 1},& j=r\end{cases}. $$
From this we conclude the desired conclusion by Corollary \ref{prop:kolyvagin}.

If we furthermore assume that the  Kato--Kolyvagin derivative is non-vanishing modulo $p$ we conclude that $a_{1,1,\ldots, 1}\in R^\times$ as desired. To see the last claim, recall that the $\lambda$-invariant of a power series with in one variable with $\mu=0$ (i.e. the number of zeroes counting with multiplicity) is exactly the minimal $n\geq 0$ such the coefficient of $T^n$ is a unit in $R$. Thus we get the desired conclusion from the above (since the contribution from $I=\{1,\ldots, r\}$ in the sum above is just a constant). 
\end{proof}
In particular, we can give an explicit bound on the set $I$ appearing in Theorem \ref{thm:nonvanishingPS} and Corollary \ref{cor:nonvanishingPS}.
\begin{corollary}\label{cor:kolynonvan}
Let $p$ be a prime and $r\geq 1$. Let $R$ be the ring of integers of a finite extension of $\Q_p$. Let $\nu\in \Lambda_{R}^\mathrm{hor}$ be a measure in the horizontal Iwasawa algebra defined from a sequence of finite abelian groups $(G_n)_{n\in \N}$ such that $G_1,\ldots, G_r$ are cyclic. Let $D^r$ denote the Kato--Kolyvagin derivative as in (\ref{eq:Dr}) and assume that $\nu(\varphi_{D^r})\not\equiv 0 \modulo p$. Then there exists a character $\chi_r:\prod_{i=1}^rG_i\rightarrow \C_p^\times$ of order dividing $p$ such that 
\begin{equation}\label{eq:chir}v_p(\nu(\chi_r))\leq \frac{r}{p-1}.\end{equation}
If furthermore $r\leq p-2$ holds. Then for any continuous character $\chi:\prod_{n\in \N\setminus \{1\}}G_n\rightarrow \C_p^\times$  of order $p$ we have that
\begin{equation}\label{eq:chirchi}v_p(\nu(\chi_r\chi))\leq \frac{r}{p-1}.\end{equation}
In particular, in this case we can pick $e=\tfrac{r}{p-1}$ and $I\subset \{1,\ldots, r\}$ in Corollary \ref{cor:nonvanishingPS}.%viewed as aone can pick $I=\{1\}$ in Theorem 
\end{corollary}
\begin{proof}
Denote by $f_{\nu,r}^\mathrm{PIE}(T)\in T^r R\llbracket T\rrbracket^\times$ the one-variable power series associated to $f_{\nu,r}(T_1,\ldots, T_r)$ as defined in equation (\ref{eq:PIE}). Then by the assumption of the Kato--Kolyvagin derivative we have for $\zeta\in \mu_p^\ast$ that 
$$ v_p(f_{\nu,r}^\mathrm{PIE}(\zeta-1))=\frac{r}{p-1}.$$
Thus by applying Corollary \ref{prop:firstmomentrvar} (see also Remark \ref{rem:intermsof}) to each summand of (\ref{eq:PIE}) we see that there exists a character $\chi_r:\prod_{i=1}^r G_i\rightarrow \C_p^\times$ of order dividing $p$ such that 
$$v_p(\nu(\chi_r))\leq \frac{r}{p-1},$$
using an argument as in (\ref{eq:boundingpval}). 

Now if $\tfrac{r}{p-1}<1$ we apply Theorem \ref{thm:nonvanishingPS} with $m=1$ to the specialization $\nu_{\chi_r}$ (as defined in equation (\ref{eq:specialization})). Clearly we have $n_{\nu_{\chi_r}}=1$ and thus we get the desired conclusion from the last part of Theorem \ref{thm:nonvanishingPS}.  
\end{proof}

\subsubsection{Hidden actions on the Iwasawa algebra}\label{sec:hidden}
Note that there is a choice of projection $G_n\twoheadrightarrow \Z/p^{m_n}$ to be made corresponding to the choice of generator of $\Z/p^{m_n}$. The choice of $\rho$ will give rise to a different digit construction and in fact one could incorporate this choice into the definition of the digit map.  This choice can be encoded by the natural action of $\prod_{n\in \N} (\Z/p^{m_n})^\times$ on $\Pi_{\underline{m}}$ given by $(a_i)_i.(b_i)_i=(b_i^{a_i})_i$. This induces an action on the set of all projections;
$$\mathcal{P}_{\underline{m}}=\{\rho: G_\N\twoheadrightarrow \Pi_{\underline{m}}\},$$
which is free and transitive. This means that for each sequence $\underline{m}$ we get a ``hidden'' ($\Z_p$-module) action of $\prod_{n\in \N} (\Z/p^{m_n})^\times$ on the Iwasawa algebra $R\llbracket \Z_p\rrbracket$. For $a=(a_n)_{n\in \N}\in \prod_{n\in \N}(\Z/p^{m_n})^\times$ this is explicitly given by 
$$ \Z_p\xrightarrow{(d_{\infty,\underline{m}})^{-1}}\Pi_{\underline{m}} \xrightarrow{a} \Pi_{\underline{m}} \xrightarrow{d_{\infty,\underline{m}}} \Z_p. $$  
%\subsubsection{The $S_\infty$-action on the digit group}
%Furthermore, we define the \emph{($p^m$-adic) digit algebra} to be; 
%$$\Z_p\llbracket (\Z/p^m)^\N\rrbracket,$$
%which is really the central object of study in the horizontal setting.
Now assume that $m_n=m$ for all $n\in \N$. Then by combining the $S_\infty$-action with the digit construction above we obtain for each $m$ a ``hidden'' $S_\infty$-action of $R$-module automorphisms on the Iwasawa algebra $R\llbracket T\rrbracket$. Explicitly, for $\sigma:\N\rightarrow \N$ this is induced by the homeomorphism of profinite sets  
$$ \Z_p\xrightarrow{(d_{\infty,m})^{-1}}(\Z/p^m)^\N \xrightarrow{\sigma} (\Z/p^m)^\N\xrightarrow{d_{\infty,m}} \Z_p. $$
It is easily seen that the $S_\infty$-action commutes with the one of $\mathcal{P}_m$ (corresponding to the choice of projection $\rho$). Thus we obtain for each $m$ an action of the big group $S_\infty\times ((\Z/p^m)^\times)^\N$ on the Iwasawa algebra $R\llbracket \Z_p\rrbracket$. This action encodes all the choices in the construction.

Finally, by combining the (un)-lacing construction with the digit map we obtain by the composition $(d_{\infty,m})^r\circ L_{r,\Z/p^m} $ a homeomorphism of profinite sets;  
$$  (\Z/p^m)^\N\xrightarrow{L_{r,\Z/p^m}} ((\Z/p^m)^\N)^r \xrightarrow{(d_{\infty,m})^r} \Z_p^r,$$
where $(d_{\infty,m})^r$ means applying the digit map of order $m$ to each of the $r$ copies of the $p^m$-th digit group $(\Z/p^m)^\N$ and $L_{r,\Z/p^m}$ denotes the standard $r$-unlacing map as in Definition \ref{def:unlacing}. We call the induced $R$-module isomorphism \begin{equation}\label{eq:rthunlacing}\Lambda_{R,m}^\mathrm{dig} \cong_R R\llbracket\Z_p^r\rrbracket, \end{equation} 
the \emph{$r$-unlaced $p^m$-adic digit map}. Finally, by combining the (standard) $r$-unlacing procedure with the digit construction we obtain a  homeomorphism of profinite sets;
$$ \Z_p^r\xrightarrow{((d_{\infty,m})^{-1})^{r}} ((\Z/p^m)^\N)^r\xrightarrow{(L_{r,\Z/p^m})^{-1}} (\Z/p^m)^\N \xrightarrow{d_{\infty,m}} \Z_p.$$
For $R\subset \C_p$ a $p$-adically complete $\Z_p$-algebra, we obtain by the Amice transform an isomorphism of $R$-modules, %\tilde{L}_{r,m}
$$ R\llbracket T_1,\ldots, T_r\rrbracket\xrightarrow{\sim} R\llbracket T\rrbracket,$$     
which we call the \emph{$p^m$-adic $r$-lacing map}. This provides a new way of turning a multivariable power series into a single variable one.%This is an example of a hidden $R$-module isomorphism of power series algebras (another example being the action of $S_\infty\times ((\Z/p^m)^\times)^\N$ on $R\llbracket T\rrbracket$ mentioned above).   

