 \subsection{The First Digit Trick}The main result of this section is the following lemma, which establishes a relation between the evaluation of an element $\nu$ of the digit algebra at a test function $g$ and the evaluation of the image of $\nu$\todo{a bit unfortunate notation} under the digit map $d_{\infty,1}$ (Definition \ref{def:digitgen}) at a related test function $\tilde{g}$.

 \begin{lemma}[The first digit trick]\label{lem:firstdigit}
 Let $g:\Z_p\rightarrow \C_p$ be a map which factors through the projection $\Z_p\twoheadrightarrow \Z_p/p\Z_p$. Let $\pi_1$ be the composition $\Z_p\twoheadrightarrow \Z_p/p\Z_p \xrightarrow{\sim} \Z/p$ and write $g=\tilde{g}\circ \pi_1$ with $\tilde{g}\in \Hom_\mathrm{Sets}(\Z/p,\C_p)$. 

 Then for any horizontal measure $\nu\in \Lambda_{R,1}^\mathrm{dig}$, we have
 $$ d_{\infty,1}(\nu)(g)=\tilde{\pi}_1(\nu)(\tilde{g}),$$
 where $\tilde{\pi}_1(\nu)$ is the pushforward of $\nu$ under the projection map onto the first factor; 
 $$\tilde{\pi}_1:(\Z/p)^\N \twoheadrightarrow \Z/p, \quad (a_1,a_2,\ldots)\mapsto a_1.$$% where the last map is given by $(a_1,a_2,\ldots)\mapsto (a_1,a_2,\ldots, a_r)$.%%{\color{red} Alternatively one can phrase it in terms of measures $\nu\in R\llbracket(\Z/p)^\N\rrbracket$.}  
 \end{lemma}  
 \begin{proof} This follows immediately from the definition of $d_{\infty,1}$ (Definition \ref{def:digitgen}; recall our abbreviated notation $d_{\infty,1}$ as explained in the discussion below loc. cit.). 
 \end{proof}

Applying the previous Lemma to the test function $g = \varphi_{D}$ from (\ref{eq:Dr}) (for $r = 1$), we conclude the following consequence for the power series associated to $d_{\infty,1}(\nu)$ by the Amice transform (Theorem \ref{thm:Amice}). %The following proof might appear harder than it actually is due to formal nature of the result.  
\begin{proposition}\label{prop:kolyvaginderiv}
Let $R$ be the ring of integers of a finite extension of $\Q_p$. Let $\nu\in \Lambda_R^\mathrm{hor}$ be a horizontal measure defined from groups $(G_n)_{n\in \N}$ all admitting $\Z/p$ as a quotient and denote by $f_{\nu}(T)\in R\llbracket T\rrbracket$ the associated power series obtained by applying the Amice transform to $d_{\infty,1}(\mu) \in R\llbracket \Z_p\rrbracket$. Let $G_1=\langle g_1\rangle$ be cyclic of order $h_1$ and denote by $D$ the first Kato--Kolyvagion derivative (\ref{eq:Dr}). Then we have the following congruence between elements of $R$; 
\begin{equation}\label{eq:derivativecong}
\frac{d}{dT}f_{\nu}(T)_{|T=0}\equiv \nu(\varphi_{D})\modulo p. 
\end{equation}
\end{proposition} 
\begin{proof}
By the definition of the Amice transform (see for example \cite[Chapter I.3.1 (1)]{deShalit}) we have
$$f_{\nu}(T)= \int_{\Z_p} (T+1)^{x} \mathrm{d}\nu(x).$$
By compactness of $\Z_p$ we are allowed to differentiate under the integral sign and it follows from the above formula that  
\begin{equation}\label{eq:partialderiv}\frac{d}{dT}f_{\nu}(T)_{|T=0}= \int_{\Z_p} x\mathrm{d}\, d_{\infty,1}(\nu)(x)=d_{\infty,1}(\nu)(\mathrm{mom}_1),\end{equation} 
where $\mathrm{mom}_1: \Z_p\rightarrow \Z_p$ is the $1$-moment function
$$ x\mapsto x.$$
This we can rewrite modulo $p$ as follows
\begin{equation}\label{eq:momcongr} \mathrm{mom}(x)
\equiv \sum_{a=0}^{p-1}a\mathbf{1}_{a+p\Z_p}(x)\modulo p.\end{equation}
We denote by $\overline{\mathrm{mom}}_1$ the function on the right-hand side of (\ref{eq:momcongr}).
The maps $\mathbf{1}_{a+p\Z_p}$ clearly factor through $\Z_p/p\Z_p\cong \Z/p$ and furthermore, we see that $\overline{\mathrm{mom}}_1=\phi\circ \pi_1$  where
\begin{equation}\label{eq:phi} \phi:=\sum_{a\in \Z/p} \tilde{a}\mathbf{1}_{a}\in \Hom(\Z/p, \Z_p), \end{equation}
$0 \le \tilde{a} \le p-1$ denotes the unique integer reducing to $a$ modulo $p$ and $\pi_1:\Z_p\twoheadrightarrow \Z/p$ is the canonical projection (as in Lemma \ref{lem:firstdigit}). 

Now let $\rho=\varprojlim_{n} \rho_n:\Pi_\infty\twoheadrightarrow (\Z/p)^\N$ be the projection obtained from a compatible system of projections 
$$\rho_n: \prod_{i=1}^nG_i\twoheadrightarrow (\Z/p)^n,\quad n\geq 1,$$
where $\rho: G_1\twoheadrightarrow \Z/p$ is defined by $\rho(g_1) = 1 \modulo p$. Then we conclude by Lemma \ref{lem:firstdigit} applied to $\rho(\nu)\in \Lambda_{R,1}^{\mathrm{dig}}$ that 
\begin{equation}\label{eq:firstcongruence} d_{\infty,1}(\rho(\nu))(\mathrm{mom}_1)\equiv d_{\infty,1}(\rho(\nu))(\overline{\mathrm{mom}}_1)\equiv \rho(\nu) (\phi)\modulo p, \end{equation}
since $\tilde{\pi}_1\circ \rho$ (with $\tilde{\pi}_1:(\Z/p)^\N\twoheadrightarrow \Z/p$ as in Lemma \ref{lem:firstdigit}). 
On the other hand we see that  
\begin{equation}\label{eq:Drmodp}D\equiv \sum_{a\in \Z/p} a\sum_{\substack{1\leq n\leq h_1\\ n\equiv a\modulo p}}[g_1^n]\mod p. \end{equation}
The right-hand side above is exactly the pullback under $\rho$ of the measure
\begin{equation}\label{eq:phiM} \mu:=\sum_{a\in \Z/p}\tilde{a} [a]\in R[\Z/p], \end{equation}
which satisfies that the associated map $\varphi_\mu\in \Hom(\Z/p,R)$ is equal to $\phi$ defined in (\ref{eq:phi}). Note that for any group homomorphism $\rho:G \rightarrow H$ and $\nu_1\in R[G],\nu_2\in R[H]$, we have
$$ \nu_1(\varphi_{\rho_\ast( \nu_2)})=\sum_{g\in G} \nu_1(\mathbf{1}_g)\nu_2(\mathbf{1}_{\rho(g)})=\sum_{h\in H} \nu_2(\mathbf{1}_h)\sum_{g\in \rho^{-1}(\{h\})} \nu_1(\mathbf{1}_g)= \rho(\nu_1)(\varphi_{\nu_2}).$$
Thus we conclude that 
$$  \nu(\varphi_D)\equiv \nu(\varphi_{\rho_\ast(\mu)})\equiv \rho(\nu)(\phi)\mod p, $$
%$$  \nu(\varphi_{D^r})\equiv D^r (\varphi_{\rho_r(\nu)})\equiv (\rho_r)_\ast (\mu)(\varphi_{\rho_r(\nu)})\equiv  \nu_r((\rho_r)_\ast \varphi_{\mu})\equiv \rho_r(\nu)(\phi)\mod p, $$
which combined with (\ref{eq:firstcongruence}) and (\ref{eq:partialderiv}) yields the desired congruence.
\end{proof}  
