\noindent From the visual representation, it is clear that $Q$ is neither identical nor the reflection of $P$. We assign the odd vertices of $P$ the partial correlation $k_{11}$ and the even vertices of $P$ the partial correlation $k_{22}$. By the color constraints specified in the theorem, the concentration matrices $K_P = (p_{ij})$ and $K_Q = (q_{ij})$ meet the following conditions:
    \begin{align*}
        p_{ii} & = k_{11} \text{ and } q_{ii} = k_{22}, \quad \text{if } i \in \{1,2, \dots, m\} \text{ is odd},\\
        p_{ii} & = k_{22} \text{ and } q_{ii} = k_{11}, \quad \text{if } i \in \{1,2, \dots, m\} \text{ is even},\\
        p_{ij} &= q_{ij} = k_{ij}, \qquad \qquad \ \text{for all } \{p_i,p_j\} \in E_P \text{ and } \{q_i,q_j\} \in E_Q.
    \end{align*}
    \noindent The concentration matrices of $P$ and $Q$ are then given by:
    \[
     K_P = \begin{pmatrix}
        k_{11} & k_{12} & 0 & \cdots & 0 \\
        k_{12} & k_{22} & k_{23} & \ddots & \vdots \\
        0 & k_{23} & k_{11} & \ddots & 0 \\
        \vdots & \ddots & \ddots & \ddots & k_{m-1m} \\
        0 & \cdots & 0 & k_{m-1m} & k_{22}
    \end{pmatrix},
    \hspace{1cm}
    K_Q = \begin{pmatrix}
        k_{22} & k_{12} & 0 & \cdots & 0 \\
        k_{12} & k_{11} & k_{23} & \ddots & \vdots \\
        0 & k_{23} & k_{22} & \ddots & 0 \\
        \vdots & \ddots & \ddots & \ddots & k_{m-1m} \\
        0 & \cdots & 0 & k_{m-1m} & k_{11}
    \end{pmatrix}.
    \]

    \noindent To calculate the determinants of $K_P$ and $K_Q$, we apply the well-known Leibniz formula:
    \[
        \operatorname{det}(K_P)  
        = \sum_{\tau \in \mathbb{S}^m} \operatorname{sgn}(\tau) \prod_{i=1}^m p_{i \tau(i)}, 
        \qquad \quad
        \operatorname{det}(K_Q)  
        = \sum_{\tau \in \mathbb{S}^m} \operatorname{sgn}(\tau) \prod_{i=1}^m q_{i \tau(i)}.
    \]
    For the tridiagonal matrices $K_P$ and $K_Q$, any permutation $\tau$ where $\tau(i)$ maps $i$ to an index not adjacent to $i$ results in a product term that is zero, since the corresponding matrix entries $p_{i \tau(i)}$ and  $q_{i \tau(i)}$ are zero for non-adjacent indices. Consequently, only permutations that are either the identity or disjoint compositions of 2-cycles, which permute adjacent indices, contribute to the determinant. Let $\mathcal{T} \subseteq \mathbb{S}^m$ denote the set of such permutations. Then:
    \[
        \operatorname{det}(K_P)  
        = \sum_{\tau \in \mathcal{T}} \operatorname{sgn}(\tau) \prod_{i=1}^m p_{i \tau(i)},
        \qquad \quad
        \operatorname{det}(K_Q)  
        = \sum_{\tau \in \mathcal{T}} \operatorname{sgn}(\tau) \prod_{i=1}^m q_{i \tau(i)}.
    \]
    The products in these formulas can be decomposed into two components: the product of variables corresponding to indices permuted under the permutation $\tau$, and the product of variables corresponding to indices fixed by $\tau$:
    \[
        \operatorname{det}(K_P)  
        = \sum_{\tau \in \mathcal{T}} \operatorname{sgn}(\tau) \prod_{\substack{i=1, \\ \tau(i) \neq i}}^m p_{i \tau(i)} \prod_{\substack{i=1, \\ \tau(i) = i}}^m p_{i \tau(i)},
        \qquad \quad
        \operatorname{det}(K_Q)  
        = \sum_{\tau \in \mathcal{T}} \operatorname{sgn}(\tau) \prod_{\substack{i=1, \\ \tau(i) \neq i}}^m q_{i \tau(i)} \prod_{\substack{i=1, \\ \tau(i) = i}}^m q_{i \tau(i)}.
    \]
    Let $t_{\tau} \in \{0,1, \dots, \frac{m}{2}\}$ denote the number of 2-cycles within the permutation $\tau \in \mathcal{T}$.
    The first product in $\operatorname{det}(K_P)$ corresponds to the off-diagonal entries of $K_P$. Any $\tau \in \mathcal{T}$ permutes an even amount of $2 t_{\tau}$ off-diagonal entries, which are equal in $K_P$ and $K_Q$. 
    Since $m$ is even, $\tau$ fixes an even amount of diagonal entries. 
    Specifically, $\tau$ fixes $\frac{m}{2} - t_{\tau}$ diagonal entries corresponding to even indices $i$, and $\frac{m}{2} - t_{\tau}$ diagonal entries corresponding to odd indices $i$. Thus, the second product in the determinant formula includes $\frac{m}{2} - t_{\tau}$ factors of $k_{11}$ and $\frac{m}{2} - t_{\tau}$ factors of $k_{22}$.
    %and $t$ off-diagonal squared factors  
    Thus, the determinant of $K_P$ simplifies as:
    \[
        \operatorname{det}(K_P)  
        = \sum_{\tau \in \mathcal{T}} \operatorname{sgn}(\tau) \ k_{11}^{\frac{m}{2}-t_{\tau}} \ k_{22}^{\frac{m}{2}-t_{\tau}} \prod_{\substack{i=1, \\ \tau(i) \neq i}}^m k_{i \tau(i)}.
    \]
    Similarly, for $K_Q$, the fixed diagonal entries contribute $\frac{m}{2} - t_{\tau}$ factors of $k_{22}$ and $\frac{m}{2} - t_{\tau}$ factors of $k_{11}$ for each $\tau \in \mathcal{T}$, giving us:
    \[
        \operatorname{det}(K_Q)  
        = \sum_{\tau \in \mathcal{T}} \operatorname{sgn}(\tau) \ k_{22}^{\frac{m}{2}-t_{\tau}} \ k_{11}^{\frac{m}{2}-t_{\tau}} \prod_{\substack{i=1, \\ \tau(i) \neq i}}^m k_{i \tau(i)}.
    \]
    Hence, we can conclude that $\det(K_P)=\det(K_Q)$.
\end{proof}

