\begin{theorem}
\label{theorem:PathDetTypeOdd}
Let $P$ and $Q$ be two colored paths on $m$ vertices with vertex sets $V_P = \{p_1, p_2, \dots, p_m\}$ and $V_Q = \{q_1, q_2, \dots, q_m\}$, and edge sets \(E_P = \{ \{p_i,p_{i+1}\} \mid i \in \{1,2, \dots, m-1\} \}\) and \(E_Q = \{ \{q_i,q_{i+1}\} \mid i, \in \{1,2, \dots, m-1\} \}\), respectively. Let $m$ be odd and the coloring of $P$ and $Q$ satisfy the following conditions:
\begin{enumerate}
\item $\lambda(p_1)=\lambda(p_{2n+1})= \lambda(q_1)=\lambda(q_{2n+1})$ for every $n\in \{1,2,\ldots, (m-1)/2\}$, 
\item $\lambda(p_{2n})=\lambda(q_{2n})$ for every $n\in \{1,2,\ldots,(m-1)/2\}$,
\item $\lambda(\{p_i,p_{i+1}\}) = \lambda(\{q_{j},q_{j+1}\})$ and $\lambda(\{p_j,p_{j+1}\}) = \lambda(\{q_{i},q_{i+1}\})$, for all odd $i \in \{1,2, \dots, m\}$ and all even $j \in \{1,2, \dots, m\}$.
\end{enumerate}
Then, $\operatorname{det}(K_P) = \operatorname{det}(K_Q)$ even though $Q$ is neither identical nor the reflection of $P$ for $m>3$.
\end{theorem}
\begin{proof} 
    The paths have the following structure:
    \begin{center}
    P: $\quad$
