        \node[draw, circle, fill=yellow] (n-2) at (10, 0) {};
        \node[draw, circle, fill=red] (n-1) at (12, 0) {};
        \node[draw, circle, fill=yellow] (n) at (14, 0) {};

        \draw[blue, thick] (1) -- (2);
        \draw[green, thick] (2) -- (3);
        \draw[blue, thick] (3) -- (4);
        \draw[green, thick] (4) -- (5);
        \draw[black, thick, dashed] (5) -- (n-2);
        \draw[blue, thick] (n-2) -- (n-1);
        \draw[green, thick] (n-1) -- (n);

        \node at (0,0.5) {$p_1$};
        \node at (2,0.5) {$p_2$};
        \node at (4,0.5) {$p_3$};
        \node at (6,0.5) {$p_{4}$};
        \node at (8,0.5) {$p_{5}$};
        \node at (10,0.5) {$p_{m-2}$};
        \node at (12,0.5) {$p_{m-1}$};
        \node at (14,0.5) {$p_m$};

    \end{tikzpicture}

    \vspace{0.5cm}

    Q: $\quad$
    \begin{tikzpicture}[scale=1]
        \node[draw, circle, fill=yellow] (1) at (0, 0) {};
        \node[draw, circle, fill=orange] (2) at (2, 0) {};
        \node[draw, circle, fill=yellow] (3) at (4, 0) {};
        \node[draw, circle, fill=magenta] (4) at (6, 0) {};
        \node[draw, circle, fill=yellow] (5) at (8, 0) {};
        \node[draw, circle, fill=yellow] (n-2) at (10, 0) {};
        \node[draw, circle, fill=red] (n-1) at (12, 0) {};
        \node[draw, circle, fill=yellow] (n) at (14, 0) {};

        \draw[green, thick] (1) -- (2);
        \draw[blue, thick] (2) -- (3);
        \draw[green, thick] (3) -- (4);
        \draw[blue, thick] (4) -- (5);
        \draw[black, thick, dashed] (5) -- (n-2);
        \draw[green, thick] (n-2) -- (n-1);
        \draw[blue, thick] (n-1) -- (n);

        \node at (0,0.5) {$q_1$};
        \node at (2,0.5) {$q_2$};
        \node at (4,0.5) {$q_3$};
        \node at (6,0.5) {$q_{4}$};
        \node at (8,0.5) {$q_{5}$};
        \node at (10,0.5) {$q_{m-2}$};
        \node at (12,0.5) {$q_{m-1}$};
        \node at (14,0.5) {$q_m$};
