    \end{center}
    By the color constraints specified in the theorem, the concentration matrices $K_P = (p_{ij})$ and $K_Q = (q_{ij})$ meet the following conditions:
    \begin{align*}
        p_{ii} & = q_{ii} = k_{ii}, \qquad \ \qquad \qquad \text{for all even } i \in \{1,2, \dots, m\},\\
        p_{ii} & = p_{jj} = q_{ii} = q_{jj} = k_{11}, \quad \text{for all odd } i,j \in \{1,2, \dots, m\},\\
        p_{ii+1} &= q_{i+1i+2} = k_{12}, \qquad \qquad \ \text{for all odd } i \in \{1,2, \dots, m-2\},\\
        p_{ii+1} &= q_{i+1i+2} = k_{23}, \qquad \qquad \ \text{for all even } i \in \{1,2, \dots, m-1\} \operatorname{mod} m-1.
    \end{align*}
    \noindent The concentration matrices of $P$ and $Q$ are therefore given by:
    \[
     K_P = \begin{pmatrix}
        k_{11} & k_{12} & 0 & 0& \cdots & \cdots & 0 \\
        k_{12} & k_{22} & k_{23} & 0 & \cdots & \cdots & \vdots \\
        0 & k_{23} & k_{11} & k_{12} & 0 & \cdots & 0 \\
        0 & 0 & k_{12} & k_{44} & k_{23} & \cdots & 0 \\        
        \vdots & \ddots & \ddots & \ddots & \ddots &  \ddots & \vdots \\
        \vdots & \ddots & \ddots & \ddots & \ddots &  \ddots & k_{23} \\
        0 & \cdots & \cdots & \cdots & 0 & k_{23} & k_{11}
    \end{pmatrix},
    \hspace{1cm}
    K_Q = \begin{pmatrix}
        k_{11} & k_{23} & 0 & 0& \cdots & \cdots & 0 \\
        k_{23} & k_{22} & k_{12} & 0 & \cdots & \cdots & \vdots \\
        0 & k_{12} & k_{11} & k_{23} & 0 & \cdots & 0 \\
        0 & 0 & k_{23} & k_{44} & k_{12} & \cdots & 0 \\        
        \vdots & \ddots & \ddots & \ddots & \ddots &  \ddots & \vdots \\
        \vdots & \ddots & \ddots & \ddots & \ddots &  \ddots & k_{12} \\
        0 & \cdots & \cdots & \cdots & 0 & k_{12} & k_{11}
    \end{pmatrix}.
    \]
We prove this theorem by applying induction on $m$, the number of vertices in $P$ and $Q$. For $m=3$, observe that $Q$ is actually the reflection of $P$, and thus we know that $\det(K_P)=\det(K_Q)$. Similarly, for $m=5$, we get the matrices $K_P$ and $K_Q$ as follows:
\[ K_P =
    \left(
    \begin{NiceMatrix}[create-large-nodes]
    k_{11} & k_{12} & 0      & 0      & 0 \\
    k_{12} & k_{22} & k_{23} & 0      & 0 \\
    0      & k_{23} & k_{11} & k_{12} & 0 \\
    0      & 0      & k_{12} & k_{44} & k_{23} \\
    0      & 0      & 0      & k_{23} & k_{11}
    \CodeAfter
      \tikz {
        \draw[black, thick] (1-1.north west) rectangle (3-3.south east);
        \node at ($(1-1.north west) + (1.15,0.25)$) {\textbf{$K_{P-2}$}};
      }
    \end{NiceMatrix}
    \right),
    \hspace{1cm}
     K_Q =
    \left(
    \begin{NiceMatrix}[create-large-nodes]
    k_{11} & k_{23} & 0      & 0      & 0 \\
    k_{23} & k_{22} & k_{12} & 0      & 0 \\
    0      & k_{12} & k_{11} & k_{23} & 0 \\
    0      & 0      & k_{23} & k_{44} & k_{12} \\
    0      & 0      & 0      & k_{12} & k_{11}
    \CodeAfter
      \tikz {
        \draw[black, thick] (1-1.north west) rectangle (3-3.south east);
        \node at ($(1-1.north west) + (1.15,0.25)$) {\textbf{$K_{Q-2}$}};
      }
    \end{NiceMatrix}
    \right).
    \]
We state the matrices for $m=5$ for the purpose of clarity. The idea here is to expand the determinant through the last row and write the expression in terms of the determinants of $K_{P-2}$ and $K_{P-4}$, where $P-2$ and $P-4$ are the colored subpaths of $P$ induced on the first $m-2$ and $m-4$ vertices, respectively. For $m=5$, the determinants of $K_P$ and $K_Q$ can be written as:
\begin{eqnarray*}
\det(K_P) 
    &=& k_{23}^2 \operatorname{det}(K_{P-2}) - k_{11} k_{44} \operatorname{det}(K_{P-2}) + k_{11} k_{12}^2 \operatorname{det} 
    \begin{pmatrix}
        k_{11} & k_{12} \\
        k_{12} & k_{22} \\ 
    \end{pmatrix}, \text{ and} \\
   \det(K_Q) &=& k_{12}^2 \operatorname{det}(K_{Q-2}) - k_{11} k_{44} \operatorname{det}(K_{Q-2}) + k_{11} k_{23}^2 \operatorname{det} 
    \begin{pmatrix}
        k_{11} & k_{23} \\
        k_{23} & k_{22} \\
    \end{pmatrix}. 
    \end{eqnarray*}
As $\det(K_{P-2})=\det(K_{Q-2})$ (as the statement is true for $m=3$), subtracting $\det(K_Q)$ from $\det(K_P)$ and interchanging $\det(K_{P-2})$ and $\det(K_{Q-2})$ gives us:
\begin{eqnarray*}
\det(K_P) - \det(K_Q) &=& 
k_{23}^2 (\operatorname{det}(K_{Q-2}) - k_{11} \operatorname{det}\begin{pmatrix}
        k_{11} & k_{23} \\
        k_{23} & k_{22} \\
    \end{pmatrix}) 
    -  \\
    &&k_{12}^2 (\operatorname{det}(K_{P-2}) - k_{11} \operatorname{det} 
    \begin{pmatrix}
        k_{11} & k_{12} \\
        k_{12} & k_{22} \\
    \end{pmatrix}) \\
    &=& k_{23}^2(\det(K_{Q-2})-k_{11}\det(K_{Q-3}))-k_{12}^2(\det(K_{P-2})-k_{11}\det(K_{P-3})) \\
   &=& k_{23}^2(k_{12}^2 \det(K_{Q-4})) - k_{12}^2(k_{23}^2\det(K_{P-4})) \\
   &=& 0,
\end{eqnarray*}
as $\det(K_{P-4})$ is also equal to $\det(K_{Q-4})$. Now, assuming the induction hypothesis on $m-2$ and $m-4$, we use the exact same technique as above to prove the induction statement. We have,
\begin{eqnarray*}
    \det(K_P)&=& k_{23}^2 \det(K_{P-2})- k_{11}k_{m-1m-1}\det(K_{P-2}) +k_{11}k_{12}^2\det(K_{P-3}), \text{ and} \\
    \det(K_Q)&=& k_{12}^2 \det(K_{Q-2})- k_{11}k_{m-1m-1}\det(K_{Q-2}) +k_{11}k_{23}^2\det(K_{Q-3}).
\end{eqnarray*}
As $\det(K_{P-2})$ is equal to $\det(K_{Q-2})$ by the induction hypothesis, interchanging them gives us,
\begin{eqnarray*}
    \det(K_P)-\det(K_Q)=&=& k_{23}^2(\det(K_{Q-2})-k_{11}\det(K_{Q-3}))-k_{12}^2(\det(K_{P-2})-k_{11}\det(K_{P-3})) \\
   &=& k_{23}^2(k_{12}^2 \det(K_{Q-4})) - k_{12}^2(k_{23}^2\det(K_{P-4})) \\
   &=& 0,
\end{eqnarray*}
as $\det(K_{Q-4})=\det(K_{P-4})$ by the induction hypothesis, thus concluding the proof.
\end{proof}

