\section{Complete proofs for the fast $(p',\zeta)$-biased generator of reference~\cite{Meka14}} \label{app:genProof}
We now present the proof of \cref{lem:eff}. \textit{All results in this section of the appendix were obtained and proved in the full manuscript of~\cite{Meka14}. Following~\cite{Meka14,comms}, we reproduce the complete proofs for the convenience of the reader.} 

\vspace{0.2cm}

\noindent To begin, we introduce some extra notation and definitions. Let $\mathbb{F}$ be a finite field, and let $Z$ and $W$ be vectors in $\mathbb{F}^{n}$ with entries $Z_{i},W_{i} \in \mathbb{F}$ for $i \in \{0,...,n-1\}$, respectively. A vector $Z$ is $p'$-sparse if it has $p'$ non-zero entries. We denote the inner product over $\mathbb{F}^{n}$ by $\langle Z,W \rangle_{\mathbb{F}^{n}} = \sum_{i=0}^{n-1}Z_{i}  W_{i} \in \mathbb{F}$, where $Z_{i}  W_{i}$ denotes multiplication over $\mathbb{F}$. We denote $U_{\mathbb{F}^{n}}$ as a uniformly distributed random vector in $\mathbb{F}^{n}$, i.e., $p_{U_{\mathbb{F}^{n}}}(Z) = |\mathbb{F}|^{-n}$ for all $Z$ in $\mathbb{F}^{n}$. For the case $\mathbb{F} = \mathrm{GF}[2]$, we use the notation $\langle Z,W \rangle_{\text{bin}}$ for $\langle Z,W \rangle_{\mathrm{GF}[2]^{n}}$ and $U_{n}$ for $U_{\mathrm{GF}[2]^{n}}$, respectively (to maintain consistency with the main text).

\begin{definition}[$\zeta$-biased for linear tests of size $p'$ over $\mathbb{F}$]
    Let $Z$ be a random vector in $\mathbb{F}^{n}$. Let $p' \leq n$ be a positive integer and $\zeta \geq 0$. $Z$ is $\zeta$-biased for linear tests of size $p'$ over $\mathbb{F}$ if, for all non-zero $p'$-sparse vectors $W \in \mathbb{F}^{n}$, the variable defined by $Z_{W} := \langle Z,W \rangle_{\mathbb{F}^{n}}$ satisfies
        \begin{equation}
            2 \cdot \mathrm{SD}[Z_{W},U_{\mathbb{F}}] \leq \zeta \ .
        \end{equation} \label{def:biasfield}
\end{definition}
\noindent Let $X$ be a bitstring of length $r$ distributed uniformly. A function $G:\{0,1\}^{r} \to \mathbb{F}^{n}$ is a $(p',\zeta)$-biased generator over $\mathbb{F}$ if the variable $G(X)$ is $\zeta$-biased for linear tests of size $p'$ over $\mathbb{F}$. We also restate the construction below for convenience.

\vspace{0.2cm}

\noindent \textbf{Construction 1} (\cite{Meka14,comms}, Section 1.1).
    Let $n $ and $ p'$ be positive integers that satisfy $p' \leq n$. Let $\zeta > 0$ and $\mathbb{F}$ be a finite field with $|\mathbb{F}| \geq \mathrm{max}\{n,p'/\zeta\}$. Let $A,B$ be arbitrary subsets of $\mathbb{F}$, with $|A|=n$ and $|B| = p'/\zeta$. Define the generator $G:B \times \mathbb{F} \rightarrow \mathbb{F}^{|A|}$ as follows: for every $\alpha \in A$,
        \begin{equation}
            G(\beta,\nu)_{\alpha} := \nu \cdot \sum_{i=0}^{p'-1}(\alpha \beta)^{i}\ , \quad \beta \in B, \ \nu \in \mathbb{F} \ . 
        \end{equation}



\begin{lemma}[\cite{Meka14,comms}, Section 1.1]
    $G$ as defined in Construction~\ref{const:eps} is a $(p',2\zeta)$-biased generator over $\mathbb{F}$ according to \cref{def:biasfield}.
    \label{lem:fieldBias}
\end{lemma}
\begin{proof}
    The generator in Construction~\ref{const:eps} maps finite field elements in $B \times \mathbb{F}$ to a vector in $\mathbb{F}^{|A|}$. Let $W$ be any vector in $\mathbb{F}^{|A|}$ with entries indexed by $W_{\alpha}$ for $\alpha \in A$. Then, according to \cref{def:biasfield}, we want to show that the random variable 
    \begin{equation}
        G_{W} := \langle W , G(\beta,\nu) \rangle_{\mathbb{F}} \ ,
    \end{equation}
    is statistically close to $U_{\mathbb{F}}$. Let $\lambda \in \mathbb{F}$, and define the degree $p'-1$ polynomial over $\mathbb{F}$,
    \begin{equation}
        P_{W}(\lambda) := \sum_{i=0}^{p'-1}\Bigg( \sum_{\alpha \in A} W_{\alpha} \alpha^{i}\Bigg) \lambda^{i} \ .
    \end{equation}
    Then, for every pair of generator inputs $\beta \in B$ and $\nu \in \mathbb{F}$,
    \begin{equation}
        \langle W , G(\beta,\nu) \rangle_{\mathbb{F}} = \sum_{\alpha \in A} W_{\alpha} G(\beta,\nu)_{\alpha} = \sum_{\alpha \in A} \sum_{i = 0}^{p'-1} W_{\alpha} \cdot \nu \cdot (\alpha \beta)^{i} = \nu \cdot \sum_{i=0}^{p'-1} \Bigg( \sum_{\alpha \in A} W_{\alpha} \alpha^{i} \Bigg) \beta^{i} = \nu \cdot P_{W}(\beta) \ .
    \end{equation}

    Next, we notice that $P_{W}$ is a non-zero polynomial whenever $W$ is $p'$-sparse. To see this, let $\tau = \{t_{0},...,t_{p'-1}\} \subseteq A$ denote the set of coordinates $\alpha$ for which $W_{\alpha}$ is non-zero. The coefficients $c_{i} \in \mathbb{F}$ of $P_{W}(\lambda)$ can be expressed as the inner product
    \begin{equation}
        c_{i} := \sum_{\alpha \in A} W_{\alpha} \alpha^{i} = \sum_{\alpha \in \tau} W_{\alpha} \alpha^{i} = \Big\langle [W_{t_{0}},...,W_{t_{p'-1}}] , [(t_{0})^{i},...,(t_{p'-1})^{i}] \Big \rangle_{\mathbb{F}} \ ,
    \end{equation}
    for $i = 0,...,p'-1$. The vector $[c_{0},...,c_{p'-1}]$ can therefore be expressed as the vector-matrix product
    \begin{equation}
        [c_{0},...,c_{p'-1}] = [W_{t_{0}},...,W_{t_{p'-1}}] \times 
        \underbrace{\begin{bmatrix}
            1 & t_{0} & (t_{0})^{2} & \cdots & (t_{0})^{p'-1}\\
            1 &  t_{1} & (t_{1})^{2} & \cdots & (t_{1})^{p'-1} \\
            \vdots & \vdots & \vdots & \ddots & \vdots \\
            1 & t_{p'-1} & (t_{p'-1})^{2} & \cdots & (t_{p'-1})^{p'-1}
        \end{bmatrix}}_{\textbf{V}}\ ,
    \end{equation}
    The matrix $\textbf{V} \in \mathbb{F}^{\, p' \times p'}$ above is a Vandermonde matrix, which is invertible if and only if all $\{t_{i}\}_{i=0}^{p'-1}$ are distinct. This condition is satisfied by definition, as they correspond to the indices of $W$ with non-zero entries. Therefore, $[c_{0}, \ldots, c_{p'-1}] \mathbf{V}^{-1} = [W_{t_{0}}, \ldots, W_{t_{p'-1}}]$ and, since $[W_{t_{0}}, \ldots, W_{t_{p'-1}}]$ is non-zero by definition, the vector $[c_{0}, \ldots, c_{p'-1}]$ cannot be the all zero vector.

    Consequently, since $P_{W}$ is a non-zero polynomial of degree at most $p'-1$ over $\mathbb{F}$, it has at most $p'-1$ roots. Given that $\beta$ is chosen uniformly from $B$, with $|B| = p'/\zeta$, the probability that $P_{W}(\beta) = 0$ is at most $(p'-1)/|B| = \zeta - \zeta/p' \leq \zeta$. Conditioned on $P_{W}(\beta) \neq 0$, the variable $\nu \cdot P_{W}(\beta)$ is uniformly distributed over $\mathbb{F}$ (since $\nu$ is chosen uniformly over $\mathbb{F}$). We therefore have
    \begin{equation}
    \begin{aligned}
         \mathrm{SD}[G_{W},U_{\mathbb{F}}] &= \frac{1}{2}\sum_{\mu \in \mathbb{F}} \Big | p_{G_{W}}(\mu) - \frac{1}{|\mathbb{F}|} \Big| 
         = \frac{1}{2}\sum_{\mu \in \mathbb{F}} \Big | \mathrm{Pr}[\nu \cdot P_{W}(\beta) = \mu ] - \frac{1}{|\mathbb{F}|} \Big|\\
         &= \frac{1}{2}\sum_{\mu \in \mathbb{F}} \Big | \mathrm{Pr}[P_{W}(\beta) = 0]\mathrm{Pr}[\nu \cdot P_{W}(\beta) = \mu| P_{W}(\beta) = 0] \\ 
         & \hspace{1.2cm} + (1-\mathrm{Pr}[P_{W}(\beta) = 0])\mathrm{Pr}[\nu \cdot P_{W}(\beta) = \mu| P_{W}(\beta) \neq 0] 
          - \frac{1}{|\mathbb{F}|} \Big|\\
          &= \frac{1}{2}\sum_{\mu \in \mathbb{F}} \Big | \mathrm{Pr}[P_{W}(\beta) = 0]\delta_{0,\mu}  + \frac{(1-\mathrm{Pr}[P_{W}(\beta) = 0])}{|\mathbb{F}|} - \frac{1}{|\mathbb{F}|} \Big|\\ 
          &= \frac{1}{2}\sum_{\mu \in \mathbb{F}} \Big | \mathrm{Pr}[P_{W}(\beta) = 0]\Big( \delta_{0,\mu} - \frac{1}{|\mathbb{F}|} \Big)  \Big| \\
          &\leq \frac{\zeta}{2} \Big | 1 - \frac{1}{|\mathbb{F}|} \Big | + \frac{\zeta}{2} \sum_{\mu \in \mathbb{F} \, : \, \mu \neq 0}   \frac{1}{|\mathbb{F}|}  = \zeta(1-1/|\mathbb{F}|) \leq \zeta \ .
    \end{aligned}
    \end{equation}
    For the fourth equality, we used the facts $\mathrm{Pr}[\nu \cdot P_{W}(\beta) = \mu| P_{W}(\beta) \neq 0]  = 1/|\mathbb{F}|$ and $\mathrm{Pr}[\nu \cdot P_{W}(\beta) = \mu| P_{W}(\beta) = 0] = \delta_{0,\mu}$. For the first inequality, we used $\mathrm{Pr}[P_{W}(\beta) = 0] \leq \zeta$ and separated the $\mu = 0$ from the sum. Multiplying both sides by 2 completes the proof.
\end{proof} 

Given a bitstring $X \in \{0,1\}^{m}$, we define the function $\mathrm{LSB}:\{0,1\}^{m} \to \{0,1\}$, which returns the least significant bit of $X$, i.e. if $X = X_{0},...,X_{m-1}$, $\mathrm{LSB}(X) = X_{m-1}$. We identify elements of $\mathrm{GF}[2^{m}]$ with vectors in $\mathrm{GF}[2]^{m}$ in the natural way\footnote{By this, we mean an element $Z \in \mathrm{GF}[2]^{m}$ is viewed as a bitstring in $\{0,1\}^{m}$, where the $i$-th bit is identified with coefficient $i-1$ of the polynomial representation of $Z$.} (and vice-versa) and, for two bitstrings $X$ and $Y$ of length $m$, $X + Y$ denotes their addition over $\mathrm{GF}[2^{m}]$ (represented as a bitstring). Then, we have that $\mathrm{LSB}(X+Y) = \mathrm{LSB}(X) \oplus \mathrm{LSB}(Y)$. Moreover, for every $\alpha \in \mathrm{GF}[2^{m}]$, define $T_{\alpha} : \mathrm{GF}[2]^{m} \to \mathrm{GF}[2]$ by $T_{\alpha}(\lambda) = \mathrm{LSB}(\alpha \cdot \lambda)$. Note that $T_{\alpha}$ is linear, and we view the product $\alpha \cdot \lambda$ as multiplication over $\mathrm{GF}[2^{m}]$. We have the following:

\begin{lemma}[\cite{Lidl96}, Theorem 2.24]
    For every $\alpha \in \mathrm{GF}[2^{m}]$, there exists an $\alpha' \in \mathrm{GF}[2^{m}]$ such that $T_{\alpha'}(\lambda) = \langle \alpha, \lambda \rangle_{\text{bin}}$ for all $\lambda \in \mathrm{GF}[2]^{m}$. \label{lem:tmap}
\end{lemma}

\begin{lemma}[\cite{Meka14,comms}, Section 1.1]
    Let $G: \{0,1\}^{r} \to \mathrm{GF}[2^{m}]^{n}$ be a $(p',\zeta)$-biased generator over $\mathrm{GF}[2^{m}]$. Then $G$ viewed as a function from $\{0,1\}^{r} \to \mathrm{GF}[2]^{m \cdot n}$ is a $(p',\zeta)$-biased generator over $\mathrm{GF}[2]$.  \label{lem:con}
\end{lemma}
\begin{proof}
    In the following, given a vector $V \in \mathrm{GF}[2]^{m\cdot n}$, we denote its entries by $V_{j}$ for $j \in \{0,...,nm-1\}$. We can also view $V$ as $n$ blocks of size $m$, and we write $\bar{V}_{i}$, $i \in \{0,...,n-1\}$ for each block, with $\bar{V}_{i} \in \mathrm{GF}[2]^{m}$. In other words, we use bars to denote blocks of size $m$, and $\bar{V}_{i}$ is the $i$-th block of $V$. Let $W \in \mathrm{GF}[2]^{m\cdot n}$ be any non-zero $p'$-sparse vector, and $X$ be a uniformly distributed bitstring over $\{0,1\}^{r}$. We will now show that the variable $G_{W} := \langle W, G(X) \rangle_{\text{bin}} \in \mathrm{GF}[2]$ is close to $U_{1}$ in statistical distance. 

    For every $W$, consider the block $\bar{W}_{i} \in \mathrm{GF}[2]^{m}$. Let $\bar{W}_{i}'\in \mathrm{GF}[2]^{m}$ be defined such that $T_{\bar{W}_{i}'}(\lambda) = \langle \bar{W}_{i} , \lambda \rangle_{\text{bin}}$ for all $\lambda \in \mathrm{GF}[2]^{m}$, according to \cref{lem:tmap}. Now, we construct the vector $W' \in \mathrm{GF}[2^{m}]^{n}$ with entries $\bar{W}_{i}'$. If $W$ is non-zero and $p'$-sparse over $\mathrm{GF}[2]$, then $W'$ is also non-zero and $p'$-sparse over $\mathrm{GF}[2]$. Given any vector $S \in \mathrm{GF}[2]^{m \cdot n}$, we have
    \begin{equation}
        \langle W,S \rangle_{\text{bin}} = \bigoplus_{i=0}^{n-1}\langle \bar{W}_{i}, \bar{S}_{i} \rangle_{\text{bin}} = \bigoplus_{i=0}^{n-1} \mathrm{LSB}\Big(\bar{W}_{i}' \cdot \bar{S}_{i} \Big) =  \mathrm{LSB}\Bigg(\sum_{i=0}^{n-1} \bar{W}_{i}' \cdot \bar{S}_{i} \Bigg) = \mathrm{LSB}\Big(\big \langle W' , S \big \rangle_{\mathrm{GF}[2^{m}]} \Big) \ .
    \end{equation}
    Applying the above to $S = G(X)$, we have
    \begin{equation}
        \langle W,G(X) \rangle_{\text{bin}} = \mathrm{LSB}\Big(\big \langle W' , G(X) \big \rangle_{\mathrm{GF}[2^{m}]} \Big) \ .
    \end{equation}
    Since $G$ is a $(p',\zeta)$-biased generator over $\mathrm{GF}[2^{m}]$, the variable $\langle W' , S \big \rangle_{\mathrm{GF}[2^{m}]}$ for any non-zero $p'$-sparse vector $W'$ is distributed $\zeta$-close to uniform over $\mathrm{GF}[2^{m}]$. Therefore, when viewing $\langle W' , S \big \rangle_{\mathrm{GF}[2^{m}]} \in \mathrm{GF}[2]^{m}$ as an $m$ length bitstring, every individual bit is distributed $\zeta$-close to uniform over $\mathrm{GF}[2]$. Therefore, $\langle W,G(X) \rangle_{\text{bin}}$ is distributed $\zeta$-close to uniformly over $\mathrm{GF}[2]$, proving the claim. 
\end{proof}

\noindent We can now establish \cref{lem:eff}.

\vspace{0.2cm}

\noindent \textbf{Lemma 4} (\cite{Meka14,comms}, Section 1.1).
\textit{Let $n,\zeta$ and $p'$ be chosen according to Construction~\ref{const:eps} with $p'$ a positive power of $2$. Let $t$ be a positive integer, and suppose $r := \log(p'/\zeta)$ is a positive integer, such that $2^{t} \geq \max\{n,2^{r}\}$. Then the generator of Construction~\ref{const:eps} viewed as a function $G:\{0,1\}^{r+t} \rightarrow \{0,1\}^{n\cdot t}$ is a $(p',2\zeta)$-biased generator. Moreover, given any seed $(\beta,\nu) \in \mathrm{GF}[2^{r}] \times \mathrm{GF}[2^{t}]$ and an index $j \in \{0,...,n-1\}$, the $j^{th}$ block (of $t$ bits) can be computed using $O(\log (p'))$ field operations over $\mathrm{GF}[2^{t}]$.}

\begin{proof}
    Based on \cref{lem:fieldBias}, we know $G: B \times \mathbb{F} \to \mathbb{F}^{|A|}$ is a $(p',2\zeta)$-biased generator over $\mathbb{F}$, for well chosen $\mathbb{F},A,B,p',n$ and $\zeta$ according to Construction~\ref{const:eps}. Let us choose $\mathbb{F} = \mathrm{GF}[2^{t}]$, $B = \mathrm{GF}[2^{r}]$ with $r = \log(p'/\zeta)$, and $|A| = n$. Then $G:\mathrm{GF}[2^{r}] \times \mathrm{GF}[2^{t}] \to \mathrm{GF}[2^{t}]^{n}$ is a $(p',2\zeta)$-biased generator over $\mathrm{GF}[2^{t}]$ when the condition $|\mathbb{F}| \geq \max\{|A|,|B|\}$ is satisfied, which translates to $2^{t} \geq \max\{n,2^{r}\}$. Now, viewing $G$ as a function $G:\{0,1\}^{r+t} \to \mathrm{GF}[2]^{n\cdot t} \equiv \{0,1\}^{n \cdot t}$, we can apply \cref{lem:con} to show $G$ is $(p',2\zeta)$-biased over $\mathrm{GF}[2]$.  

    We now establish the claim of computation time. Let $\tilde{\mathbb{Z}} = \{2^{l} \, : \, l \in \mathbb{Z}_{\geq 0}\}$ and define $f:\mathbb{F} \times  \tilde{\mathbb{Z}} \to \mathbb{F}$ by $f(\lambda,p') := \sum_{i=0}^{p'-1} \lambda^{i}$. Observe that 
    \begin{equation}
        f(\lambda,p') = \sum_{i=0}^{p'-1} \lambda^{i} = (1+\lambda)(1+\lambda^{2} + \lambda^{4} + ... + \lambda^{p'-2}) = (1+\lambda)\sum_{i=0}^{p'/2 -1 } (\lambda^{2})^{i} = (1+\lambda)f(\lambda^{2},p'/2) \ .
    \end{equation}
    Writing $p' = 2^{l}$ for a positive integer $l$, we have $f(\lambda,2^{l}) = (1+\lambda)f(\lambda^{2},2^{l-1})$, and applying this procedure $l$ times, we arrive at
    \begin{equation}
        f(\lambda,p') = \prod_{j=0}^{l-1} (1+\lambda^{2^{j}})f(\lambda^{2^{l}},1) = \prod_{j=0}^{l-1} (1+\lambda^{2^{j}}) \ .
    \end{equation}
    For $\alpha \in A$, $\beta \in B$ and $\nu \in \mathbb{F}$, we can write
    \begin{equation}
        G(\beta,\nu)_{\alpha} = \nu \cdot \sum_{i=0}^{p'-1} (\alpha \beta)^{i} = \nu \cdot f(\alpha \beta,p') = \nu \cdot \prod_{j=0}^{l-1} (1+(\alpha \beta)^{2^{j}}) \ .
    \end{equation}
    The above element of $\mathbb{F}$, viewed as a string of $t$ bits, can be computed in $O(\log(p'))$ finite field operations over $\mathbb{F} = \mathrm{GF}[2^{t}]$. This completes the proof.
\end{proof}



\section{Proofs for the new construction of Raz's extractor}

\subsection{Proof of \cref{lem:newRaz1}} \label{app:newRaz1}
\noindent \textbf{Lemma 5}.
    \textit{Let $n_{1}$ and $n_{2}$ be positive integers, where $n_{1}$ is even and $n_{2} \leq n_{1}/2$. Define $N = (n_{1}/2)2^{n_{2}}$. Then for any positive integers $k_{1},k_{2},m,l,p$ and $\gamma > 0$ such that $m \leq n_{1}/2$, $l \leq n_{2} + \log(n_{1}/2), \ p \leq 2^{l}/m$, $p$ is even and any
    \begin{equation}
            \gamma \geq 2^{(n_{1}-k_{1})/p} \cdot \big[ (2\zeta)^{1/p} + p \cdot 2^{-k_{2}/2}\big],
        \end{equation}
    where $\zeta = 2^{l-n_{1}/2}$, we have the following:
    \begin{enumerate}[(i)]
        \item The generator of Construction~\ref{const:eps} viewed as a function $G:\{0,1\}^{n_{1}} \rightarrow \{0,1\}^{N}$ is a $(p',2\zeta)$-biased generator with $p' = 2^{l}$. 
        \item Consider the output of $G$ as $2^{n_{2}}$ blocks of size $n_{1}/2$ bits, and let $G(X)_{(i,y)}$ denote bit $i \in \{0,...,m-1\}$ of block $y \in \{0,1\}^{n_{2}}$. Then the function $\mathrm{Ext}:\{0,1\}^{n_{1}} \times \{0,1\}^{n_{2}} \rightarrow \{0,1\}^{m}$ defined by $\mathrm{Ext}(x,y)_{i} = G(x)_{(i,y)}$ is a $(n_1, k_1, n_2, k_2, m, \epsilon = 2^{m/2}\gamma)$ two-source extractor, and a strong (in either input) $(n_{1},k_{1},n_{2}',k_{2}',m, \gamma')$ two-source extractor, where
        \begin{equation}
            \begin{aligned}
                k_{1}' &= k_{1} + m/2 + 2 + \log (1/\gamma), \\
                k_{2}' &= k_{1} + m/2 + 2 + \log (1/\gamma), \\
                \gamma' &= \gamma \cdot 2^{m/2+1}.
            \end{aligned}
        \end{equation}
        \item Given $x \in \{0,1\}^{n_{1}}$ and $y \in \{0,1\}^{n_{2}}$, $\mathrm{Ext}(x,y)$ can be computed with computation time $O(n_{1}\log (n_{1})\log( p'))$.
    \end{enumerate} 
}
\begin{proof}
    \noindent \textbf{Part (i):} Choose the following parameters for \cref{lem:eff}:
    \begin{equation}
        t = n_{1}/2, \ n = 2^{n_{2}} \ .
    \end{equation}
    Since $\zeta = p' 2^{-n_{1}/2}$, $r = \log(p'/\zeta) = n_{1}/2$. We then have the finite field $\mathbb{F}$ is given by $\mathbb{F} = \mathrm{GF}[2^{t}] = \mathrm{GF}[2^{n_{1}/2}]$, and the two subsets are given by $A = \mathrm{GF}[n] = \mathrm{GF}[2^{n_{2}}]$ and $B = \mathrm{GF}[2^{r}] = \mathrm{GF}[2^{n_{1}/2}]$. The condition $2^{t} \geq \max\{n,2^{r}\}$ reads $2^{n_{1}/2} \geq \max \{ 2^{n_{2}}, 2^{n_{1}/2}\}$,
    which is satisfied by the constraint $n_{1}/2 \geq n_{2}$. We can therefore apply \cref{lem:eff} to obtain a generator for $n \cdot t = (n_{1}/2)2^{n_{2}}$ binary random variables $2p'2^{n_{1}/2}$-biased for linear tests of size $p'$, provided $p' \leq N$, which is satisfied since $l \leq n_{2} + \log (n_{1}/2)$. Note this sequence is generated using $t + r = n_{1}$ random bits.

    \vspace{0.2cm}

    \noindent \textbf{Part (ii):} We use the first $n_{1}/2$ bits of $X=x$ to select $\beta_{x} \in B = \mathrm{GF}[2^{n_{1}/2}]$, and the remaining $n_{1}/2$ bits to select $\nu_{x} \in \mathbb{F} = \mathrm{GF}[2^{n_{1}/2}]$. We can then define $2^{n_{2}}$ blocks, via arbitrary choice of $\alpha \in A \subset \mathrm{GF}[2^{n_{1}/2}]$, with $|A| = 2^{n_{2}}$, and associate the finite field elements $G(\beta_{x},\nu_{x})_{\alpha} \in \mathbb{F} = \mathrm{GF}[2^{n_{1}/2}]$, from \cref{eq:gen}. We denote its binary form 
    \begin{equation}
        G_{y}(x) = G(x)_{(y,0)},...,G(x)_{(y,n_{1}/2-1)} \in \{0,1\}^{n_{1}/2} \ ,
    \end{equation}
    where we exchanged the label $\alpha$ with a bitstring $y \in \{0,1\}^{n_{2}}$,\footnote{This assignment can be done using any bijection between the $2^{n_{2}}$ elements in $A$ and strings $y \in \{0,1\}^{n_{2}}$.} and exchanged the label $(\beta_{x},\gamma_{x})$ with $x$. By part $(i)$, the set $\{G(X)_{(y,i)}\}_{y,i}$ constitutes $(n_{1}/2)2^{n_{2}} \geq m \, 2^{n_{2}}$ binary random variables $2\zeta$-biased for linear tests of size $p'$, which can be constructed using $n_{1}$ random bits. The claim is then a corollary of \cref{lem:raz}. Note that only $m \, 2^{n_{2}}$ variables constructed from $n_{1}$ bits are required for \cref{lem:raz}, and the proof holds identically when we have access to $N > m \, 2^{n_{2}}$ bits since, given a string of $N$ bits $\zeta$-biased for linear tests of size $p'$, any sub-string of length $< N$ inherits the same property by definition. 

    \vspace{0.2cm}

    \noindent \textbf{Part (iii):} For a given $x \in \{0,1\}^{n_{1}}$ and $y \in \{0,1\}^{n_{2}}$, computation of the output $\mathrm{Ext}(x,y) = \mathrm{Ext}(x,y)_{0},...,\mathrm{Ext}(x,y)_{m-1}$ corresponds to computing the single block $G_{y}(x)$ and taking the first $m$ bits (since $m \leq n_{1}/2$). The claim then follows from the efficient properties of the generator $G$ in \cref{lem:eff}. 
\end{proof}

\subsection{Proof of \cref{thm:newRaz}}
\label{app:newRaz}
\noindent \textbf{Theorem 1.} \textit{Let $n_{1}, k_{1}, n_{2}, k_{2}, m$ be positive integers, $0 < \delta < 1/2$ and $0.25 < \lambda < (\delta k_2 / 16 - 1)$, such that $n_{2} \leq n_{1}/2$ and
    \begin{align}\label{constr3}
        k_1 &\geq \left(\frac{1}{2} + \delta\right)n_1 + 2\log(n_1) + 1\ , \\
        \label{constr4}
        k_2 &\geq \max\Big[3.2 \log \Big(\frac{8n_1}{k_2}\Big), 40 \Big]\ ,\\
       \label{constr5}
        m &\leq \frac{1}{\lambda} \Big( \frac{\delta k_2}{16} - 1 \Big)\ .
    \end{align}
    Then there exists an explicit $(n_{1},k_{1},n_{2},k_{2},m,\epsilon \leq 2^{(1 - 4\lambda)m/2 - 1})$ two-source extractor that can be computed in $O(n_1 \log (n_1)^2)$ time, and an explicit strong $(n_{1},k'_{1},n_{2},k'_{2},m,\epsilon' \leq 2^{(1 - 4\lambda)m/2})$ two-source extractor that can be computed in $O(n_1 \log (n_1)^2)$ time, with
    \begin{equation}
    \begin{aligned}
        k_1' &= k_1 + 3(m+1)\ , \\
        k_2' &= k_2 + 3(m+1)\ .
    \end{aligned}
    \end{equation} }


\begin{proof}
    Our proof follows the overall structure of Raz’s~\cite{Raz05} proof of Theorem 1, incorporating several improvements to achieve better parameters.
    We choose $N = (n_{1}/2) 2^{n_2}$, $p' = 2^{l}$ where $l = \floor*{\log \big(m(n_{1}-k_{1})\big)}$ and $\zeta = 2^{l-n_{1}/2}$. 
    Therefore, $\log(p')= O(\log(n_1))$ and $p' \leq m(n_{1}-k_{1})$. 
    Next, define $r := \log(p'/\zeta) = n_1/2$ and $t := n_1/2$. 
    Hence, by \cref{lem:eff}, we have that $G_0, \ldots, G_{N-1}$ binary random variables that are $2\zeta$-biased for linear tests of size $p'$ can be computed from $n_1$ random bits, with any constant multiple of $n_1/2$ being computable with time $O(n_1 \log (n_1)^2)$.
    For some even integer $p \leq p'$, we define 
    \begin{align}
        \log(\gamma_1) &= \frac{1}{p} \Big(n_{1}-k_{1} + \log(2\zeta) \Big) \ , \\
        \log(\gamma_2) &= (n_{1}-k_{1})/p + \log(p) - k_{2}/2 \ ,
        \label{eq:loggamma_2}
    \end{align}
    and
    \begin{align} 
        \gamma_1 + \gamma_2 = 2^{(n_{1}-k_{1})/p} \cdot \big[ (2\zeta)^{1/p} + p \cdot 2^{-k_{2}/2}\big]\ .
    \end{align}
    We now consider two cases. \newline
    \noindent \textbf{Case 1: $k_{2} < 4(n_{1}-k_{1})$.} Set $p$ to the smallest even integer larger than $8(n_{1}-k_{1})/k_{2}$.
    Then,
    \begin{align} \label{eq:pBounds}
        8(n_{1}-k_{1})/k_{2} \leq p \leq 8n_{1}/k_{2}\ .
    \end{align}
    Next, by inserting $\zeta = p' 2^{-n_{1}/2} = 2^{l - n_{1}/2}$ and $l = \floor*{\log m(n_{1}-k_{1})}$, we get
    \begin{equation}
    \begin{aligned}
        -\log(\gamma_{1}) &= \frac{-1}{p}\left(n_{1}-k_{1} + 1 + l - n_{1}/2 \right) \\
        &= \frac{1}{p}\left(k_{1} - n_{1}/2 - \floor*{\log  \big(m(n_{1}-k_{1})\big)}) -1 \right)\ .
    \end{aligned}
    \end{equation}
    To lower bound the above, we use the largest value of $p$ from \cref{eq:pBounds}, since \cref{constr3} implies that $k_1 - \frac{n_1}{2} - \floor*{\log \big(m(n_{1}-k_{1})\big)} - 1 \geq 0$. This follows from the fact that 
    \begin{equation}
    \begin{aligned}
        k_1 - \frac{n_1}{2} - \floor*{\log \big(m(n_{1}-k_{1})\big)} -1 &> k_1 - \frac{n_1}{2} - \log \big(\frac{k_2}{\lambda 32}(n_{1}-k_{1})\big) - 1\\ 
        &> k_1 - \frac{n_1}{2} - \log \big(\frac{k_2}{8}(n_{1}-k_{1})\big) -1 \\
        &> k_1 - \frac{n_1}{2} - 2\log(n_1) -1 \geq 0 \ ,
    \end{aligned}
    \end{equation} 
    where the first inequality uses \cref{constr5} followed by the bound $\delta < 1/2$, the second follows from the bound $\lambda > 1/4$, the third uses $k_{2}(n_{1} - k_{1}) < n_{1}^{2}$, and the last follows from \eqref{constr3} and the fact that $\delta > 0$.
    Therefore 
    \begin{align}
        -\log(\gamma_{1}) &= \frac{1}{p}\left(k_{1} - \frac{n_{1}}{2} - \floor*{\log \big(m(n_{1}-k_{1})\big)} -1\right) \\
        &\geq \frac{k_2}{8n_1}\left(k_{1} - \frac{n_{1}}{2} - \floor*{\log \big(m(n_{1}-k_{1})\big)} -1\right) \\
        &\geq \frac{k_2}{8n_1}\left(k_{1} - \frac{n_1}{2} - 2\log (n_1) -1\right) \\
        &\geq \frac{k_2}{8n_1}\delta n_1 \\
        &\geq 2 (\lambda m + 1) \ ,
    \end{align}
    where the penultimate inequality uses the bound on $k_1$ from \cref{constr3} and the final inequality uses the bound on $m$ from \cref{constr5}.
    Next, we bound $\gamma_2$ using the restrictions on $p$ in \cref{eq:pBounds},
    \begin{align}
        -\log(\gamma_{2}) &= \frac{k_{1} - n_1}{p} - \log(p) + \frac{k_{2}}{2} \\
        &\geq \frac{k_2(k_{1} - n_1)}{8(n_1 - k_1)} - \log\Big(\frac{8n_1}{k_2}\Big) + \frac{k_{2}}{2} \\
        &= \frac{3k_2}{8} - \log\Big(\frac{8n_1}{k_2}\Big)\ . 
    \end{align}
    Noting that $\log(8n_{1}/k_{2}) \leq 5k_{2}/16 $ by \eqref{constr4} and $\delta < 1/2$,
    \begin{equation}
        \frac{3k_2}{8} - \log\Big(\frac{8n_1}{k_2}\Big) \geq \frac{3k_2}{8} - \frac{5k_2}{16}
        > \frac{3k_2}{8} - \frac{3 - \delta}{8}k_{2} = \frac{k_{2}\delta}{8} \geq 2 (\lambda m + 1),
    \end{equation}
    where the final inequality comes from \cref{constr5}.
    Therefore, combining the bounds on $\gamma_{1}$ and $\gamma_{2}$, we get that
    \begin{align}
        \gamma_1 + \gamma_2 \leq 2^{-2\lambda m - 2} + 2^{-2\lambda m - 2} = 2^{-2\lambda m - 1}\ .
    \end{align} 
    \newline
    \noindent \textbf{Case 2: $k_{2} \geq 4(n_{1}-k_{1})$.} Set $p = 2$. 
    We find
    \begin{align}
        -\log(\gamma_{1}) &= \frac{1}{p}\left(k_{1} - \frac{n_{1}}{2} - \floor*{\log \big(m(n_{1}-k_{1})\big)} -1\right) \\
        &=  \frac{1}{2}\left(k_{1} - \frac{n_{1}}{2} - \floor*{\log \big(m(n_{1}-k_{1})\big)} -1\right) \\
        &\geq  \frac{k_2}{8n_1}\left(k_{1} - \frac{n_{1}}{2} - \floor*{\log \big(m(n_{1}-k_{1})\big)} -1\right) \\
        &\geq \frac{k_2}{8n_1}\delta n_1 \\
        &\geq 2 (\lambda m + 1) \ ,
    \end{align}
    where the first inequality follows from the constraint $k_{2} \leq n_{2} \leq n_{1}/2$, and the remainder follows the steps in Case 1.
    Now, we consider $\gamma_2$:
    \begin{equation}
    \begin{aligned}
       -\log(\gamma_{2}) &= \frac{k_{1} - n_1}{p} - \log(p) + \frac{k_{2}}{2} \\
        &= \frac{k_{1} - n_1}{2} - \log(2) + \frac{k_{2}}{2} \\
        &= \frac{k_{1} - n_1}{2} + \frac{k_{2}}{2} - 1 \\
        &\geq \frac{3k_{2}}{8} - 1 \\
        &\geq 2 (\lambda m + 1) \ ,
    \end{aligned} 
    \end{equation}
    where the penultimate inequality comes from the fact that the Case 2 condition implies $n_{1} - k_{1} \leq k_{2}/4$, so $(k_{1} - n_{1})/2 + k_{2}/2 -1 \geq - k_{2}/8 + k_{2}/2 - 1 = 3k_{2}/8 - 1$. The final inequality comes from the fact that $2(\lambda m + 1) \leq  \frac{\delta k_2}{8} \leq \frac{3k_{2}}{8} - 1$, where we used \eqref{constr5} followed by \eqref{constr4}.
    Therefore, combining the bounds on $\gamma_{1}$ and $\gamma_{2}$, we get that
    \begin{align}
        \gamma_1 + \gamma_2 \leq 2^{-2\lambda m - 2} + 2^{-2\lambda m - 2} = 2^{-2\lambda m - 1}\ .
    \end{align}
    By \cref{lem:newRaz1}, we now recover an $(n_{1},k_{1},n_{2},k_{2},m,\epsilon = 2^{m/2}\gamma \leq 2^{m/2}2^{-2\lambda m - 1} = 2^{(1 - 4\lambda)m/2 - 1})$ two-source extractor with computation time $O(n_{1} \log(n_{1})\log(p')) = O(n_{1}\log(n_{1})^{2})$,
    and a strong $(n_{1},k'_{1},n_{2},k'_{2},m,\epsilon' \leq 2^{(1 - 4\lambda)m/2})$ two-source extractor, where
    \begin{align}
        k_1' &= k_1 + 3(m+1) \ ,\\
        k_2' &= k_2 + 3(m+1)\ ,
    \end{align} with the same computation time, concluding the proof.
\end{proof}

\section{Quantum-proofing with the classical-quantum XOR lemma} \label{app:cq1}
Informally, the classical XOR lemma~\cite{GoldreichXOR} states that, given $m$ binary random variables $X = X_{0},...,X_{m-1}$, the statistical distance $\mathrm{SD}[X,U_{m}]$ is bounded by the maximum bias, $\mathrm{MB}[X]$, up to a factor of $2^{m/2}$, i.e. $\mathrm{SD}[X,U_{m}] \leq 2^{m/2 - 1} \mathrm{MB}[X]$. The maximum bias quantifies the uncertainty of sums of certain bit positions of $X$, $\mathrm{MB}[X] = 2\max_{\tau}\mathrm{SD}[X_{\tau},U_{1}]$, where $\tau$ is any non-empty sub-set of $\{0,...,m-1\}$ and $X_{\tau} = \bigoplus_{i \in \tau}X_{i}$. To extract many bits, Raz shows that the 1-bit extractor defined in \cite[Lemma 3.3]{Raz05} implies a bound on the maximum bias of the $m$-bit extractor output, $\mathrm{MB}[\mathrm{Ext}(X,Y)]$, from which the XOR lemma yields a bound on the uniformity of the full extractor output, $\mathrm{SD}[\mathrm{Ext(X,Y)},U_{m}]$, with a penalty factor $2^{m/2}$. One route to making the Raz extractor quantum-proof would be to take Raz's strong 1-bit extractor, and obtain a strong, quantum-proof 1-bit extractor via a general reduction such as the Markov~\cite{AF15} or bounded storage model~\cite{Konig_2008}. Then using a classical-quantum (cq) XOR lemma~\cite{Kasher}, an $m$-bit quantum-proof extractor could be obtained analogously to the original proof.    

This proof structure will, in general, give a different set of final parameters to those obtained in \cref{cor:qproofRaz}, where the Markov model was applied to the $m$-bit Raz extractor directly. Specifically, the additional extractor error incurred by applying the Markov model scales exponentially in the output size $m$ (cf. \cref{lem:qproofMM}), and only applying this to the 1-bit extractor may be less penalizing. However, for the cq-XOR lemma presented in~\cite{Kasher} we could not find an improvement; this is due to the fact that the cq version is not tight compared to its classical counter part, and contributes an additional factor of $2^{m/2}$ to the error (i.e., $\mathrm{SD}[X,U_{m}] \leq 2^{m - 1} \mathrm{MB}[X]$). This is enough to diminish any potential advantage from this alternative proof structure. On the other hand, if a cq-XOR lemma was proven with the same penalty as the classical version, an improvement in parameters would be possible. 

Formally, given a random string of $m$ bits $X_{0},...,X_{m-1}$, let $\tau \subseteq \{0,...,m-1\}$ be a non-empty subset of indices, and define the binary random variables $X_{\tau} = \bigoplus_{i \in \tau} X_{i}$. The maximum bias of $X$ is given by  
\begin{equation}
    \mathrm{MB}[X] := 2\cdot \max_{\tau \neq \varnothing} \mathrm{SD}[X_{\tau},U_{1}].
\end{equation}
Then the classical XOR lemma is the following result:
\begin{lemma}
    Let $X_{0},...,X_{m-1}$ be $m$ binary random variables. Then
    \begin{equation}
        \mathrm{SD}[X,U_{m}] \leq \frac{2^{m/2}}{2} \mathrm{MB}[X].
    \end{equation} \label{lem:cXOR}
\end{lemma}
\noindent For proof see~\cite{GoldreichXOR}. This relationship is established by relating $\mathrm{SD}$ and $\mathrm{MB}$ to the $l_{1}$ and $l_{\infty}$ norms, respectively, on the space of probability distributions in $\mathbb{R}^{2^{m}}$, and applying relevant norm inequalities. The quantum case is defined analogously: consider the cq-state
\begin{equation}
    \rho_{XE} = \sum_{x \in \{0,1\}^{m}} p_{X}(x)\ketbra{x}{x} \otimes \rho_{E}^{x}\ .
\end{equation}
Define, for $\mu \in \{0,1\}$, 
\begin{equation}
    \Pi_{\mu}^{\tau} := \sum_{\substack{y\in\{0,1\}^{m} \\ \mathrm{s.t.} \ \bigoplus_{i \in \tau}y_{i}=\mu}} \ketbra{y}{y}, \ K_{\mu}^{\tau} := \ket{\mu} \otimes  \Pi_{\mu}^{\tau}\ . 
\end{equation}
Note that $K_{0}^{\tau \dagger}K_{0}^{\tau} + K_{1}^{\tau \dagger}K_{1}^{\tau} = \Pi_{0}^{\tau} + \Pi_{1}^{\tau} = \mathds{1}_{X}$, hence $\{K_{\mu}^{\tau}\}_{\mu}$ form a set of Kraus operators for every non-empty $\tau$. Applying this channel to $\rho_{XE}$ yields
\begin{equation}
    \sum_{\mu =0}^{1} (K_{\mu}^{\tau} \otimes \mathds{1}_{E})\rho_{XE} (K_{\mu}^{\tau} \otimes \mathds{1}_{E})^{\dagger} = \sum_{\mu=0}^{1} \ketbra{\mu}{\mu} \otimes \Bigg( \sum_{\substack{x \in\{0,1\}^{m}\\ \mathrm{s.t.} \ \bigoplus_{i \in \tau}x_{i}=\mu}} p_{X}(x)\ketbra{x}{x} \otimes \rho_{E}^{x}\Bigg)\ .
\end{equation}
Taking the partial trace over $X$, and labeling the entire channel (including identity on $E$) $\Lambda_{\tau}$, we define
\begin{equation}
    \rho_{X_{\tau}E} := \Lambda_{\tau}[\rho_{XE}] = \sum_{\mu=0}^{1} \ketbra{\mu}{\mu} \otimes \Bigg( \sum_{\substack{x \in\{0,1\}^{m}\\ \mathrm{s.t.} \ \bigoplus_{i \in \tau}x_{i}=\mu}} p_{X}(x)\rho_{E}^{x}\Bigg)\ . 
\end{equation}

This allows us to define the maximum bias of $\rho_{XE}$ with respect to $E$ (slightly neglecting notation by using the same label as in the classical case), 
\begin{equation}
    \mathrm{MB}[\rho_{XE}]:= \max_{\tau \neq \varnothing}  \| \rho_{X_{\tau}E} - \omega_{2} \otimes \rho_{E}\|_{1}\ ,
\end{equation}
where the maximum is taken over all non-empty subsets $\tau$. The aim is to bound $\mathrm{TD}[\rho_{XE},\omega_{m} \otimes \rho_{E}]$ by $\mathrm{MB}[\rho_{XE}]$; we interpret such a bound as a classical-quantum version of the XOR lemma. Notably, a cq-XOR lemma of this type was proven by Kasher and Kempe~\cite{KK}:
\begin{lemma}[\cite{KK}, Lemma 10]
    Let $\rho_{XE}$ be an arbitrary cq-state, and $d = \mathrm{dim}[\mathcal{H}_{E}]$. Then
    \begin{equation}
        \mathrm{TD}[\rho_{XE},\omega_{m} \otimes \rho_{E}] \leq 2^{\min\{m,d\}/2}\sqrt{\sum_{\tau \neq \varnothing} \Big( \mathrm{TD}[\rho_{X_{\tau}E} , \omega_{2} \otimes \rho_{E}] \Big)^{2} }. \label{eq:oldcqXOR}
    \end{equation} \label{lem:oldCQXOR}
\end{lemma}
\noindent \cref{lem:oldCQXOR} can be used to quantum-proof Raz's extractor in the following way. Recall Raz's strong, 1-bit extractor, obtained by setting $m =1$ in \cref{lem:raz}.
\begin{lemma}[\cite{Raz05}]
    Let $N = 2^{n_{2}}$. Let $G_{0},...,G_{N-1}$ be 0-1 random variables $\zeta$-biased for linear tests of size $p'$ that can be constructed using $n_{1}$ random bits. Define $\mathrm{Ext}:\{0,1\}^{n_{1}}\times \{0,1\}^{n_{2}} \to \{0,1\}$ by $\mathrm{Ext}(x,y) = G(x)_{y}$. Then, for any even integer $p \leq p'$ and any $k_{1},k_{2}$, the function $\mathrm{Ext}$ is an $(n_{1},k_{1}',n_{2},k_{2}',1,\gamma \, 2^{3/2})$ strong (in either source) two-source extractor for any $\gamma \geq 2^{(n_{1}-k_{1})/p} \cdot \big[ \zeta^{1/p} + p \cdot 2^{-k_{2}/2}\big]$ and $k_{1}' = k_{1} + 5/2 + \log(1/\gamma)$, $k_{2}' = k_{2} + 5/2 + \log(1/\gamma)$.  
\end{lemma}
\noindent Applying \cref{lem:qproofMM}, we obtain a strong 1-bit two-source extractor that is quantum-proof in the Markov model,
\begin{corollary}
    Let $N = 2^{n_{2}}$. Let $G_{0},...,G_{N-1}$ be 0-1 random variables $\zeta$-biased for linear tests of size $p'$ that can be constructed using $n_{1}$ random bits. Define $\mathrm{Ext}:\{0,1\}^{n_{1}}\times \{0,1\}^{n_{2}} \to \{0,1\}$ by $\mathrm{Ext}(x,y) = G(x)_{y}$. Then, for any even integer $p \leq p'$ and any $k_{1},k_{2}$, the function $\mathrm{Ext}$ is a quantum-proof $(n_{1},k_{1},n_{2}',k_{2}',1,\sqrt{3\sqrt{2}\gamma})$ two-source extractor in the Markov model, for any $\gamma \geq 2^{(n_{1}-k_{1})/p} \cdot \big[ \zeta^{1/p} + p \cdot 2^{-k_{2}/2}\big]$ and $k_{1}' = k_{1} + 1 + 2\log(1/\gamma)$, $k_{2}' = k_{2} + 1 + 2\log(1/\gamma)$. \label{cor:1bitQ}
\end{corollary}

\noindent Combining with \cref{lem:oldCQXOR}, we arrive at the following:
\begin{lemma}
    Let $N = m \cdot 2^{n_{2}}$. Let $G_{0},...,G_{N-1}$ be 0-1 random variables $\zeta$-biased for linear tests of size $p'$ that can be constructed using $n_{1}$ random bits. Define $\mathrm{Ext}:\{0,1\}^{n_{1}}\times \{0,1\}^{n_{2}} \to \{0,1\}^{m}$ by $\mathrm{Ext}(x,y)_{i} = G(x)_{(i,y)}$. Then, for any even integer $p \leq p'/m$ and any $k_{1},k_{2}$, the function $\mathrm{Ext}$ is a strong (in either input) quantum-proof $(n_{1},k_{1},n_{2}',k_{2}',m,2^{m} \, \sqrt{3\sqrt{2}\gamma})$ two-source extractor in the Markov model, with $\gamma \geq 2^{(n_{1}-k_{1})/p} \cdot \big[ \zeta^{1/p} + p \cdot 2^{-k_{2}/2}\big]$ and $k_{1}' = k_{1} + 1 + 2\log(1/\gamma)$, $k_{2}' = k_{2} + 1 + 2\log(1/\gamma)$. \label{lem:mbitQ} 
\end{lemma}
\begin{proof}
    First, we reproduce the proof in \cite[Lemma 3.3]{Raz05}. For every non-empty $\tau \in \{0,...,m-1\}$, define $\mathrm{Ext}_{\tau} : \{0,1\}^{n_{1}} \times \{0,1\}^{n_{2}} \to \{0,1\}$, by 
    \begin{equation}
        \mathrm{Ext}_{\tau}(x,y) = \bigoplus_{i \in \tau} \mathrm{Ext}_{i}(x,y) = \bigoplus_{i \in \tau} Z_{(i,y)}(x)\ .
    \end{equation}
For a fixed $\tau$, note that the set of variables $\big \{ Z_{y|\tau} := \bigoplus_{i \in \tau} Z_{(i,y)} \ : \ y \in \{0,1\}^{n_{2}}\}$ is $\zeta$-biased for linear tests of size $p'/m$. This follows from the fact that, for any non-empty $\mathcal{Y} \subset \{0,1\}^{n_{2}}$ satisfying $|\mathcal{Y}| \leq p'/m$, define  
\begin{equation}
    Z_{\mathcal{Y}} := \bigoplus_{y \in \mathcal{Y}} Z_{y|\tau} = \bigoplus_{y \in \mathcal{Y}}\bigoplus_{i \in \tau} Z_{(i,y)}\ .
\end{equation}
Note that $|\mathcal{Y}|\cdot | \tau | = p' |\tau|/m \leq p'$, implying $Z_{\mathcal{Y}}$ must be $\zeta$-close to uniform, since $\{Z_{(i,y)}\}_{i,y}$ are $\zeta$-biased for linear tests of size $p'$. Therefore, for every non-empty $\tau$, the variables $\{ \mathrm{Ext}_{\tau}(x,y)\}_{y \in \{0,1\}^{n_{2}}} = \{ Z_{y|\tau}(x) \}_{y \in \{0,1\}^{n_{2}}}$ are $\zeta$-biased for linear tests of size $p'/m$. By \cref{cor:1bitQ} the function $\mathrm{Ext}_{\tau}(x,y) = Z_{y|\tau}(x)$ is an $(n_{1},k_{1},n_{2}',k_{2}',1,\epsilon'=\sqrt{3\gamma/2})$ strong (in either input) 1-bit extractor, quantum-proof in the Markov model from \cref{cor:1bitQ}. Choosing the extractor to be strong in the first source, this implies
    \begin{equation}
        \mathrm{TD}\big[\rho_{\mathrm{Ext}_{\tau}(X,Y)XE}, \omega_{2} \otimes \rho_{XE} \big] \leq \epsilon' \label{eq:exp}
    \end{equation} 
    for all non-empty $\tau$. Notice that
    \begin{equation}
        \rho_{\mathrm{Ext}_{\tau}(X,Y)XE} = \Lambda_{\tau}[\rho_{\mathrm{Ext}(X,Y)XE}]\ ,
    \end{equation}
    and \cref{eq:exp} implies $\mathrm{MB}[\rho_{\mathrm{Ext}(X,Y)XE}] \leq 2 \epsilon'$. We can directly apply \cref{lem:oldCQXOR} to obtain
    \begin{equation}
        \mathrm{TD}[\rho_{\mathrm{Ext}(X,Y)XE},\omega_{m}\otimes \rho_{XE}] \leq \epsilon' \cdot 2^{m}\ .
    \end{equation}
\end{proof}
Notice that the error increases by a factor of $2^{m}$, compared to $2^{m/2}$ in the classical case. Alternatively, we could apply the Markov model directly to the original $m$-bit extractor, resulting in the parameters of \cref{cor:mbitQ2}, restated below:

\vspace{0.2cm}


\noindent \textbf{Corollary 2.} \textit{Let $N = m \cdot 2^{n_{2}}$. Let $G_{0},...,G_{N-1}$ be 0-1 random variables $\zeta$-biased for linear tests of size $p'$ that can be constructed using $n_{1}$ random bits. Define $\mathrm{Ext}:\{0,1\}^{n_{1}}\times \{0,1\}^{n_{2}} \to \{0,1\}^{m}$ by $\mathrm{Ext}(x,y)_{i} = G(x)_{(i,y)}$. Then, for any even integer $p \leq p'/m$ and any $k_{1},k_{2}$, the function $\mathrm{Ext}$ is a strong (in either input) $(n_{1},k_{1}',n_{2},k_{2}',m,2^{3m/4} \, \sqrt{3\gamma/2})$ two-source extractor quantum-proof in the Markov model, with $\gamma \geq 2^{(n_{1}-k_{1})/p} \cdot \big[ \zeta^{1/p} + p \cdot 2^{-k_{2}/2}\big]$ and $k_{1}' = k_{1} + 1 + 2\log(1/\gamma)$, $k_{2}' = k_{2} + 1 + 2\log(1/\gamma)$.}

\noindent Comparing the parameters, we have 
    \begin{align}
        \mathrm{\cref{lem:mbitQ} \ (CQ-XOR \ lemma):}& \ \ \ \epsilon = 2^{m} \, \sqrt{3\sqrt{2}\gamma}, \ \ \ k_{i}' = k_{i} + 1 + 2\log(1/\gamma), \label{eq:q1}\\
        \mathrm{\cref{cor:mbitQ2} \ (Markov \ model \ directly):}& \ \ \ \epsilon = 2^{3m/4} \, \sqrt{3\gamma/2}, \ \  k_{i}' = k_{i} + 1 + 2\log(1/\gamma).\label{eq:q2}
    \end{align}
On the other hand, a tight CQ-XOR lemma would result in 
\begin{equation}
    \mathrm{(Tight \ CQ-XOR \ lemma):} \ \ \ \epsilon = 2^{m/2} \, \sqrt{3\sqrt{2}\gamma}, \ \ \ k_{i}' = k_{i} + 1 + 2\log(1/\gamma), \label{eq:q3}
\end{equation}
which would give an improvement by decreasing the error exponent from $3m/4$ to $m/2$.

