\section{Averaging Feller Semigroups}
\label{Section: averaging feller semigroups}

Both  the anomalous diffusion defined in Section \ref{Diffusion model 1} and the para-Markov chains recalled in Section \ref{Basic notions and preliminary results} are governed by equations of the form   $ \partial _t^\nu q= -(-G)^\nu q$.
 One can conjecture that this theory can be extended to more general cases. In particular, we might think that, whenever a non-Markovian process $X = \{X_t,\ t\geq0\}$ is equal in distribution to $ \lg M_{\Lam t},\ t\geq0\rg$, where $M = \{M_t,\ t\geq0\}$ is a Markovian process  and $\Lam$ is a Lamperti random variable, then its governing equation is of the type $ \partial _t^\nu q= -(-G)^\nu q$, where $G$ is the infinitesimal generator of $M$.
In this section we make this idea rigorous and we present the connection between random scaling of Markov processes and non-local operators. 
This connection, which is interesting in itself, will be used later in the paper.

Let us consider a Polish space $(E,\mathcal{E})$ endowed by its Borel $\sigma$-algebra.
Let $\l \Omega, \mathcal{F}, \mathbb{P}^x \r$, $x\in E$, be a family of probability spaces equipped with a filtration $\lg \mathcal{F}_t,\ t\geq0 \rg$. Let $M = \lg M_t,\ t\geq0\rg$ be an adapted Feller process, which takes value on $(E,\mathcal{E})$, associated with the Feller semigroup of operators
\begin{align}
\sgM_t h(x)= \mathbb{E}^x h(M_t) \notag %\label{aa}
\end{align}
on the Banach space $\l C_0(E), \left\| \cdot \right\| \r$,
endowed with the sup-norm. Feller semigroups are strongly continuous, i.e. $\left\| \sgM_t h -h \right\| \to 0$ as $t \to 0$ (for more on Feller semigroups see \cite{schillinglevy}). It is known that the mapping $t \mapsto \sgM_t  h$ is the unique solution to the abstract Cauchy problem
$$ \frac{\partial }{\partial  t} g(t) = Gg(t) \qquad g(0)=h \qquad h\in \Dom (G)$$
where $G$ is the infinitesimal generator of the semigroup.

We here consider the operators $\{ \sgL_t\}_{t \geq 0}$ defined through the Bochner integrals
 \begin{align}
     \sgL_t h \, = \, \int_0^{\infty} \sgM_{ty} h \, \mathpzc{l}(y)dy
     \label{bb}
 \end{align}
 where $\mathpzc{l}(\cdot)$ denotes a density of a Lamperti distribution as in Equation \eqref{Misura Lamperti distribution}.

%\subsection{Governing equation} \label{sezione equazione governante}

%Premettiamo che la funzione di Mittagleffler $\mathcal{M}(x)$ può essere scritta nella forma (8.5) di pag. 361 del libro di Kolokoltsov di Laura. E questa forma è molto adatta per definire l'operatore $\mathcal{M(A)}$ dove A è il generatore di un semigruppo strongly continuous. Infatti, come dice in formula 9.13 nel capitolo 9, la forma in serie di potenze va bene solo se $A$ è bounded.

We now show that the mapping  $t \mapsto \sgL_th$ is the unique solution of the following (non-local) abstract Cauchy problem
\begin{align}
\frac{\partial ^\nu}{\partial t^\nu} g(t) = -(-G)^\nu g(t) \qquad g(0)=h \in \Dom(G),\notag %  \label{cc}
\end{align}
where the operators are defined as follows. The fractional derivative on the left-hand side is
\begin{align}
\frac{\partial^\nu}{\partial t^\nu} g(t) := \, \frac{1}{\Gamma (1-\nu)}\frac{\partial }{\partial t} \int_0^t (g(s)-g(0)) (t-s)^{-\nu} ds  
\label{deffrac}
\end{align}
for any $g$ such that the integral makes sense as a Bochner integral on $C_0 (E)$ and the differentiation is possible in the strong sense. The operator defined in Equation \eqref{deffrac} is the abstract analogue of the Caputo fractional derivative in Equation \eqref{Definizione di Derivata di Caputo}. In order to define the operator $- \l -G \r^\nu$ we use Bochner subordination technique, as follows. We define the family of operators $\lg \sub_t \rg_{t \geq 0}$ such that
\begin{align}
\sub_t h := \int_{0}^{+\infty} \sgM_sh \,  \mu_t(s)ds
\label{subsem}
\end{align}
where $\mu_t(\cdot)$ is the density of a stable subordinator $\{H(t),\ t\geq 0\}$ of stability index  $\nu \in (0,1)$, i.e., a strictly increasing L\'evy process with Laplace transform
\begin{align}
    e^{-t\lambda^\nu} \, = \, \int_0^{+\infty} e^{-\lambda s} \, \mu_t(s) ds.
    \label{laplacestable}
\end{align}
It is known that the family $\lg \sub_t \rg_{t\geq0}$ forms a strongly continuous semigroup on $C_0(E)$ \cite[Proposition 13.1]{librobern} and that it is generated by the operator $G^{(\nu)}$ such that \cite[Theorem 13.6]{librobern}
\begin{align}
    G^{(\nu)} h := \int_0^{+\infty} \l \sgM_s h - h \r \frac{\nu s^{-\nu-1}}{\Gamma (1-\nu)}ds , \qquad h\in \Dom(G),
\label{defGnu}
\end{align}
a Bochner integral on $C_0(E)$. It is further true that (see \cite{schillingpaper})
\begin{align}
  G^{(\nu)} \mid_{\text{Dom}(G)}  = -\l -G \r^\nu.
\end{align}
In the following, we shall denote  by 
$
\{L(t),\ t\geq 0\}
$
the inverse process of $H$,  i.e.  
\begin{align}
L(t) := \inf \ll s \geq 0 : H(s) > t \rr \qquad t\geq 0  \label{definizione inverso}.
\end{align}
The random variable $ L(t) $ is known to be absolutely continuous for each $t>0$ and belongs to the class of inverse subordinators, crucial processes in the context of anomalous diffusion related to fractional kinetic (see more on inverse subordinators in \cite{tlms}).

\begin{te} \label{teorema equazione}
    Let $\lg \sgM_t \rg_{t\geq0} $ be a Feller semigroup as above, generated by $\l G, \Dom(G) \r$. Consider the operators $\lg \sgL_t \rg_{t\geq0}$ defined in Equation \eqref{bb} and the abstract Cauchy problem
        \begin{align}
            \frac{\partial^{\nu}}{\partial t^\nu} g(t) = -(-G)^\nu g(t) \qquad g(0)=h,
        \label{eqgen}
    \end{align}
    where the operators appearing in Equation \eqref{eqgen} are defined as in Equations \eqref{deffrac} and \eqref{defGnu}. It is true that: 
    \begin{enumerate}
        \item $\lg \sgL_t \rg_{t\geq0}$ is a family of uniformly bounded linear operators on $C_0(E)$ such that
        \begin{align*}
            \sgL_t : C_0(E) \mapsto C_0 (E) \qquad \sgL_t : \text{Dom}(G) \mapsto \text{Dom}(G)
        \end{align*}
        for any $t \geq 0$;
        \item For any $h \in C_0(E)$ the mapping $t \mapsto \mathcal{Q}_th$ is strongly continuous, i.e., $\left\| \sgL_th - \sgL_sh \right\| \to 0$, as $t \to s$ for any $s,t \geq 0$; 
        \item For any $h \in \text{Dom}(G)$ the mapping $t \mapsto \sgL_t h$ solves Equation \eqref{eqgen}. % \bt{in the sense that $\mathcal{Q}_th \in \text{Dom}(G)$ for any $t \geq0$, the fractional derivative exists in the strong sense and both $t \mapsto \mathcal{Q}_th$ and $t \mapsto -(-G)^\nu \mathcal{Q}_th$ are bounded (strongly) continuous functions on $C_0(E)$;}
    \item If $\mathpzc{q}(t)$ is a bounded (strongly) continuous solution on $C_0(E)$ to Equation \eqref{eqgen} such that $t \mapsto -(-G)^\nu \mathpzc{q}(t)$ is bounded and (strongly) continuous, then $\mathpzc{q}(t) = \mathcal{Q}_th$ for any $t \geq 0$.
    \end{enumerate}
\end{te}

\begin{proof}
For the proof the following representation for $\sgL_t$:
\begin{align}
\sgL_t h \, = \, \int_0^{+\infty} \sub_s h \,  \lambda_t(s)ds
\label{repr}
\end{align}
is used, where $\lambda_t(\cdot)$ is the density of the inverse stable subordinator defined in Equation \eqref{definizione inverso}
and $\sub_s$ is defined in Equation \eqref{subsem}. In order to derive representation \eqref{repr} we use the following arguments. Consider $H_i := \lg H_i(t),\ t\geq 0 \rg$, $i=1,2$, two i.i.d. stable subordinators, having Laplace transform as in Equation \eqref{laplacestable}   and let us use the notation $\lg L_2(t),\ t\geq 0 \rg$ for the inverse process of $H_2$. 
Note that 
\begin{align*}
\mathbb{E}e^{-\eta H_1(L_2(t))}& = \mathbb{E} e^{-\eta ^\nu L_2(t)}= \mathcal{M}_{\nu}(-t^\nu \eta ^\nu)  \qquad \eta \geq 0,
\end{align*}
where we used the Laplace transform in Equation \eqref{laplacestable} and the fact that (see Remark 3.1 in \cite{MeerJap})

\begin{align}
    \int_0^{+\infty} e^{- \gamma s} \lambda_t(ds) \, = \, \mathcal{M}_\nu \l - \gamma  t^\nu \r, \qquad \gamma \geq 0.
\end{align}
We further observe that the Definition \ref{Definition of Lamperti distribution} of Lamperti distribution  gives 
\begin{align*}
    \mathbb{E} e^{-\eta t \mathcal{L}}&= \mathcal{M}_\nu(-t^\nu \eta ^\nu), \qquad \eta \geq0,
\end{align*}
so that
\begin{align}
    t\mathcal{L}\overset{d}{=} H_1(L_2(t)). %\notag %\label{tL = H(L(t)) equivalenza in distribuzione della mistura di lamperti}
\end{align}
We now use the notation $\mathpzc{g}_t(\cdot)$ for the density of $H_1(L_2(t))$, i.e.
\begin{align}
    \mathpzc{g}_t(z) \, := \, \int_0^{+\infty} \mu_s(z) \lambda_t(s)ds \qquad z>0. \label{densità del subordinatore subordinato}
\end{align}
%where we recall that $\mu_s(dz)$ is the \textcolor{green}{density} of a stable subordinator while $\lambda_t(ds)$ is the distribution of the inverse stable subordinator.


%Equation \eqref{tL = H(L(t)) equivalenza in distribuzione della mistura di lamperti} states that integrating with respect to the measure $\mathpzc{l}$ or the distribution of $H_1(L_2(t))$, say $\mathpzc{g}_t(\cdot)$ is equivalent (as we are considering only the the single time distribution).
It follows that
\begin{align}
    \sgL_t h&= \int _0^{\infty} \sgM_{ty}h \, \mathpzc{l}(y)dy     \nonumber \\
    &=   \int _0^{\infty} \sgM_{z}h \, \mathpzc{g}_t(z)dz\notag \\
    &= \int _0^{\infty} \sub_{s}h \, \lambda_t(s)ds
\end{align}
where in the last step we used Equation \eqref{densità del subordinatore subordinato}, the definition of $\sub_t$ in Equation \eqref{subsem} and the Fubini theorem for Bochner integrals (see \cite[Theorem 1.1.9]{abhn}).

We are now ready to prove the Theorem.
\begin{enumerate}
    \item 
        The linearity simply follows from the definition \eqref{bb}. Similarly, the fact that $\sgL_t h\in C_0(E)$ for each $h\in C_0(E)$ and $t\geq0$ comes from the definition of Bochner integral provided that the integral exists. This can be  seen by using \cite[Theorem 1.1.4]{abhn} that applies here since $\left\| \mathcal{T}_{ty}h  \right\| \leq \left\| h \right\|$. The same argument leads to contractivity, indeed,
       \begin{align}
        \left\|  \sgL_t h \right\| \, =\, & \left\| \int_0^{+\infty} \sgM_{ty} h \mathpzc{l}(dy)  \right\| \notag \\
        \leq  \, & \int_0^{+\infty} \left\| \sgM_{ty}h  \right\| \, \mathpzc{l}(dy) \notag \\
        \leq \, & \left\| h \right\|, 
    \end{align}
   which implies that $\lg \sgL_t \rg_{t\geq0}$ is uniformly bounded. 
   So, the operators $\lg \sgL_t \rg$ are also well-defined and contractive.

    We have that $\lg\sgM_t \rg_{t \geq 0}$ is a Feller semigroup, therefore we can apply \cite[Lemma 4.5]{schillinglevy} to conclude that the subordinate semigroup $\lg \sub_t \rg_{t \geq 0}$ is also a Feller semigroup. It follows that $\sub_t$ maps $C_0(E)$ and $\text{Dom}(G)$ into themselves and it is strongly continuous. 

    We now prove that $\sgL_t h \in \Dom (G)$ if $h\in \Dom (G)$.  We shall use that $\text{Dom}(G)\subseteq \text{Dom}\l G^{(\nu)} \r $ and that $G^{(\nu)} \sub_y h = \sub_y G^{(\nu)} h$ for $h \in \text{Dom}(G)$. To get this result, it is sufficient to check the assumptions of \cite[Proposition 1.1.7]{abhn}. Specifically, one has that $\sgL_t h= \int _0^\infty \sub_sh \lambda _t(s) ds$ is well defined, i.e. 
\begin{align*}
    s \mapsto \sub_sh \lambda _t(s)
\end{align*}
is Bochner integrable for any $t>0$. Moreover, $\sub_sh \lambda _t(s)$    falls in the domain of $G^{(\nu)}$ because $G^{(\nu)}$ is the generator of $\sub_s$. 
Furthermore, we know that $G^{(\nu)}\sub_sh \lambda _t(s)= \sub_s (G^{(\nu)}h) \lambda _t(s) $ and $\sub_s (G^{(\nu)}h) \lambda _t(s)$ is Bochner integrable so that 
\begin{align*}
    s\mapsto G^{(\nu)}\sub_sh \lambda _t(s)
\end{align*}
is Bochner integrable as well, and the first item of the thesis follows. 

    \item Now we prove strong continuity. Again, the subordinate semigroup $\lg \sub_t \rg_{t \geq 0}$ is a Feller semigroup and it is strongly continuous. Furthermore, since $L_2(t)$ is the inverse of a strictly increasing subordinator, then it is path-continuous and then $\lg \sub_{L_2(t)} \rg_{t\geq0}$ is strongly continuous.

    By the representation \eqref{repr} we have that
    \begin{align}
        \sgL_t h \, = \, \mathbb{E} \sub_{L_2(t)}h,
        \notag %\label{strongcont}
    \end{align}
    which gives
    \begin{align*}
        || \sgL_{t_2} h - \sgL_{t_1} h || \leq \E || \sub_{L_2(t_2)}h  - \sub_{L_2(t_1)}h|| \qquad t_1,t_2 \geq0.
    \end{align*}
    Consider  the limit $t_1 \to t_2$. Using $\left\| \sub_{L_2(t) }h \right\| \leq \left\| h \right\|$ to apply the dominated convergence for Bochner integrals (\cite[Theorem 1.1.8]{abhn}), we get strong continuity.

    \item 
        As a consequence of \cite[Theorem 3.1]{fracCauchy} a Feller semigroup $\lg \sub_{t} \rg_{t\geq0}$ generated by $G^{(\nu)}\mid_{\text{Dom}(G)} = - \l -G \r^\nu$, integrated against the distribution of an inverse stable subordinator defines a mapping that solves Equation \eqref{eqgen}.
    Consistently, from Items (1) and (2) above, the functions 
    \begin{align*}
        t\mapsto \frac{\partial ^{\nu}}{\partial t^{\nu}} \sgL_t h\ \qquad \text{and} \qquad t\mapsto -(-G)^{\nu}\sgL_t h
    \end{align*}
    are well defined in the strong sense. 
    \item First, we prove that $t\longmapsto G^{(\nu)}\mathcal{Q}_th$ is bounded and (strongly) continuous for each $h\in \Dom(G)$. Indeed,
    \begin{align}
       G^{(\nu)} \mathcal{Q}_t h \, = \, \int_0^{+\infty} \mathcal{U}_s G^{(\nu)} h \lambda_t(s) ds \, = \, \mathcal{Q}_t G^{(\nu)} h
    \end{align}
    by the same arguments used in the proof of Item (1) and the strong continuity follows from the strong continuity and boundedness of $t \mapsto \mathcal{Q}_t G^{(\nu)} h$, since $G^{(\nu)} h \in C_0(E)$.

    Uniqueness follows from a Laplace transform argument. Note that $v(t) = \mathpzc{q}(t) - \mathcal{Q}_th$ solves the problem \eqref{eqgen} with $v(0)=0$. We can take the Laplace transform, $t \mapsto s$, of Equation \eqref{eqgen}, which is well defined by the boundedness of both sides. 

    Denoting by $\widetilde{v}$ the Laplace transform of $v$, one gets
    \begin{align}
        s^{\alpha} \widetilde{v}(s) = G^{(\nu)} \widetilde{v}(s) \iff \l s^\alpha -G^{(\nu)} \r \widetilde{v}(s) = 0.
    \end{align}
    Since the resolvent $\l s^\alpha-G^{(\nu)} \r^{-1}$ exists and is bounded, we have $\widetilde{v}(s)=0$ for any $s \geq 0$ being $\widetilde{v}(s)$ continuous.
\end{enumerate}

\end{proof}



In the next section we shall apply the theory of averaging Feller semigroups to transport processes. Before doing that, in the following remark we clarify the statement of Remark \ref{Anomalous diffusion: remark equazione governante}.
\begin{os}
    \label{fradens}
    From Proposition \ref{Convergence model 1: ugualianza fdd del mb lampertizzato} and the previous Theorem, the process $W_t$ is such that the function $q(x,t) = \mathds{E}^xu\l W_t\r$ solves a fractional kinetic equation of the form of Equation \eqref{eqgen}. In this case, the corresponding Feller process is a Brownian motion whose generator is such that $G|_{C_0^2 (\mathbb{R}^d)} = \Delta$, i.e., the Laplace operator. Therefore \eqref{eqgen} reduces to a fractional diffusion equation in both time and space. It follows that
    \begin{align}
        q(x,t) = \int_{\mathbb{R}^d} u(y) p_t(y-x)dy,
    \end{align}
    where $p_t(y-x)$ is a density for the random variable $W_t$, satisfies Equation \eqref{eqgen} with $G^\nu|_{C_0^2 (\mathbb{R}^d)} = -(-\Delta)^\nu$. Furthermore, $p_t(y-x) dy \to \delta_x(dy)$ weakly as $t \to 0$ and thus we can conclude that $p_t(y-x)$ satisfies the equation in the sense of fundamental solutions.
\end{os}




\section{Motion among random obstacles (Model 2)}

\subsection{Transport  with infinite mean flight times and random speed} \label{Subsection: Random flight Model 2}
We here consider another non-Markovian,  isotropic transport process, which differs from Model 1 because the speed of the particle is not fixed anymore. 
Specifically, we here assume that the speed is a random variable which is stochastically dependent on the random flight times. Again, the random number of direction changes up to time $t$ is $\ef_t$, i.e. the exchangeable fractional Poisson process defined in Section \ref{Exchengeable Fractional PP}. 
In more detail, the model is defined by the following assumptions.


\begin{assumption}{A2}{}\label{Isotropic: assumptions Model 2}
Suppose that in Definition \ref{Definizione isotropic transport process generica} the vectors $\l \mathcal{C}, J_1^{(\nu)},\ldots, J_n^{(\nu)}\r$, $n \geq1$, under all the probability measures $\mathds{P}^{(x,v)}$, have density given by
    \begin{align}
        \mathds{P}^{(x,v)}\lq \mathcal{C}\in d\tau, J_1^{(\nu)}\in dx_1,\ldots, J_n^{(\nu)} \in dx_n \rq = \l \lambda \frac{\tau}{c} \r^n e^{-\lambda \frac{\tau}{c} \sum_{i = 1}^nx_i}\ \mathpzc{l}\l \frac{\tau}{c}\r \frac{1}{c}\ d\tau dx_1\ldots dx_n \label{Random flight 2: densità congiunta C e Js}
    \end{align}
    where $\mathpzc{l}(\cdot)$ denotes the Lamperti distribution as in Equation \eqref{Misura Lamperti distribution}, which is equivalent to say that
    \begin{align}
        \l \mathcal{C}, J_1^{(\nu)}, \dots, J_n^{(\nu)} \r \overset{d}{=} \l  c \Lam , \frac{1}{\mathcal{L}}J_1, \dots, \frac{1}{\mathcal{L}}J_n \r \label{Random flight 2: uguaglianza in distribuzione C e Js}
    \end{align}
    where $\{J_n,\ n\geq 1\}$ are i.i.d. exponential variables of mean $1/ \lambda$.
    \end{assumption}
This assumption has the following implications: 
    \begin{enumerate}
    \item The joint distribution of the flight times $\lg J_n^{(\nu)},\ n\geq1 \rg$ is given by Equation \eqref{exchangeable fractional Poisson: joint survival function for (J_1, ..., J_n)} for some $\nu\in(0,1]$.
    \item The speed is $\mathcal{C} =  c \Lam $ where $c$ is a positive constant and $\mathcal{L}$ follows a Lamperti distribution of parameter $\nu$, as in Definition \ref{Definition of Lamperti distribution}.
    \item  The speed increases with $\Lam$ but at the same time each flight time decreases, such that the free path remains unchanged.
\end{enumerate}
We shall denote the random flight process of Assumptions \ref{Isotropic: assumptions Model 2} by
\begin{align*}
        \l \Xcl,  \Vcl\r,  \qquad \nu \in (0,1].
\end{align*}
In this setting, the flight times $\lg J_n^{(\nu)},\ n\geq1 \rg$ are dependent and they all have the same Mittag-Leffler distribution, so that $\mathbb{E}J_n^{(\nu)} =\infty$ for each $n\geq1$. Note that for $\nu = 1$ one re-obtains the isotropic Markovian random flight of Section \ref{Markovian random flight}.

The process is non-Markovian but, as shown in the following theorem, it is equal in distribution to a mixture of Markovian random flights of the type defined in Section \ref{Markovian random flight}.
In the same theorem we also determine the governing equation of $\l \Xcl, \Vcl \r$ which involves fractional power of the operators appearing in the linear Boltzmann equation \eqref{Boltzmann equation}.

We will use the family of operators $\lg\opmoddue_t\rg_{t\geq0}$ defined by
\begin{align}
    \opmoddue_t h (x,v) &:= \mathds{E}^{(x,v)} \lq h \l \Xcl,  \Vcl\r  \rq \qquad h \in  C_0\l \mathbb{R}^d \times S^{d-1} \r. \label{ooo} 
\end{align}
Specifically, we will consider the Boltzmann semigroup $\lg \sgM_t^{(c,\lambda)} \rg_{t\geq0}$ as defined in Equation \eqref{semigruppo Boltzmann} with representation as in Theorem \ref{Isotropic: teorema rappresentazione semigrouppo Boltzmann}. Then, by applying the Phillips formula \eqref{defGnu} to it, we are able to properly define the fractional power of the Boltzmann generator \eqref{Boltzmann generator} as

\begin{align} \label{Isotrpoic: fractional Boltzmann operator modello 1}
    -\bigg ( -c\, v\cdot \nabla -\lambda (L-\mathcal{I}) \bigg )^\nu h := \int_0^{\infty} \l \sgM_s^{(c,\lambda)} h - h \r \frac{\nu s^{-\nu - 1}}{\Gamma(1 - \nu)}ds, \qquad h\in D,
\end{align}
where $D$ is the domain of the Boltzmann generator as in Equation \eqref{Isotropic: dominio del generatore del semigruppo markoviano}.


\begin{te} \label{Model 2: teorema equazione Boltzmann frazionaria e uguaglianza in distribuzione}
    Let  $\l X^{(c,\lambda)}_t, V^{(c ,\lambda)}_t \r$ be the Markovian random flight defined in Section  \ref{Markovian random flight} and let $\mathcal{L}$ be a Lamperti random variable. Then
    \begin{align} \label{mixture Model 2}
        \l \Xcl,  \Vcl \r \overset{\text{d}}{=} \l X^{(c ,\lambda)}_{\mathcal{L}t}, V^{(c ,\lambda ) }_ { \mathcal{L}  t} \r.
    \end{align}
   Moreover, for $h \in  \text{D}$,   the function $ t \mapsto \opmoddue_t h$ defined in Equation \eqref{ooo} is the unique solution of the (abstract) fractional Boltzmann equation
    \begin{align}                           \frac{\partial ^\nu}{\partial   t^\nu} g(t) = -\bigg (-c\, v\cdot \nabla  -\lambda (L-\mathcal{I}) \bigg )^\nu g(t)   \notag %\label{fbe}
    \end{align}
    subject to $g(0)= h$, in the sense of Theorem \ref{teorema equazione}, Item (4).
\end{te}
\begin{proof}
Under the Assumptions \ref{Isotropic: assumptions Model 2}, the isotropic transport process in Definition \ref{Definizione isotropic transport process generica} reads

\begin{align*}
    \l \begin{matrix}
        \Vcl \\  \Xcl
    \end{matrix} \r &= 
    \l \begin{matrix}
        v_m \\  
        x + \sum_{k = 1}^{m} \mathcal{C}v_{k-1}J_k^{(\nu)} + \mathcal{C} v_m\l t - \sum_{k = 1}^{m} J_k^{(\nu)} \r
    \end{matrix} \r
    \qquad
    \sum_{k = 1}^{m} J_k^{(\nu)} \leq t < \sum_{k = 1}^{m+1} J_k^{(\nu)}
\end{align*}
for $m \geq 0$,
which can compactly be re-written as
\begin{align*}
\l \begin{matrix}
        \Vcl \\  \Xcl
    \end{matrix} \r  = 
    \sum_{m = 0}^{+\infty} \l \begin{matrix}
        v_m \\  
        x + \sum_{k = 1}^{m} \mathcal{C}v_{k-1}J_k^{(\nu)} + \mathcal{C} v_m\l t - \sum_{k = 1}^{m} J_k^{(\nu)} \r
    \end{matrix} \r 
    \mathds{1}_{\lg \sum_{k = 1}^{m} J_k^{(\nu)} \leq t < \sum_{k = 1}^{m+1} J_k^{(\nu)} \rg}.
\end{align*}

From Equation \eqref{Random flight 2: uguaglianza in distribuzione C e Js} we have, for each $t\geq0$,
\begin{align*}
    \l \begin{matrix}
        \Vcl \\  \Xcl
    \end{matrix} \r \overset{d}{=} 
    \l \begin{matrix}
        v_m \\  
        x + \sum_{k = 1}^{m} cv_{k-1}J_k + c v_m\l \mathcal{L}t - \sum_{k = 1}^{m} J_k \r
    \end{matrix} \r
    \qquad
    \sum_{k = 1}^{m} J_k \leq \mathcal{L}t < \sum_{k = 1}^{m+1} J_k
\end{align*} 
and the equality in distribution of Equation \eqref{mixture Model 2} follows. 

Hence we can re-write \eqref{ooo} as 
\begin{align*}
    \opmoddue_t h (x,v)&= \int _0^{\infty} \mathds{E}^{(x,v)} \lq h  \l X^{(c,\lambda )}_{lt}, V^{(c,\lambda)}_{lt} \r \rq \, \mathpzc{l}(dl)   \\
    & \notag  = \int _0^{\infty} \sgM^{(c, \lambda )}_{lt} h (x,v) \,  \mathpzc{l}(dl)
\end{align*}
where $\sgM_t ^{(c,\lambda)}$ is the Markovian semigroup defined in Equation \eqref{semigruppo Boltzmann}. We recall that the family $\lg \sgM_t^{(c, \lambda)} \rg _{t\geq0}$ is a Feller semigroup, whose generator  \eqref{Boltzmann generator} has domain $D$, hence $\opmoddue_t$ is an averaged Feller semigroup of the form of Equation \eqref{bb}.
We fall under the assumptions of Theorem \ref{teorema equazione} from which the result immediately follows.
\end{proof}

\begin{os} \label{Model 2: Remark sull'uguaglianza in distribuzione del ranom flight}
    By using analogous arguments as in the above proof, recalling Equation \eqref{Random flight 2: uguaglianza in distribuzione C e Js} and observing that each $ \frac{1}{\Lam} J_i$  follows an exponential distribution of random mean $1 / (\lambda \Lam)$,  we also get
 \begin{align} 
        \l \Xcl,  \Vcl \r \overset{\text{d}}{=} \l X^{(c \mathcal{L},\lambda \mathcal{L})}_t, V^{(c \mathcal{L},\lambda \mathcal{L})}_t \r. \notag
    \end{align}
    The dependence of Equation \eqref{Random flight 2: densità congiunta C e Js} guarantees that each flight time is inversely proportional to the speed; therefore, the length of each free path remains constant under the scaling with the Lamperti variable.
\end{os}

\begin{os}
    Under Assumptions \ref{Isotropic: assumptions Model 1}, the random variable $\Xl$ is supported on a ball centered at the starting position $x$ of radius $ct$, and thus the mean square displacement, computed in  Proposition \ref{Model 1: proposition on mean squared  displacement}, is finite. 
        Instead, in the case of  Assumptions \ref{Isotropic: assumptions Model 2} the speed is random with a distribution supported on $(0 +\infty)$, and thus the radius of the ball can assume any positive value. It follows that the random position $\Xcl$ is not supported anymore on a set with finite measure. Furthermore, from the  mean squared  displacement of the Markovian random flight in Equation \eqref{Markovian: mean squared  displacement random flight} and using the representation of the process in Theorem \ref{Model 2: teorema equazione Boltzmann frazionaria e uguaglianza in distribuzione}, it is not hard to see that the random flight is superdiffusive with infinite  mean square displacement.
\end{os}



\subsubsection{Other types of fractional Boltzmann equations}
In some recent papers, other fractional Boltzmann equations have been studied. 
In \cite{RicciutiToaldo}, the authors considered  a semi-Markov transport process. Here, the flight times are i.i.d. Mittag-Leffler random variables, i.e. the counting process is a renewal process, also known as fractional Poisson process, see \cite{Beghin, Dicrescenzo, MainardiGorenfloScalas}.
Such a transport process is governed by the fractional Boltzmann equation
$$ \l \frac{\partial }{\partial t}-cv\cdot \nabla _x \r^\nu g(x,v,t) -\frac{t^{-\nu}}{\Gamma (1-\nu)}h(x+cvt,v) =  \lambda (L-\mathcal{I})  g(x,v,t)$$
under the condition $g(x,v,0)=h(x,v)$. The authors also proved that a suitable scaling limit leads to an anomalous diffusive process with continuous trajectories and finite velocity, say $\lg \widetilde{W}_t,\ t\geq 0\rg$, having a super-diffusive behavior, with the mean-squared  displacement growing as $\mathbb{E}\left| \widetilde{W}_t\right|_e^2\sim Ct^2$, $C>0$.

Another fractional Boltzmann equation with the form
\begin{align} 
\frac{\partial ^\nu}{\partial t ^\nu} g(x,v,t)=  c\, v\cdot \nabla _x  g(x,v,t)+\lambda (L-\mathcal{I}) g(x,v,t)
\end{align}
has been considered in \cite{Garra}.
In this case, the transport process is constructed as the Markovian random flight, time-changed with the inverse of a $\nu$-stable subordinator.


\subsection{Boltzmann-Grad approximation and anomalous diffusion} \label{Boltzmann-Grad approximation and anomalous diffusion model 2}

We here show that the same anomalous diffusion as in Section \ref{Diffusion model 1}, i.e., the Mittag-Leffler anomalous-diffusion process, can approximate a
different Lorentz model. We indeed  consider a Lorentz process with a Poissonian distribution of obstacle centres, defined as in Gallavotti \cite{Gallavotti}, except for the fact that the speed of the particle is here assumed to be random. Under a Boltzmann-Grad procedure, this process is proved to converge to the non-Markovian random flight defined as in Model 2. A further scaling limit leads to the Mittag-Leffler anomalous-diffusion process.

The speed of such Lorentz process is assumed to follow a Lamperti distribution as in Definition \ref{Definition of Lamperti distribution}, which is characterized by a power law decaying density. From a physical point of view this means that the gas particles are not in thermal equilibrium, in which case the speed has an exponentially decaying distribution. Indeed, it is known that a perfect gas in thermal equilibrium has a Maxwell-Boltzmann distribution for the particle velocities.

To fix the notation, consider a Poisson point process with intensity $\rho \in (0, \infty)$ for the obstacle centres. All the obstacles are spheres of radius $R$. We shall indicate with $\l \mathcal{X}^c_t,\mathcal{V}^c_t \r$ the Lorentz process as in Gallavotti \cite{Gallavotti}. The particle speed is given by the constant $c>0$, as indicated by the superscript. It is known that under the Boltzmann Grad limit
\begin{align} \label{Model 2: BG limit for Poisson}
    \rho \to \infty \qquad R \to 0 \qquad  \rho c \pi R^2 \to \lambda \in (0,\infty),
\end{align}
we have that
\begin{align}
    \l \mathcal{X}^c_t, \mathcal{V}^c_t \r   \overset{d}{\to} \l X_t^{(c, \lambda)}, V^{(c, \lambda)}_t \r \label{Model 2: Convergenza al random flight markovian Gallavotti}
\end{align}
 where $\l X^{(c, \lambda)}, V^{(c, \lambda)} \r$ is the Markovian random flight recalled in Section \ref{Markovian random flight}.

Now, consider another Lorentz process defined analogously as by Gallavotti \cite{Gallavotti}, where the particle speed is given by $\mathcal{C}= c \Lam $, being $\mathcal{L}$ a Lamperti random variable. It can be  proved that the free-flight time distribution has infinite mean analogously to what happens in Lemma \ref{Distribuzione free flight time o tempo di volo}.
For this new process, let us denote the position of the particle at time $t$ by $ \mathcal{X}_t^{(2)}$  and the unit velocity vector at time $t$, i.e. the direction of the particle at time $t$, by $ \mathcal{V}_t^{(2)}$.   We call $\l \X^{(2)}, \V^{(2)} \r := \lg \l \X^{(2)}_t, \V^{(2)}_t \r,\ t\geq0 \rg$ this Lorentz process in $\mathbb{R}^3 \times S^2$, with initial data $\l \X_0^{(2)}, \V_0^{(2)} \r$. The superscript indicates that this is the second Lorentz model considered in this paper. As in Section \ref{Sec: The Boltzmann-Grad limit modello 1} we denote 
 $P^{(x,v)} \l \cdot \r := P \l \cdot | \ \mathcal{X}_0^{(2)} = x, \mathcal{V}_0^{(2)} = v \r$. Under any $P^{(x,v)}$, we can write
\begin{align}
    \l \X^{(2)}_t, \V^{(2)}_t \r \overset{d}{=} \l \mathcal{X}^{ c \Lam }_t, \mathcal{V}^{ c \Lam }_t \r , \qquad \forall t\geq0 .\label{zzz}
\end{align}
This Lorentz process also depends on the parameters $\rho$ and $\nu$, and on the size of the obstacles $R$. Note that here the dependence on $\nu$ is only due to the random speed of the particle, being the random field Poissonian. As in the previous section, to simplify the notation, we will not make this dependence explicit.  Once again, for $\nu=1$, the speed is constant since $\mathcal{L}=1$ almost surely, and such Lorentz process coincides with that of Gallavotti's model. 
\begin{te}
Consider the Lorentz process $\l \X^{(2)}, \V^{(2)} \r$ defined above.
Under the Boltzmann-Grad limit  \ref{Model 2: BG limit for Poisson} we have \begin{align*}
    P^{(x,v)} \l \X^{(2)}_t\in dx', \V^{(2)}_t \in dv' \r \to \mathds{P}^{(x,v)} \l \Xcl  \in dx', \Vcl  \in dv' \r
\end{align*}
weakly, for all $t>0$ and for all $(x,v) \in \mathbb{R}^3 \times S^2$, where the limit process is the random flight defined in Section \ref{Subsection: Random flight Model 2}.
\end{te}
\begin{proof}
Let us write
\begin{align*}
    E^{(x,v)} h\l \X^{(2)}_t, \V^{(2)}_t \r  = \int _{S^2} \int _{B_{ct}(x)} h(x', v') P^{(x,v)} \l \X^{(2)}_t \in dx', \V^{(2)}_t \in dv' \r.
\end{align*}
where $B_{ct}(x)$ indicates the ball centered in $x$ of radius $ct$.
To get the statement, we shall prove that
\begin{align}
    \lim _{R\to 0} E^{(x,v)}h\l \X^{(2)}_t, \V^{(2)}_t \r  = E^{(x,v)} h \l X^{(c \mathcal{L},\lambda \mathcal{L})}_t, V^{(c \mathcal{L},\lambda \mathcal{L})}_t \r \qquad \forall \, \,\,h\in C_b(\mathbb{R}^3\times S^2),  \label{Model 2: Val atteso di h(pos ,vel)}
\end{align}
 where $\l X^{(c, \lambda)}, V^{(c, \lambda)} \r$ is the Markovian random flight recalled in Section \ref{Markovian random flight} and the thesis will follow from the representation of the second random flight as in Remark \ref{Model 2: Remark sull'uguaglianza in distribuzione del ranom flight}.

Specifically, we have from Equation \eqref{zzz}
\begin{align*}
    \lim _{R\to 0} E^{(x,v)}h\l \X^{(2)}_t, \V^{(2)}_t \r  &= \lim_{R\to0} E^{(x,v)}h\l \X_t^{ c \Lam }, \V_t^{ c \Lam } \r \\
    &= \lim_{R\to0} \int_0^{\infty} \mathds{E}^{(x,v)}h\l \X_t^{l c}, \V_t^{l c} \r  P\l \Lam \in dl \r.
\end{align*}
Now we observe that $h$ is bounded and so is the expected value. Using the dominated convergence theorem in the previous Equation then yields
\begin{align*}
     \int_0^{\infty} \l \lim_{R\to0} \mathds{E}^{(x,v)}h\l \X_t^{cl}, \V_t^{cl} \r \r P\l \Lam \in dl \r = \int_0^{\infty} \mathds{E}^{(x,v)}h\l X_t^{(cl, \lambda l)}, V_t^{(cl, \lambda l)} \r P\l \Lam \in dl \r
\end{align*}
where we used Equations \eqref{Model 2: BG limit for Poisson} and \eqref{Model 2: Convergenza al random flight markovian Gallavotti}, i.e. the same convergence theorem of Gallavotti's model, where the speed $c$   is replaced by $cl$ and hence $\lambda$ is replaced by $\lambda l$. The equality \eqref{Model 2: Val atteso di h(pos ,vel)} immediately follows.
\end{proof}
In the following theorem we prove that under an appropriate scaling limit the random flight of model 2 converges to the same anomalous diffusion as in Section \ref{Diffusion model 1}.

\begin{te}
Let $W$ be a Mittag-Leffler anomalous-diffusion process as in Definition \ref{Definition: anomalous diffusion}. Let $B$ be the corresponding Brownian motion, in the sense of Proposition \ref{Convergence model 1: ugualianza fdd del mb lampertizzato}. Then, under the scaling limit
\begin{align}
    c\to \infty \qquad \lambda \to \infty \qquad \frac{c^2}{\lambda} = 1 \label{Model 2: diffusive limit}
\end{align}
we have that
\begin{align*}
     \lg X_{(2)}^{\nu}(t)\rg \overset {fdd}{\longrightarrow}\{W_t\} .
\end{align*}
\end{te}


\begin{proof}
Without loss of generality, we shall put $c^2 = \lambda $ and consider the one-variable limit as $c\to\infty$.
The proof is based on the representation in Theorem \ref{Model 2: teorema equazione Boltzmann frazionaria e uguaglianza in distribuzione}. Firstly, we observe that
\begin{align*}
   \mathds{P}^{(x,v)}\l X_{(2)}^{\nu}(t_1) \in A_1,\ldots, X_{(2)}^{\nu}(t_n) \in A_n \r 
    =  \int_{0}^{\infty}\mathds{P}^{(x,v)} \l X^{(c,\lambda)}_{l t_1}\in A_1,\ldots, X^{(c,\lambda)}_{l t_n}\in A_n \r \mathpzc{l}(dl)
\end{align*}
where $A_i$ are continuity sets, $i=1,\ldots,n$, $n\geq1$. We now apply the diffusive limit \eqref{Model 2: diffusive limit} to both members of the above equation. By the dominated convergence theorem, 

\begin{align*}
  &  \lim_{c\to\infty} \mathds{P}^{(x,v)}\l X_{(2)}^{\nu}(t_1) \in A_1,\ldots, X_{(2)}^{\nu}(t_n) \in A_n \r\notag \\ = &\lim_{c\to\infty} \int_{0}^{\infty}\mathds{P}^{(x,v)} \l X^{(c,\lambda)}_{l t_1}\in A_1,\ldots, X^{(c,\lambda)}_{l t_n}\in A_n \r \mathpzc{l}(dl) \\
    =& \int_{0}^{\infty} \lq \lim_{c\to\infty} \mathds{P}^{(x,v)} \l X^{(c,\lambda)}_{l t_1}\in A_1,\ldots, X^{(c,\lambda)}_{l t_n}\in A_n \r \rq \mathpzc{l}(dl) \\
    =&  \mathbb{P}^x\l B_{t_1 \Lam} \in A_1,\ldots, B_{t_n \Lam}  \in A_n \r
\end{align*}
where we used Proposition \ref{limite diffusivo classico} with $D = 1$.
Finally, by Proposition \ref{Convergence model 1: ugualianza fdd del mb lampertizzato} we get 
\begin{align*}
    \lim_{c\to\infty} \mathds{P}^{(x,v)}\l X_{(2)}^{\nu}(t_1) \in A_1,\ldots, X_{(2)}^{\nu}(t_n) \in A_n \r = \mathbb{P}^x\l W_{t_1} \in A_1,\ldots, W_{t_1} \in A_n \r.
\end{align*}
\end{proof}














