\section{Existence of Mittag-Leffler point process} \label{Appendix: Existence of Mittag-Leffler point process}
As a first step, we demonstrate the existence of \(\Pi\) on finite Borel subsets of \(\mathbb{R}^3\).

\begin{lem}
\label{lemmaexistfinite}
    Let $S$ be a Borel set of $\mathbb{R}^3$ with finite Lebesgue measure $|\cdot|$: $|S|<+\infty$. Then define
        \begin{align}
        \Pi_{S}  := \sum_{k=1}^{\ef} \delta_{C_k}
    \end{align}
    where $\lg C_k \rg_{k \in \lg 1, \ldots, \ef \rg}$ is a sequence of i.i.d. r.v.'s uniform on $S$ and independent of $\ef$ which, in its turn, is a r.v. with a fractional Poisson distribution
    \begin{align}
        P \l \ef = n \r \, = \, \frac{1}{n!} \l \rho |S| \r^n (-1)^n \mathcal{M}_\nu^{(n)} \l -\rho^\nu |S|^\nu \r,
    \end{align}
    where $\rho \in \mathbb{R}^+$.
 Then $\Pi_S$ is a measure as in Definition \ref{Fractional Poisson field} with $\mu(\cdot) = |\cdot \cap S|/ |S|$.
\end{lem}
\begin{proof}
   We show that $\Pi_{S}$ defined as above is a random measure that satisfies the Definition \ref{Fractional Poisson field} for $\mu = |\cdot \cap S|/|S|$. Hence, denoting by $\Pi_{S}^\prime$ a random measure as in Definition \ref{Fractional Poisson field}, we use \cite[Corollary 10.1]{kallenberg} and thus we show that
   \begin{align}
       E e^{-\Pi_{S} f} = E e^{-\Pi_{S}^\prime f} 
   \end{align}
   for any $f$ positive, continuous with compact support. We have that
   \begin{align}
       E e^{-\Pi_{S} f} \, = \,& E e^{-\sum_{k=1}^{\ef} f (C_k)} \, = \, E \l E e^{-f(C_1)} \r^{\ef} \notag \\
       = \, & \sum_m \l \frac{1}{|S|}\int_{S} e^{-f(s)} ds  \r^m P \l \ef = m \r \notag \\
       = \, & \sum_m \l \frac{1}{|S|}\int_{S} e^{-f(s)} ds  \r^m \frac{1}{m!}   \l |S|\rho \r^m (-1)^m \mathcal{M}_\nu^{(m)} \l -\l |S|\rho \r^\nu \r \notag \\
       = \, & \int_0^{+\infty} \sum_m \l \frac{1}{|S|}\int_{S} e^{-f(s)} ds  \r^m \frac{l^m(\rho|S|)^m}{m!}e^{-l\rho |S|} \mathpzc{l}(dl) \notag \\
       = \, & \int_0^{+\infty }e^{- l|S|\rho\frac{1}{|S|}\int_{S}\l 1- e^{-f(s)} \r ds } \mathpzc{l}(dl) \notag \\
       = \, & \mathcal{M}_\nu \l -\rho^\nu \l \int_{S} \l 1-e^{-f(s)} \r ds \r^\nu \r,
   \end{align}
   where $l$ is the realisation of a Lamperti random variable $\mathcal{L}$ of parameter $\nu$.
   Now, take a simple function $f = \sum_j a_j \mathds{1}_{A_j}$. Then we have that
   \begin{align}
       E e^{-\Pi_{S}^\prime f} \, &= \, E e^{- \sum_j a_j \Pi_{S}^\prime \mathds{1}_{A_j}} \, = \, E \prod_j e^{- a_j \Pi_{S}^\prime \mathds{1}_{A_j}} = \notag \\
        &\sum_{k_1 \cdots k_j}  \prod_j  \frac{1}{k_1! \cdots k_j!}e^{-a_j k_j } \rho^{k_j} \l |A_j \cap S|\r^{k_j} (-1)^{\sum_j k_j} \mathcal{M}_\nu^{\l \sum_j k_j \r} \l - \rho^\nu \l \sum_j \l |A_j \cap S| \r^{k_j} \r^\nu \r \notag \\
       &= \sum_{k_1 \cdots k_j} \prod_j \frac{1}{k_1! \cdots k_j!}e^{-a_j k_j} \rho^{k_j} \l |A_j \cap S| \r^{k_j} \int_0^{+\infty} e^{-\rho \sum_j \l |A_j \cap S|\r^{k_j} s } s^{\sum_jk_j} (-1)^{\sum_j k_j} \mathpzc{l}(ds) \notag \\
   & = \int_0^{+\infty} e^{-s\rho \sum_{j} |A_j \cap S| \l 1-e^{-a_j} \r} \mathpzc{l}(ds) = \mathcal{M}_\nu \l -\rho^\nu \l \sum_j |A_j \cap S| \l 1-e^{-a_j} \r \r^\nu \r \notag \\
    & = \mathcal{M}_\nu \l -\rho^\nu \l  \int_{S } \l 1-e^{-f(s)} \r ds \r^\nu \r .    \label{simplefunction}
   \end{align}
   Pick now $f$ such that $f_k \uparrow f$ for $f_k$ simple. Then, by monotone convergence we get that $\Pi_{S}^\prime f_k \uparrow \Pi_{S}^\prime f$ as well as
   \begin{align}
%       |S|^{-1} \int_{S} \l 1-e^{-f_k(s)} \r ds \uparrow  |S|^{-1} \int_{S} \l 1-e^{-f(s)} \r ds.
\int_{S} \l 1-e^{-f_k(s)} \r ds \uparrow  \int_{S} \l 1-e^{-f(s)} \r ds.
   \end{align}
Hence, by dominated convergence we obtain $ E e^{-\Pi_{S}^\prime f}= E e^{-\Pi_{S} f}$.
\end{proof}
% \begin{lem}
%     Let $B_n$ be a partition of $\mathbb{R}^3$ such that $|B_n|<+\infty$ for any $n$. Define
%     \begin{align}
%         \Pi_{B_n}  := \sum_{k=0}^{\ef} \delta_{C_k}
%     \end{align}
%     where $C_k$, $k=1, 2, \cdots$ is a sequence of i.i.d. r.v.'s uniform on $B$ independent of $\ef$, i.e, a r.v. with the distribution of the counting process $\ef$ at time $|B|$. Then $\sum_n \Pi_{B_n}$ is a measure as in Definition \ref{Fractional Poisson field} for $S = \mathbb{R}^3$ and $ \mu(B) = |B|$.
% \end{lem}
It turns out that $\Pi$ is a Cox process in the sense of \cite[Page 180]{kallenberg}. Take a random measure on $(\mathbb{R}^3, \mathcal{B}(\mathbb{R}^3))$, say $\Xi$. A point process $\Pi$ on $\mathbb{R}^3$ is said to be a Cox process directed by $\Xi$ if it is conditionally Poisson with the intensity $\Xi$, i.e., $\mathbb{E}(\Pi \mid \Xi) = \Xi$ a.s..
\begin{lem}
\label{lemmarestriction}
Define the measure on $\mathcal{B}(\mathbb{R}^3)$ as $\Xi (\cdot)\coloneqq \mathcal{L}\rho | \cdot |$ where $\mathcal{L}$ is a Lamperti random variable and $\rho \in \mathbb{R}^+$.
A random measure on $\l \mathbb{R}^3, \mathcal{B} (\mathbb{R}^3), |\cdot| \r$ as in Definition \ref{Fractional Poisson field} on $\mathbb{R}^3$ is a Cox point process directed by $\Xi$. The restriction of $\Pi$ on a Borel set $B$ with $|B|<+\infty$ is a random measure of the same type on $S=B$ and thus it has the representation given in Lemma \ref{lemmaexistfinite}.
\end{lem}
\begin{proof}
Denote by $\mathcal{P}^\xi$ a Poisson random measure with the intensity $\xi(\cdot)$, for a measure $\xi (\cdot)$ on $\mathcal{B}(\mathbb{R}^3)$. Use \cite[Corollary 10.1]{kallenberg} to see that $\Pi$ has the same distribution as $\mathcal{P}^\Xi$ where $\Xi$ is independent of $\mathcal{P}^\xi$. Indeed note that, for any positive $f$ continuous with compact support, we have that
    \begin{align}
        E e^{-\Pi f} \, = \, E e^{-\mathcal{P}^\mathcal{L} f} \, = \, \int_0^{+\infty} E e^{-\mathcal{P}^sf} \mathpzc{l}(ds).
    \end{align}
    Observe that $\mathcal{P}^s$ is, for any $s>0$ fixed, a Poisson random measure with intensity $\rho| \cdot |$. Then
    \begin{align}
     E e^{-\Pi f} \, = \, \int_0^{\infty} e^{- l\rho \int_{\mathbb{R}^3}\l 1-e^{-f(s)} \r ds} \mathpzc{l}(d l)\, = \, \mathcal{M}_{\nu}\l -\rho^\nu \int_{\mathbb{R}^3} \l 1-e^{-f(s)} \r ds \r.
    \end{align}
    For $\Pi^\prime$ to be a measure as in Definition \ref{Fractional Poisson field} we can compute the Laplace functional for a simple function $f$ as in \eqref{simplefunction} and then the Cox property follows from monotone and dominated convergence. It follows that
    \begin{align}
        \mathbb{E} \left[ \Pi \mid \Xi \right] \, = \mathbb{E} \left[ \mathcal{P}^\Xi \mid \Xi \right]\, = \, \Xi 
    \end{align}
    where we used the independence of $\Xi$ and $\mathcal{P}^\xi$ together with the freezing Lemma (see, e.g., \cite[Lemma A.3]{schillingBM}).


    Consider now the restriction $\Pi|_B$, we have that, for any $f$ positive, continuous and compactly supported that
    \begin{align}
        E e^{-\Pi|_B f} \, = \, \mathcal{M}_\nu \l -\rho^\nu \l \int_B \l 1-e^{-f(s)} \r ds\r^\nu \r
    \end{align}
    proceeding as in \eqref{simplefunction} and using monotone and dominated convergence.
\end{proof}


\section{Details on the proof of the Boltzmann-Grad limit} \label{Appendix: appendice sulla convergenza dominata}
Following Gallavotti's intuition, the tube-like flow is the union of non-disjoint cylinders, and its volume is given by
\begin{align}
    \left| \Theta\l \underline{\widetilde{\tau}}, \underline{\widetilde{v}} \r \right| = \pi R^2ct+o(R^2). \label{Approssimazione volume del tubo di flusso}
\end{align}

We note that by Equation \eqref{BG limit}  $\rho ^n c^n \pi^n R^{2n} = \lambda^n$. Now, let us call $\Theta := \Theta\l \underline{\widetilde{\tau}}, \underline{\widetilde{v}} \r$ and

\begin{align*}
    a_n(R) :&= \int _{0< \tau _1 < \tau _2 < \dots < \tau_n < t} \int _{(S^2)^{n}}(-\lambda)^n h\l  \Xt(\underline{\widetilde{\tau}}, \underline{\widetilde{v}}),  \Vt(\underline{\widetilde{\tau}}, \underline{\widetilde{v}})\r \mathcal{M}^{(n)}_{\nu}\l- \rho^{\nu} \left| \Theta \right|^{\nu}\r \\
    &\qquad\qquad\qquad\qquad\qquad\qquad \mu(dv_1)\dots \mu(dv_n)\,  d\tau _1 \dots d\tau _n .
\end{align*}

We need it to be absolutely dominated by $b_n$ for each $n\geq 1$, the last one being independent of $R$ and summable.

Firstly, we observe that
\begin{align*}
    \left| h\l  \Xt(\underline{\widetilde{\tau}}, \underline{\widetilde{v}}),  \Vt(\underline{\widetilde{\tau}}, \underline{\widetilde{v}})\r \right| < \zeta_1 \qquad \text{for some } \zeta_1\in (0,\infty). 
\end{align*}

Moreover, using the notation for the derivative of the Mittag-Leffler function in Equation \eqref{Derivative of Mittag Leffler function} we get

\begin{align*}
    &\int _{0< \tau _1 < \tau _2 < \dots < \tau_n < t} \int _{(S^2)^{n}} \bigg |\mathcal{M}^{(n)}_{\nu}\l- \rho^{\nu} \left| \Theta  \right|^{\nu}\r \bigg |\, \mu(dv_1)\dots \mu(dv_n)\,  d\tau _1 \dots d\tau _n \\
    &= \int _{0< \tau _1 < \tau _2 < \dots < \tau_n < t} \int _{(S^2)^{n}} \bigg |  \l \frac{d}{d\l\rho |\Theta| \r} \r^n  \int_0^{\infty}   e^{-\rho |\Theta| l}P(\Lam \in dl) \bigg |\, \mu(dv_1)\dots \mu(dv_n)\,  d\tau _1 \dots d\tau _n.
\end{align*}

We now observe that the correction term in the approximation of the volume of the tube-like flow \eqref{Approssimazione volume del tubo di flusso} is negative. Moreover, for $R$ sufficiently small, we can write 

\begin{align*}
    \lambda t + \rho \, o \l R^2 \r \geq \frac{\lambda t}{2} \implies e^{-\l \lambda t + \rho \, o \l R^2\r  \r} \leq e^{-\frac{\lambda t}{2}}.
\end{align*}

Then, by using dominated convergence, the above equation reads
\begin{align*}
    &\int _{0< \tau _1 < \tau _2 < \dots < \tau_n < t} \int _{(S^2)^{n}} \int_0^{\infty}   l^n e^{- l \l \lambda t + \rho \, o \l R^2\r \r} P(\Lam \in dl) \mu(dv_1)\dots \mu(dv_n)\,  d\tau _1 \dots d\tau _n \\
    &\leq \int _{0< \tau _1 < \tau _2 < \dots < \tau_n < t} \int _{(S^2)^{n}}
     \int_0^{\infty}   l^n e^{-l \frac{\lambda t}{2} }  P(\Lam \in dl) \mu(dv_1)\dots \mu(dv_n)\,  d\tau _1 \dots d\tau _n \\
    &= \frac{t^n}{n!}  \int_0^{\infty}   l^n e^{-\frac{\lambda t}{2} l}  P(\Lam \in dl),
\end{align*}

where the inequality holds for sufficiently small $R$.
Finally, 

\begin{align*}
    |a_n(R)| \leq \zeta_1 \frac{1}{2^n}\int_0^{\infty} \frac{\l \lambda l t \r^n}{n!} e^{-\lambda t l} P(\Lam \in dl) =: b_n
\end{align*}
and 
\begin{align*}
    \sum_{n\geq 1}b_n &= \sum_{n\geq1} \zeta_1 \frac{1}{2^n}\int_0^{\infty} \frac{\l \lambda l t \r^n}{n!} e^{-\lambda t l} P(\Lam \in dl) \\ &\leq \zeta_1 \int_0^{\infty}   e^{-\lambda t l} \l e^{\lambda tl } - 1  \r P(\Lam \in dl)\\
    &= \zeta_1 \l 1 - \int_0^{\infty} e^{\lambda l t} P\l \Lam \in dl \r \r < \infty.
\end{align*}




