  \centering
  \includegraphics[width=0.495\textwidth]{figs/cc_mutation_H0.pdf}
  \includegraphics[width=0.495\textwidth]{figs/ccsne_mutation_H0.pdf}
  \includegraphics[width=0.495\textwidth]{figs/cc_mutation_Om0.pdf}
  \includegraphics[width=0.495\textwidth]{figs/ccsne_mutation_Om0.pdf}
  \includegraphics[width=0.495\textwidth]{figs/cc_mutation_Ode0.pdf}
  \includegraphics[width=0.495\textwidth]{figs/ccsne_mutation_Ode0.pdf}
