 	\section{Characterization of isotropic kernels on \texorpdfstring{\(\real^\dims\)}{Rd} }
\label{sec:positive_definite}

The defining property of isotropic \shortkernels{} is the identity \(\kernel(Ux,Uy) = \kernel(x,y)\) for all $x,y\in \real^\dims, U\in O(\dims)$. The tuple \((x,y)\) may thus be characterized by the invariants
\[
	(\norm x,\norm y,\scal xy)
	\quad \text{or alternatively} \quad
	\bigl(\norm x,\norm y,\scal{\tfrac{x}{\|x\|}}{\tfrac{y}{\|y\|}}\bigr)~,
\]
leading to natural equivalence classes of tuples for isotropy.
In our main characterization result (Theorem \ref{thm: isotropy
characterization}) the third, spherical component
translates to Gegenbauer polynomials, see e.g.\ \citep{reimerGegenbauerPolynomials2003}, which were already used by
\citet{schoenbergPositiveDefiniteFunctions1942} to characterize the
\(O(\dims)\)-invariant \shortkernels{} on \(\sphere\).

We denote the Gegenbauer polynomial of index \(\lambda = (\dims-2)/2\) and
degree \(n\) by \(\uP_n\). In our characterizations we use the
\emph{normalized Gegenbauer polynomials} defined by\footnote{
    Note that \(|\uP_n(t)|\le \uP_n(1)\) and \(0<\uP_n(1)<\infty\), e.g.\@ \citep[][Eq.
    (2.16), (2.13)]{reimerGegenbauerPolynomials2003} .
}
\begin{equation}
    \label{eq: Gegenbauer polynomials}
    \uPnorm_n(t) := \begin{cases}
        \uP_n(t)/\uP_n(1) & \lambda < \infty
        \\
        t^n & \lambda = \infty.
    \end{cases}
\end{equation}
Note that the case \(\lambda=\infty\) can also be viewed as a limiting case.
Specifically, \citet[Lemma 1]{schoenbergPositiveDefiniteFunctions1942}
shows for any $t\in [-1,1]$ that \(\uPnorm_n(t)\) converges to \(t^n\) uniformly in \(n\) as
\(\lambda\to\infty\). In our setting, the index \(\lambda=(d-2)/2\)
is determined by the dimension \(\dims\). In high dimension \(\dims \gg 1\),
the set of isotropic \shortkernels{} \(\PDset_{O(\dims)}\) is therefore well approximated by
the isotropic \shortkernels{} in the space of sequences \(\real^\infty \equiv
\ell^2\), which have a more intuitive characterization in terms of standard monomials in
place of Gegenbauer polynomials. More specifically,
the isotropic \shortkernels{} ``valid in all finite dimensions'' coincide with the
isotropic \shortkernels{} on \(\ell^2\) (more details in Lemma \ref{lem: valid in all dimensions}).
For the interpretation of the following characterization it is therefore
often reasonable to assume \(\dims=\infty\).


\begin{theorem}[Characterization of isotropic positive definite \shortkernels]
    \label{thm: isotropy characterization}
    Let \(d \in \{2,3,\dots, \infty\}\) and \(\lambda = \tfrac{\dims-2}2\).
    For a continuous function \(\kernel\colon \real^\dims \times \real^\dims \to
    \complex\), the following assertions are
    equivalent:
    \begin{enumerate}[label={(\roman*)}]
        \item\label{it: positive, definite isotropic}
        The function $\kernel$ is an isotropic \pdkernel{} i.e.
        \[
            \kernel(x,y) = \kernel(Ux, Uy)
        \]
        for every linear isometry \(U\in O(\dims)\).
        \item\label{it: pos definite, weak representation}
        The function $\kernel$ is a \pdkernel{} and has the representation
        \[
            \kernel(x,y) = \kappa\bigl(\|x\|, \|y\|, \langle x, y\rangle\bigr)
        \]
        for a continuous \(\kappa\colon M \to \complex\) with \(M=\{ (r,s, \gamma) \in [0,\infty)^2 \times \real : |\gamma| \le rs\}\).
        \item\label{it: representation}
        The function $\kernel$ has the representation
        \begin{equation}
            \label{eq: kernel representation}
            \kernel(x,y)
            = \sum_{n=0}^\infty \alpha^{(\dims)}_n \bigl(\|x\|, \|y\|\bigr)
            \uPnorm_n\bigl(\bigl\langle \tfrac{x}{\|x\|}, \tfrac{y}{\|y\|}\bigr\rangle\bigr),
        \end{equation}
        where \(\alpha^{(\dims)}_n\colon [0,\infty)^2\to\complex\) are unique, continuous,
        \pdkernels, which are summable, i.e.
        \(\sum_{n=0}^\infty \alpha^{(\dims)}_n(r,r) < \infty\) for any \(r\in
        [0,\infty)\), and zero at the origin, i.e. 
        \begin{equation}
            \label{eq: zero in origin}
            \alpha^{(\dims)}_n(r,0) = \alpha^{(\dims)}_n(0,r) = 0
            \qquad \forall r \in [0,\infty),\; \forall n\ge 1.
        \end{equation}
        Here \eqref{eq: zero in origin} ensures that \eqref{eq: kernel representation} is well defined as the normalized Gegenbauer polynomials $\uPnorm_n$ are uniformly bounded by $1$ and $\uPnorm_0\equiv 1$.
\end{enumerate}
    The kernels $\alpha_n$ are real-valued if and only if $\kernel$ is real-valued.
    And for \(\dims <\infty\), the \shortkernels{} \(\alpha^{(\dims)}_n\) can be
    represented as
    \begin{align}
    	\label{eq:alpha_formula}
        \alpha^{(\dims)}_n(r,s)
        = \frac{\bigl\langle \kappa(r,s, rs\,\cdot), \uPnorm_n\bigr\rangle_\weight}{\|\uPnorm_n(\cdot)\|_w^2}
        = \frac{\int_{-1}^1 \kappa(r,s, rs\rho) \uPnorm_n(\rho)\weight(\rho) d\rho}{\|\uPnorm_n\|_w^2} ,
    \end{align}
    with weight function \(\weight(\rho) =(1-\rho^2)^{\lambda-\frac12}\)
    and inner product defined by 
    \[
        \langle f,g\rangle_\weight :=  \int_{-1}^1 f(\rho) g(\rho) \weight(\rho) d\rho .
    \]
\end{theorem}
The core idea of the proof of Theorem~\ref{thm: isotropy characterization}
(see appendix) is to translate
results about \pdkernels{} on \((0,\infty) \times \sphere\), independently
discoverd by \citet{guellaSchoenbergsTheoremPositive2019} and
\citet{estradeCovarianceFunctionsSpheres2019}, to a characterization of
isotropic \shortkernels{} on \(\real^\dims \setminus \{0\}\).


