For the interpretation of Theorem \ref{thm: isotropy characterization} we suggested the
assumption of \(\dims=\infty\). We made this suggestion because the isotropic kernels in \(\real^\infty\)
can be viewed as a limiting subset of the isotropic kernels in finite dimension. This observation
was already made by \citet{schoenbergPositiveDefiniteFunctions1942} and is explained in more
detail in the following remark.


\begin{remark}[Embedding]\label{rem:dimensional_hierarchy}
    Embedding of the finite dimensional spaces \(\real^\dims\) into the space of
    sequences \(\real^\infty:=\ell^2\)
	naturally results in
	\begin{equation}
		\label{eq: dimensional hierarchy}	
		\real^1 \subset \real^2 \subset\dots \subset \real^\infty.
	\end{equation}
    While the representation \(\kernel(x,y) = \kappa(\|x\|, \|y\|,
    \scal{x}{y})\) may be used to lift any isotropic kernel
	$\kernel \in \PDset_{O(\dims)}$ into any $\real^m$ for
	$m\in\nat\cup\{\infty\}$, this function is not necessarily positive definite
	for any \(m\). However, since any positive definite function remains positive
	definite on a subspace, \eqref{eq: dimensional hierarchy} implies the relation
    \begin{equation}
        \label{eq: pd subset relation}    
        \PDset_{O(1)}(\real) \supseteq \PDset_{O(2)}(\real^2) \supseteq \dots \supseteq \PDset_{O(\infty)}(\real^\infty).
		\qedhere
    \end{equation}
\end{remark}
The set of functions $\kappa(\|x\|,\|y\|,\scal xy)$ that result in \emph{positive definite} functions $\kernel(x,y)\equalDef \kappa(\norm x,\norm y,\scal xy)$ in all dimensions, is therefore the set
of isotropic kernels on the space of eventually zero sequences
\(\bigcup_{\dims\in \nat} \real^\dims\). However these functions coincide with the
positive definite kernels on the entire sequence space \(\ell^2\).
\begin{lemma}
	\label{lem: valid in all dimensions}
	If $\kernel(x,y) \equalDef \kappa(\norm x,\norm y,\scal xy)$ defines a \pdkernel{} on $\real^\dims$ for all $\dims\in\nat$, then it also defines a \pdkernel{} on $\real^\infty = \ell^2$, that is
	\[
	\textstyle
	\bigcap_{\dims \in \nat} \PDset_{O(d)}(\real^\dims) = \PDset_{O(\infty)} (\ell^2).
	\]
\end{lemma}

 	\section{Strict positive definiteness}
\label{sec: strict positive definite}

Recall that a \shortkernel{} \(\kernel\) on $\real^\dims$ is called strictly positive definite, if for any $m\in\nat$, distinct $x_1,\dots ,x_m\in\real^\dims$ and $c\in \complex^m\setminus\{0\}$ we have 
\begin{align*}
	\sum_{i,j=1}^m c_i \conj{c_j}\kernel(x_i, x_j) > 0.
\end{align*}
In this section we characterize the requirements for a continuous, isotropic
\pdkernel{} to have this stronger property.
\begin{theorem}[Characterization of isotropic \spdkernels]
    \label{thm:strictly_pos_def}
    Let \(\dims \in \{3,\dots, \infty\}\).  For a continuous isotropic \pdkernel{} \(\kernel\colon \real^\dims
    \times \real^\dims \to \complex\)  with representation as in Theorem~\ref{thm: isotropy
    characterization}, the following assertions are equivalent:
    \begin{enumerate}[label={(\roman*)}]
        \item\label{it: strict positive definite}
        The \shortkernel{} \(\kernel\) is strictly positive definite;
        \item\label{it: infinitely even and odd elements in set}
        \(\alpha_0^{(\dims)}(0,0)>0\), and
        for any \(m\in \nat\), distinct \(r_1,\dots, r_m\in (0,\infty)\) and \(c \in \complex^m\setminus\{0\}\)
        the set
        \[
            \Bigl\{
                n \in \nat_0 :
                c^\transpose \Bigl[\alpha^{(\dims)}_n(r_i, r_j)\Bigr]_{i,j=1}^m \conj{c} > 0
            \Bigr\}
        \]
        contains infinitely many even and infinitely many odd integers.
        \item\label{it: even and odd kernels strict pos. def.}
        \(\alpha_0^{(\dims)}(0,0)>0\), and for each \(\gamma \ge 0\) the even and odd \shortkernels{}
        \[
            \alpha_\gamma^e(r,s) := \sum_{2n \ge \gamma} \alpha_{2n}^{(\dims)}(r,s)
            \quad\text{and}\quad
            \alpha_\gamma^o(r,s) := \sum_{2n+1 \ge \gamma} \alpha_{2n+1}^{(\dims)}(r,s)
        \]
        are both strictly positive definite on \((0,\infty)\).
    \end{enumerate}
    Furthermore, the following statement is sufficient for strict positive definiteness:
    \begin{enumerate}[label={(\roman*)},resume]
        \item\label{it: infinitely many even and odd n strict pos. def.}
        \(\alpha_0^{(\dims)}(0,0)>0\), and \(\alpha_n^{(\dims)}\) is strictly positive
        definite on \((0,\infty)\) for infinitely many even and odd \(n\in \nat_0\).
    \end{enumerate}
    If \(\alpha_0^{(\dims)}(0,0) =0\) but all other requirements in \ref{it:
    infinitely even and odd elements in set}, \ref{it: even and odd kernels
    strict pos. def.}, \ref{it: infinitely many even and odd n strict pos. def.}
    are satisfied, then \(\kernel\) is strictly positive definite on
    \(\real^\dims\setminus\{0\}\). \ref{it: infinitely even and odd elements in
    set} and \ref{it: even and odd kernels strict pos. def.} without \(\alpha_0^{(\dims)}(0,0) > 0\)
    are also necessary for strict positive definiteness on \(\real^\dims\setminus\{0\}\).
\end{theorem}

A proof can be found in Section \ref{subsec:strictly-pos-def}.
For the proof of Theorem \ref{thm:strictly_pos_def} we again utilize the map
from \((0,\infty)\times \sphere\) to \(\real^\dims\setminus\{0\}\) and base our
results on those by
\citet{guellaSchoenbergsTheoremPositive2019}.
Note that we consider \(\sphere\) while they considered \(\sphere[\dims]\),
leading to an index shift. Since they had to single out
the case \(\dims=2\) case, we do so as well and the following result
covers this case.
\begin{theorem}[Isotropic strictly positive definite kernels for \(\dims=2\)] 
    \label{thm:strictly_pos_def_dim2}
    Let \(\kernel\colon\real^2 \times\real^2 \to \complex\) be a continuous isotropic \pdkernel{} with decomposition as in Theorem~\ref{thm:
    isotropy characterization}. Then \emph{necessary} conditions for
    strict positive definiteness include
    \begin{enumerate}[label={(\roman*)}]
        \item \(\alpha_0^{(2)}(0,0)>0\), and
        for any \(m\in \nat\), \(c \in \complex^m\setminus\{0\}\) and \(r_1,\dots, r_m\in (0,\infty)\)
        the set
        \[
            \Bigl\{
                n \in \integer :
                c^\transpose \Bigl[\alpha^{(2)}_{|n|}(r_i, r_j)\Bigr]_{i,j=1}^m \conj{c} > 0
            \Bigr\}
        \]
        intersects every full arithmetic progression\footnote{
            Recall, that a full arithmetic progression is a set of the form \((k \integer + m)\) with \(k\in \nat\) and \(m\in \{0,\dots k-1\}\).
        } in \(\integer\).

        \item \(\alpha_0^{(2)}(0,0)>0\), and for each full arithmetic progression \(S\) in \(\integer\)
        the \shortkernel{}
        \[
            (r,s) \mapsto \sum_{n\in S} \alpha^{(2)}_{|n|}(r,s) \qquad r,s\in (0,\infty).
        \]
        is strictly positive definite.
    \end{enumerate}
    and a \textbf{sufficient} condition for strict positive definiteness of \(\kernel\)
    is
    \begin{enumerate}[label={(\roman*)},resume]
        \item \(\alpha_0^{(2)}(0,0)>0\), and the set \(\{n \in \integer : \alpha_{|n|}^{(2)} \text{ is strictly positive definite}\}\)
        intersects every full arithmetic progression in \(\integer\).
    \end{enumerate}
\end{theorem} 	\section{Applications and examples}\label{sec: applications}

A survey of common kernel functions, whether 
implemented in scientific software libraries, e.g.\ \verb|KernelFunctions.jl|
\citep{galy-fajouJuliaGaussianProcessesKernelFunctionsjlV010652025},
or presented in foundational textbooks, e.g. \citep[Ch.\
4]{rasmussenGaussianProcessesMachine2006}, reveals that the vast
majority of canonical examples belongs to one of three categories
\begin{enumerate}[noitemsep]
	\item \textbf{stationary isotropic kernels}, i.e.\ functions
	of the distance \(\|x-y\|\),

	\item \textbf{dot product kernels}, i.e.\ functions of the inner product \(\langle x,y\rangle\),

	\item \textbf{specialized kernels} tailored for specific applications such as the
	\emph{neural network kernels}.
\end{enumerate}
Isotropic kernels jointly generalize the first two categories and
cover some specialized kernels, specifically the neural network kernels.
They can therefore serve as a unifying framework to avoid the separate treatment of
stationary isotropic kernels and dot product kernels
as in \citep{roosHighDimensionalGaussianProcess2021,amentScalableFirstOrderBayesian2022}.

In Section \ref{sec: stationary isotropic and dot product} we illustrate the
unification of stationary isotropic and dot product kernels with examples.
In Section \ref{sec: machine learning} we highlight the importance of isotropic kernels
for the theory of machine learning. We demonstrate that limiting neural network kernels
are isotropic but not stationary and therefore do not fall in any of the previous
kernel classes while our results do apply. We finish the section with well known explicit examples.

\subsection{Stationary isotropic and dot product kernels}
\label{sec: stationary isotropic and dot product}

Isotropic kernels include both stationary isotropic kernels and dot product
kernels. Hence both classes can be analyzed using the characterization of
isotropic kernels (Theorem \ref{thm: isotropy characterization}).

\begin{example}[Stationary isotropic kernels on \(\ell^2\)]
	The stationary isotropic kernels on \(\ell^2\) have been characterized by
	\citet{schoenbergMetricSpacesPositive1938} (see also Table \ref{table:
	characterizations}) to be of the form
	\[
		\kernel(x,y) = \int_{[0, \infty)} \exp\bigl(-s^2\tfrac{\|x-y\|^2}2\bigr)d\mu(s)
	\]
	for a finite `Schoenberg measure' \(\mu\) on the interval \([0, \infty)\).
	Note that Gaussian kernels correspond to Dirac Schoenberg measures \(\mu\).
	Expanding the squared norm and using the series representation of the exponential,
	the kernel above can be related to the characterization of isotropic kernels
	in Theorem \ref{thm: isotropy characterization}
	\begin{align*}
		\kernel(x,y)
		&= \int_{[0, \infty)}  \exp\bigl(-s^2\tfrac{\|x\|^2+\|y\|^2}2\bigr) \sum_{k=0}^\infty\frac{(s^2\langle x,y\rangle)^k}{k!} \mu(ds)
		\\
		&= \sum_{k=0}^\infty \underbrace{\Bigl(\int_{[0, \infty)} \exp\bigl(-s^2\tfrac{\|x\|^2+\|y\|^2}2\bigr) s^{2k} \mu(ds)\Bigr)\tfrac{\|x\|^k\|y\|^k}{k!}}_{= \alpha_k(\|x\|, \|y\|)}
		\bigl\langle \tfrac{x}{\|x\|},\tfrac{y}{\|y\|} \bigr\rangle^k.
	\end{align*}
	Denoting \(\phi_k(t) := \exp(-t^2/2)t^k\) we can equivalently represent the kernels \(\alpha_k\) by
	\[
		\alpha_k(\|x\|, \|y\|) = \frac1{k!} \int_{[0, \infty)} \phi_k(s\|x\|)\phi_k(s\|y\|)\mu(ds).
		\qedhere
	\]
\end{example}



\begin{example}[Dot product kernels]\label{example:dot_product_kernels}
	Dot product kernels are of the form \(\kernel(x,y):= \kappa(\scal{x}{y})\) and
	hence are isotropic. Restricted to the sphere they exhaust all isotropic
	kernels and are characterized by \citet{schoenbergPositiveDefiniteFunctions1942} (see also Table \ref{table: characterizations}).
	A dot product kernel $\kernel$ valid in all dimensions is of
	the form
	\begin{equation}
		\label{eq: representation dot product kernels}	
		\kernel(x,y) = \sum_{n=0}^\infty a_n \langle x,y\rangle^n,
	\end{equation}
	with \((a_n)_{n\in \nat_0}\) a nonnegative, absolutely summable sequence.  
	Such kernels are also
	referred to as `spherical spin glasses' in statistical
	physics, e.g.\@ \citep[][]{panchenkoSherringtonKirkpatrickModel2013}.

	The dot product kernels on the sequence space \(\ell^2\) are
	still characterized by \eqref{eq: representation dot product kernels}, together with the simple requirement that \((a_nt^n)_{n\in \nat_0}\) must be summable for any \(t>0\), see
	\citep{pinkusStrictlyPositiveDefinite2004} and references therein.
	A simple alternative proof of this result based on the characterization of
	isotropic kernels (Theorem \ref{thm: isotropy characterization}) can be
	found in the appendix (Lemma \ref{lem: classification of dot product kernels
	infinite dim}).
\end{example}







\subsection{Machine Learning}\label{sec: machine learning}

Non-stationary isotropic kernels arise naturally in the analysis of infinitely
wide neural networks. These limiting networks offer tractable surrogates for
highly overparametrized neural networks. Specifically, under suitable random
initialization, the infinite width limit of a neural network is a Gaussian
process
e.g.\@
\citep[][]{williamsComputingInfiniteNetworks1996,choKernelMethodsDeep2009,leeDeepNeuralNetworks2018,yangTensorProgramsWide2019}
and limit training dynamics can be described by kernel gradient descent governed by the \emph{Neural Tangent Kernel (NTK)}, e.g.\@
\citep[][]{jacotNeuralTangentKernel2018,yangTensorProgramsII2020}.
In this section we demonstrate that both, the covariance kernel of the
infinite-width Gaussian process as well as the NTK, are non-stationary isotropic
kernels.
\citet{benningRandomFunctionDescent2024} further
conjecture that \emph{non-stationary} isotropic covariance kernels are required
to accurately model error (aka cost, or risk) functions in machine learning as Gaussian processes.


\begin{definition}[Feed-forward neural network]\label{def:feed-forward-net} An \(L\)-layer neural network
\(f_\theta\colon \real^\dims \to \real\)
is defined as \(f_\theta(x) := z^{(L)}\), where \(x^{(0)} := x\) and the
	collection of all parameters \(\theta=(W^{(l)}, b^{(l)})_{l=1,\dots, L}\)
	recursively defines
	\begin{alignat*}{2}
z^{(l)} & := \gamma_lW^{(l)} x^{(l-1)} +  b^{(l)} &&\in \real^{n_l},
		\\ x^{(l)} &:= \phi(z^{(l)}) &&\in \real^{n_l}.
\end{alignat*}
	The \emph{activation function} $\phi\colon\real\to\real$ is applied
	coordinate-wise and the normalization factors
	\[
		\gamma_l := \begin{cases}
			\frac{1}{\sqrt{n_{l-1}}} & l \ge 2
			\\
			1 & l=1
		\end{cases}
	\]
	allow for a non-trivial limit in the width of hidden layers.

	In the \emph{NTK initialization,} all parameters \(\theta\) are independently standard normal distributed.
\end{definition}





The limit kernels of a feed-forward network naturally depend on the activation function. However in any case they are isotropic.
\begin{corollary}[Limit network \shortkernels]\label{cor: limit_kernels}
	Consider a feed-forward network  with NTK initialization as in Definition \ref{def:feed-forward-net} with polynomially bounded activation function $\phi$.
	Then there exists a Gaussian process $g$ on $\real^\dims$ such that, in distribution, as the widths $n$ of the hidden layers increase
	\[
	f_\theta \overset{n\to\infty}{\longrightarrow} g.
	\]
	This process $g$, the so called \emph{Neural Network
		Gaussian process (NNGP)}, has mean zero and covariance
	\shortkernel{} $\nngp{}$, which is a non-stationary isotropic kernel of the
	form
	\begin{equation}
		\label{eq: joint nngp form}	
		\nngp{} (\xxs,\xys)
		= \sum_{m=0}^\infty \alpha_m(\norm {\xxs}, \norm{\xys})
		\bigl\langle \tfrac{\xxs}{\|\xxs\|}, \tfrac{\xys}{\|\xys\|}\bigr\rangle^m.
	\end{equation}
	Here \(\alpha_n\colon [0,\infty)^2\to\real\) are unique, continuous,
	\pdkernels. These \shortkernels{} are summable, i.e.
	\(\sum_{m=0}^\infty \alpha_m(r,r) < \infty\) for any \(r\in
	[0,\infty)\), and zero at the origin, i.e. 
	\(
	\alpha_m(r,0) = \alpha_m(0,r) = 0
	\)	
	for all $ r \in [0,\infty), n\ge 1$.
\end{corollary}
\begin{proof}
	Following \citet{haninRandomNeuralNetworks2023}, we can combine Eq.\ (1.7) and Eq.\ (1.8) therein to obtain
	\begin{align*}
		\nngp{l}(\xxs,\xys)
		&= 1+ F_\phi\Bigl(
		\nngp{l-1}(\xxs,\xys),\nngp{l-1}(\xxs,\xxs),\nngp{l-1}(\xys,\xys)
		\Bigr)
		\quad (l\ge 1)\\
		\nngp{1} &= 1  + \scal {\xxs}{\xys}.
	\end{align*}
	The exact form of $F_\phi$ is irrelevant here; it
	suffices to note that it is continuous.  
	This recursion demonstrates the isotropy of $\nngp{} =\nngp{L}$ as
	it only depends on $\scal{\xxs}{\xys}$, $\norm{\xxs}^2$ and $\norm{\xys}^2$ 
	which are invariant under mutual linear isotropies. 
Moreover, the function $F_\phi$ does not depend on the input dimension and thereby the kernel function
		\(\kappa\) with
		\[
		\kappa(\|x\|, \|y\|, \langle x,y\rangle) = \nngp{}(x,y).
		\]	
	Since \(\kappa\) is valid in all dimensions it produces
	a kernel on \(\ell^2\) by Lemma \ref{lem: valid in all dimensions}.
	The representation \eqref{eq: joint nngp form} of \(\nngp{}\) follows from Theorem \ref{thm: isotropy characterization}.
\end{proof}



\begin{remark}[Neural Tangent Kernel]
	From similar recursive representations it is possible to infer isotropy
	for the \emph{Neural Tangent Kernel} (NTK) \cite{jacotNeuralTangentKernel2018}
	defined by
	\[
		\ntk{}(\xxs,\xys):= \lim_{n\to \infty} \scal{\nabla_\theta f_\theta (\xxs)}{\nabla_\theta f_\theta(\xys)},
	\]
	which describes training dynamics of highly overparameterized networks.
\end{remark}
The isotropy of the limit neural network \shortkernels{} stems from the
isotropic processing of the inputs in the first hidden layer by the linear
multiplication with the Gaussian matrix $W^{(1)}$.
Specifically, let
${W_{i,\cdot}^{(1)}} \sim \mathcal{N}(0,\identity_\dims)$, then  for inputs
$\xx, \xy \in\real^\dims$ the
post-activation vectors have the coordinate-wise distribution
\begin{align}
	\label{eq:linear_layer_isotropy}
	\begin{pmatrix}
		W^{(1)}_{i,\cdot}\xx \\
		W^{(1)}_{i,\cdot} \xy
	\end{pmatrix} 
	\sim \mathcal{N}\Big(0,\begin{pmatrix}
		\scal {\xx}{\xx} & \scal{\xx}{\xy}\\
		\scal{\xy}{\xx} & \scal{\xy}{\xy}
	\end{pmatrix}\Big)
\end{align}
and the coordinates are independent.
This is an isotropic distribution in the sense that it is invariant under $A\in O(\dims)$ acting simultaneously on $\xx$ and $\xy$.
The isotropy \eqref{eq:linear_layer_isotropy} of linear layers, which are
central in neural network architectures, leads to isotropic limit
\shortkernels{} in much more general settings:


\begin{remark}[Other Network Architectures]
	Using `Tensor programs' \citep{yangTensorProgramsII2020} it is possible to
	recursively calculate the limiting kernels of numerous neural network
	architectures such as
	RNNs 
and 
	transformers as well as networks containing batchnorm and
	pooling layers. 
	Remarkably, it turns out that any network where the input is first processed by a fully connected linear layer (as in Def.\@ \ref{def:feed-forward-net}) yields isotropic limit kernels.
	The recursive formulas obtained tend to be
	complicated, but it is often straightforward to infer isotropy. 
\end{remark}

Neural network kernels can appear to be entirely unrelated, and the following examples illustrate the variety of such kernels.
What connects them
is that they are isotropic and thereby of the form \eqref{eq: joint nngp form}. 
\begin{example}[NNGP-kernels of shallow networks]	
	\leavevmode
	Consider a neural network as in Definition
	\ref{def:feed-forward-net} with $L=2$, but \emph{without bias }$b^{(l)}$.
	Varying the activation function $\phi$ yields a wide range of NNGP-kernels.
	\begin{itemize}		
		\item For the ReLU activation function \(\phi(x) = \max\{0,x\}\)		
		\citet{choKernelMethodsDeep2009} calculate the NNGP-kernel to be the `arccosine kernel'		
		\begin{align*}			
			\nngp{}(\xxs,\xys) =&\, \frac1\pi\|x\| \|y\| J_1(\cos^{-1}(\scal xy))~,\\			
			J_1(\theta) \equalDef&\, \sin(\theta) + (\pi -\theta)\cos(\theta)~.			
		\end{align*}		
		\item 	\citet{williamsComputingInfiniteNetworks1996} shows that 		
		the NNGP-kernel for a shallow neural network with the `error function' as		
		activation function is the `arcsin kernel'		
		\[
		\nngp{} (\xxs,\xys) = \arcsin\Bigl(\frac{\scal xy}{\sqrt{(1+\|x\|^2)(1+\|y\|^2)}}\Bigr).
		\]
		\item
		For the class of activation functions
		\[
			\phi(x) = \sum_{n=0}^\infty a_n h_n(x),
		\]
		where \(a_n \in \real\) and $h_n$ denotes the $n$-th Hermite polynomial, \citet[Thm.\@
		3.1]{simonReverseEngineeringNeural2022} show that the NNGP kernel of a \(2\)-layer neural network for spherical inputs, i.e.\@ $\norm x=\norm y=1$,
		is of the form
		\[
			\nngp{}(x,y) = \sum_{n=0}^\infty a_n^2 \scal xy^n.
		\]
		Using Lemma \ref{lem: classification of dot product kernels infinite
		dim} \emph{any} continuous isotropic kernel on $\sphere[\infty]$ may
		thereby be interpreted as an NNGP-kernel with spherical input.\qedhere
	\end{itemize}
\end{example}






