 	\subsection{Proofs for Section \ref{sec:positive_definite}}\label{subsec:pos-def}

Since we are interested in characterizing isotropic kernels on \(\real^\dims\) we consider \(\sphere\), whereas the
source we build our proofs on \citep{guellaSchoenbergsTheoremPositive2019}
considers \(\sphere[\dims]\). We also work with the normalized Gegenbauer
polynomials while they state their result with the unnormalized ones. For
your convenience we therefore restate their main theorem in our setting and notation.

\begin{theorem}[Characterization of kernels on \(\domain \times \sphere\), \cite{guellaSchoenbergsTheoremPositive2019}]
	\label{thm: guella XxS characterization}
	Let \(\dims \in \{2,3,\dots, \infty\}\) and define \(\lambda:=\frac{\dims-2}2\). For a
	function \(\kernel: (\domain \times \sphere)^2 \to \complex\) which is
	isotropic on the sphere, i.e.  of
	the form 
	\[
	\kernel((r,v), (s,w)) = f_{\sphere[]}(r,s, \langle v ,w\rangle),
	\]
	the following are equivalent 
	\begin{enumerate}[label=(\roman*)]
		\item The function \(\kernel \) is a \pdkernel{} and for all $r,s\in \domain$ the function
		\(f_{\sphere[]}(r,s, \rho)\) is continuous in \([-1,1]\).

		\item The function $\kernel$ has series representation of the form
		\[
		f_{\sphere[]}(r,s, \rho)
		= \sum_{n=0}^\infty \alpha^{(\dims)}_n(r,s) \uPnorm_n(\rho), \qquad \rho\in [-1,1],
		\]
		where \(\alpha^{(\dims)}_n: \domain^2 \to \complex\) are \pdkernels{} for all \(n\in \nat_0\)
		that are summable, i.e.  \(\sum_{n=0}^\infty \alpha^{(\dims)}_n(r,r) <
		\infty\) for all \(r\in \domain\).
	\end{enumerate}
	If $\kernel$ satisfies one of these equivalent conditions and \(\dims<\infty\)
	the \shortkernels{} \(\alpha^{(\dims)}_n\) moreover have the representation
	\[
	\alpha^{(\dims)}_n(r,s) = Z \int_{-1}^1 f_{\sphere[]}(r,s, \rho) \uPnorm_n(\rho)(1-\rho^2)^{(\dims-3)/2} d\rho
	\]
	with normalizing constant
	\[
	Z = Z(n, \dims) = \Bigl[\int_{-1}^{1} [\uPnorm_n(\rho)]^2(1-\rho)^{(\dims-3)/2}d\rho\Bigr]^{-1}.
	\]
\end{theorem}
\begin{proof}
	This is essentially Theorem~2.3 by \citet{guellaSchoenbergsTheoremPositive2019} except
	that we translate their \(a_n^{\dims}(r,s)\) into \(\alpha^{(\dims)}_n(r,s) := a_n^{(\dims)}(r,s) \uP_n(1)\)
	for the use with \emph{normalized} ultraspherical polynomials.
\end{proof}

\begin{lemma}[Characterization of \(O(\dims)\)]
	\label{lem: characterization of O(d)}
	For \(x_1, \dots, x_n \in \real^\dims\), \(y_1,\dots, y_n \in \real^\dims\) with \(\dims \in \{1,\dots, \}\cup \{\infty\}\) the following 
	are equivalent
	\begin{enumerate}[label={(\alph*)}]
		\item\label{it: inner products equal} \(\langle x_i, x_j\rangle = \langle y_i, y_j\rangle\) for all \(i,j\le n\)
		\item\label{it: linear isometry exists} there exists \(\phi\in O(\dims)\) such that \(\phi(x_i) = y_i\) for all \(i\le n\).
	\end{enumerate}
\end{lemma}

This result is well known and a proof can be found in \citep[Prop.~F.4]{benningRandomFunctionDescent2024}.
\begin{proof}[Proof of Lemma \ref{lem: valid in all dimensions}]
	`\(\supseteq\)' follows from \eqref{eq: pd subset relation}. For
	`\(\subseteq\)' we need to prove that the representation \(\kappa\) of a \pdkernel{} $\kernel$ on $\cap_{\dims \in \nat} \PDset_{O(d)}(\real^\dims)$ induces a \pdkernel{} on \(\ell^2\). For this consider vectors \(x_1,\dots,x_n \in \ell^2\)
	and apply Lemma \ref{lem: characterization of O(d)} to obtain $U\in
	O(\infty)$ to map \(x_1,\dots,x_n\) into \(\real^n\subseteq \ell^2\). By positive
	definiteness in \(\PDset_{O(n)}(\real^n)\) Equation
	\eqref{eq:positive_definite_definition} follows.
\end{proof}
The following observation is used for the extension of an isotropic continuous  \pdkernel{} on $(0,\infty) \times \sphere \simeq \real^\dims\setminus \{0\}$ to a \pdkernel{} on  $\real^\dims$.
\begin{lemma}[Continuous extension]
	\label{lem: continuous extension}
	Let \(\kernel\colon \domain \times \domain \to \complex\) be a continuous function
	on some topological space \(\domain\) and let $A\subset \domain$ be a
	set such that the closure of \(\domain \setminus A\) is $\domain$.
	If $\kernel$ is positive definite on $\domain\setminus A$, then \(\kernel\) is positive definite on \(\domain\).
\end{lemma}
\begin{proof}
	Let \(x_0,\dots, x_m\in \domain\) and \(c_0,\dots, c_m \in \complex\)
	and choose for $i=1,\dots, m$ a sequence $x_i^{(n)} \in \domain\setminus A$ such that $x_i^{(n)}\overset{n\to \infty}{\longrightarrow} x_i$.
	By continuity and positive definiteness of $\kernel$ we have 
	\[
	\sum_{i,j=0}^m c_i \conj{c_j} \kernel(x_i, x_j)= \lim_{n\to \infty} \sum_{i,j=0}^m  c_i\conj{c_j} \kernel(x_i^{(n)}, x_j^{(n)})\ge 0.
	\qedhere
	\]
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm: isotropy characterization}]
	\textbf{\ref{it: positive, definite isotropic} \(\Leftrightarrow\) \ref{it: pos definite, weak representation}:} 
	Apart from the continuity of \(\kappa\), this equivalence has already been shown
	in \citet[Appendix F]{benningRandomFunctionDescent2024}.
	\\
	``\(\Leftarrow\)'': This follows
	directly from the fact that \(U\) is a linear isometry that preserves norms
	and inner products. \\
	``\(\Rightarrow\)'':
	Let $M_\ge := \{(r,s,\gamma) \in M : r \ge s\}$.  Using two orthonormal
	vectors \(e_1, e_2\), which exist due to \(\dims\ge 2\), we define
	\emph{continuous} maps
	$\varphi,\psi: M_\ge \to \real^\dims$ by
	\[
	\varphi(r,s,\gamma) := r e_1,\qquad
	\psi(r,s,\gamma) := \begin{cases}
		\frac{\gamma}{r} e_1 + e_2 \sqrt{s^2 - \frac{\gamma^2}{r^2}} & r>0,\\
		0 & r=0.
	\end{cases}
	\]
	By construction of $M_{\ge}$ all \((r,s,\gamma)\in M_\ge\) satisfy $r\ge s$ and $rs\ge \vert\gamma\vert$ and hence $\psi$ is continuous away from $(0,0,0)$. For the continuity of $\psi$ in \((0,0,0)\) 
	consider
	\begin{align*}
		\|\psi(r,s,\gamma)\| \le \tfrac{rs}{r} + s = 2s \to 0
		\quad \text{for}\quad (r,s,\gamma) \to (0,0,0).
	\end{align*}
	The goal of $\varphi$ and $\psi$ is to create two vectors of
	specified length and angle. Indeed, for \(\theta=(r,s,\gamma)\) we have
	\begin{equation}
		\label{eq:preserved_directions}
		\|\varphi(\theta)\| = r, \quad \|\psi(\theta)\| = s, \quad \langle \varphi(\theta), \psi(\theta)\rangle = \gamma.
	\end{equation}
	The continuity requirement prevented the definition of \(\varphi\) and \(\psi\)
	on the entirety of $M$. To deal with $r<s$ we define the swap function
	\(\tau(r,s,\gamma) := (s,r,\gamma)\).
	With its help we finally define $\kappa\colon M\to \complex$ for $\theta = (r,s,\gamma)$ as
	\begin{equation}
		\label{eq: definition of kappa}
		\kappa(r,s,\gamma) := 
		\begin{cases}
			\kernel\bigl(\varphi(\theta), \psi(\theta)\bigr) &  \text{ if } r\ge s \iff \theta \in M_\ge  \\
			\kernel\bigl(\psi(\tau(\theta)), \varphi(\tau(\theta)) \bigr)	& \text{ if } r\le s.
		\end{cases}
	\end{equation}
	Clearly, \(\kappa\) is continuous if it is well-defined in \(r=s\) since \(\varphi\), \(\psi\) and \(\tau\) are
	continuous. For the case \(r=s\),
	Lemma~\ref{lem: characterization of O(d)} and equation
	\eqref{eq:preserved_directions} yield a linear isometry $U\in
	O(\dims)$ such that $U\varphi (\theta) = \psi(\tau(\theta))$
	and $U \psi(\theta) = \varphi(\tau(\theta))$ and thus
	\[
	\kernel\bigl(\varphi(\theta) , \psi(\theta)\bigr)
	\overset{\text{isotropy}}= \kernel\bigl( U \varphi(\theta), U\psi(\theta) \bigr)
	= \kernel\bigl(\psi(\tau(\theta)), \varphi(\tau(\theta))\bigr).
	\]
	It remains to show that $\kappa(\| x\|,\|y\|,\langle x,y\rangle)= \kernel
	(x,y)$ holds for all $x,y\in \real^\dims$. Since the other case works analogous
	we assume w.l.o.g.\@ $\|x\|\ge \|y\|$ and denote by $\theta :=(\|x\|,\|y\|,\langle x,y
	\rangle)$ the input to \(\kappa\). Then by Lemma~\ref{lem: characterization of O(d)}
	and \eqref{eq:preserved_directions} there again exists
	$U\in  O(\dims)$  such that \(U x = \varphi(\theta)\) and \(Uy = \psi(\theta)\)
	and we conclude
	\begin{align*}
		\kernel(x,y)
		= \kernel(Ux, Uy)
		=  \kernel(\varphi(\theta), \psi(\theta))
		= \kappa(\theta).
	\end{align*}


	\textbf{\ref{it: positive, definite isotropic} \(\Rightarrow\) \ref{it: representation}:}
	Over the homeomorphism \(T\colon (0,\infty) \times \sphere\to
	\real^d\setminus\{0\}\) with \(T(r,v) = rv\)
	we define the continuous \shortkernel{} $\kernel_{\sphere[]}\colon
	((0,\infty) \times \sphere)^2 \to \complex $ by
	\[
	\kernel_{\sphere[]} ((r,v),(s,w))
	:= \kernel(rv,sw)
	\overset{\ref{it: pos definite, weak representation}}=
	\kappa\bigl(r, s, rs \langle v, w\rangle \bigr).
	\]
	With \(f_{\sphere[]}(r,s,\rho):= \kappa(r,s,rs\rho)\)
	it is clear that Theorem~\ref{thm: guella XxS characterization} is
	applicable and we obtain by its representation of \(f_{\sphere[]}\) for any
	\(x,y\in \real^\dims\setminus\{0\}\) 
	\[
	\kernel(x,y)
	= f_{\sphere[]}\Bigl(\|x\|,\|y\|,\bigl\langle \tfrac{x}{\|x\|},\tfrac{y}{\|y\|}\bigr\rangle\Bigr)
	= \sum_{n=0}^\infty \alpha_n^{(\dims)} (\|x\|,\|y\|) \uPnorm_n\Bigl(\bigl\langle \tfrac{x}{\|x\|},\tfrac{y}{\|y\|}\bigr\rangle\Bigr),
	\]
	where $\alpha_n^{(\dims)}$ are \pdkernels{} on
	$(0,\infty)$ that are summable on the diagonal. What remains to be shown is that
	these \shortkernels{} are continuous and can be extended to $[0,\infty)$, that this
	extension indeed resembles $\kernel$, that they are all real valued if and only if $\kernel$ is and that \eqref{eq: zero in
		origin} and \eqref{eq:alpha_formula} hold. To this end we investigate the cases
	$\dims<\infty$ and $\dims=\infty$ separately.

	\begin{enumerate}[wide]
		\item \textbf{Case \(\dims<\infty\)}:
		For all $n\in\nat$ and all $r,s\in (0,\infty)$ we have by Theorem~\ref{thm: guella XxS characterization} 
		\[
		\alpha^{(\dims)}_n(r,s)
		= Z \int_{-1}^1
		\overbrace{\kappa(r,s,rs\rho)}^{=f_{\sphere[]}(r,s, \rho)} \uPnorm_n(\rho)\weight(\rho) d\rho.
		\]
		To extend \(\alpha^{(\dims)}_n\) to a continuous function on
		$[0,\infty)^2$, which yields \eqref{eq:alpha_formula} by definition, we use that
		\(\kappa\) is continuous by \ref{it: pos definite, weak
			representation} and apply dominated convergence using  
		\[
		|\uPnorm_n(\rho)\weight(\rho)|
		= |\uPnorm_n(\rho)(1-\rho^2)^{\lambda -\frac12}|
		\le 1,
		\]
		which follows from \(|\uP_n(\rho)| \le \uP_n(1)\) \citep[e.g.][Eq. (2.16)]{reimerGegenbauerPolynomials2003}.
		This continuous extension remains positive definite by Lemma~\ref{lem:
			continuous extension}. To see that this extension results in a representation
		of $\kernel$, observe that, by the orthogonality of
		the Gegenbauer polynomials with respect to the weight function $w(\rho)
		= (1-\rho^2)^{\lambda - \frac12}$
		\citep[Theorem~2.3]{reimerGegenbauerPolynomials2003} and $\uPnorm_0 \equiv 1$
		we have for $r\ge 0$
		\[
		\alpha^{(\dims)}_n(r,0)
		= \frac{\bigl\langle \kappa(r,0, 0), \uPnorm_n\bigr\rangle_\weight}{\|\uPnorm_n\|_w^2}
		= \kappa(r,0, 0)\frac{\bigl\langle \uPnorm_0, \uPnorm_n\bigr\rangle_\weight}{\|\uPnorm_n\|_w^2}
= \kappa (r,0,0) \delta_{n0},
		\]
		where $\delta_{n0}$ denotes the Kronecker delta. This implies \eqref{eq: zero in origin}
		and we also obtain
		\[
		\kernel(x,0)
		= \kappa(\|x\|,0, 0 ) = \sum_{n=0}^\infty\underbrace{\alpha^{(\dims)}_n(\|x\|, \|0\|)}_{=\kappa (\|x\|,0,0) \delta_{n0}}
		\underbrace{\uPnorm_n\bigl(\langle \tfrac{x}{\|x\|}, \tfrac{0}{\|0\|}\rangle \bigr)}_{\overset{\text{def.}}=1}.
		\]
		By an analogous argument the representation also holds for
		\(\kernel(0,x)\). The representation is also unique by
		orthogonality of the Gegenbauer polynomials, because if
		\(\tilde\alpha^{(\dims)}_n\) is another representation, then
		\begin{align*}
			\alpha_m^{(\dims)}(r,s)
			= \frac{\langle \kappa(r,s, rs\,\cdot), \uPnorm_m\rangle_\weight}{\|\uPnorm_m\|_\weight^2}
			&= \frac{\Bigl\langle \sum_{n=0}^\infty \tilde\alpha_n^{(\dims)}(r,s)\uPnorm_n(\cdot), \uPnorm_m(\cdot)\Bigr\rangle_\weight}{\|\uPnorm_m\|_\weight^2}
			\\
			&= \tilde\alpha_m^{(\dims)}(r,s).
		\end{align*}
		From the integral representation \eqref{eq:alpha_formula} we furthermore see that all $\alpha_n^{(\dims)}$  are real if and only if $\kernel$ is real, as the Gegenbauer polynomials are real valued.

		\item \textbf{Case \(\dims=\infty\):}
		First note that the \(\alpha^{(\infty)}_n\) are \emph{continuous} \pdkernels{} on
		\((0,\infty)\)
		\cite[Example~2.4]{guellaSchoenbergsTheoremPositive2019}.  For the
		extension we select two orthonormal vectors \(e_1,e_2\) and observe
		\begin{align*}
			\kernel(r e_1, r e_1) - \kernel(r e_1, r e_2)
			&= \sum_{n=0}^\infty \alpha^{(\infty)}_n(r,r)\langle e_1, e_1\rangle^n
			- \sum_{n=0}^\infty \alpha^{(\infty)}_n(r,r)\langle e_1, e_2\rangle^n
			\\
			&= \sum_{n=\red{1}}^\infty \alpha^{(\infty)}_n(r,r).
		\end{align*}
		By continuity of \(\kernel\) we obtain
		\[
		0 = \lim_{r\to 0}\kernel(r e_1, r e_1) - \kernel(r e_1, r e_2)
		= \lim_{r\to 0}\sum_{n=1}^\infty \alpha_n^{(\infty)}(r,r).
		\]
		Since \(\alpha^{(\infty)}_n(r,r)\ge 0\) holds for all $n\in\nat$ since
		the $\alpha^{(\infty)}_n$ are kernels, this implies
		\(\alpha^{(\infty)}_n(r,r) \to 0\) for all \(n\ge 1\).
		Assume \(r=0\) or \(s=0\) and 
		let \((r_l, s_l)\overset{n\to \infty}{\longrightarrow}(r,s)\). Then the Cauchy-Schwarz inequality yields
		\[
		|\alpha^{(\infty)}_n(r_l, s_l) - \underbrace{\alpha^{(\infty)}_n(r,s)}_{=0}|
		\overset{\text{C.S.}}\le \sqrt{\alpha^{(\infty)}(r_l, r_l) \alpha^{(\infty)}_n(s_l, s_l)} \overset{l\to\infty} \longrightarrow 0.
		\]
		Hence, we can continuously extend \(\alpha^{(\infty)}_n\) by zero as claimed in \eqref{eq: zero in origin}.
		Lemma~\ref{lem: continuous extension} implies for \(n>0\) that this continuous extension of \pdkernels{} \(\alpha^{(\infty)}_n\)  is positive definite. 
		We continue with the extension in the case \(n=0\). For this consider
		\[
		\kernel(r e_1, s e_2)
		= \sum_{n=0}^\infty \alpha^{(\infty)}_n(r,s) \langle e_1, e_2\rangle^n
		= \alpha^{(\infty)}_0(r,s).
		\]
		This yields the continuous extension \(\alpha^{(\infty)}_0(r,s) :=
		\kernel(re_1,se_2)\). Lemma~\ref{lem: continuous extension} shows
		that this extension remains positive definite.  What is left to prove is
		that our continuous extension of the \shortkernels{}
		\(\alpha^{(\infty)}_n\) does in fact lead to a representation 
		of \(\kernel\) and uniqueness. For the former, let $x,y\in \real^\dims$ and w.l.o.g.\@ assume $x=0$ to
		obtain
		\[
		K(x,y)
		= K(0,\|y \| e_2 )
		= \alpha_0^{(\infty)}(0,\|y\| )
		= \sum_{n=0}^\infty \alpha_n^{(\infty)}(0,\|y\|) \langle \tfrac{0}{\|0\|}, y\rangle^n.
		\]
		For uniqueness of the \(\alpha_n^{(\infty)}\) observe that
		\(
		\kappa(r,s, rs\rho) = \sum_{n=0}^\infty \alpha_n^{(\infty)}(r,s) \rho^n
		\)
		is clearly an analytic function in \(\rho\) defined on \([-1,1]\) for
		all \(r,s\) and the coefficients \(\alpha_n^{(\infty)}(r,s)\) thereby unique. Furthermore, this shows that all kernels $\alpha^{(\infty)}_n$ are real valued if and only if $\kernel$ is real valued.
	\end{enumerate}

	\textbf{\ref{it: representation} \(\Rightarrow\) \ref{it: positive, definite isotropic}:} 
	Isotropy is obvious and it remains to show
	positive definiteness. We split the series representation into two parts
	\begin{equation*}
\kernel(x,y)
		= \underbrace{\alpha^{(\dims)}_0(\|x\|, \|y\|)}_{\kernel_0(x,y)}
		+ \underbrace{\sum_{n=1}^\infty \alpha^{(\dims)}_n(\|x\|, \|y\|)\uPnorm_n\bigl(\langle \tfrac{x}{\|x\|}, \tfrac{y}{\|y\|}\rangle\bigr)}_{=\kernel_{>0}(x,y)},
	\end{equation*}
	where we use \(\uPnorm_0 \equiv 1\).  
	Let $m\in \nat , x_1,\dots,x_m\in \real^\dims, c_1,\dots,c_m\in \complex$
	and let without loss of generality $x_i=0$ if and only if $i=1$. Since
	$\alpha_n^{(\dims)}(0,r)=0$ for $n\ge 1$ we obtain
	\[
	\sum_{i,j=1}^m c_i \conj{c_j} \kernel(x_i,x_j)
	= \sum_{i,j=1}^m c_i\conj{c_j} \kernel_0(x_i,x_j) + \sum_{i,j=2}^m c_i\conj{c_j} \kernel_{>0}(x_i,x_j).
	\]
	Since $\alpha_0^{(d)}$ is a \shortkernel{} on $[0,\infty)$ we get that the first
	summand is non-negative. The second summand is non-negative, since it only
	contains $x_i\in \real^\dims \setminus\{0\}$ and the restriction
	$\kernel_{>0}\vert_{(\real^\dims\setminus \{0\})^2}$ is positive definite
	using the homeomorphism $T:(0,\infty) \times \sphere\to \real^\dims
	\setminus \{0\},\; (r,v)\mapsto rv$ and Theorem~\ref{thm: guella XxS
		characterization} characterizing \shortkernels{} on \((0,\infty)\times \sphere\).
\end{proof}

\subsection{Proofs for section \ref{sec: strict positive definite}}\label{subsec:strictly-pos-def}

In this section we provide proofs for the theorems of Section \ref{sec: strict positive definite} that
characterize positive definite kernels.


\begin{proof}[Proof of Theorem \ref{thm:strictly_pos_def}]
	Recall the decomposition 
\eqref{eq: kernel representation}, i.e.
	\[
	\kernel(x,y)
	= \underbrace{\alpha^{(\dims)}_0(\|x\|, \|y\|)}_{=:\kernel_0(x,y)}
	+ \underbrace{\sum_{n=1}^\infty \alpha^{(\dims)}_n(\|x\|, \|y\|) \uPnorm_n(\langle \tfrac{x}{\|x\|}, \tfrac{y}{\|y\|}\rangle)}_{=:\kernel_{>0}(x,y)},
	\]
	with \pdkernels{} $\kernel_0$ and $\kernel_{>0}$.  Let \(m\in
	\nat\), \(c\in (\complex\setminus\{0\})^m\) and let  \(x_1,\dots, x_m\in
	\real^\dims\) be distinct locations where \(x_1=0\) w.l.o.g.\@, then we have
	\begin{equation}
		\label{eq: decomposition}
		\sum_{i,j=1}^m c_i \conj{c_j} \kernel(x_i,x_j)
		= \sum_{i,j=1}^m c_i\conj{c_j} \kernel_0(x_i,x_j)
		+ \sum_{i,j=2}^m c_i\conj{c_j} \kernel_{> 0}(x_i,x_j)
\end{equation}
	using that \(\kernel_{>0}(x,0) = \kernel_{>0}(0,x) = 0\) for all \(x\in \real^\dims\)
	due to \eqref{eq: zero in origin}
	in Theorem~\ref{thm: isotropy characterization}.

	``\ref{it: infinitely even and odd elements in set}, \ref{it: even and odd kernels strict pos. def.}, \ref{it: infinitely many even and odd n strict pos. def.} \(\Rightarrow\) \ref{it: strict positive definite}'':
	For strict positive definiteness of \(\kernel\) we need to show \eqref{eq: decomposition}
	is non-zero. Since both summands are non-negative it is sufficient if either one is non-zero.
	With the usual homeomorphism the conditions in \ref{it: infinitely even and odd elements in set},
	\ref{it: even and odd kernels strict pos. def.} and \ref{it: infinitely many
		even and odd n strict pos. def.} 
	imply the conditions in Theorem 3.5, 3.7 and 3.9 of
	\citet{guellaSchoenbergsTheoremPositive2019} on \((0,\infty)\times
	\sphere\). Since these conditions are satisfied for \(\kernel_{>0}\) if
	they are satisfied for \(\kernel\) we thereby see that \(\kernel_{>0}\) is strictly positive definite on
	\(\real^\dims \setminus\{0\}\).
	If \(m>1\) the second term in \eqref{eq: decomposition} is therefore
	non-zero.  
	If $m=1$ then the first term is
	\[
	\sum_{i,j=1}^m c_i\conj{c_j} \kernel_0(x_i,x_j)
	= |c_1|^2 \alpha_0^{(\dims)}(0,0) >0.
	\]

	``\ref{it: strict positive definite} \(\Rightarrow\) \ref{it: infinitely even and odd elements in set}, \ref{it: even and odd kernels strict pos. def.}'':
	If \(\kernel\) is strictly positive definite on \(\real^\dims\), then
	\(\alpha^{(\dims)}_0(0,0)>0\) by the selection of \(m=1\), \(c=1\),
	\(x_1=0\) in \eqref{eq: decomposition}. 
	Mapping strict positive definiteness of \(\kernel\) on \(\real^\dims\setminus\{0\}\)
	into strict positive definiteness on \((0,\infty)\times \sphere\), the
	assertions \ref{it: infinitely even and odd elements in set} and \ref{it:
		even and odd kernels strict pos. def.} follow from Theorem 3.5 and 3.7 of
	\citet{guellaSchoenbergsTheoremPositive2019}.

	The final remark about strict positive definiteness on \(\real^\dims\setminus\{0\}\)
	follows similarly from the homeomorphism to \((0,\infty)\times \sphere\) and
	the results of \citet{guellaSchoenbergsTheoremPositive2019}.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:strictly_pos_def_dim2}]
	The proof of this Theorem is identical to the proof of Theorem \ref{thm:strictly_pos_def}	
	with the uses of Theorems 3.5, 3.7 and 3.9 by
	\citet{guellaSchoenbergsTheoremPositive2019} replaced by Theorems 3.6, 3.8
	and 3.9 respectively.
\end{proof}

\begin{remark}[Universal kernels]
	For future work characterizing \emph{universal} isotropic \shortkernels{} we point out
	their characterization on the sphere by \citet[Theorem
	10]{micchelliUniversalKernels2006}.  It might be possible to extend this
	result to $(0,\infty) \times \sphere$ analogous to the work of
	\citet{guellaSchoenbergsTheoremPositive2019} for (strictly) \pdkernels{},
	and if that succeeds one can use the isomorphy of $(0,\infty)\times \sphere$
	and $\real^\dims \setminus \{0\}$ in a fashion similar to our proof of
	Theorem \ref{thm: isotropy characterization} and Theorem
	\ref{thm:strictly_pos_def} to obtain the desired characterization.
\end{remark}


\subsection{Characterization of continuous dot product kernels \texorpdfstring{on \(\ell^2\)}{}}
\label{sec: characterization of cont. dot product kernels}

The following lemma, which can be found in \citep{pinkusStrictlyPositiveDefinite2004} and the references
therein, classifies which functions $\kappa\colon\real\to\real$ define (strictly)
positive definite dot product kernels valid in all dimensions, or
equivalently in $\ell^2$.
Using Theorem \ref{thm: isotropy characterization} we provide an
alternative proof. 

\begin{lemma}[Classification of continuous dot product kernels on $\ell^2$]
	\label{lem: classification of dot product kernels infinite dim}
	Let $\kernel(x,y) := \kappa(\scal xy)$ be a continuous positive definite scalar product kernel on $\ell^2$. Then 
	\begin{align}
		\label{eq:scalar_kernel_classification}
		\kernel(x,y) = \sum_{n=0}^\infty a_n \scal xy^n
	\end{align}
	holds, where $0\le a_n$ for all $n$ and  $(a_n t^n )_{n\ge 0} \in \ell^1$ holds for all $t\in\real$. On the other hand, each such sequence $(a_n)_{n\ge 0}$ yields a continuous scalar product kernel on $\ell^2$.

	Furthermore a kernel  $\kernel(x,y)= \sum_{n=0}^\infty a_n \scal xy^n$ is strictly positive definite on $\ell^2$ if and only if $a_n>0$ holds for infinitely many even and infinitely many odd indices $n$.
\end{lemma}
\begin{proof}
	If $\kernel(x,y) := \kappa(\scal xy)$ defines a positive definite kernel on $\ell^2$ we have 
	by Theorem \ref{thm: isotropy characterization}
	\[
		\kernel(x,y)
		= \sum_{n=0}^{\infty}\alpha_n(\norm x,\norm y)
		\bigl(\bigl\langle \tfrac{x}{\|x\|}, \tfrac{y}{\|y\|}\bigr\rangle\bigr)^n
		=\sum_{n=0}^{\infty}
		\underbrace{\frac{\alpha_n(\norm x,\norm y)}{(\norm x\norm y)^n}}_{
			=: \tilde\alpha_n(\|x\|, \|y\|)
		}
		\scal xy^n.
	\]
	Since the \(\alpha_n\) are continuous we may restrict ourselves to \(x,y\in \ell^2\setminus\{0\}\)
	where \(\tilde \alpha_n\) is well defined. To prove \(\tilde \alpha_n\) is constant
	for every \(n\) we need to show for any \(r_1,s_1 > 0\) and \(r_2, s_2>0\)
	that \(\tilde \alpha_n(r_1,s_1) = \tilde \alpha_n(r_2,s_2)\). To this end
	we define for \(i\in \{1,2\}\)
	\[
		x_i(t) = r_i e_1
		\qquad
		y_i(t) = \frac{t}{r_i} + \sqrt{s_i^2 - (t/r_i)^2} e_2
	\]
	for all \(t\in [-\epsilon, \epsilon]\) with \(\epsilon = \min\{r_1s_1, r_2s_2\}>0\).
	Observe that these satisfy
	\[
		\scal{x_i(t)}{y_i(t)}=t,
		\qquad
		\norm{x_i(t)} = r_i
		\quad\text{and}\quad
		\norm{y_i(t)}=s_i.
	\]
	Consequently we have for all \(t\in [-\epsilon, \epsilon]\)
	\begin{align*}
		0 &= \kappa(t) - \kappa(t)
		\\
		&= \kernel(x_1(t), y_1(t)) - \kernel(x_2(t), y_2(t))
		\\
		&= \sum_{n=0}^\infty \bigl(\tilde \alpha_n(r_1, s_1) - \tilde \alpha_n(r_2,s_2)\bigr) t^n.
	\end{align*}
	This implies \(\tilde \alpha_n(r_1, s_1) = \tilde \alpha_n(r_2,s_2)\) because the
	coefficients of a power series are unique. And since the \(r_i\) and \(s_i\) were arbitrary
	the \(\tilde \alpha_n\) are constant, say \(\tilde \alpha_n \equiv a_n
	\in \real\) on \((0, \infty)^2\).
	By Theorem \ref{thm: isotropy characterization}, the $\alpha_n$ are a continuous
	kernels on $[0,\infty)^2$ that are zero at the origin for \(n\ge 1\) and we thus obtain
	\[
		\alpha_n(\norm x,\norm y) = a_n \cdot (\norm x\norm y)^n,
	\]
	where the \(a_n\) must be non-negative for \(\alpha_n\) to be positive
	definite.
	But this implies \eqref{eq:scalar_kernel_classification} and we observe that that
	$(a_nt^n)_{n\in \nat_0} \in \ell^1$ holds for all $t\ge 0$ as
	\eqref{eq:scalar_kernel_classification} converges. 

	For the converse statement simply observe that
	each non-negative series $a_n$ with $(t^na_n)_{n\in \nat_0} \in \ell^1$ for all $t\in
	\real$  defines a scalar product kernel on $\ell^2$ by evoking Theorem
	\ref{thm: isotropy characterization}.

	Now as we understand the form of scalar product kernels, the claims for strict positive definiteness follow directly from Theorem \ref{thm:strictly_pos_def}.
\end{proof}
