 The classical work of Franel \cite{Franel} and Landau \cite{Landau} showed that the quantitative statement about the uniform distribution of Farey fractions and the Riemann hypothesis are equivalent. Denote $N(Q)=|\mathscr{F}_Q|$ and $\mathscr{F}_Q=\{\beta_1<\beta_2\cdots<\beta_{N(Q)}\}$. Then, Franel proved that 
 %the supremum of the real parts of the zeros of the Riemann zeta function is the infimum of $\theta$ for which the following estimate holds
%\[\sum_{i=1}^{N(Q)}R_{N(Q)}^2(\gamma_i)=\BigO{Q^{-2+2\theta}}. \]
%In particular, 
the Riemann hypothesis is equivalent to the asymptotic formula
\[\sum_{i=1}^{N(Q)}R_{N(Q)}^2(\beta_i)=\BigO{Q^{-1+\epsilon}},\ \text{for all}\ \epsilon>0. \]
Note that by definition $R_{N(Q)}(\beta_j)=\left|\beta_j-\frac{j}{N(Q)}\right|.$
A similar version of Franel's result was proved by Landau \cite{Landau}, stating that the Riemann hypothesis is true if and only if, for all $\epsilon>0$,
\[\sum_{j=1}^{N(Q)}R_{N(Q)}(\beta_j)=\BigO{Q^{1/2+\epsilon}}.\]
We first derive an analogue of the above result for the sequence $\left(\mathscr{F}_{Q,k}^{(m)}\right)_{Q\geq 1}$. Denote $\mathcal{N}(Q,k,m)=|\mathscr{F}_{Q,k}^{(m)}|$ and $\mathscr{F}_{Q,k}^{(m)}=\{\gamma_1<\gamma_2\cdots<\gamma_{\mathcal{N}(Q,k,m)}\}$. 
\begin{thm}\label{thm2}
 Let $R_{\mathcal{N}(Q,k,m)}(\gamma_j)=\left|\gamma_j-\frac{j}{\mathcal{N}(Q,k,m)}\right|$. The generalized Riemann hypothesis (GRH) holds true if and only if, for all $\epsilon>0$, 
    \[\sum_{j=1}^{\mathcal{N}(Q,k,m)}R_{\mathcal{N}(Q,k,m)}(\gamma_j)=\BigOm{Q^{\frac{1}{2}+\epsilon}}. \]
   % where $\beta_j=\gamma_j-\frac{j}{\mathcal{N}(Q,k)}$.
\end{thm}
We next prove a closed-form formula for the second moment of the displacement of Farey fractions with $k$-free denominators. 
\begin{thm}\label{beta2}
   Let $R_{\mathcal{N}(Q,k,m)}(\gamma_j)=\left|\gamma_j-\frac{j}{\mathcal{N}(Q,k,m)}\right|$, and $M_q\left(x \right)=\sum_{\substack{n\leq x\\nq\equiv b\pmod{m}}}\mu(n)\mu_k(nq)^2$ for integers $b,m$ as in \eqref{f_k}, then, we have
   \[\sum_{j=1}^{\mathcal{N}(Q,k,m)}R_{\mathcal{N}(Q,k,m)}^2(\gamma_j)=\frac{1}{12\mathcal{N}(Q,k,m)}\left(\sum_{q_1, q_2\leq Q}M_{q_1}\left(\frac{Q}{q_1}\right)M_{q_2}\left(\frac{Q}{q_2}\right)\frac{(\gcd(q_1,q_2))^2}{q_1q_2}-1 \right).\]
 Moreover, the right-hand side above is
   bounded by \[\ll_{m} \left\{\begin{array}{cc}
   {\exp{\left(-c\frac{(\log Q)^{3/5}}{(\log\log Q)^{1/5}} \right)}},  & \mbox{unconditionally} ,\\
  {Q^{-1+\epsilon}},   & \mbox{on the GRH}.
\end{array}\right. \]
\end{thm}



