    where \[ M_q(x)=\sum_{\substack{n\leq x\\qn\equiv b\pmod{m}}}\mu(n)\mu_k(qn)^2 .\]
\end{lem}
\begin{proof}
    We write
    %\[\sum_{v=1}^{\mathcal{N}(Q,k)}f(\gamma_v)=\sum_{q\leq Q}\mu_k(q)^2\sum_{\substack{a\leq q\\\gcd(a,q)=1}}f\left(\frac{a}{q}\right). \]
    \begin{align*}
     \sum_{j=1}^{\mathcal{N}(Q,k,m)}f(\gamma_j)&=\sum_{\substack{q\leq Q\\q\equiv b\pmod{m}}}\mu_k(q)^2\sum_{\substack{a\leq q\\(a,q)=1}}f\left(\frac{a}{q}\right)\\
     &=\sum_{\substack{q\leq Q\\q\equiv b\pmod{m}}}\mu_k(q)^2\sum_{\substack{a\leq q}}f\left(\frac{a}{q}\right)\sum_{\substack{d|a\\d|q}}\mu(d)
     =\sum_{d\leq Q}\mu(d)\sum_{\substack{q\leq Q\\q\equiv b\pmod{m}\\ d|q}}\mu_k(q)^2\sum_{\substack{\substack{a\leq q\\ d|a}}}f\left(\frac{a}{q}\right)\\
     &=\sum_{d\leq Q}\mu(d)\sum_{\substack{q\leq\frac{Q}{d}\\qd\equiv b\pmod{m}}}\mu_k(qd)^2\sum_{a\leq q}f\left(\frac{a}{q}\right)=\sum_{q\leq Q}M_q\left(\frac{Q}{q}\right)\sum_{a\leq q}f\left(\frac{a}{q}\right).
     %&=\sum_{d\leq Q}\mu(d)\sum_{\substack{q\leq\frac{Q}{d}\\\gcd(q,d)=1}}\mu_k(q)^2\sum_{a\leq q}f\left(\frac{a}{q}\right)+\sum_{d\leq Q}\mu(d)\sum_{\substack{q\leq\frac{Q}{d}\\\gcd(q,d)\ne 1}}\mu_k(qd)^2\sum_{a\leq q}f\left(\frac{a}{q}\right).\numberthis\label{2}
    \end{align*}
    \end{proof}



