\subsection{Weighted lattice point counting}
The results in this section are essential in the derivation of the $\nu$-level correlation function and the explicit expression for the pair correlation function. These results involve a variation of the following result of \cite{Cobeli} for lattice point counting in bounded domains. 
\begin{lem}[Lemma 1, \cite{Cobeli}]\label{Zaharescu lemma}
    Let $\Omega\subset [1, R]^2$ be a bounded region and assume that $f$ is a continuously differentiable function on $\Omega,$ then
   \[\sum_{\substack{(a,b)\in \Omega\cap\mathbb{Z}^2\\}}f(a,b)=\iint_{\Omega}f(x,y)dxdy+ \left(\left\|{\frac{\partial f}{\partial x}}\right\|_{\infty}+\left\|{\frac{\partial f}{\partial y}}\right\|_{\infty}\right)\text{Area}(\Omega)\log R+\left\|f \right\|_{\infty}(R+\text{length}(\delta\Omega)\log R).\] 
\end{lem}
We prove weighted versions of the above result consisting of coprimality constraints and twisted by M\"{o}bius functions. This involves several significant modifications. In particular, we need to deal with
the extra M\"{o}bius twists in the sums and handle the extra coprimality conditions by carefully reducing the regions using several change of variables.

\begin{lem}\label{key lemma}
Let $R>1$ be a real number and let $\delta_1$ and $\delta_2$ be $k$-free numbers. Let $\Omega\subset [1, R]^2$ be a bounded region and assume that $f$ is a continuously differentiable function on $\Omega.$ For any positive integers $r_1$ and $r_2$, we have 
   \[\sum_{\substack{(a,b)\in \Omega\cap\mathbb{Z}^2\\(a,r_1)=(b,r_2)=(a,b)=1}}\mu_k(a\delta_1)^2\mu_k(b\delta_2)^2f(a,b)=\frac{6P_{r_1,r_2}^{k}(\delta_1,\delta_2)}{\pi^2}\iint_{\Omega}f(x,y)dxdy+E(r_1,r_2),\numberthis\label{2.3}\] 
   where
   \begin{align*}
       P_{r_1,r_2}^{k}(\delta_1,\delta_2)=&\frac{\phi(r_1)\phi(r_2)}{r_1r_2}\prod_{p|r_1r_2}\left(1-\frac{1}{p^2}\right)^{-1} \prod_{\substack{p|r_1\\(p,r_2)=1}}\left(1-\frac{\gcd(p^k,\delta_2)}{p^k} \right)\prod_{\substack{p|r_2\\(p,r_1)=1}}\left(1-\frac{\gcd(p^k,\delta_1)}{p^{k}} \right) \\&\times\prod_{\substack{p\\(p,r_1r_2)=1}}\left(1-\frac{\gcd(p^k,\delta_2)}{p^{k-1}(p+1)} \right)\left(1-\frac{\gcd(p^k,\delta_1)}{p^{k-1}(p+1)}\left(1-\frac{\gcd(p^k,\delta_2)}{p^{k-1}(p+1)} \right)^{-1} \right)
   \end{align*}
   and
       \[ E(r_1,r_2)\ll_k \left(\tau\left(r_1 \right)\left\|{\frac{\partial f}{\partial x}}\right\|_{\infty}+\tau\left(r_2 \right)\left\|{\frac{\partial f}{\partial y}}\right\|_{\infty}\right)\text{Area}(\Omega)R^{\frac{1}{k}}\log^2R+R^{1+\frac{1}{k}}\log^2R\left\|f \right\|_{\infty}\left(\tau(r_1)+\tau(r_2) \right).\]
\end{lem}
\begin{proof}
We have
    \begin{align*}
        M:&=\sum_{\substack{(a,b)\in\Omega\cap\mathbb{Z}^2\\(a,r_1)=(b,r_2)=(a,b)=1}}\mu_k(a\delta_1)^2\mu_k(b\delta_2)^2f(a,b)
        %=\sum_{\substack{(a,b)\in\Omega\cap\mathbb{Z}^2\\(a,r_1)=(b,r_2)=(a,b)=1}}f(a,b)\sum_{d_1^k|a\delta_1}\mu(d_1)\sum_{d_2^k|b\delta_2}\mu(d_2)\\
        =\sum_{\substack{d_1^k\leq R\delta_1\\ d_2^k\leq R\delta_2}}\mu(d_1)\mu(d_2)\sum_{\substack{(a,b)\in\Omega\cap\mathbb{Z}^2\\(a,r_1)=(b,r_2)=(a,b)=1\\d_1^k|a\delta_1, d_2^k|b\delta_2}}f(a,b).
    \end{align*}
 Using the fact that $a|bc$ if and only if $\frac{a}{\gcd(a,c)}|b$, the above identity can be expressed as   
 \begin{align*}
   M&=\sum_{\substack{d_1^k\leq R\delta_1\\ d_2^k\leq R\delta_2}}\mu(d_1)\mu(d_2)\sum_{\substack{(a,b)\in\Omega\cap\mathbb{Z}^2\\(a,r_1)=(b,r_2)=(a,b)=1\\\frac{d_1^k}{\gcd(d_1^k,\delta_1)}|a, \frac{d_2^k}{\gcd(d_2^k,\delta_2)}|b}}f(a,b) \\
   %&=\sum_{\substack{d_1^k\leq R\delta_1\\ d_2^k\leq R\delta_2}}\mu(d_1)\mu(d_2)\sum_{\substack{(a,b)\in\Omega_{(d_1,d_2)}\cap\mathbb{Z}^2\\\left(\frac{d_1^ka_1}{\gcd(d_1^k,\delta_1)},r_1\right)=\left(\frac{d_2^kb_1}{\gcd(d_2^k,\delta_2)},r_2\right)=1\\\left(\frac{d_1^ka_1}{\gcd(d_1^k,\delta_1)},\frac{d_2^kb_1}{\gcd(d_2^k,\delta_2)}\right)=1\\}}g(a_1,b_1)\\
   &=\sum_{\substack{d_1^k\leq R\delta_1, d_2^k\leq R\delta_2\\ \left(\frac{d_1^k}{\gcd(d_1^k,\delta_1)},r_1\right)=\left(\frac{d_2^k}{\gcd(d_2^k,\delta_2)},r_2\right)=1\\\left(\frac{d_1^k}{\gcd(d_1^k,\delta_1)},\frac{d_2^k}{\gcd(d_2^k,\delta_2)}\right)=1}}\mu(d_1)\mu(d_2)\sum_{\substack{(a_1,b_1)\in\Omega_{(d_1,d_2)}\cap\mathbb{Z}^2\\\left(a_1,\frac{r_1d_2^k}{\gcd(d_2^k,\delta_2)}\right)=1=\left(b_1,\frac{r_2d_1^k}{\gcd(d_1^k,\delta_1)}\right)\\(a_1,b_1)=1}}g(a_1,b_1),\numberthis\label{k56}
 \end{align*}
 where $g(a_1,b_1)=f\left(\frac{d_1^ka_1}{\gcd(d_1^k,\delta_1)},\frac{d_2^kb_1}{\gcd(d_2^k,\delta_2)}\right)$ and
 \[\Omega_{(d_1,d_2)}=\left\{(x,y)\ :\ x\in\frac{\gcd(d_1^k,\delta_1)}{d_1^k}[1, R],\ y\in\frac{\gcd(d_2^k,\delta_2)}{d_2^k}[1, R] \right\}.\]
We first estimate the inner sum in the above identity. Therefore
\begin{align*}
M^{(1)}:&=\sum_{\substack{(a_1,b_1)\in\Omega_{(d_1,d_2)}\cap\mathbb{Z}^2\\\left(a_1,\frac{r_1d_2^k}{\gcd(d_2^k,\delta_2)}\right)=1=\left(b_1,\frac{r_2d_1^k}{\gcd(d_1^k,\delta_1)}\right)\\(a_1,b_1)=1}}g(a_1,b_1)
=\sum_{\substack{(a_1,b_1)\in\Omega_{(d_1,d_2)}\cap\mathbb{Z}^2\\\left(a_1,\frac{r_1d_2^k}{\gcd(d_2^k,\delta_2)}\right)=1=\left(b_1,\frac{r_2d_1^k}{\gcd(d_1^k,\delta_1)}\right)\\}}g(a_1,b_1)\sum_{d|\gcd(a_1,b_1)}\mu(d)\\
&=\sum_{\substack{d\leq R\min\left(\frac{\gcd(d_1^k,\delta_1)}{d_1^k},\frac{\gcd(d_2^k,\delta_2)}{d_2^k} \right)\\\left(d,\frac{r_1r_2d_1^kd_2^k}{\gcd(d_1^k,\delta_1)\gcd(d_2^k,\delta_2)}\right)=1}} \mu(d)\sum_{\substack{(a_2,b_2)\in\frac{1}{d}\Omega_{(d_1,d_2)}\cap\mathbb{Z}^2\\\left(a_2,\frac{r_1d_2^k}{\gcd(d_2^k,\delta_2)}\right)=1=\left(b_2,\frac{r_2d_1^k}{\gcd(d_1^k,\delta_1)}\right)}}g(da_2,db_2)\\
&=\sum_{\substack{d\leq R\min\left(\frac{\gcd(d_1^k,\delta_1)}{d_1^k},\frac{\gcd(d_2^k,\delta_2)}{d_2^k} \right)\\\left(d,\frac{r_1r_2d_1^kd_2^k}{\gcd(d_1^k,\delta_1)\gcd(d_2^k,\delta_2)}\right)=1}} \mu(d)\sum_{\substack{(a_2,b_2)\in\frac{1}{d}\Omega_{(d_1,d_2)}\cap\mathbb{Z}^2}}g(da_2,db_2)\sum_{\substack{s|a_2\\s|\frac{r_1d_2^k}{\gcd(d_2^k,\delta_2)}}}\mu(s)\sum_{\substack{t|b_2\\t|\frac{r_2d_1^k}{\gcd(d_1^k,\delta_1)}}}\mu(t)\\
&=\sum_{\substack{d\leq R\min\left(\frac{\gcd(d_1^k,\delta_1)}{d_1^k},\frac{\gcd(d_2^k,\delta_2)}{d_2^k} \right)\\\left(d,\frac{r_1r_2d_1^kd_2^k}{\gcd(d_1^k,\delta_1)\gcd(d_2^k,\delta_2)}\right)=1}} \mu(d)\sum_{\substack{s|\frac{r_1d_2^k}{\gcd(d_2^k,\delta_2)}}}\mu(s)\sum_{\substack{t|\frac{r_2d_1^k}{\gcd(d_1^k,\delta_1)}}}\mu(t)\sum_{\substack{(a_3,b_3)\in\Gamma\cap\mathbb{Z}^2}}h(a_3,b_3),\numberthis\label{k52}
\end{align*}
where $h(a_3,b_3)=f\left(\frac{dsd_1^ka_3}{\gcd(d_1^k,\delta_1)},\frac{dtd_2^kb_3}{\gcd(d_2^k,\delta_2)}\right)$ and
\[\Gamma=\left\{(x,y)\ :\ x\in\frac{\gcd(d_1^k,\delta_1)}{dsd_1^k}[1, R],\ y\in\frac{\gcd(d_2^k,\delta_2)}{dtd_2^k}[1, R] \right\}. \]
We use Lemma \ref{Zaharescu lemma} to estimate the innermost sum in \eqref{k52}
\begin{align*}
\sum_{\substack{(a_3,b_3)\in\Gamma\cap\mathbb{Z}^2}}h(a_3,b_3)=&\iint_{\Gamma}h(x,y)dxdy\\&+\BigO{\left(\left\|{\frac{\partial h}{\partial x}}\right\|_{\infty}+\left\|{\frac{\partial h}{\partial y}}\right\|_{\infty}\right)\text{Area}(\Gamma)+\left\|h \right\|_{\infty}(1+\text{length}(\partial \Gamma))}\\
=&\frac{\gcd(d_1^k,\delta_1)\gcd(d_2^k,\delta_2)}{std^2d_1^kd_2^k}\iint_{\Omega}f(x,y)dxdy+\BigO{\left\|f \right\|_{\infty}\frac{R}{d}\left(\frac{\gcd(d_1^k,\delta_1)}{sd_1^k}+\frac{\gcd(d_2^k,\delta_2)}{td_2^k}\right)}\\&+\BigO{\left(\frac{\gcd(d_2^k,\delta_2)}{dtd_2^k}\left\|{\frac{\partial f}{\partial x}}\right\|_{\infty}+\frac{\gcd(d_1^k,\delta_1)}{dsd_1^k}\left\|{\frac{\partial f}{\partial y}}\right\|_{\infty}\right)\text{Area}(\Omega)}.
\end{align*}
By invoking the above estimate into \eqref{k52}, we obtain
\begin{align*}
    M^{(1)}=&\frac{\gcd(d_1^k,\delta_1)\gcd(d_2^k,\delta_2)}{d_1^kd_2^k}\sum_{\substack{d\leq R\min\left(\frac{\gcd(d_1^k,\delta_1)}{d_1^k},\frac{\gcd(d_2^k,\delta_2)}{d_2^k} \right)\\\left(d,\frac{r_1r_2d_1^kd_2^k}{\gcd(d_1^k,\delta_1)\gcd(d_2^k,\delta_2)}\right)=1}} \frac{\mu(d)}{d^2}\sum_{\substack{s|\frac{r_1d_2^k}{\gcd(d_2^k,\delta_2)}, t|\frac{r_2d_1^k}{\gcd(d_1^k,\delta_1)}}}\frac{\mu(s)\mu(t)}{st}\iint_{\Omega}f(x,y)dxdy\\&+\BigO{\left(\tau\left(\frac{r_1d_2^k}{\gcd(d_2^k,\delta_2)} \right)\frac{\gcd(d_2^k,\delta_2)}{d_2^k}\left\|{\frac{\partial f}{\partial x}}\right\|_{\infty}+\tau\left(\frac{r_2d_1^k}{\gcd(d_1^k,\delta_1)} \right)\frac{\gcd(d_1^k,\delta_1)}{d_1^k}\left\|{\frac{\partial f}{\partial y}}\right\|_{\infty}\right)\text{Area}(\Omega)\log^2R}\\&+\BigO{R\log^2R\left\|f \right\|_{\infty}\left(\tau\left(\frac{r_2d_1^k}{\gcd(d_1^k,\delta_1)} \right)\frac{\gcd(d_1^k,\delta_1)}{d_1^k}+\tau\left(\frac{r_1d_2^k}{\gcd(d_2^k,\delta_2)} \right)\frac{\gcd(d_2^k,\delta_2)}{d_2^k}\right)}.\numberthis\label{k53}
\end{align*}
We next estimate the summation in \eqref{k53}
\begin{align*}
    M^{(11)}:&=\sum_{\substack{d\leq R\min\left(\frac{\gcd(d_1^k,\delta_1)}{d_1^k},\frac{\gcd(d_2^k,\delta_2)}{d_2^k} \right)\\\left(d,\frac{r_1r_2d_1^kd_2^k}{\gcd(d_1^k,\delta_1)\gcd(d_2^k,\delta_2)}\right)=1}} \frac{\mu(d)}{d^2}\sum_{\substack{s|\frac{r_1d_2^k}{\gcd(d_2^k,\delta_2)}, t|\frac{r_2d_1^k}{\gcd(d_1^k,\delta_1)}}}\frac{\mu(s)\mu(t)}{st}\\
    &=\sum_{\substack{d=1\\\left(d,\frac{r_1r_2d_1^kd_2^k}{\gcd(d_1^k,\delta_1)\gcd(d_2^k,\delta_2)}\right)=1}}^{\infty} \frac{\mu(d)}{d^2}\prod_{p|\frac{r_1d_2^k}{\gcd(d_2^k,\delta_2)}}\left(1-\frac{1}{p} \right)\prod_{p|\frac{r_2d_1^k}{\gcd(d_1^k,\delta_1)}}\left(1-\frac{1}{p} \right)+\BigO{\frac{\max(d_1^k, d_2^k)}{R}}\\
    &=\prod_{p|\frac{r_1d_2^k}{\gcd(d_2^k,\delta_2)}}\left(1-\frac{1}{p} \right)\prod_{p|\frac{r_2d_1^k}{\gcd(d_1^k,\delta_1)}}\left(1-\frac{1}{p} \right)\prod_{\substack{p\\\left(p,\frac{r_1r_2d_1^kd_2^k}{\gcd(d_1^k,\delta_1)\gcd(d_2^k,\delta_2)}\right)=1}}\left(1-\frac{1}{p^2}\right)+\BigO{\frac{\max(d_1^k, d_2^k)}{R}}. \numberthis\label{k54}
\end{align*}
The above estimate in conjunction with \eqref{k53} and \eqref{k56} gives
\begin{align*}
    M=&\frac{1}{\zeta(2)}\iint_{\Omega}f(x,y)dxdy\sum_{\substack{d_1^k\leq R\delta_1, d_2^k\leq R\delta_2\\ \left(\frac{d_1^k}{\gcd(d_1^k,\delta_1)},r_1\right)=\left(\frac{d_2^k}{\gcd(d_2^k,\delta_2)},r_2\right)=1\\\left(\frac{d_1^k}{\gcd(d_1^k,\delta_1)},\frac{d_2^k}{\gcd(d_2^k,\delta_2)}\right)=1}}\frac{\mu(d_1)\mu(d_2)\gcd(d_1^k,\delta_1)\gcd(d_2^k,\delta_2)}{d_1^kd_2^k}\prod_{p|\frac{r_1d_2^k}{\gcd(d_2^k,\delta_2)}}\left(1-\frac{1}{p} \right)\\ &\times\prod_{p|\frac{r_2d_1^k}{\gcd(d_1^k,\delta_1)}}\left(1-\frac{1}{p} \right) \prod_{p|\frac{r_1r_2d_1^kd_2^k}{\gcd(d_1^k,\delta_1)\gcd(d_2^k,\delta_2)}}\left(1-\frac{1}{p^2} \right)^{-1}+\BigO{R^{1+\frac{1}{k}}\log^2R\left\|f \right\|_{\infty}\left(\tau(r_1)+\tau(r_2) \right)}
    \\&+\BigO{\left(\tau\left(r_1 \right)\left\|{\frac{\partial f}{\partial x}}\right\|_{\infty}+\tau\left(r_2 \right)\left\|{\frac{\partial f}{\partial y}}\right\|_{\infty}\right)\text{Area}(\Omega)R^{\frac{1}{k}}\log^2R}\\
    =&\frac{1}{\zeta(2)}\prod_{p|r_1r_2}\left(1-\frac{1}{p^2} \right)^{-1}\prod_{p|r_1}\left(1-\frac{1}{p}\right)\prod_{p|r_2}\left(1-\frac{1}{p}\right)\iint_{\Omega}f(x,y)dxdy\sum_{\substack{d_1, d_2=1\\ \left(\frac{d_1^k}{\gcd(d_1^k,\delta_1)},r_1\right)=\left(\frac{d_2^k}{\gcd(d_2^k,\delta_2)},r_2\right)=1\\\left(\frac{d_1^k}{\gcd(d_1^k,\delta_1)},\frac{d_2^k}{\gcd(d_2^k,\delta_2)}\right)=1}}^{\infty}\\&\times\frac{\mu(d_1)\mu(d_2)\gcd(d_1^k,\delta_1)\gcd(d_2^k,\delta_2)}{d_1^kd_2^k}\prod_{\substack{p|\frac{d_1^k}{\gcd(d_1^k,\delta_1)}\\(p,r_2)=1}}\left(1-\frac{1}{p} \right)\prod_{\substack{p|\frac{d_2^k}{\gcd(d_2^k,\delta_2)}\\(p,r_1)=1}}\left(1-\frac{1}{p} \right)\\&\times \prod_{\substack{p|\frac{d_1^kd_2^k}{\gcd(d_1^k,\delta_1)\gcd(d_2^k,\delta_2)}\\(p,r_1r_2)=1}}\left(1-\frac{1}{p^2} \right)^{-1}+E(r_1,r_2).\numberthis\label{k55}
\end{align*}
