\begin{lem}\label{key lemma1}
     Let $\Omega\subset [1, R]^2$ be a bounded region and let $f$ be a continuously differentiable function on $\Omega.$ Then, we have
     \[\sum_{\substack{(a,b)\in \Omega\cap\mathbb{Z}^2\\(am,b)=1}}\mu_k(b)^2f(a,b)=\frac{6\phi(m)P_k(m)}{\pi^2}\iint_{\Omega}f(x,y)dxdy+E,\numberthis\label{2.}\] 
     where
      \begin{align*} 
  P_k(m)=\frac{1}{m}\prod_{p|m}\left(1-\frac{1}{p^2} \right)^{-1} \prod_{\substack{p\\(p,m)=1}}\left(1-\frac{1}{p^{k-1}(p+1)}\right),
     \end{align*}
     and
       \[ E\ll_{k,m} \left(\left\|{\frac{\partial f}{\partial x}}\right\|_{\infty}+\left\|{\frac{\partial f}{\partial y}}\right\|_{\infty}\right)\text{Area}(\Omega){R^{\frac{1}{k}}}\log^2 R+\|f\|_{\infty}R^{1+\frac{1}{k}}\log^2 R.\]
    \end{lem}
\begin{proof}
    The proof is similar to Lemma \ref{key lemma}.
\end{proof}
\subsection{Weighted character sums} We will need the following estimate on weighted character sums to deal with the contribution coming from non-principal Dirichlet characters modulo $m$ in the computations for Theorems \ref{v correlation} and \ref{main result}.
\begin{prop}\label{prop15}
  Let $R>1,\ M$ and $\Lambda$ be positive real numbers and let $\delta$ be a positive integer. Suppose $\chi$ is a non-principal Dirichlet character modulo $m$ and $f$ is a continuously differentiable function with Supp$(f)\subset(0,\Lambda)$. Then for any integer $r\geq 1$, we have
  \[\sum_{\substack{a\leq R\\(a,r)=1}}\mu_k(a\delta)^2\chi(a)f\left(\frac{M}{a}\right)=\BigOmlamda{\tau(r)R^{\frac{1}{k}} \log R}. \]
\end{prop}
\begin{proof}
    We have
    \begin{align*}
        \sum_{\substack{a\leq R\\(a,r)=1}}\mu_k(a\delta)^2\chi(a)f\left(\frac{M}{a}\right)&=\sum_{\substack{a\leq R\\(a,r)=1}}\chi(a)f\left(\frac{M}{a}\right)\sum_{d^k|a\delta}\mu(d)\\
        &=\sum_{\substack{d^k\leq R\delta\\\left(\frac{d^k}{\gcd(d^k,\delta)},r\right)=1}}\mu(d)\chi\left(\frac{d^k}{\gcd(d^k,\delta)}\right)\sum_{\substack{a\leq \frac{R\gcd(d^k,\delta)}{d^k}\\(a,r)=1}}\chi(a)f\left(\frac{M\gcd(d^k,\delta)}{d^ka}\right).\\
        %&=\sum_{\substack{d^k\leq R\\(d,r)=1}}\mu(d)\chi^k(d)\sum_{\substack{a\leq R/d^k}}\chi(a)f\left(\frac{M}{d^ka}\right)\sum_{s|(a,r)}\mu(s)\\
        %&=\sum_{s|r}\mu(s)\chi(s)\sum_{\substack{d^k\leq R\\(d,r)=1}}\mu(d)\chi^k(d)\sum_{\substack{a\leq R/d^ks}}\chi(a)f\left(\frac{M}{d^ksa}\right).
    \end{align*}
In the last step, we used the fact that $a|bc$ if and only if $\frac{a}{\gcd(a,c)}|b$. Since $\delta$ is $k$-free $-$ otherwise the result would follow trivially $-$ it follows that $\left(\frac{d^k}{\gcd(d^k,\delta)},r\right)=1$ if and only if $(d,r)=1$. Therefore
\begin{align*}
 \sum_{\substack{a\leq R\\(a,r)=1}}\mu_k(a\delta)^2\chi(a)f\left(\frac{M}{a}\right)&= \sum_{\substack{d^k\leq R\delta\\\left(d,r\right)=1}}\mu(d)\chi\left(\frac{d^k}{\gcd(d^k,\delta)}\right)\sum_{\substack{a\leq \frac{R\gcd(d^k,\delta)}{d^k}\\(a,r)=1}}\chi(a)f\left(\frac{M\gcd(d^k,\delta)}{d^ka}\right)\\
 &=\sum_{s|r}\mu(s)\chi(s)\sum_{\substack{d^k\leq R\delta\\\left(d,r\right)=1}}\mu(d)\chi\left(\frac{d^k}{\gcd(d^k,\delta)}\right)\sum_{\substack{a\leq \frac{R\gcd(d^k,\delta)}{sd^k}}}\chi(a)f\left(\frac{M\gcd(d^k,\delta)}{sd^ka}\right).\numberthis\label{1}
\end{align*}
To estimate the inner-most sum, we apply Abel summation formula
    \begin{align*}
     \sum_{\substack{a\leq \frac{R\gcd(d^k,\delta)}{sd^k}}}\chi(a)f\left(\frac{M\gcd(d^k,\delta)}{d^ksa}\right)=& f\left(\frac{M}{R}\right) \sum_{\substack{a\leq \frac{R\gcd(d^k,\delta)}{sd^k}}}\chi(a)\\&+\int_{1}^{\frac{R\gcd(d^k,\delta)}{sd^k}}\sum_{a\leq x}\chi(a)f^{\prime}\left(\frac{M\gcd(d^k,\delta)}{d^ksx}\right)\frac{M\gcd(d^k,\delta)dx}{d^ksx^2}\ll_{m,\Lambda}\log R. 
    \end{align*}
  The above estimate in conjunction with \eqref{1} gives the required result.   
\end{proof}
    \section{Weyl sum}
In this section, we study the equidistribution of the sequence $\left(\mathfrak{F}_{Q,k}^{(m)}\right)_Q$ by establishing an estimate for its associated Weyl sum.
%\subsection{Proof of Theorem \ref{Weyl sum}}
\begin{proof}[Proof of Theorem \ref{Weyl sum}]
     We have
    \begin{align*}
        \sum_{\gamma\in \mathfrak{F}_{Q,k}^{(m)}}e(r\gamma)&=\sum_{\substack{q\leq Q\\q\equiv b\pmod{m}}}\mu_k(q)^2\sum_{\substack{1\leq a\leq q\\(a,q)=1}}e\left(\frac{ar}{q} \right)
    =\sum_{\substack{q\leq Q\\q\equiv b\pmod{m}}}\mu_k(q)^2\sum_{1\leq a\leq q}e\left(\frac{ar}{q} \right)\sum_{d|\gcd(a,q)}\mu(d)\\
    %&=\sum_{d\leq Q}\mu(d) \sum_{\substack{q\leq Q\\q\equiv b\pmod{m}\\d|q}}\mu_k(q)^2\sum_{\substack{1\leq a\leq q\\ d|a}}e\left(\frac{ar}{q} \right)
    &=\sum_{d\leq Q}\mu(d) \sum_{\substack{q\leq \frac{Q}{d}\\qd\equiv b\pmod{m}}}\mu_k(qd)^2\sum_{1\leq a\leq q}e\left(\frac{ar}{q} \right)\\
    &=\sum_{d\leq Q}\mu(d)\sum_{\substack{q\leq \frac{Q}{d}\\qd\equiv b\pmod{m} \\q|r}}q\mu_k(qd)^2
    =\sum_{\substack{q\leq Q \\q|r}}q\sum_{\substack{d\leq\frac{Q}{q}\\qd\equiv b\pmod{m}}}\mu(d)\mu_k(qd)^2.
    %&=\sum_{\substack{q\leq Q\\ q|r}}q\mu_k(q)^2\sum_{\substack{d\leq\frac{Q}{q}\\(d,q)=1}}\mu(d)+\sum_{\substack{q\leq Q\\ q|r}}q\sum_{\substack{d\leq\frac{Q}{q}\\(d,q)\ne 1}}\mu(d)\mu_k(qd)^2
    \end{align*}
    We use Proposition \ref{mu} to estimate the inner sum above, and we find that
   \begin{align*}
    \sum_{\gamma\in \mathfrak{F}_{Q,k}^{(m)}}e(r\gamma)&\ll_{m} Q\exp{\left(-c\frac{(\log Q)^{3/5}}{(\log\log Q)^{1/5}} \right)}\sum_{q|r}\mu_k(q)^2 \prod_{p|q}\left(1-\frac{1}{\sqrt{p}} \right)^{-1} 
    \ll_{m,r} Q\exp{\left(-c\frac{(\log Q)^{3/5}}{(\log\log Q)^{1/5}} \right)}.
   \end{align*} 
   This completes the proof of Theorem \ref{Weyl sum}.
\end{proof}





\section{GRH and Farey fractions}
In this section, we develop an equivalent criterion for the Generalized Riemann Hypothesis in terms of the distribution of $\mathfrak{F}_{Q,k}^{(m)}$.
\subsection{Proof of Theorem \ref{thm2}}
We first assume that
\[\sum_{j=1}^{\mathcal{N}(Q,k,m)}R_{\mathcal{N}(Q,k,m)}(\gamma_j)=\BigOm{Q^{\frac{1}{2}+\epsilon}}. \]
We apply Lemma \ref{f(gamma)} with $f(x)=e(x)$ and obtain
\begin{align*}
   \sum_{v=1}^{\mathcal{N}(Q,k,m)}e(\gamma_v)&=\sum_{q\leq Q}M_q\left(\frac{Q}{q}\right)\sum_{a\leq q}e\left(\frac{a}{q}\right)=M_1(Q), 
\end{align*}
where $M_1(Q)=M(Q)=\sum_{\substack{n\leq Q\\n\equiv b\pmod{m}}}\mu(n)$.
In the last step, we used the following identity
\[\sum_{a\leq q}e\left(\frac{a}{q}\right)=\left\{\begin{array}{cc}
   1,  & \mbox{if} \ q=1,\\
  0,   & \mbox{otherwise}. 
\end{array}\right. \]
We have
\begin{align*}
    M(Q)&=\sum_{v=1}^{\mathcal{N}(Q,k,m)}e(\gamma_v)
    =\sum_{v=1}^{\mathcal{N}(Q,k,m)}e\left(\gamma_v-\frac{v}{\mathcal{N}(Q,k,m)}+\frac{v}{\mathcal{N}(Q,k,m)} \right)\\
    %&=\sum_{v=1}^{\mathcal{N}(Q,k,m)}e(R_{\mathcal{N}(Q,k,m)}(\gamma_v)) e\left(\frac{v}{\mathcal{N}(Q,k,m)} \right)\\
    &=\sum_{v=1}^{\mathcal{N}(Q,k,m)}e\left(\frac{v}{\mathcal{N}(Q,k,m)} \right)(e(R_{\mathcal{N}(Q,k,m)}(\gamma_v))-1)+\sum_{v=1}^{\mathcal{N}(Q,k,m)}e\left(\frac{v}{\mathcal{N}(Q,k,m)} \right).
\end{align*}
This yields
\begin{align*}
    |M(Q)|&\leq \sum_{v=1}^{\mathcal{N}(Q,k,m)}|e(R_{\mathcal{N}(Q,k,m)}(\gamma_v))-1|
    %\leq 2\sum_{v=1}^{\mathcal{N}(Q,k,m)}|\sin{\pi R_{\mathcal{N}(Q,k,m)}(\gamma_v)}|\\
    \leq 2\pi \sum_{v=1}^{\mathcal{N}(Q,k,m)}R_{\mathcal{N}(Q,k,m)}(\gamma_v)\ll_{m} Q^{\frac{1}{2}+\epsilon}.
\end{align*}
Thus, GRH holds. For the converse, assume that GRH is true.  We apply Lemma \ref{f(gamma)} with $f(x)=x-\lfloor x\rfloor-\frac{1}{2}$. We have
\begin{align*}
    G(u)=\sum_{v=1}^{\mathcal{N}(Q,k,m)}f(u+\gamma_v)&=\sum_{q\leq Q}M_q\left(\frac{Q}{q}\right)\sum_{a\leq q}f\left(u+\frac{a}{q}\right)
    =\sum_{q\leq Q}M_q\left(\frac{Q}{q}\right)f(qu).
    %&=\sum_{q\leq Q}\mu_k(q)^2M_q^{(1)}\left(\frac{Q}{q}\right)\sum_{a\leq q}f\left(u+\frac{a}{q}\right)+\sum_{q\leq Q}M_q^{(2)}\left(\frac{Q}{q}\right)\sum_{a\leq q}f\left(u+\frac{a}{q}\right)\\
    %&=\sum_{q\leq Q}\mu_k(q)^2f(qu)M_q^{(1)}\left(\frac{Q}{q}\right)+\sum_{q\leq Q}f(qu)M_q^{(2)}\left(\frac{Q}{q}\right).
\end{align*}
%In the last step, we used Proposition \ref{prop6}. 
We denote
\[I:=\int_0^1(G(u))^2du. \numberthis\label{k16}\]

Case-I: If
\[G(u)=\sum_{q\leq Q}M_q\left(\frac{Q}{q}\right)f(qu).\]
Substituting in \eqref{k16}, we have
\begin{align*}
I&=\int_0^1 \sum_{q_1\leq Q}f(q_1u)M_{q_1}\left(\frac{Q}{q_1}\right)\sum_{q_2\leq Q}f(q_2u)M_{q_2}\left(\frac{Q}{q_2}\right)du\\
    %&+\int_0^1\sum_{q_1\leq Q}f(q_1u)M_{q_1}^{(2)}\left(\frac{Q}{q_1}\right)\sum_{q_2\leq Q}f(q_2u)M_{q_2}^{(2)}\left(\frac{Q}{q_2}\right)du\\
    %&+2\int_0^1 \sum_{q_1\leq Q}\mu_k(q_1)^2f(q_1u)M_{q_1}^{(1)}\left(\frac{Q}{q_1}\right)\sum_{q_2\leq Q}f(q_2u)M_{q_2}^{(2)}\left(\frac{Q}{q_2}\right)du\\
    &=\sum_{q_1, q_2\leq Q}M_{q_1}\left(\frac{Q}{q_1}\right)M_{q_2}\left(\frac{Q}{q_2}\right)\int_0^1f(q_1u)f(q_2u)du.
    %&+\sum_{q_1, q_2\leq Q}M_{q_1}^{(2)}\left(\frac{Q}{q_1}\right)M_{q_2}^{(2)}\left(\frac{Q}{q_2}\right)\int_0^1f(q_1u)f(q_2u)du\\
    %&+\sum_{q_1, q_2\leq Q}\mu_k(q_1)^2M_{q_1}^{(1)}\left(\frac{Q}{q_1}\right)M_{q_2}^{(2)}\left(\frac{Q}{q_2}\right)\int_0^1f(q_1u)f(q_2u)du
    \numberthis\label{3}
\end{align*}
 The above integral is estimated as in \cite[p. 266-267]{Edwards} which yields
\[\int_0^1f(q_1u)f(q_2u)du=\frac{(\gcd(q_1,q_2))^2}{12q_1q_2}. \]
Hence, the above estimate with \eqref{3} gives
\begin{align*}
  I&=\frac{1}{12}\sum_{q_1, q_2\leq Q}M_{q_1}\left(\frac{Q}{q_1}\right)M_{q_2}\left(\frac{Q}{q_2}\right)\frac{(\gcd(q_1,q_2))^2}{q_1q_2} . \numberthis\label{4}  
