\begin{align*}
    I&=\sum_{v=1}^{\mathcal{N}(Q,k,m)}\int_{\gamma_{v-1}}^{\gamma_v}\left(\frac{1}{2}+u\mathcal{N}(Q,k,m)-v\right)^2du\\
    &=\frac{1}{3\mathcal{N}(Q,k,m)}\sum_{v=1}^{\mathcal{N}(Q,k,m)}\left(\left(\gamma_v\mathcal{N}(Q,k,m)-v+\frac{1}{2}\right)^3-\left(\gamma_{v-1}\mathcal{N}(Q,k,m)-v+\frac{1}{2}\right)^3\right)\\
