\leq \left(\mathcal{N}(Q,k,m)\sum_{v=1}^{\mathcal{N}(Q,k,m)}(R_{\mathcal{N}(Q,k,m)}(\gamma_v))^2\right)^{1/2}\leq C^{1/2}Q^{1/2+\epsilon}.
\end{align*}
This completes the proof of Theorem \ref{thm2}.








