\subsection{Proof of Theorem \ref{beta2}}
Employing \eqref{4} and \eqref{6}, we have
\begin{align*}
    \mathcal{N}(Q,k,m)\sum_{v=1}^{\mathcal{N}(Q,k,m)}(R_{\mathcal{N}(Q,k,m)}(\gamma_v))^2+\frac{1}{12}&=\frac{1}{12}\sum_{q_1, q_2\leq Q}M_{q_1}\left(\frac{Q}{q_1}\right)M_{q_2}\left(\frac{Q}{q_2}\right)\frac{(\gcd(q_1,q_2))^2}{q_1q_2}.
    \end{align*}
    Therefore, we have
    \begin{align*}
    \sum_{v=1}^{\mathcal{N}(Q,k,m)}(R_{\mathcal{N}(Q,k,m)}(\gamma_v))^2&=\frac{1}{12\mathcal{N}(Q,k,m)}\left(\sum_{q_1, q_2\leq Q}M_{q_1}\left(\frac{Q}{q_1}\right)M_{q_2}\left(\frac{Q}{q_2}\right)\frac{(\gcd(q_1,q_2))^2}{q_1q_2}-1\right).
\end{align*}
This completes the proof of the first part of Theorem \ref{beta2}.
In order to prove second part, we use the above identity and obtain
\begin{align*}
  \sum_{v=1}^{\mathcal{N}(Q,k,m)}(R_{\mathcal{N}(Q,k,m)}(\gamma_v))^2
  %=&\frac{1}{12\mathcal{N}(Q,k,m)}\left(\sum_{q_1, q_2\leq Q}M_{q_1}\left(\frac{Q}{q_1}\right)M_{q_2}\left(\frac{Q}{q_2}\right)\frac{(q_1,q_2)^2}{q_1q_2}-1 \right)\\
    =&\frac{1}{12\mathcal{N}(Q,k,m)}\left(\sum_{q_1\leq Q}\sum_{\substack{d_1\leq \frac{Q}{q_1}\\q_1d_1\equiv b\pmod{m}}}\mu(d_1)\mu_k(q_1d_1)^2\sum_{q_2\leq Q}\right. \\ &\times \left.\sum_{\substack{d_2\leq \frac{Q}{q_2}\\q_2d_2\equiv b\pmod{m}}}\mu(d_2)\mu_k(q_2d_2)^2 \frac{(\gcd(q_1,q_2))^2}{q_1q_2}-1 \right).\numberthis\label{26}
\end{align*}
Let $\gcd(q_1,q_2)=\delta$ so that $q_1=q_1^{\prime}\delta$ and $q_2=q_2^{\prime}\delta$ with $(q_1^{\prime},q_2^{\prime})=1$. The above identity can be expressed as
\begin{align*}
\sum_{v=1}^{\mathcal{N}(Q,k,m)}(R_{\mathcal{N}(Q,k,m)}(\gamma_v))^2=&\frac{1}{12\mathcal{N}(Q,k,m)}\left(\sum_{\delta\leq Q}\sum_{q_1^{\prime}\leq \frac{Q}{\delta}}\frac{1}{q_1^{\prime}}\sum_{\substack{d_1\leq \frac{Q}{q_1^{\prime}\delta}\\q_1^{\prime}d_1\delta\equiv b\pmod{m}}}\mu(d_1)\mu_k(q_1^{\prime}d_1\delta)^2\right. \\ &\times \left.\sum_{\substack{q_2^{\prime}\leq \frac{Q}{\delta}\\(q_1^{\prime},q_2^{\prime})=1}}\frac{1}{q_2^{\prime}}\sum_{\substack{d_2\leq \frac{Q}{q_2^{\prime}\delta}\\q_2^{\prime}d_2\delta\equiv b\pmod{m}}}\mu(d_2)\mu_k(q_2^{\prime}d_2\delta)^2 -1 \right).\numberthis\label{k22}
\end{align*}
We apply Dirichlet hyperbola method to estimate the inner sum on the above identity
\begin{align*}
    S:=&\sum_{\substack{q\leq \frac{Q}{\delta}\\(q,l)=1}}\frac{1}{q}\sum_{\substack{d\leq \frac{Q}{q\delta}\\qd\delta\equiv b\pmod{m}}}\mu(d)\mu_k(qd\delta)^2\\
    =&\sum_{\substack{q\leq \sqrt{\frac{Q}{\delta}}\\(q,l)=1}}\frac{1}{q}\sum_{\substack{d\leq \frac{Q}{q\delta}\\qd\delta\equiv b\pmod{m}}}\mu(d)\mu_k(qd\delta)^2+\sum_{d\leq\sqrt{\frac{Q}{\delta}}}\mu(d)\sum_{\substack{q\leq\frac{Q}{d\delta}\\qd\delta\equiv b\pmod{m}\\ (q,l)=1}}\frac{\mu_k(qd\delta)^2}{q}\\&-\sum_{\substack{q\leq \sqrt{\frac{Q}{\delta}}\\(q,l)=1}}\frac{1}{q}\sum_{\substack{d\leq\sqrt{\frac{Q}{\delta}}\\qd\delta\equiv b\pmod{m}}}\mu(d)\mu_k(qd\delta)^2.
\end{align*}
Employing Proposition \ref{mu} to the inner sum in the first and last terms, and Proposition \ref{Prop1} to the inner sum in the second term of the above identity, we obtain
\begin{align*}
    S&\ll_{m} \frac{Q}{\delta}\sum_{\substack{q\leq \sqrt{\frac{Q}{\delta}}\\(q,l)=1}}\frac{1}{q^2} \exp{\left(-c\frac{(\log Q/q\delta)^{3/5}}{(\log\log Q/q\delta)^{1/5}} \right)}\prod_{p|q\delta}\left(\frac{\sqrt{p}}{\sqrt{p}-1}\right)\prod_{p|\ell}\left(1-\frac{1}{\sqrt{p}}\right)^{-1}\\ &\ll_{m} \frac{Q}{\delta}\exp{\left(-c\frac{(\log Q/\delta)^{3/5}}{(\log\log Q/\delta)^{1/5}} \right)}\prod_{p|\delta}\left(\frac{\sqrt{p}}{\sqrt{p}-1}\right)\prod_{p|\ell}\left(1-\frac{1}{\sqrt{p}}\right)^{-1}.
\end{align*}
Inserting the above estimate into \eqref{k22} gives
\begin{align*}
   \sum_{v=1}^{\mathcal{N}(Q,k,m)}(R_{\mathcal{N}(Q,k,m)}(\gamma_v))^2&\ll_{m} \frac{Q^2}{\mathcal{N}(Q,k,m)} \sum_{\delta\leq Q}\frac{1}{\delta^{2-\epsilon}}\exp{\left(-c\frac{(\log Q/\delta)^{3/5}}{(\log\log Q/\delta)^{1/5}} \right)}\\
   &\ll_{m} \sum_{\delta\leq\sqrt{Q}}\frac{1}{\delta^{2-\epsilon}}\exp{\left(-c\frac{(\log Q/\delta)^{\frac{3}{5}}}{(\log\log Q/\delta)^{\frac{1}{5}}} \right)}+\sum_{\sqrt{Q}<\delta\leq Q}\frac{1}{\delta^{2-\epsilon}}\exp{\left(-c\frac{(\log Q/\delta)^{\frac{3}{5}}}{(\log\log Q/\delta)^{\frac{1}{5}}} \right)}\\
   %&\ll_{k,m} \exp{\left(-c\frac{(\log Q)^{\frac{3}{5}}}{(\log\log Q)^{\frac{1}{5}}} \right)}+\frac{1}{\sqrt{Q}}
   &\ll_{m} \exp{\left(-c\frac{(\log Q)^{\frac{3}{5}}}{(\log\log Q)^{\frac{1}{5}}} \right)}.
\end{align*}
This completes the proof unconditionally. We now estimate the sum on the right-hand side of \eqref{k22} under the assumption of the GRH. Assuming GRH, we apply Proposition \ref{mu}. Therefore, 
\begin{align*}
   \sum_{v=1}^{\mathcal{N}(Q,k,m)}(R_{\mathcal{N}(Q,k,m)}(\gamma_v))^2&\ll_{m} \frac{Q^{1+\epsilon}}{\mathcal{N}(Q,k,m)} \sum_{\delta\leq Q}\frac{1}{\delta^{1+\epsilon}}\sum_{q_1^{\prime}\leq \frac{Q}{\delta}}\frac{1}{(q_1^{\prime})^{\frac{3}{2}+\epsilon}}\sum_{q_2^{\prime}\leq \frac{Q}{\delta}}\frac{1}{(q_2^{\prime})^{\frac{3}{2}+\epsilon}}\ll_{m} Q^{-1+\epsilon}.
\end{align*}
This completes the proof of Theorem \ref{beta2}.








