\section{$\nu$-level correlations }
The following section discusses the $\nu$-level correlation measure of the sequence $\left(\mathfrak{F}_{Q,k}^{(m)}\right)_Q$. We begin by establishing a closed-form formula for the exponential sum over the Farey fractions whose denominators are $k$-free and lie in an arithmetic progression.
\begin{lem}\label{exp nu}
   Let $r\in \mathbb{Z},$ we have
   \[\sum_{\gamma\in \mathfrak{F}_{Q,k}^{(m)}}e(r\gamma)=\sum_{\substack{q\leq Q\\q|r}}qM_q\left(\frac{Q}{q} \right), \]
   where $M_q(x)=\sum_{\substack{d\leq x\\qd\equiv b\pmod{m}}}\mu(d)\mu_k(qd)^2$.
\end{lem}
\begin{proof}
    We have
    \begin{align*}
        \sum_{\gamma\in \mathfrak{F}_{Q,k}^{(m)}}e(r\gamma)&=\sum_{\substack{q\leq Q\\q\equiv b\pmod{m}}}\mu_k(q)^2\sum_{\substack{1\leq a\leq q\\(a,q)=1}}e\left(\frac{ar}{q} \right)
    =\sum_{\substack{q\leq Q\\q\equiv b\pmod{m}}}\mu_k(q)^2\sum_{1\leq a\leq q}e\left(\frac{ar}{q} \right)\sum_{d|\gcd(a,q)}\mu(d)\\
    %&=\sum_{d\leq Q}\mu(d) \sum_{\substack{q\leq Q\\q\equiv b\pmod{m}\\d|q}}\mu_k(q)^2\sum_{\substack{1\leq a\leq q\\ d|a}}e\left(\frac{ar}{q} \right)
    &=\sum_{d\leq Q}\mu(d) \sum_{\substack{q\leq \frac{Q}{d}\\qd\equiv b\pmod{m}}}\mu_k(qd)^2\sum_{1\leq a\leq q}e\left(\frac{ar}{q} \right)
    %=\sum_{d\leq Q}\mu(d)\sum_{\substack{q\leq \frac{Q}{d}\\qd\equiv b\pmod{m}\\ q|r}}q\mu_k(qd)^2
    =\sum_{\substack{q\leq Q\\ q|r}}qM_q\left(\frac{Q}{q} \right).
    \end{align*}
\end{proof}

\subsection{Proof of Theorem \ref{v correlation}}
In order to establish the $\nu$-level correlation measure for the sequence of Farey fractions with $k$-free denominators $q$ that run through a given arithmetic progression, we need to estimate, for any positive real number $\Lambda$, the quantity
\[\mathcal{S}_{\mathfrak{F}_{Q,k}^{(m)}}^{\nu}(\Lambda)=\frac{1}{\mathcal{N}{(Q,k,m)}}\#\{(\gamma_1,\ldots,\gamma_{\nu})\in \left(\mathfrak{F}_{Q,k}^{(m)}\right)^{\nu}: \gamma_i\ \text{distinct}, (\gamma_1-\gamma_2,\ldots,\gamma_{\nu-1}-\gamma_{\nu})\in\frac{1}{\mathcal{N}{(Q,k,m)}}\mathfrak{B}+\mathbb{Z}^{\nu-1}\}. \]
To estimate this, we build upon the ideas introduced in \cite{BocaF} making several necessary and technical modifications on the way. 
For a smooth real valued function $H$ on $\mathbb{R}^{\nu-1}$ such that Supp$(H)\subset(0,\Lambda)^{\nu-1}$, define
\[f(y)=\sum_{r\in \mathbb{Z}^{\nu-1}}H(\mathcal{N}{(Q,k,m)}(y+r)),\ y\in\mathbb{R}^{\nu-1}, \]
and
\[S^{(\nu)}_{Q,k}=\sum_{\gamma_i\in\mathfrak{F}_{Q,k}^{(m)}, \text{distinct}}f(\gamma_1-\gamma_2,\ldots,\gamma_{\nu-1}-\gamma_{\nu}). \numberthis\label{h1}\]
Since Supp$H\subset(0,\Lambda)$, the condition $\gamma_i\ne\gamma_j$ for $i\ne j$ can be removed for $Q$ large enough that $\mathcal{N}({Q,k,m})>\Lambda.$ Let
 \[f(y)=\sum_{r\in \mathbb{Z}^{\nu-1}}c_re(r\cdot y)\]
 be the Fourier series expansion of $f$, with the Fourier coefficients 
 \begin{align*}
     c_r&=\int_{[0,1)^{\nu-1}}f(x)e(-r\cdot x)dx
     %=\sum_{m\in\mathbb{Z}^{\nu-1}}\int_{[0,1)^{\nu-1}}H(\mathcal{N}{(Q,k,m)}(x+m))e(-n\cdot x)dx\\
     %&=\int_{\mathbb{R}^{\nu-1}}H(\mathcal{N}{(Q,k,m)}v)e(-n\cdot v)dv
     =\frac{1}{(\mathcal{N}{(Q,k,m))^{\nu-1}}}\widehat{H}\left(\frac{r}{\mathcal{N}{(Q,k,m)}}\right),\numberthis\label{Fourier coef}
 \end{align*}
 where $\widehat{H}$ is the Fourier transform of $H.$ Then by \eqref{h1}, we have
\begin{align*}
     S^{(\nu)}_{Q,k}&=\sum_{\gamma_1,\ldots,\gamma_{\nu}\in \mathfrak{F}_{Q,k}^{(m)}}f(\gamma_1-\gamma_2,\ldots,\gamma_{\nu-1}-\gamma_{\nu})
     =\sum_{\substack{\gamma_1,\ldots,\gamma_{\nu}\in \mathfrak{F}_{Q,k}^{(m)}\\r_1,\ldots,r_{\nu-1}\in\mathbb{Z}}}c_re(r\cdot(\gamma_1-\gamma_2,\ldots,\gamma_{\nu-1}-\gamma_{\nu}))\\
     &=\sum_{\substack{\gamma_1,\ldots,\gamma_{\nu}\in \mathfrak{F}_{Q,k}^{(m)}\\r_1,\ldots,r_{\nu-1}\in\mathbb{Z}}}c_re(r_1\gamma_1)e((r_2-r_1)\gamma_2)\ldots e((r_{\nu-1}-r_{\nu-2})\gamma_{\nu-1})e(r_{\nu-1}\gamma_{\nu}).\numberthis\label{k66}
 \end{align*}
By applying Lemma \ref{exp nu} to the above identity yields
\begin{align*}
    S^{(\nu)}_{Q,k}
    %&=\sum_{r=(r_1,\ldots,r_{\nu-1})\in\mathbb{Z}^{\nu-1}}c_r\sum_{\substack{d_1|r_1\\d_2|r_2-r_1\\\ldots\\d_{\nu-1}|r_{\nu-1}-r_{\nu-2}\\d_{\nu}|r_{\nu-1}}}d_1\cdots d_{\nu}M_{d_1}\left(\frac{Q}{d_1} \right)\cdots M_{d_{\nu}}\left(\frac{Q}{d_{\nu}} \right)\\
    &=\sum_{1\leq d_1,\ldots,d_{\nu}\leq Q}d_1\cdots d_{\nu}M_{d_1}\left(\frac{Q}{d_1} \right)\cdots M_{d_{\nu}}\left(\frac{Q}{d_{\nu}} \right)\sum_{\substack{d_1|r_1\\d_2|r_2-r_1\\\ldots\\d_{\nu-1}|r_{\nu-1}-r_{\nu-2}\\d_{\nu}|r_{\nu-1}}}c_r.
\end{align*}
The divisibility conditions in the inner-sum of the above identity can be expressed as
\begin{align*}
    r_1&=l_1d_1\\
    r_2&=l_1d_1+l_2d_2\\
    &\cdots\\
    r_{\nu-1}&=l_1d_1+\cdots+l_{\nu-1}d_{\nu-1}=l_{\nu}d_{\nu}
\end{align*}
for some $l_1,\ldots,l_{\nu}\in\mathbb{Z}$. We denote $d=(d_1,\ldots,d_{\nu-1})\in\square_Q^{\nu-1}:=[1,Q]^{\nu-1}\cap\mathbb{Z}^{\nu-1}$, $l=(l_1,\ldots,l_{\nu-1})$. We obtain
\begin{align*}
   S^{(\nu)}_{Q,k}=& \sum_{d\in\square_Q^{\nu-1}}d_1\cdots d_{\nu-1}M_{d_1}\left(\frac{Q}{d_1} \right)\cdots M_{d_{\nu-1}}\left(\frac{Q}{d_{\nu-1}} \right)\\&\times\sum_{l\in\mathbb{Z}^{\nu-1}}c_{d_1l_1,d_1l_1+d_2l_2,\ldots,d_1l_1+\cdots+d_{\nu-1}l_{\nu-1}}\sum_{d_{\nu}|d_1l_1+\cdots+d_{\nu-1}l_{\nu-1}}d_{\nu}M_{d_{\nu}}\left(\frac{Q}{d_{\nu}} \right).\numberthis\label{h3}
\end{align*}
By using \eqref{Fourier coef} and Lemma \ref{exp nu}, the two inner sums in \eqref{h3} take the form
\begin{align*}
\sum_{\substack{l\in\mathbb{Z}^{\nu-1}\\\gamma\in\mathfrak{F}_{Q,k}^{(m)}}}&c_{d_1l_1,d_1l_1+d_2l_2,\ldots,d_1l_1+\cdots+d_{\nu-1}l_{\nu-1}}e(-\gamma d\cdot l)\\
%&=\sum_{\substack{r\in\mathbb{Z}^{\nu-1}\\\gamma\in\mathfrak{F}_{Q,k}^{(m)}}}\int_{\mathbb{R}^{\nu-1}}e\left(-\gamma\sum_{i=1}^{\nu-1}d_ir_i-\sum_{j=1}^{\nu-1}x_j(d_1r_1+\cdots+d_jr_j) \right)H(\mathcal{N}{(Q,k,m)}x)dx\\
%&=\sum_{\substack{r\in\mathbb{Z}^{\nu-1}\\\gamma\in\mathfrak{F}_{Q,k}^{(m)}}}\int_{\mathbb{R}^{\nu-1}}e\left(-\sum_{i=1}^{\nu-1}d_ir_i(x_i+\cdots+x_{\nu-1}+\gamma)\right)H(\mathcal{N}{(Q,k,m)}x)dx\\
&=\sum_{\substack{l\in\mathbb{Z}^{\nu-1}\\\gamma\in\mathfrak{F}_{Q,k}^{(m)}}}\int_{\mathbb{R}^{\nu-1}}e\left(-\sum_{i=1}^{\nu-1}d_il_i(x_i+\cdots+x_{\nu-1})\right)H(\mathcal{N}{(Q,k,m)}(x_1,\ldots,x_{\nu-2},x_{\nu-1}-\gamma))dx.\numberthis\label{h2}
\end{align*}
We take $y_i=d_i(x_i+\cdots+x_{\nu-1}),\ i=1,\ldots,\nu-1$ with $y=(y_1,\ldots,y_{\nu-1})\in\mathbb{R}^{\nu-1}$ and set
\[H_{\mathcal{N}{(Q,k,m)};d,\gamma}(y)=H\left(\mathcal{N}{(Q,k,m)}\left(\frac{y_1}{d_1}-\frac{y_2}{d_2} \right),\ldots,\mathcal{N}{(Q,k,m)}\left(\frac{y_{\nu-2}}{d_{\nu-2}}-\frac{y_{\nu-1}}{d_{\nu-1}} \right),\mathcal{N}{(Q,k,m)}\left(\frac{y_{\nu-1}}{d_{\nu-1}}-\gamma \right) \right). \]
Therefore, the identity in \eqref{h2} can be expressed as follows
\begin{align*}
    \frac{1}{d_1\cdots d_{\nu-1}}&\sum_{\gamma\in\mathfrak{F}_{Q,k}^{(m)}}\sum_{l\in\mathbb{Z}^{\nu-1}}\int_{\mathbb{R}^{\nu-1}}e(-l\cdot y)H_{\mathcal{N}{(Q,k,m)};d,\gamma}(y)dy
    =\frac{1}{d_1\cdots d_{\nu-1}}\sum_{\gamma\in\mathfrak{F}_{Q,k}^{(m)}}\sum_{l\in\mathbb{Z}^{\nu-1}}\widehat{H}_{\mathcal{N}{(Q,k,m)};d,\gamma}(l).
\end{align*}
Employing the Poisson summation formula to the inner sum of the above identity and inserting it back into \eqref{h3}, we obtain
\begin{align*}
   S^{(\nu)}_{Q,k}&= \sum_{d\leq\square_Q^{\nu-1}}M_{d_1}\left(\frac{Q}{d_1} \right)\cdots M_{d_{\nu-1}}\left(\frac{Q}{d_{\nu-1}} \right)\sum_{\gamma\in\mathfrak{F}_{Q,k}^{(m)}}\sum_{l\in\mathbb{Z}^{\nu-1}}H_{\mathcal{N}{(Q,k,m)};d,\gamma}(l). 
\end{align*}
As Supp$H\subset(0,\Lambda)^{\nu-1}$, we have
\[0<\mathcal{N}{(Q,k,m)}\left(\frac{l_j}{d_j}-\frac{l_{j+1}}{d_{j+1}} \right)<\Lambda^{\prime},\ j=1,\ldots,\nu-2. \]
The above inequalities implies $l_jd_{j+1}-l_{j+1}d_j\geq 1$ and
\[\Lambda>\frac{\mathcal{N}{(Q,k,m)}(l_jd_{j+1}-l_{j+1}d_j)}{d_jd_{j+1}}\geq \frac{\mathcal{N}{(Q,k,m)}}{d_jd_{j+1}}. \]
Therefore, for all $Q\geq Q_0(\Lambda)$ using above inequality we get
\[\frac{Q^2}{d_jd_{j+1}}=\frac{Q^2}{\mathcal{N}{(Q,k,m)}}\cdot \frac{\mathcal{N}{(Q,k,m)}}{d_jd_{j+1}}<\frac{Q^2\Lambda}{\mathcal{N}{(Q,k,m)}}<\frac{\Lambda}{\mathscr{C}(k,m)}=:\mathcal{C}{(\Lambda,k,m)}. \]
Note that both $Q/d_j\ge 1$ and $Q/d_{j+1}\ge 1$. Therefore, for all $Q\geq Q_0(\Lambda)$, we have
$1\leq \frac{Q}{d_j}\leq\mathcal{C}{(\Lambda,k,m)},\ j=1\ldots,\nu-1.$
Similarly, we obtain
\[\frac{Q}{q}\leq\mathcal{C}{(\Lambda,k,m)}.\numberthis\label{h5} \]
Hence,
\begin{align*}
    S^{(\nu)}_{Q,k}
%& \sum_{d\leq\square_Q^{\nu-1}}\sum_{l\in\mathbb{Z}^{\nu-1}}\sum_{\substack{1\leq n_j\leq Q/d_j\\n_jd_j\equiv b\pmod{m}}}(\mu(n_1)\cdots\mu(n_{\nu-1}))(\mu_k(n_1d_1)^2\cdots\mu_k(n_{\nu-1}d_{\nu-1})^2)\\&\times\sum_{\substack{a/q\in\mathfrak{F}_{Q,k}^{(m)}\\q\geq Q/\mathcal{C}{(\Lambda,k,m)}}}H_{\mathcal{N}{(Q,k,m)};d,\gamma}(l)\\
    =&\sum_{1\leq n_j\leq \mathcal{C}{(\Lambda,k,m)}}\mu(n_1)\cdots\mu(n_{\nu-1})\sum_{\substack{1\leq d_j\leq Q/n_j\\n_jd_j\equiv b\pmod{m}}}\mu_k(n_1d_1)^2\cdots\mu_k(n_{\nu-1}d_{\nu-1})^2\sum_{l\in\mathbb{Z}^{\nu-1}}\\&\times\sum_{\substack{a/q\in\mathfrak{F}_{Q,k}^{(m)}\\q\geq Q/\mathcal{C}{(\Lambda,k,m)}}}H_{\mathcal{N}{(Q,k,m)};d,\gamma}(l).\numberthis\label{h4}
\end{align*}
We set $\Delta_j=ql_j-ad_j$ for $j=1,\ldots,\nu-1$. Consequently, $l_j$ is uniquely determined as $l_j=\frac{\Delta_j+ad_j}{q}$. This in turn implies that
\[\frac{l_j}{d_j}-\frac{l_{j+1}}{d_{j+1}}=\frac{\Delta_j+ad_j}{qd_j}-\frac{\Delta_{j+1}+ad_{j+1}}{qd_{j+1}}=\frac{1}{q}\left(\frac{\Delta_j}{d_j}-\frac{\Delta_{j+1}}{d_{j+1}} \right),\ j=1,\ldots,\nu-2. \]
Moreover,
\[\frac{l_{\nu-1}}{d_{\nu-1}}-\frac{a}{q}=\frac{\Delta_{\nu-1}}{qd_{\nu-1}}. \]
Also, $d_j$ satisfy the congruence $d_j\equiv -\bar{a}\Delta_j\pmod{q},\ j=1,\ldots,\nu-1$, where $1\leq\bar{a}\leq q$ such that $a\bar{a}=1\pmod{q}$. 
Since Supp$H\subset(0,\Lambda)^{\nu-1}$, we get
\[0<\frac{\mathcal{N}{(Q,k,m)\Delta_j}}{qd_j}
%=\mathcal{N}{(Q,k,m)}\left(\frac{l_{j}}{d_{j}}-\frac{a}{q} \right)
=\mathcal{N}{(Q,k,m)}\left(\frac{l_{j}}{d_{j}}-\frac{l_{j+1}}{d_{j+1}} \right)+\cdots+\mathcal{N}{(Q,k,m)}\left(\frac{l_{\nu-1}}{d_{\nu-1}}-\frac{a}{q} \right)<(\nu-j)\Lambda^{\prime}. \]
For $Q\geq Q_0(\Lambda)$, the above inequalities give
\[1\leq\Delta_j\leq\frac{qd_j(\nu-j)\Lambda}{\mathcal{N}{(Q,k,m)}}\leq\frac{Q^2(\nu-j)\Lambda}{\mathcal{N}{(Q,k,m)}}\leq (\nu-j)\mathcal{C}{(\Lambda,k,m)}; \]
thus, we have $1\leq\Delta_1,\ldots,\Delta_{\nu-1}\leq (\nu-1)\mathcal{C}{(\Lambda,k,m)}$. Therefore, \eqref{h4} becomes
\begin{align*}
  S^{(\nu)}_{Q,k}=& \sum_{1\leq n_j\leq \mathcal{C}{(\Lambda,k,m)}}\mu(n_1)\cdots\mu(n_{\nu-1})\sum_{1\leq\Delta_j\leq(\nu-1)\mathcal{C}{(\Lambda,k,m)}}\sum_{\substack{1\leq d_j\leq Q/n_j\\n_jd_j\equiv b\pmod{m}}}\mu_k(n_1d_1)^2\cdots\mu_k(n_{\nu-1}d_{\nu-1})^2\\
  &\times\sum_{\substack{a/q\in\mathfrak{F}_{Q,k}^{(m)}, q\geq Q/\mathcal{C}{(\Lambda,k,m)}\\d_j\equiv -\bar{a}\Delta_j\pmod{q}}}H\left(\frac{\mathcal{N}{(Q,k,m)}}{q}\left(\frac{\Delta_1}{d_1}-\frac{\Delta_2}{d_2},\ldots,\frac{\Delta_{\nu-2}}{d_{\nu-2}}-\frac{\Delta_{\nu-1}}{d_{\nu-1}},\frac{\Delta_{\nu-1}}{d_{\nu-1}} \right) \right).
\end{align*}
We simplify the above expression by employing the linear transformation $T$ defined in \eqref{k63}. We set $\Tilde{H}=H\circ T$, which is smooth and Supp$\Tilde{H}\subset(0,(\nu-1)\Lambda]\times\cdots\times(0,\Lambda]$. The above identity then becomes
\begin{align*}
  S^{(\nu)}_{Q,k}=& \sum_{1\leq n_j\leq \mathcal{C}{(\Lambda,k,m)}}\mu(n_1)\cdots\mu(n_{\nu-1})\sum_{1\leq\Delta_j\leq(\nu-1)\mathcal{C}{(\Lambda,k,m)}}\sum_{\substack{1\leq d_j\leq Q/n_j\\n_jd_j\equiv b\pmod{m}}}\mu_k(n_1d_1)^2\cdots\mu_k(n_{\nu-1}d_{\nu-1})^2\\
  &\times\sum_{\substack{a/q\in\mathfrak{F}_{Q,k}^{(m)}, q\geq Q/\mathcal{C}{(\Lambda,k,m)}\\ d_j=-\bar{a}\Delta_j\pmod{q}}} \Tilde{H}\left(\frac{\mathcal{N}{(Q,k,m)}}{q}\left(\frac{\Delta_1}{d_1},\frac{\Delta_2}{d_2},\ldots,\frac{\Delta_{\nu-1}}{d_{\nu-1}} \right) \right). 
\end{align*}
We define
$e_j=\frac{d_j+\bar{a}\Delta_j}{q},\ j=1,\ldots,\nu-1.$
Note that $e_j$ is an integer since $d_j=-\bar{a}\Delta_j\pmod{q}$. As $d_j,\bar{a}$, and $ \Delta_j$ are all integers, it follows that $e_j\geq 1$. Moreover, using \eqref{h5}, we obtain $1\leq e_j\leq \nu\mathcal{C}{(\Lambda,k,m)},\ j=1,\ldots,\nu-1$. For each value of $e_j$, with $a,q,$ and $ \Delta_j$ fixed, we obtain a unique value of $d_j$; in particular, $d_j=qe_j-\bar{a}\Delta_j$. Also, with fixed $e_j$ and $\Delta_j$ and variable $a/q\in\mathfrak{F}_{Q,k}^{(m)}$, in order for $d_j$ to belong to the set $\{1,\ldots,\lfloor Q/n_j\rfloor \}$, $a$ and $q$ must satisfy $\frac{Q}{n_j\mathcal{C}{(\Lambda,k,m)}}\leq qe_j-\bar{a}\Delta_j\leq\frac{Q}{n_j} $.
We consider the region
\[\Omega_{n,e,k,\Delta}=\left\{(x,y): 0<x\leq y\leq 1,\ y\geq \frac{1}{\mathcal{C}{(\Lambda,k,m)}},\ \frac{n_j^{-1}}{\mathcal{C}{(\Lambda,k,m)}}\leq ye_j-x\Delta_j\leq\frac{1}{n_j},\ \Psi_k(n_j(ye_j-x\Delta_j))=1 \right\}. \]
We next set the functions $f_{k,e,\Delta}, f_{k,e,\Delta}^{(j)}$ defined on $\Omega_{n,e,k,\Delta}$ as follows
\[f_{k,e,\Delta}(x,y)=\Tilde{H}\left(f_{k,e,\Delta}^{(1)}(x,y),\ldots,f_{k,e,\Delta}^{(\nu-1)}(x,y)\right)\ \text{and}\ f_{k,e,\Delta}^{(j)}(x,y)=\frac{\mathcal{N}{(Q,k,m)}\Delta_j}{y(ye_j-x\Delta_j)},\ j=1,\ldots,\nu-1. \]
We also set $a^{\prime}=\bar{a}$ and note that $a^{\prime}/q\in\mathfrak{F}_{Q,k}^{(m)}$ with $q\geq Q/\mathcal{C}{(\Lambda,k,m)}$ as $a/q\in\mathfrak{F}_{Q,k}^{(m)}$. Therefore
\begin{align*}
   S^{(\nu)}_{Q,k}&= \sum_{1\leq n_j\leq \mathcal{C}{(\Lambda,k,m)}}\mu(n_1)\cdots\mu(n_{\nu-1})\sum_{\substack{1\leq\Delta_j\leq(\nu-1)\mathcal{C}{(\Lambda,k,m)}\\1\leq e_j\leq \nu\mathcal{C}{(\Lambda,k,m)}}}\sum_{\substack{(a^{\prime},q)\in Q\Omega_{n,e,k,\Delta}\\ (a^{\prime},q)=1, \mu_k(q)^2=1\\q\equiv b\pmod{m}}}f_{k,e,\Delta}(a^{\prime},q)\\
   &=\frac{1}{\phi(m)}\sum_{\chi}\chi(\bar{b})\sum_{1\leq n_j\leq \mathcal{C}{(\Lambda,k,m)}}\mu(n_1)\cdots\mu(n_{\nu-1})\sum_{\substack{1\leq\Delta_j\leq(\nu-1)\mathcal{C}{(\Lambda,k,m)}\\1\leq e_j\leq \nu\mathcal{C}{(\Lambda,k,m)}}}\sum_{\substack{(a^{\prime},q)\in Q\Omega_{n,e,k,\Delta}\\ (a^{\prime},q)=1, \mu_k(q)^2=1}}\chi(q)f_{k,e,\Delta}(a^{\prime},q).\numberthis\label{k65}
\end{align*}
 To estimate the inner sum in the above identity for the principal character $\chi=\chi_0$, we apply Lemma \ref{key lemma1}
\begin{align*}
  \sum_{\substack{(a^{\prime},q)\in Q\Omega_{n,e,k,\Delta}\\ (a^{\prime},q)=1, \mu_k(q)^2=1\\(q,m)=1}}f_{k,e,\Delta}(a^{\prime},q)&=\frac{6\phi(m)P_k(m)}{\pi^2}\iint_{Q\Omega_{n,e,k,\Delta}}f_{k,e,\Delta}(x,y)+\BigOm{Q^{1+\frac{1}{k}}\log^2 Q},\numberthis\label{k64}   
\end{align*}
 and for the non-principal character, we employ Proposition \ref{prop15}
\begin{align*}
  \sum_{\substack{(a^{\prime},q)\in Q\Omega_{n,e,k,\Delta}\\ (a^{\prime},q)=1, \mu_k(q)^2=1}}\chi(q)f_{k,e,\Delta}(a^{\prime},q)\ll_{m} Q^{1+\frac{1}{k}+\epsilon}\log Q.  
\end{align*}
By invoking the above estimates in \eqref{k65}, and making the change of variables $(u,v)=(Qx,Qy)$ in the main term of \eqref{k64}, we obtain
\begin{align*}
    S^{(\nu)}_{Q,k}&= \frac{6Q^2P_k(m)}{\pi^2}\sum_{1\leq n_j\leq \mathcal{C}{(\Lambda,k,m)}}\mu(n_1)\cdots\mu(n_{\nu-1})\sum_{\substack{1\leq\Delta_j\leq(\nu-1)\mathcal{C}{(\Lambda,k,m)}\\1\leq e_j\leq \nu\mathcal{C}{(\Lambda,k,m)}}}\mathcal{I}_{k}(r,e,\Delta)+\BigOm{Q^{1+\frac{1}{k}+\epsilon}\log^2 Q},\numberthis\label{h6}
\end{align*}
where
\[\mathcal{I}_{k}(r,e,\Delta)=\iint_{\Omega_{n,e,k,\Delta}}g_{k,e,\Delta}(x,y)dxdy, \numberthis\label{h7}\]
\[g_{k,e,\Delta}(x,y)=\Tilde{H}\left(g_{k,e,\Delta}^{(1)}(x,y),\ldots,g_{k,e,\Delta}^{(\nu-1)}(x,y)\right)\ \text{and}\ g_{k,e,\Delta}^{(j)}(x,y)=\frac{\mathcal{N}{(Q,k,m)}\Delta_j}{Q^2y(ye_j-x\Delta_j)},\  j=1,\ldots,\nu-1. \]
%\[g_{k,e,\Delta}^{(j)}(x,y)=\frac{\mathcal{N}{(Q,k,m)}\Delta_j}{Q^2y(ye_j-x\Delta_j)},\ j=1,\ldots,\nu-1. \]
Employing Proposition \ref{prop1} and the inequality
\[|\Tilde{H}(v)-\Tilde{H}(w)|\leq \|\Tilde{H}^{\prime} \||v-w|\leq 2\|H^{\prime}\| |v-w|, \]
we observe that \eqref{h6} holds true when $g_{k,e,\Delta}^{(j)}$ is replaced by
\[g_{k,e,\Delta}^{(j)}(x,y)=\frac{\mathscr{C}(k,m)\Delta_j}{y(ye_j-x\Delta_j)},\ j=1,\ldots,\nu-1, \]
in the formula for $g_{k,e,\Delta}$. Therefore
\begin{align*}
    S^{(\nu)}_{Q,k}&= \frac{6Q^2P_k(m)}{\pi^2}\sum_{1\leq n_j\leq \mathcal{C}{(\Lambda,k,m)}}\mu(n_1)\cdots\mu(n_{\nu-1})\sum_{\substack{1\leq\Delta_j\leq(\nu-1)\mathcal{C}{(\Lambda,k,m)}\\1\leq e_j\leq \nu\mathcal{C}{(\Lambda,k,m)}}}\mathcal{I}_{k}(r,e,\Delta)+\BigOm{Q^{1+\frac{1}{k}+\epsilon}\log^2 Q}, 
\end{align*}
where $\mathcal{I}_{k}(r,e,\Delta)$ is as in \eqref{h7}. We also note that the region can be extended to
\[\Tilde{\Omega}_{n,e,k,\Delta}=\left\{(x,y): 0<x\leq y\leq 1,\ y\geq \frac{1}{\mathcal{C}{(\Lambda,k,m)}},\ 0< ye_j-x\Delta_j\leq\frac{1}{n_j},\ \Psi_k(n_j(ye_j-x\Delta_j))=1 \right\}. \]
If $(x,y)\in\Tilde{\Omega}_{n,e,k,\Delta}\setminus\Omega_{n,e,k,\Delta} $, there is some $j$ such that $|ye_j-x\Delta_j|<1/n_j\mathcal{C}{(\Lambda,k,m)}$, which implies that
\[|g_{k,e,\Delta}^{(j)}(x,y)|\geq n_j\Delta_j\mathscr{C}(k,m)\mathcal{C}{(\Lambda,k,m)} \geq \mathscr{C}(k,m)\mathcal{C}{(\Lambda,k,m)}=\Lambda. \]
This in turn implies that $g_{k,e,\Delta}=0$ on $\Tilde{\Omega}_{n,e,k,\Delta}\setminus\Omega_{n,e,k,\Delta}$. Therefore
\begin{align*}
   S^{(\nu)}_{Q,k}=& \frac{6Q^2P_k(m)}{\pi^2}\sum_{1\leq n_j\leq \mathcal{C}{(\Lambda,k,m)}}\mu(n_1)\cdots\mu(n_{\nu-1})\sum_{\substack{1\leq\Delta_j\leq(\nu-1)\mathcal{C}{(\Lambda,k,m)}\\1\leq e_j\leq \nu\mathcal{C}{(\Lambda,k,m)}}}\iint_{\Tilde{\Omega}_{n,e,k,\Delta}}g_{k,e,\Delta}(x,y)dxdy\\&+\BigOm{Q^{1+\frac{1}{k}+\epsilon}\log^2 Q}. \numberthis\label{h8} 
\end{align*}
%\[S^{(\nu)}_{Q,k}= \frac{6Q^2P_k}{\pi^2}\sum_{1\leq n_j\leq \mathcal{C}{(\Lambda,k,m)}}\mu(n_1)\cdots\mu(n_{\nu-1})\sum_{\substack{1\leq\Delta_j\leq(\nu-1)\mathcal{C}{(\Lambda,k,m)}\\1\leq e_j\leq \nu\mathcal{C}{(\Lambda,k,m)}}}\iint_{\Tilde{\Omega}_{n,e,k,\Delta}}g_{k,e,\Delta}(x,y)dxdy+\BigOkm{Q^{1+\frac{1}{k}}\log^2 Q}. \numberthis\label{h8}\]
On taking $A_j=e_jn_j,\ B_j=\Delta_jn_j,\ A=(A_1,\ldots,A_{\nu-1}) $ and $B=(B_1,\ldots,B_{\nu-1})$ and considering the region $\Omega_{A,B,\Lambda,k}$ and map $T_{A,B}$. We set
\[\mathcal{I}_{k,\Lambda}(A,B)=\iint_{\Omega_{A,B,\Lambda,k}}\Tilde{H}\circ T_{A,B}. \]Therefore \eqref{h8} becomes
\begin{align*}
    S^{(\nu)}_{Q,k}&= \frac{6Q^2P_k(m)}{\pi^2}\sum_{\substack{1\leq A_j\leq\nu\mathcal{C}^2{(\Lambda,k,m)}\\1\leq B_j\leq (\nu-1)\mathcal{C}^2{(\Lambda,k,m)}}}\mathcal{I}_{k,\Lambda}(A,B)\sum_{n_j|\gcd(A_j,B_j)}\mu(n_1)\cdots\mu(n_{\nu-1})+\BigOm{Q^{1+\frac{1}{k}+\epsilon}\log^2 Q}\\
    &=\frac{6Q^2P_k(m)}{\pi^2}\sum_{\substack{1\leq A_j\leq\nu\mathcal{C}^2{(\Lambda,k,m)}\\1\leq B_j\leq (\nu-1)\mathcal{C}^2{(\Lambda,k,m)}\\(A_j,B_j)=1}}\mathcal{I}_{k,\Lambda}(A,B)+\BigOm{Q^{1+\frac{1}{k}+\epsilon}\log^2 Q}.
\end{align*}
Using Proposition \ref{prop1} with the above formula yields
\[\frac{S^{(\nu)}_{Q,k}}{\mathcal{N}{(Q,k,m)}}=\frac{6P_k(m)}{\pi^2\mathscr{C}(k,m)}\sum_{\substack{1\leq A_j\leq\nu\mathcal{C}^2{(\Lambda,k,m)}\\1\leq B_j\leq (\nu-1)\mathcal{C}^2{(\Lambda,k,m)}\\(A_j,B_j)=1}}\mathcal{I}_{k,\Lambda}(A,B)+\BigOm{Q^{-1+\frac{1}{k}+\epsilon}\log^2 Q}. \]

By the standard approximation argument, we next approximate $H$ by the characteristic function of a box $\mathfrak{B}\in(0,\Lambda)^{\nu-1}$ from above and from below. Thus, we have
\begin{align*}
   \mathcal{S}^{\nu}(\mathfrak{B})&=\lim_{Q\to\infty}\frac{1}{\mathcal{N}{(Q,k,m)}}S^{(\nu)}_{Q,k}=\frac{6P_k(m)}{\pi^2\mathscr{C}(k,m)}\sum_{\substack{1\leq A_j\leq(\nu-1)\mathcal{C}^2{(\Lambda,k)}\\1\leq B_j\leq \nu\mathcal{C}^2{(\Lambda,k)}\\(A_j,B_j)=1}}\iint_{\Omega_{A,B,\Lambda,k}}\chi_{\mathcal{B}}\circ T\circ T_{A,B} \\
   &=\frac{6P_k(m)}{\pi^2\mathscr{C}(k,m)}\sum_{\substack{1\leq A_j\leq(\nu-1)\mathcal{C}^2{(\Lambda,k)}\\1\leq B_j\leq \nu\mathcal{C}^2{(\Lambda,k)}\\(A_j,B_j)=1}}\text{area}\left(\Omega_{A,B,\Lambda,k}\cap T_{A,B}^{-1}(T^{-1}\mathfrak{B}) \right).
\end{align*}
This completes the proof of Theorem \ref{v correlation}.
\section{Pair correlation }
In this final section, we prove Theorem \ref{main result} by combining estimates on exponential sums over elements in $\mathfrak{F}_{Q,k}^{(m)}$, and invoking the key Lemma \ref{key lemma} on weighted lattice point counting.
  \subsection{Proof of Theorem \ref{main result}}
 To prove Theorem \ref{main result}, we need to estimate, for any positive real number $\Lambda$, the quantity
\[S_{\mathfrak{F}_{Q,k}^{(m)}}^{(2)}(\Lambda)=\frac{1}{\mathcal{N}{(Q,k,m)}}\#\{(\gamma_1,\gamma_2)\in \left(\mathfrak{F}_{Q,k}^{(m)}\right)^2: \gamma_1\ne\gamma_2, \gamma_1-\gamma_2\in\frac{1}{\mathcal{N}{(Q,k,m)}}(0,\Lambda)+\mathbb{Z}\},\numberthis\label{S lambda}\]
as $Q\to \infty.$ 
% We use the approach of Boca and Zaharescu in \cite{BocaF}, and change the problem of counting the tuples in \eqref{S lambda} into estimating the exponential sum over Farey fractions with $k$-free denominators. We have
Let $H$ be any continuously differentiable function with Supp\ $H\subset(0,\Lambda)$. To estimate \eqref{S lambda}, we consider \eqref{k66} with $\nu=2$. We obtain
\[S_{Q,k}^{(2)}
     =\sum_{r\in \mathbb{Z}}c_r\sum_{\gamma_1\in \mathfrak{F}_{Q,k}^{(m)}}e(r\gamma_1)\sum_{\gamma_2\in \mathfrak{F}_{Q,k}^{(m)}}e(r\gamma_2).\numberthis\label{exp}\]
     We employ Lemma \ref{exp nu} into the above identity and express it as
\begin{align*}
    S_{Q,k}^{(2)}&=\sum_{r\in\mathbb{Z}}c_r\sum_{d_1,d_2\leq Q}\mu(d_1)\mu(d_2)\sum_{\substack{q_1\leq\frac{Q}{d_1}, q_2\leq\frac{Q}{d_2}\\ [q_1,q_2]|r\\ q_1d_1\equiv b\pmod{m}\\ q_2d_2\equiv b\pmod{m} }}q_1q_2\mu_k(q_1d_1)^2\mu_k(q_2d_2)^2\\
&=\sum_{d_1,d_2\leq Q}\mu(d_1)\mu(d_2)\sum_{\substack{q_1\leq\frac{Q}{d_1}, q_2\leq\frac{Q}{d_2}\\ q_1d_1\equiv b\pmod{m}\\ q_2d_2\equiv b\pmod{m} }}q_1q_2\mu_k(q_1d_1)^2\mu_k(q_2d_2)^2\sum_{r\in\mathbb{Z}}c_{r[q_1,q_2]},\numberthis\label{k35}
\end{align*}
where $[q_1,q_2]$ is least common multiple of $q_1$ and $q_2$. By using \cite[(3.4)]{Chaubey}, we obtain
\begin{align*}
\sum_{r\in\mathbb{Z}}c_{[q_1,q_2]r}&
%=\sum_{r\in\mathbb{Z}}\widehat{H}_{[q_1,q_2]}(r)
    %=\sum_{r\in\mathbb{Z}}H_{[q_1,q_2]}(r)
    =\sum_{r\in\mathbb{Z}}\frac{1}{[q_1,q_2]}H\left(\frac{r\mathcal{N}{(Q,k,m)}}{[q_1,q_2]} \right).\numberthis\label{k36}
\end{align*}
Using the above identity into \eqref{k35}, we obtain
\begin{align*}
   S_{Q,k}^{(2)} &= \sum_{d_1,d_2\leq Q}\mu(d_1)\mu(d_2)\sum_{\substack{q_1\leq\frac{Q}{d_1}, q_2\leq\frac{Q}{ d_2}\\ q_1d_1\equiv b\pmod{m}\\ q_2d_2\equiv b\pmod{m} }}\gcd(q_1,q_2)\mu_k(q_1d_1)^2\mu_k(q_2d_2)^2\sum_{r\in\mathbb{Z}}H\left(\frac{r\mathcal{N}{(Q,k,m)}}{[q_1,q_2]} \right)\\
   &=\sum_{\delta\leq Q}\delta \sum_{d_1,d_2\leq \frac{Q}{\delta}}\mu(d_1)\mu(d_2)\sum_{\substack{q_1\leq\frac{Q}{\delta d_1}, q_2\leq\frac{Q}{\delta d_2}\\ q_1\delta d_1\equiv b\pmod{m}\\ q_2\delta d_2\equiv b\pmod{m} \\ (q_1,q_2)=1}}\mu_k(q_1d_1\delta)^2\mu_k(q_2d_2\delta)^2\sum_{r\in\mathbb{Z}}H\left(\frac{r\mathcal{N}{(Q,k,m)}}{q_1q_2\delta} \right).\numberthis\label{k51}
\end{align*}
 For the non-zero contribution from $H$, using the fact that Supp$H \subset (0,\Lambda)$ and Proposition \ref{prop1}, one must have
\[0<\frac{\mathcal{N}{(Q,k,m)}r}{q_1q_2\delta}<\Lambda,\numberthis\label{nonzero contribution}\] which implies 
\[\delta d_1d_2r<\frac{\Lambda}{{\mathscr{C}(k,m)}}=:\mathcal{C}{(\Lambda,k,m)}.\]
By applying the above estimate and observing that
\[H\left(\frac{\mathcal{N}{(Q,k,m)}r}{q_1
q_2\delta} \right)=H\left(\frac{Q^2\mathscr{C}(k,m)r}{q_1q_2\delta} \right)+\BigOm{\frac{r}{q_1q_2\delta}Q^{\frac{2(2k-1)}{3k-2}}},\]
the sum in \eqref{k51} can be expressed as 
\begin{align*}
    S_{Q,k}^{(2)} =&\sum_{\substack{d_1,d_2,\delta, r\geq 1\\\delta d_1d_2r<\mathcal{C}{(\Lambda,k,m)}}}\delta \mu(d_1)\mu(d_2)\sum_{\substack{q_1\leq\frac{Q}{\delta d_1}, q_2\leq\frac{Q}{\delta d_2}\\ q_1\delta d_1\equiv b\pmod{m}\\ q_2\delta d_2\equiv b\pmod{m} \\ (q_1,q_2)=1}}\mu_k(q_1d_1\delta)^2\mu_k(q_2d_2\delta)^2H\left(\frac{Q^2\mathscr{C}(k,m)r}{q_1q_2\delta} \right)\\ &+\BigOm{Q^{\frac{2(2k-1)}{3k-2}}(\log Q)^2}\\
    =&\frac{1}{\phi^2(m)}\sum_{\substack{\chi(\text{mod}\ {m})\\\chi^{\prime}(\text{mod}\ {m})}}\sum_{\substack{d_1, d_2,\delta, r\geq 1\\\delta d_1d_2r<{\mathcal{C}(\Lambda,k,m)}}}\delta {\chi}(\delta d_1\bar{b}){\chi^{\prime}}(\delta d_2\bar{b})\mu_k(\delta)^2\mu(d_1)\mu(d_2)\sum_{\substack{q_1\leq\frac{Q}{\delta d_1}, q_2\leq\frac{Q}{\delta d_2}\\(q_1,q_2)=1 }}\chi(q_1)\chi^{\prime}(q_2)\\&\times\mu_k(q_1d_1\delta)^2\mu_k(q_2d_2\delta)^2 H\left(\frac{Q^2\mathscr{C}(k,m)r}{q_1q_2\delta} \right)+\BigOm{Q^{\frac{2(2k-1)}{3k-2}}(\log Q)^2}.\numberthis\label{k61}
\end{align*}
Next, we deal with the cases of principal and non-principal characters separately.

Case-I: If $\chi=\chi_0$ and $\chi^{\prime}=\chi_0^{\prime}$ then we have
\begin{align*}
   S_{Q,k}^{(2)}(\chi_0,\chi_0^{\prime})&=\sum_{\substack{d_1, d_2,\delta, r\geq 1\\\delta d_1d_2r<{\mathcal{C}(\Lambda,k,m)}\\(d_1d_2\delta,m)=1}}\delta\mu_k(\delta)^2\mu(d_1)\mu(d_2)\sum_{\substack{q_1\leq\frac{Q}{\delta d_1}, q_2\leq\frac{Q}{\delta d_2}\\ (q_1q_2,m)=1=(q_1,q_2) }}\mu_k(q_1d_1\delta)^2\mu_k(q_2d_2\delta)^2 H\left(\frac{Q^2\mathscr{C}(k,m)r}{q_1q_2\delta} \right)\numberthis\label{k57}.  
\end{align*}
To estimate the inner sum in the above identity, we employ Lemma \ref{key lemma} which counts the $k$-free lattice points with some weight and congruence constraints. Note that, since Supp $H\subset(0,\Lambda)$, for the non-zero contribution from $H$, one has $0<\frac{Q^2\mathscr{C}(k,m)r}{x_1x_2\delta}<\Lambda$. For $0<x_1\leq \frac{Q}{\delta d_1}$ and $0<x_2\leq \frac{Q}{\delta d_2}$, we obtain
\[\frac{1}{x_1}\leq \frac{\mathcal{C}{(\Lambda,k,m)}}{rd_2Q}\ \text{and}\ \frac{1}{x_2}\leq \frac{\mathcal{C}{(\Lambda,k,m)}}{rd_1Q}. \numberthis\label{x_1}\]
%Similarly
%\[\frac{1}{x_2}\leq \frac{\mathcal{C}_{\Lambda}}{rd_1Q}.\numberthis\label{x_2}\]
Using \eqref{x_1} and the necessary condition for the non-zero contribution of $H$,  we get
\[\left|\frac{\partial H}{\partial x_1}(x_1,x_2)\right|\ll\frac{1}{Q}\ \text{and}\ \left|\frac{\partial H}{\partial x_2}(x_1,x_2)\right|\ll\frac{1}{Q}.\]
Hence
\[\|DH\|_{\infty}\ll\frac{1}{Q}.\]
Employing Lemma \ref{key lemma} with $r_1=r_2=m,\ \delta_1=d_1\delta,\ \delta_2=d_2\delta$, and $f(a,b)=H\left(\frac{Q^2\mathscr{C}(k,m)r}{ab\delta} \right)$, the inner-sum in \eqref{k57} is expressed as
\begin{align*}
    \sum_{\substack{q_1\leq\frac{Q}{\delta d_1}, q_2\leq\frac{Q}{\delta d_2}\\ (q_1q_2,m)=1, (q_1,q_2)=1 }}&\mu_k(q_1d_1\delta)^2\mu_k(q_2d_2\delta)^2H\left(\frac{Q^2\mathscr{C}(k,m)r}{q_1q_2\delta} \right)\\&=\frac{6P_{m,m}^{k}(d_1\delta,d_2\delta)}{\pi^2}\int_0^{\frac{Q}{\delta d_1}}\int_0^{\frac{Q}{\delta d_2}}  H\left(\frac{Q^2\mathscr{C}(k,m)r}{xy\delta} \right)dxdy+\BigOm{\tau(m)Q^{1+\frac{1}{k}}\log^2Q}.\numberthis\label{k4}
\end{align*}
Using the fact that Supp$H\subset(0,\lambda)$ and by a suitable change of variable the integral in \eqref{k4} can be expressed as
\[\int_0^{\frac{Q}{\delta d_1}}\int_0^{\frac{Q}{\delta d_2}}H\left(\frac{Q^2\mathscr{C}(k,m)r}{xy\delta} \right)dxdy=\frac{Q^2\mathscr{C}(k,m)r}{\delta}\int_{r\delta d_1d_2\mathscr{C}(k,m)}^{\Lambda}\frac{H(\lambda)}{\lambda^2}\log\left(\frac{\lambda}{r\delta d_1d_2\mathscr{C}(k,m)} \right)d\lambda. \]
The above identity with \eqref{k57} and \eqref{k4} gives
\begin{align*}
    S_{Q,k}^{(2)}(\chi_0,\chi_0^{\prime})=&\frac{6Q^2\mathscr{C}(k,m)}{\pi^2}\sum_{\substack{d_1, d_2,\delta, r\geq 1\\\delta d_1d_2r<{\mathcal{C}(\Lambda,k,m)}\\(d_1d_2\delta,m)=1}}r\mu_k(\delta)^2\mu(d_1)\mu(d_2)P_{m,m}^{k}(d_1\delta,d_2\delta)\int_{r\delta d_1d_2\mathscr{C}(k,m)}^{\Lambda}\frac{H(\lambda)}{\lambda^2}\\&\times\log\left(\frac{\lambda}{r\delta d_1d_2\mathscr{C}(k,m)} \right)d\lambda+\BigOm{Q^{1+\frac{1}{k}}\log^2Q}\\
    =&\frac{6Q^2\mathscr{C}(k,m)}{\pi^2}\sum_{1\leq n<\mathcal{C}(\Lambda,k,m)}\int_{n\mathscr{C}(k,m)}^{\Lambda}\frac{H(\lambda)}{\lambda^2}\log\left(\frac{\lambda}{n\mathscr{C}(k,m)} \right)d\lambda\\&\times\sum_{\substack{\delta d_1d_2r=n\\(d_1d_2\delta,m)=1}}r\mu_k(\delta)^2\mu(d_1)\mu(d_2)P_{m,m}^{k}(d_1\delta,d_2\delta)+\BigOm{Q^{1+\frac{1}{k}}\log^2Q}\\
    =&\frac{6Q^2\mathscr{C}(k,m)}{\pi^2}\int_{0}^{\Lambda}\frac{H(\lambda)}{\lambda^2}\sum_{1\leq n<\mathcal{C}(\Lambda,k,m)}F_k(n)\log\left(\frac{\lambda}{n \mathscr{C}(k,m)} \right)d\lambda+\BigOm{Q^{1+\frac{1}{k}}\log^2Q},\numberthis\label{k62}
\end{align*}
where
\begin{align*}
    F_k(n)=\sum_{\substack{\delta d_1d_2r=n\\(d_1d_2\delta,m)=1}}r\mu_k(\delta)^2\mu(d_1)\mu(d_2)P_{m,m}^{k}(d_1\delta,d_2\delta).
\end{align*}

Case-II: Suppose at least one of $\chi$ or $\chi^{\prime}$ is non-principal.
\begin{align*}
  S_{Q,k}^{(2)}(\chi,\chi^{\prime})=& \sum_{\substack{d_1, d_2,\delta, r\geq 1\\\delta d_1d_2r<{\mathcal{C}(\Lambda,k,m)}}}\delta {\chi}(\delta d_1\bar{b}){\chi^{\prime}}(\delta d_2\bar{b})\mu_k(\delta)^2\mu(d_1)\mu(d_2)\sum_{\substack{q_1\leq\frac{Q}{\delta d_1}, q_2\leq\frac{Q}{\delta d_2}\\ (q_1,q_2)=1 }}\chi(q_1)\chi^{\prime}(q_2)\\&\times \mu_k(q_1d_1\delta)^2\mu_k(q_2d_2\delta)^2H\left(\frac{Q^2\mathscr{C}(k,m)r}{q_1q_2\delta} \right)\\
  =& \sum_{\substack{d_1, d_2,\delta, r\geq 1\\\delta d_1d_2r<{\mathcal{C}(\Lambda,k,m)}}}\delta {\chi}(\delta d_1\bar{b}){\chi^{\prime}}(\delta d_2\bar{b})\mu_k(\delta)^2\mu(d_1)\mu(d_2)\sum_{\substack{q_1\leq\frac{Q}{\delta d_1}}}\chi(q_1)\mu_k(q_1d_1\delta)^2\\&\times\sum_{\substack{q_2\leq\frac{Q}{\delta d_2}\\(q_2, q_1)=1}}\chi^{\prime}(q_2)\mu_k(q_2d_2\delta)^2 H\left(\frac{Q^2\mathscr{C}(k,m)r}{q_1q_2\delta} \right).\numberthis\label{k42}
\end{align*}
In order to estimate the inner sum in the above identity, we use Proposition \ref{prop15} with $f\left(\frac{M}{q_2} \right)=H\left(\frac{Q^2\mathscr{C}(k,m)r}{q_1q_2\delta} \right)$ and obtain
\[\sum_{\substack{q_2\leq\frac{Q}{\delta d_2}\\(q_2, q_1)=1}}\chi^{\prime}(q_2)\mu_k(q_2d_2\delta)^2 H\left(\frac{Q^2\mathscr{C}(k,m)r}{q_1q_2\delta} \right)\ll_{m} \tau(q_1)\left(\frac{Q}{\delta d_2}\right)^{\frac{1}{k}}\log \frac{Q}{\delta d_2}, \]
and this in conjunction with \eqref{k42} yields
\[S_{Q,k}^{(2)}(\chi,\chi^{\prime})\ll_{m} Q^{1+\frac{1}{k}+\epsilon}\log Q. \numberthis\label{k27}\]
We collect the estimates from \eqref{k62} and \eqref{k27} and insert them into \eqref{k61}. We obtain
\begin{align*}
   S_{Q,k}^{(2)} &=\frac{6Q^2\mathscr{C}(k,m)}{\pi^2\phi^2(m)}\int_{0}^{\Lambda}\frac{H(\lambda)}{\lambda^2}\sum_{1\leq n<\mathcal{C}(\Lambda,k,m)}F_k(n)\log\left(\frac{\lambda}{n \mathscr{C}(k,m)} \right)d\lambda+\BigOm{Q^{1+\frac{1}{k}+\epsilon}\log^2Q}\\
   &=Q^2\mathscr{C}(k,m)\int_{0}^{\Lambda}H(\lambda)\mathfrak{g}_{m,k}(\lambda)d\lambda+\BigOm{Q^{1+\frac{1}{k}+\epsilon}\log^2Q}.
\end{align*}
Therefore
\[\frac{S_{Q,k}^{(2)}}{\mathcal{N}(Q,k)}=\int_{0}^{\Lambda}H(\lambda)\mathfrak{g}_{m,k}(\lambda)d\lambda+\BigOm{Q^{-1+\frac{1}{k}+\epsilon}\log^2Q}. \]
We next approximate $H$ by the characteristic function of $(0,\Lambda)$, using the standard approximation argument, to obtain
\[\mathcal{S}^{2}((0,\Lambda))=\lim_{Q\to\infty}S_{\mathfrak{F}_{Q,k}^{(m)}}^{(2)}(\Lambda)=\int_0^{\Lambda}\mathfrak{g}_{m,k}(\lambda)d\lambda.\]
This completes the proof of Theorem \ref{main result}.
