import pandas as pd
from robustipy.models import OLSRobust

# 1. Simulation parameters
n, p = 1000, 5
sigma_X = np.eye(p)
rng = np.random.default_rng()

# 2. Draw covariates X and error e
X = rng.multivariate_normal(mean=np.zeros(p), cov=sigma_X, size=n)
e = rng.standard_normal(n)

# 3. Stack beta‐vectors into a (4×p) matrix
B = np.array([
    [0.20,  0.50, -0.40, -0.10, 0.20],
    [0.30,  0.40, -0.35, -0.10, 0.20],
    [0.15,  0.60, -0.45, -0.10, 0.20],
    [0.40,  0.30, -0.50, -0.10, 0.20],
])  # shape = (4, p)

# 4. Build df, generate outcomes y_1…y_4 and controls z_1…z_4
