\begin{equation*}
	\lim_{i\to\infty}\int_{\Omega\setminus U} \abs{\nabla\cdot u_i}^2\,\di x = \lim_{i\to\infty}\int_{\Omega\setminus U} \abs{\nabla\cdot\widehat{u}_i}^2\,\di x = \lim_{i\to\infty}\int_{\Omega\setminus U} \abs{\nabla\cdot\widetilde{u}_i}^2\,\di x = 0.
\end{equation*}
%
We may write
%
\begin{equation} \label{eq:caseB}
	\Lambda-\Lambda_{\emptyset}^C = (\Lambda - \Lambda_2) + (\Lambda_2-\Lambda_1) + (\Lambda_1-\Lambda_0) + (\Lambda_0-\Lambda_\emptyset^C),
\end{equation}
%
and separately estimate each of the above of differences. Using Lemmas~\ref{lemma:monoback}--\ref{lemma:monoC0} gives:
%
\begin{align}
	\inner{(\Lambda - \Lambda_2)g_i,g_i} &\leq  \int_{\Dm\cup\Dp} \frac{\lambda_0}{\lambda}(\lambda_0-\lambda)\abs{\nabla\cdot \widetilde{u}_i}^2 + 2\frac{\mu_0}{\mu}(\mu_0-\mu)\frob{\widehat{\nabla}\widetilde{u}_i}^2\,\di x, \label{eq:caseB1}\\
