	\inner{(\Lambda_0-\Lambda_\emptyset^C)g_i,g_i} &\leq K\int_C \frob{\widehat{\nabla}u_i}^2\,\di x. \label{eq:caseB4}
\end{align}
%
The right-hand sides of \eqref{eq:caseB3}, \eqref{eq:caseB4}, and the part of the integral over $\Dm$ in \eqref{eq:caseB1} tend to zero as $C\cup D_0\cup \Dm \subset \Omega\setminus\overline{U}$. By Assumption~\ref{assump:technical} we may assume that $\inf_B(\mu_+-\mu_0)>0$. Since $B\subset \Dp$, $\lambda_+\geq\lambda_0$, and $\mu_+\geq \mu_0$, the right-hand side of \eqref{eq:caseB1} tends to minus infinity for $i\to\infty$. From \eqref{eq:caseB} we thus have
