\section{Proof of Theorem~\ref{thm:monopos}} \label{sec:monoposproof}

\subsection*{Proof of ``$\boldsymbol{B\subset D \Rightarrow \Lambda_{\beta,B}\geq \Lambda_\emptyset^{D}}$''}

Define the following truncated Lam\'e parameters:
%
\begin{equation} \label{eq:epspos}
	\lambda_\epsilon = \begin{cases}
		\lambda_0 & \text{in } \Omega\setminus D\\
		\epsilon^{-1}\lambda_0 & \text{in } D
	\end{cases}
	\quad \text{and}
	\quad
	\mu_\epsilon = \begin{cases}
		\mu_0 & \text{in } \Omega\setminus D\\
		\epsilon^{-1}\mu_0 & \text{in } D.
	\end{cases}
\end{equation}
%
As $B\subset D$, for small enough $\epsilon>0$ we have $\lambda_0+\beta\chi_B \leq \lambda_\epsilon$ and $\mu_0+\beta\chi_B \leq \mu_\epsilon$. Thus Lemma~\ref{lemma:monoback} implies $\Lambda_{\beta,B}\geq \Lambda(\lambda_\epsilon,\mu_\epsilon)$. Now the convergence in operator norm as $\epsilon\to 0$ by Theorem~\ref{thm:convergence} implies $\Lambda_{\beta,B}\geq \Lambda_\emptyset^{D}$.

\subsection*{Proof of ``$\boldsymbol{B\subset D \Rightarrow \Lambda_0 + \DLambda_{\beta,B}\geq \Lambda_\emptyset^{D}}$''}

We use the notation
%
\begin{equation} \label{eq:kappa}
	\kappa = \min\{\inf(\lambda_0),\inf(\mu_0)\},
\end{equation}
%
and fix an $\alpha_0>0$ satisfying
%
\begin{equation} \label{eq:alpha0}
	\beta \leq \frac{\alpha_0}{1+\alpha_0}\kappa.
\end{equation}
%
Now we consider a small enough $\epsilon>0$ such that
%
\begin{equation} \label{eq:epsalph1}
	1-\epsilon \geq \frac{\alpha_0}{1+\alpha_0}.
\end{equation}
%
Let $\lambda_\epsilon$ and $\mu_\epsilon$ be as in \eqref{eq:epspos} and $u_0 = u_g^{\lambda_0,\mu_0}$. The set inclusion $B\subset D$ combined with Lemma~\ref{lemma:monoback} and \eqref{eq:kappa}--\eqref{eq:epsalph1} gives
%
\begin{align*}
	\inner{(\Lambda_0 + \DLambda_{\beta,B} - \Lambda(\lambda_\epsilon,\mu_\epsilon))g,g} \hspace{-3cm}& \\
	&\geq \int_D (1-\epsilon)\lambda_0\abs{\nabla u_0}^2 + 2(1-\epsilon)\mu_0\frob{\widehat{\nabla}u_0}^2\,\di x -\beta \int_B \abs{\nabla\cdot u_0}^2 + 2\frob{\widehat{\nabla}u_0}^2\, \di x \\
	&\geq \int_B [(1-\epsilon)\lambda_0-\beta]\abs{\nabla u_0}^2 + 2[(1-\epsilon)\mu_0-\beta]\frob{\widehat{\nabla}u_0}^2\,\di x \\
	&\geq \frac{\alpha_0}{1+\alpha_0}\int_B (\lambda_0-\kappa)\abs{\nabla u_0}^2 + 2(\mu_0-\kappa)\frob{\widehat{\nabla}u_0}^2\,\di x \geq 0.
\end{align*}
%
Using Theorem~\ref{thm:convergence}, the operator norm convergence for $\epsilon\to 0$ yields $\Lambda_0 + \DLambda_{\beta,B} \geq \Lambda_\emptyset^{D}$.

\subsection*{Proof of ``$\boldsymbol{\Lambda_{\beta,B}\geq \Lambda_\emptyset^{D} \Rightarrow B\subset D}$''}

Let $u_0 = u_g^{\lambda_0,\mu_0}$. Lemma~\ref{lemma:monoback} and Lemma~\ref{lemma:monoCinfty} give
%
\begin{align}
	\inner{(\Lambda_{\beta,B}-\Lambda_\emptyset^D)g,g} &= \inner{(\Lambda_{\beta,B}-\Lambda_0)g,g} + \inner{(\Lambda_0-\Lambda_\emptyset^D)g,g} \notag\\
	&\leq K\int_D \frob{\widehat{\nabla}u_0}^2\,\di x - \beta\int_B \frac{\lambda_0}{\lambda_0+\beta}\abs{\nabla\cdot u_0}^2 + 2\frac{\mu_0}{\mu_0+\beta}\frob{\widehat{\nabla}u_0}^2\,\di x. \label{eq:extramonopos}
\end{align}
%
Assume $B\not\subset D$ so that $B\setminus D$ contains an open ball $\widehat{B}$, in which we may concentrate localized potentials via a suitable set $U$. To this end, let $U\subset\overline{\Omega}$ be a relatively open connected set that intersects $\GammaN$, compactly contains $\widehat{B}$, and satisfies $\overline{U}\cap D = \emptyset$. Pick $(g_i)$ in $L^2_\diamond(\GammaN)^d$ via Lemma~\ref{lemma:locpot} such that $u_i = u_{g_i}^{\lambda_0,\mu_0}$ satisfies
%
\begin{equation*}
	\lim_{i\to\infty}\int_B \abs{\nabla\cdot u_i}^2\,\di x = \lim_{i\to\infty}\int_B \frob{\widehat{\nabla}u_i}^2\,\di x = \infty 
\end{equation*}
%
and
%
\begin{equation*}
	\lim_{i\to\infty}\int_D \abs{\nabla\cdot u_i}^2\,\di x = \lim_{i\to\infty}\int_D \frob{\widehat{\nabla}u_i}^2\,\di x = 0,
\end{equation*}
%
where we used the set inclusions $D\subset\Omega\setminus\overline{U}$ and $\widehat{B}\subseteq B$. Now \eqref{eq:extramonopos} gives
%
\begin{align*}
	\inner{(\Lambda_{\beta,B}-\Lambda_\emptyset^D)g_i,g_i} \hspace{-2cm}& \\
	&\leq K\int_D \frob{\widehat{\nabla}u_i}^2\,\di x - \beta\int_B \frac{\lambda_0}{\lambda_0+\beta}\abs{\nabla\cdot u_i}^2 + 2\frac{\mu_0}{\mu_0+\beta}\frob{\widehat{\nabla}u_i}^2\,\di x \to -\infty
\end{align*}
%
for $i\to\infty$. Thereby $B\not\subset D$ implies $\Lambda_{\beta,B} \not\geq \Lambda_\emptyset^{D}$, which is the contrapositive formulation of the statement we are proving.

\subsection*{Proof of ``$\boldsymbol{\Lambda_0 + \DLambda_{\beta,B}\geq \Lambda_\emptyset^{D} \Rightarrow B\subset D}$''}

Assume $B\not\subset D$. We pick $(g_i)$ in $L^2_\diamond(\GammaN)^d$ and $u_i = u_{g_i}^{\lambda_0,\mu_0}$ as in the proof of ``$\Lambda_{\beta,B}\geq \Lambda_\emptyset^{D} \Rightarrow B\subset D$''. Now Lemma~\ref{lemma:monoCinfty} gives
%
\begin{align*}
	\inner{(\Lambda_0 + \DLambda_{\beta,B} - \Lambda_\emptyset^{D})g_i,g_i} \hspace{-2cm}& \\
	&\leq K\int_D \frob{\widehat{\nabla}u_i}^2\,\di x -\beta \int_B \abs{\nabla\cdot u_i}^2 + 2\frob{\widehat{\nabla}u_i}^2\, \di x \to -\infty
\end{align*}
%
for $i\to\infty$. Thereby $B\not\subset D$ implies $\Lambda_0 + \DLambda_{\beta,B} \not\geq \Lambda_\emptyset^{D}$, which is the contrapositive formulation of the statement we are proving.

\section{Proof of Theorem~\ref{thm:mononeg}} \label{sec:mononegproof}

\subsection*{Proof of ``$\boldsymbol{B\subset D \Rightarrow \Lambda_D^{\emptyset} \geq \Lambda_{-\beta,B}}$''}

Define the following truncated Lam\'e parameters:
%
\begin{equation}  \label{eq:epsneg}
	\lambda_\epsilon = \begin{cases}
		\lambda_0 & \text{in } \Omega\setminus D\\
		\epsilon\lambda_0 & \text{in } D
	\end{cases}
	\quad \text{and}
	\quad
	\mu_\epsilon = \begin{cases}
		\mu_0 & \text{in } \Omega\setminus D\\
		\epsilon\mu_0 & \text{in } D.
	\end{cases}
\end{equation}
%
As $B\subset D$ and $\beta < \kappa$ by \eqref{eq:kappa}, for small enough $\epsilon>0$ we have $\lambda_\epsilon \leq \lambda_0-\beta\chi_B$ and $\mu_\epsilon \leq \mu_0-\beta\chi_B$. Thus Lemma~\ref{lemma:monoback} implies $\Lambda(\lambda_\epsilon,\mu_\epsilon) \geq \Lambda_{-\beta,B}$. Now the convergence in operator norm as $\epsilon\to 0$ guaranteed by Theorem~\ref{thm:convergence} implies $\Lambda_D^{\emptyset} \geq \Lambda_{-\beta,B}$.

\subsection*{Proof of ``$\boldsymbol{B\subset D \Rightarrow \Lambda_D^{\emptyset} \geq \Lambda_0 + \DLambda_{-\beta,B}}$''}

Let $\lambda_\epsilon$ and $\mu_\epsilon$ be as in \eqref{eq:epsneg} and $u_0 = u_g^{\lambda_0,\mu_0}$. The set inclusion $B\subset D$ combined with Lemma~\ref{lemma:monoback} and \eqref{eq:kappa}--\eqref{eq:epsalph1} gives
%
\begin{align*}
	\inner{(\Lambda(\lambda_\epsilon,\mu_\epsilon) - \Lambda_0 - \DLambda_{-\beta,B})g,g} \hspace{-3cm}& \\
	&\geq \int_D (1-\epsilon)\lambda_0\abs{\nabla u_0}^2 + 2(1-\epsilon)\mu_0\frob{\widehat{\nabla}u_0}^2\,\di x -\beta \int_B \abs{\nabla\cdot u_0}^2 + 2\frob{\widehat{\nabla}u_0}^2\, \di x \\
	&\geq \int_B [(1-\epsilon)\lambda_0-\beta]\abs{\nabla u_0}^2 + 2[(1-\epsilon)\mu_0-\beta]\frob{\widehat{\nabla}u_0}^2\,\di x \\
	&\geq \frac{\alpha_0}{1+\alpha_0}\int_B (\lambda_0-\kappa)\abs{\nabla u_0}^2 + 2(\mu_0-\kappa)\frob{\widehat{\nabla}u_0}^2\,\di x \geq 0.
\end{align*}
%
Using Theorem~\ref{thm:convergence}, the operator norm convergence for $\epsilon\to 0$ yields $\Lambda_D^{\emptyset} \geq \Lambda_0 + \DLambda_{-\beta,B}$.

\subsection*{Proof of ``$\boldsymbol{\Lambda_D^{\emptyset} \geq \Lambda_{-\beta,B} \Rightarrow B\subset D}$''}

We set
%
\begin{equation}  \label{eq:Dneg}
	\lambda = \begin{cases}
		\lambda_0 & \text{in } \Omega\setminus D\\
		0 & \text{in } D
	\end{cases}
	\quad \text{and}
	\quad
	\mu = \begin{cases}
		\mu_0 & \text{in } \Omega\setminus D\\
		0 & \text{in } D.
	\end{cases}
\end{equation}
%
Let $\lambda_\epsilon$ and $\mu_\epsilon$ be as in \eqref{eq:epsneg} and $u_\epsilon = u_g^{\lambda_\epsilon,\mu_\epsilon}$. Then Lemma~\ref{lemma:monoback} gives
%
\begin{equation*}
	\inner{(\Lambda(\lambda_\epsilon,\mu_\epsilon)-\Lambda_{-\beta,B})g,g} \leq (1-\epsilon)\int_D\lambda_0\abs{\nabla\cdot u_\epsilon}^2+2\mu_0\frob{\widehat{\nabla}u_\epsilon}^2\,\di x - \beta\int_B\abs{\nabla\cdot u_\epsilon}^2+2\frob{\widehat{\nabla}u_\epsilon}^2\,\di x.
\end{equation*}
%
Letting $\epsilon\to 0$ and using Theorem~\ref{thm:convergence} yields
%
\begin{equation} \label{eq:extramononeg}
	\inner{(\Lambda_D^\emptyset-\Lambda_{-\beta,B})g,g} \leq \int_D\lambda_0\abs{\nabla\cdot \widehat{u}}^2+2\mu_0\frob{\widehat{\nabla}\widehat{u}}^2\,\di x - \beta\int_B\abs{\nabla\cdot \widehat{u}}^2+2\frob{\widehat{\nabla}\widehat{u}}^2\,\di x,
\end{equation}
%
where $\widehat{u} = Eu_g^{\lambda,\mu}$.

Assume $B\not\subset D$ so that $B\setminus D$ contains an open ball $\widehat{B}$, in which we may concentrate localized potentials via a suitable set $U$. To this end, let $U\subset\overline{\Omega}$ be a relatively open connected set that intersects $\GammaN$, compactly contains $\widehat{B}$, and satisfies $\overline{U}\cap D = \emptyset$. We now pick $(g_i)$ in $L^2_\diamond(\GammaN)^d$ via Lemma~\ref{lemma:locpot} and Lemma~\ref{lemma:locpotextreme} such that $\widehat{u}_i = Eu_{g_i}^{\lambda,\mu}$ satisfies
%
\begin{equation*}
	\lim_{i\to\infty}\int_B \abs{\nabla\cdot \widehat{u}_i}^2\,\di x = \lim_{i\to\infty}\int_B \frob{\widehat{\nabla}\widehat{u}_i}^2\,\di x = \infty
\end{equation*}
%
and
%
\begin{equation*}
	\lim_{i\to\infty}\int_D \abs{\nabla\cdot \widehat{u}_i}^2\,\di x = \lim_{i\to\infty}\int_D \frob{\widehat{\nabla}\widehat{u}_i}^2\,\di x = 0,
\end{equation*}
%
where we used the set inclusions $D\subset\Omega\setminus\overline{U}$ and $\widehat{B}\subseteq B$. Now \eqref{eq:extramononeg} gives
%
\begin{align*}
	\inner{(\Lambda_D^{\emptyset} - \Lambda_{-\beta,B})g_i,g_i} \hspace{-2cm}& \\
	&\leq \int_D \lambda_0\abs{\nabla\cdot \widehat{u}_i}^2 + 2\mu_0\frob{\widehat{\nabla}\widehat{u}_i}^2\,\di x -\beta \int_B \abs{\nabla\cdot \widehat{u}_i}^2 + 2\frob{\widehat{\nabla}\widehat{u}_i}^2\, \di x \to -\infty
\end{align*}
%
for $i\to\infty$. Thereby $B\not\subset D$ implies $\Lambda_D^{\emptyset} \not\geq \Lambda_{-\beta,B}$, which is the contrapositive formulation of the statement we are proving.

\subsection*{Proof of ``$\boldsymbol{\Lambda_D^{\emptyset} \geq \Lambda_0 + \DLambda_{-\beta,B} \Rightarrow B\subset D}$''}

Assume $B\not\subset D$ and let $\lambda$ and $\mu$ be as in \eqref{eq:Dneg}. We pick $(g_i)$ in $L^2_\diamond(\GammaN)^d$ as in the proof of ``$\Lambda_D^{\emptyset} \geq \Lambda_{-\beta,B} \Rightarrow B\subset D$'', such that $u_i = u_{g_i}^{\lambda_0,\mu_0}$ and $\widehat{u}_i = Eu_{g_i}^{\lambda,\mu}$ satisfy
%
\begin{equation*}
	\lim_{i\to\infty}\int_B \abs{\nabla\cdot u_i}^2\,\di x = \lim_{i\to\infty}\int_B \frob{\widehat{\nabla}u_i}^2\,\di x = \infty
\end{equation*}
%
and
%
\begin{equation*}
	\lim_{i\to\infty}\int_D \abs{\nabla\cdot \widehat{u}_i}^2\,\di x = \lim_{i\to\infty}\int_D \frob{\widehat{\nabla}\widehat{u}_i}^2\,\di x = 0.
\end{equation*}
%
Now Lemma~\ref{lemma:monoC0} gives
%
\begin{align*}
	\inner{(\Lambda_D^\emptyset - \Lambda_0 - \DLambda_{-\beta,B})g_i,g_i} \hspace{-2cm}& \\
	&\leq \int_D \lambda_0\abs{\nabla\cdot \widehat{u}_i}^2 + 2\mu_0\frob{\widehat{\nabla}\widehat{u}_i}^2\,\di x -\beta \int_B \abs{\nabla\cdot u_i}^2 + 2\frob{\widehat{\nabla}u_i}^2\, \di x \to -\infty
\end{align*}
%
for $i\to\infty$. Thereby $B\not\subset D$ implies $\Lambda_D^{\emptyset} \not\geq \Lambda_0 + \DLambda_{-\beta,B}$, which is the contrapositive formulation of the statement we are proving.

\section{Proof of Theorem~\ref{thm:monofinitelin}} \label{sec:monofinitelinptoof}

Recall from Definition~\ref{def:posneginc} that $D = \Dm\cup\Dp$ in case of \emph{non-extreme} inclusions, and $\lambda$ and $\mu$ are on the form
%
\begin{equation*} 
	\lambda = \begin{cases}
		\lambda_0 & \text{in } \Omega\setminus D \\
		\lambda_- & \text{in } \Dm \\
		\lambda_+ & \text{in } \Dp 
	\end{cases}
	\quad\text{and}\quad
	\mu = \begin{cases}
		\mu_0 & \text{in } \Omega\setminus D \\
		\mu_- & \text{in } \Dm \\
		\mu_+ & \text{in } \Dp,
	\end{cases}
\end{equation*}
%
where $\lambda_- \leq \lambda_0 \leq \lambda_+$ and $\mu_-\leq\mu_0\leq\mu_+$ (all functions in $L^\infty_+(\Omega)$) and satisfy Assumption~\ref{assump:technical}.

\subsection*{Proof of ``$\boldsymbol{D\subseteq C \Rightarrow \Lambda_0 + \DLambda_{-\betaU\beta,C} \geq \Lambda(\lambda,\mu) \geq \Lambda_0 + \DLambda_{\beta,C}}$''}

Let $u_0 = u_g^{\lambda_0,\mu_0}$. Since $D\subseteq C$, $\lambda_- \leq \lambda_0$, and $\mu_- \leq \mu_0$, the assumption \eqref{eq:betalinpos} and Lemma~\ref{lemma:monoback} give
%
\begin{align*}
	\inner{(\Lambda(\lambda,\mu) - \Lambda_0 - \DLambda_{\beta,C})g,g} \hspace{-3cm}&\\
	&\geq \int_{\Dp} (\lambda_0 - \lambda_+)\abs{\nabla\cdot u_0}^2 + 2(\mu_0-\mu_+)\frob{\widehat{\nabla}u_0}^2\,\di x + \beta\int_C \abs{\nabla\cdot u_0}^2 +2\frob{\widehat{\nabla}u_0}^2\,\di x \\
	&\geq \beta\int_{C\setminus \Dp} \abs{\nabla\cdot u_0}^2 +2\frob{\widehat{\nabla}u_0}^2\,\di x \geq 0.
\end{align*}
%
Next we consider the other inequality. \eqref{eq:betaL}, \eqref{eq:betaU}, and \eqref{eq:betalinneg} imply
%
\begin{equation} \label{eq:monolinneg1}
	\frac{\lambda_0}{\lambda_-}(\lambda_- - \lambda_0) = \frac{\lambda_0(\lambda_- - \lambda_0)}{\lambda_0 + (\lambda_- - \lambda_0)} \geq \frac{-\betaU\frac{\beta}{1+\beta}\betaL}{\betaL - \frac{\beta}{1+\beta}\betaL} = -\betaU\beta.
\end{equation}
%
A similar computation also gives
%
\begin{equation} \label{eq:monolinneg2}
	\frac{\mu_0}{\mu_-}(\mu_- - \mu_0) \geq -\betaU\beta.
\end{equation}
%
Since $D\subseteq C$, $\lambda_+\geq\lambda_0$, and $\mu_+\geq\mu_0$, the estimates \eqref{eq:monolinneg1}, \eqref{eq:monolinneg2}, and Lemma~\ref{lemma:monoback} give
%
\begin{align*}
	\inner{(\Lambda_0 + \DLambda_{-\betaU\beta,C} - \Lambda(\lambda,\mu))g,g} \hspace{-4.5cm}&\\
	&\geq \int_{\Dm} \frac{\lambda_0}{\lambda_-}(\lambda_- - \lambda_0)\abs{\nabla\cdot u_0}^2 + 2\frac{\mu_0}{\mu_-}(\mu_- - \mu_0)\frob{\widehat{\nabla}u_0}^2\,\di x + \betaU\beta\int_C \abs{\nabla\cdot u_0}^2 +2\frob{\widehat{\nabla}u_0}^2\,\di x \\
	&\geq \betaU\beta \int_{C\setminus \Dm} \abs{\nabla\cdot u_0}^2 +2\frob{\widehat{\nabla}u_0}^2\,\di x \geq 0.
\end{align*}

\subsection*{Proof of ``$\boldsymbol{\Lambda_0 + \DLambda_{-\betaU\beta,C} \geq \Lambda(\lambda,\mu) \geq \Lambda_0 + \DLambda_{\beta,C} \Rightarrow D\subseteq C}$''}

Assume that $D\not\subseteq C$. Since $D,C\in\mathcal{A}$ and by Assumption~\ref{assump:technical}, there exists an open ball $B\subset D\setminus C$ and a relatively open connected set $U\subset \overline{\Omega}$, such that $U$ intersects $\GammaN$, $B\Subset U$, $\overline{U}\cap C = \emptyset$, and one of two options holds:
%
\begin{equation*}
	\textup{Case A: } \overline{U}\cap D \subseteq \Dp \quad \text{or} \quad
	\textup{Case B: } \overline{U}\cap D \subseteq \Dm.
\end{equation*}
%
We consider these cases separately. 

As we shall see below, the combination of the two cases proves that $D\not\subseteq C$ implies either $\Lambda_0 + \DLambda_{-\betaU\beta,C} \not\geq \Lambda(\lambda,\mu)$ or $\Lambda(\lambda,\mu) \not\geq \Lambda_0 + \DLambda_{\beta,C}$, which is the contrapositive formulation of the statement we are proving. In particular, case A will contradict the second operator inequality, while case B will contradict the first operator inequality. 

For both cases we pick $(g_i)$ in $L^2_\diamond(\GammaN)^d$ via Lemma~\ref{lemma:locpot} such that $u_i = u_{g_i}^{\lambda_0,\mu_0}$ satisfies
%
\begin{equation*}
	\lim_{i\to\infty}\int_B \abs{\nabla\cdot u_i}^2\,\di x = \lim_{i\to\infty}\int_B \frob{\widehat{\nabla}u_i}^2\,\di x = \infty
\end{equation*}
%
and
%
\begin{equation*}
	\lim_{i\to\infty}\int_{\Omega\setminus U} \abs{\nabla\cdot u_i}^2\,\di x = \lim_{i\to\infty}\int_{\Omega\setminus U} \frob{\widehat{\nabla}u_i}^2\,\di x = 0.
\end{equation*}

\subsection*{Case A}

By Lemma~\ref{lemma:monoback} we get
%
\begin{align*}
	\inner{(\Lambda(\lambda,\mu) - \Lambda_0 - \DLambda_{\beta,C})g_i,g_i} \hspace{-4cm}&\\
	&\leq \int_{\Dm\cup\Dp} \frac{\lambda_0}{\lambda}(\lambda_0-\lambda)\abs{\nabla\cdot u_i}^2 +  2\frac{\mu_0}{\mu}(\mu_0-\mu)\frob{\widehat{\nabla}u_i}^2\,\di x + \beta\int_C \abs{\nabla\cdot u_i}^2 +2\frob{\widehat{\nabla}u_i}^2\,\di x. 
\end{align*}
%
The integrals over $C$ and over $\Dm$ tend to zero as $C\cup\Dm\subset\Omega\setminus\overline{U}$. By Assumption~\ref{assump:technical} we may assume that $\inf_B(\mu_+-\mu_0)>0$. As $B\subset \Dp$, $\lambda_+\geq\lambda_0$, and $\mu_+\geq \mu_0$, the integral over $\Dp$ tends to minus infinity for $i\to\infty$. Thus we conclude that
%
\begin{equation*}
	\lim_{i\to\infty}\inner{(\Lambda(\lambda,\mu) - \Lambda_0 - \DLambda_{\beta,C})g_i,g_i} = -\infty,
\end{equation*}
%
which means that $\Lambda(\lambda,\mu) \not\geq \Lambda_0 + \DLambda_{\beta,C}$.

\subsection*{Case B}

By Lemma~\ref{lemma:monoback} we get
%
\begin{align*}
	\inner{(\Lambda_0 + \DLambda_{-\betaU\beta,C} - \Lambda(\lambda,\mu))g_i,g_i} \hspace{-4cm}&\\
	&\leq \int_{\Dm\cup\Dp} (\lambda-\lambda_0)\abs{\nabla\cdot u_i}^2 + 2(\mu - \mu_0)\frob{\widehat{\nabla}u_i}^2\,\di x + \betaU\beta\int_C \abs{\nabla\cdot u_i}^2 +2\frob{\widehat{\nabla}u_i}^2\,\di x.
\end{align*}
%
The integrals over $C$ and over $\Dp$ tend to zero as $C\cup\Dp\subset\Omega\setminus\overline{U}$. By Assumption~\ref{assump:technical} we may assume that $\sup_B(\mu_- - \mu_0)<0$. As $B\subset \Dm$, $\lambda_-\leq\lambda_0$, and $\mu_-\leq \mu_0$, the integral over $\Dm$ tends to minus infinity for $i\to\infty$. Thus we conclude that
%
\begin{equation*}
	\lim_{i\to\infty}\inner{(\Lambda_0 + \DLambda_{-\betaU\beta,C} - \Lambda(\lambda,\mu))g_i,g_i} = -\infty,
\end{equation*}
%
which means that $\Lambda_0 + \DLambda_{-\betaU\beta,C} \not\geq \Lambda(\lambda,\mu)$.

